# ============================================================================
# HELPER FUNCTIONS
# ============================================================================

def generate_event_id():
    """
    Generate a unique event ID for correlating logs across main and worker logs.
    
    Format: timestamp-random (e.g., 20260115-143052-a3f9)
    
    Returns:
        str: Unique event ID
    """
    timestamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    random_suffix = ''.join(random.choices(string.ascii_lowercase + string.digits, k=4))
    return f"{timestamp}-{random_suffix}"

def interruptible_sleep(duration, shutdown_event, check_interval=0.1):
    """
    Sleep for a duration while checking shutdown_event periodically.
    
    This allows long sleeps to be interrupted by CTRL+C or shutdown signals.
    
    Args:
        duration: Total sleep duration in seconds
        shutdown_event: threading.Event to check for shutdown
        check_interval: How often to check shutdown_event (default: 0.1s)
    
    Returns:
        bool: True if sleep completed normally, False if interrupted by shutdown
    """
    end_time = time.time() + duration
    while time.time() < end_time:
        if shutdown_event.is_set():
            return False  # Interrupted
        remaining = end_time - time.time()
        if remaining > 0:
            time.sleep(min(check_interval, remaining))
    return True  # Completed normally

