def check_python_version():
    """
    Verify that Python version is 3.13 or higher.
    
    This is a critical requirement as the test script uses features
    that are only available in Python 3.13+.
    
    Requirements: 2.1
    
    Raises:
        SystemExit: If Python version is insufficient
    """
    current_version = sys.version_info[:2]
    
    print(f"Checking Python version...")
    print(f"  Current version: Python {current_version[0]}.{current_version[1]}")
    print(f"  Required version: Python {REQUIRED_PYTHON_VERSION[0]}.{REQUIRED_PYTHON_VERSION[1]} or higher")
    
    if current_version < REQUIRED_PYTHON_VERSION:
        print()
        print("❌ ERROR: Insufficient Python version")
        print()
        print(f"This script requires Python {REQUIRED_PYTHON_VERSION[0]}.{REQUIRED_PYTHON_VERSION[1]} or higher.")
        print(f"You are currently running Python {current_version[0]}.{current_version[1]}.")
        print()
        print("Please upgrade Python:")
        print("  - Visit https://www.python.org/downloads/")
        print(f"  - Or use pyenv: pyenv install {REQUIRED_PYTHON_VERSION[0]}.{REQUIRED_PYTHON_VERSION[1]}")
        print()
        sys.exit(1)
    
    print(f"  ✓ Python version is sufficient")
    print()


def check_package_dependencies():
    """
    Verify that all required Python packages are installed.
    
    Checks for:
    - boto3: AWS SDK for Python
    - requests: HTTP library for API calls
    - psutil: System and process utilities (for resource monitoring)
    
    Requirements: 2.2
    
    Raises:
        SystemExit: If any required package is missing
    """
    print("Checking Python package dependencies...")
    
    # Define required packages with their import names
    required_packages = {
        'boto3': 'boto3',
        'requests': 'requests',
        'psutil': 'psutil'
    }
    
    missing_packages = []
    
    for package_name, import_name in required_packages.items():
        spec = importlib.util.find_spec(import_name)
        if spec is None:
            print(f"  ❌ {package_name} - NOT INSTALLED")
            missing_packages.append(package_name)
        else:
            print(f"  ✓ {package_name} - installed")
    
    if missing_packages:
        print()
        print("❌ ERROR: Missing required packages")
        print()
        print("The following packages are required but not installed:")
        for package in missing_packages:
            print(f"  - {package}")
        print()
        print("Install missing packages:")
        print(f"  pip install {' '.join(missing_packages)}")
        print()
        print("Or install all requirements:")
        print("  pip install -r requirements.txt")
        print()
        sys.exit(1)
    
    print("  ✓ All required packages are installed")
    print()


def check_aws_cli():
    """
    Verify that AWS CLI is installed and accessible.
    
    The AWS CLI is required for certain operations like querying CloudFormation
    stack outputs and Service Quotas.
    
    Requirements: 2.3
    
    Raises:
        SystemExit: If AWS CLI is not installed or not accessible
    """
    print("Checking AWS CLI installation...")
    
    # Check if AWS CLI is in PATH
    aws_cli_path = shutil.which('aws')
    
    if aws_cli_path is None:
        print("  ❌ AWS CLI - NOT FOUND")
        print()
        print("❌ ERROR: AWS CLI not installed")
        print()
        print("The AWS CLI is required for this script.")
        print()
        print("Install AWS CLI:")
        print("  - macOS: brew install awscli")
        print("  - Linux: pip install awscli")
        print("  - Windows: Download from https://aws.amazon.com/cli/")
        print()
        print("Or follow the official guide:")
        print("  https://docs.aws.amazon.com/cli/latest/userguide/getting-started-install.html")
        print()
        sys.exit(1)
    
    print(f"  ✓ AWS CLI found at: {aws_cli_path}")
    
    # Check AWS CLI version
    try:
        result = subprocess.run(
            ['aws', '--version'],
            capture_output=True,
            text=True,
            timeout=API_TIMEOUT_VALIDATION
        )
        version_output = result.stdout.strip() or result.stderr.strip()
        print(f"  ✓ Version: {version_output}")
    except subprocess.TimeoutExpired:
        print("  ⚠ Warning: AWS CLI version check timed out")
    except Exception as e:
        print(f"  ⚠ Warning: Could not determine AWS CLI version: {e}")
    
    print()


def check_aws_credentials(aws_profile=None, aws_region=None):
    """
    Verify that AWS credentials are configured and valid.
    
    Tests credentials by making a simple AWS API call (STS GetCallerIdentity).
    
    Args:
        aws_profile: AWS profile name to use (optional)
        aws_region: AWS region to use (optional)
    
    Requirements: 2.4
    
    Raises:
        SystemExit: If AWS credentials are not configured or invalid
    """
    print("Checking AWS credentials...")
    
    try:
        # Create session with profile if specified
        session_kwargs = {}
        if aws_profile:
            session_kwargs['profile_name'] = aws_profile
            print(f"  Using AWS profile: {aws_profile}")
        if aws_region:
            session_kwargs['region_name'] = aws_region
            print(f"  Using AWS region: {aws_region}")
        
        session = boto3.Session(**session_kwargs)
        
        # Test credentials with STS GetCallerIdentity
        sts = session.client('sts')
        identity = sts.get_caller_identity()
        
        print(f"  ✓ AWS credentials are valid")
        print(f"  ✓ Account ID: {identity['Account']}")
        print(f"  ✓ User/Role ARN: {identity['Arn']}")
        print()
        
        return session
        
    except ProfileNotFound:
        print(f"  ❌ AWS profile '{aws_profile}' not found")
        print()
        print("❌ ERROR: AWS profile not configured")
        print()
        print(f"The specified profile '{aws_profile}' does not exist.")
        print()
        print("Configure AWS profile:")
        print(f"  aws configure --profile {aws_profile}")
        print()
        print("Or list available profiles:")
        print("  aws configure list-profiles")
        print()
        sys.exit(1)
        
    except NoCredentialsError:
        print("  ❌ No AWS credentials found")
        print()
        print("❌ ERROR: AWS credentials not configured")
        print()
        print("Configure AWS credentials:")
        print("  aws configure")
        print()
        print("Or set environment variables:")
        print("  export AWS_ACCESS_KEY_ID=your_access_key")
        print("  export AWS_SECRET_ACCESS_KEY=your_secret_key")
        print()
        sys.exit(1)
        
    except ClientError as e:
        print(f"  ❌ AWS credentials are invalid: {e}")
        print()
        print("❌ ERROR: AWS credentials validation failed")
        print()
        print("Your credentials may be expired or invalid.")
        print("Please reconfigure:")
        print("  aws configure")
        print()
        sys.exit(1)
        
    except Exception as e:
        print(f"  ❌ Unexpected error: {e}")
        print()
        print("❌ ERROR: Could not validate AWS credentials")
        print()
        sys.exit(1)


def check_iam_permissions(aws_session):
    """
    Check IAM permissions for required AWS services.
    
    This performs basic checks to verify the credentials have necessary permissions
    for DynamoDB, CloudWatch, SNS, and S3 operations. This is a best-effort check;
    some permission issues may only be discovered during actual test execution.
    
    Args:
        aws_session: boto3 Session object with configured credentials
    
    Requirements: 2.5, 2.6
    """
    print("Checking IAM permissions...")
    
    services_to_check = {
        'dynamodb': 'DynamoDB (for test configuration and player state)',
        'cloudwatch': 'CloudWatch (for metrics and monitoring)',
        'sns': 'SNS (for alerting)',
        's3': 'S3 (for log archival and reports)'
    }
    
    warnings = []
    
    for service, description in services_to_check.items():
        try:
            client = aws_session.client(service)
            
            # Perform a simple read operation to test permissions
            if service == 'dynamodb':
                client.list_tables(Limit=1)
            elif service == 'cloudwatch':
                # list_metrics doesn't support pagination parameters in the way we need
                # Just call it without parameters to test permissions
                client.list_metrics()
            elif service == 'sns':
                client.list_topics()
            elif service == 's3':
                client.list_buckets()
            
            print(f"  ✓ {service.upper()} - permissions OK")
            
        except ClientError as e:
            error_code = e.response.get('Error', {}).get('Code', 'Unknown')
            if error_code in ['AccessDenied', 'UnauthorizedOperation', 'AccessDeniedException']:
                print(f"  ⚠ {service.upper()} - insufficient permissions")
                warnings.append(f"{service.upper()}: {description}")
            else:
                print(f"  ⚠ {service.upper()} - could not verify ({error_code})")
        except Exception as e:
            print(f"  ⚠ {service.upper()} - could not verify: {e}")
    
    print()
    
    if warnings:
        print("⚠ WARNING: Some permissions may be insufficient")
        print()
        print("The following services may have permission issues:")
        for warning in warnings:
            print(f"  - {warning}")
        print()
        print("The test may fail during execution if these permissions are required.")
        print("Ensure your IAM user/role has the necessary permissions.")
        print()
        
        # Ask user if they want to continue
        response = input("Continue anyway? (yes/no): ").strip().lower()
        if response not in ['yes', 'y']:
            print("Exiting...")
            sys.exit(0)
        print()


