def parse_arguments():
    """
    Parse and validate command-line arguments.
    
    Supports:
    - Mode selection: --generate-new, --test-config-id, --dry-run
    - AWS configuration: --aws-profile, --region
    - Test parameters: --duration, --target-rps, --max-players
    - Optional: --config-file, --log-dir, --skip-validation
    
    Requirements: 5.1, 5.2, 5.3
    
    Returns:
        argparse.Namespace: Parsed arguments
    """
    parser = argparse.ArgumentParser(
        description='Load and Stress Testing System for Stats & Leaderboards',
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
Examples:
  Generation Mode:
    python test_LoadAndStressTests.py --generate-new --aws-profile dev --region us-west-2
  
  Execution Mode:
    python test_LoadAndStressTests.py --test-config-id test-20241024-abc123 --aws-profile dev --region us-west-2
        """
    )
    
    # Mode selection (mutually exclusive)
    mode_group = parser.add_mutually_exclusive_group(required=True)
    mode_group.add_argument('--generate-new', action='store_true',
                           help='Generate new test configuration and Test Config ID')
    mode_group.add_argument('--test-config-id', type=str,
                           help='Execute test using existing Test Config ID (optional - auto-detects if only one running)')
    mode_group.add_argument('--list', action='store_true',
                           help='List all Test Config IDs with names and status')
    mode_group.add_argument('--list-supported-genres', action='store_true',
                           help='List all supported game genres from genre definitions')
    mode_group.add_argument('--delete-config', type=str, metavar='CONFIG_ID',
                           help='Delete a Test Config ID (must be AVAILABLE, not RUNNING)')
    mode_group.add_argument('--force-unlock', action='store_true',
                           help='Force remove GLOBAL_TEST_LOCK (emergency use only)')
    
    # Generation options
    parser.add_argument('--overwrite', action='store_true',
                       help='Automatically overwrite existing test configuration with same name (no prompt)')
    
    # Test configuration naming and genre
    parser.add_argument('--test-name', type=str,
                       help='Human-readable name for test configuration (required with --generate-new, 1-64 chars)')
    parser.add_argument('--genre', type=str,
                       help='Game genre for test configuration (optional with --generate-new, random if not specified)')
    
    # Validation mode (can be used with --test-config-id)
    parser.add_argument('--dry-run', action='store_true',
                       help='Validate configuration without executing (use with --test-config-id)')
    
    # AWS configuration
    parser.add_argument('--aws-profile', type=str, default=None,
                       help='AWS profile name to use')
    parser.add_argument('--region', type=str, default=DEFAULT_AWS_REGION,
                       help=f'AWS region (default: {DEFAULT_AWS_REGION})')
    parser.add_argument('--stack-name', type=str, default='GameStatsLeaderboardsStack',
                       help='CloudFormation stack name for infrastructure discovery (default: GameStatsLeaderboardsStack)')
    
    # Test configuration
    parser.add_argument('--duration', type=int, default=DEFAULT_TEST_DURATION,
                       help=f'Test duration in seconds (default: {DEFAULT_TEST_DURATION}, range: {MIN_TEST_DURATION}-{MAX_TEST_DURATION})')
    parser.add_argument('--max-players', type=int, default=None,
                       help=f'Maximum concurrent players per instance (default: {DEFAULT_PLAYERS_PER_INSTANCE}, range: {MIN_PLAYERS_PER_INSTANCE}-{MAX_PLAYERS_PER_INSTANCE}). '
                            f'For large-scale tests (e.g., 100k players), run multiple instances with the same Test Config ID.')
    
    # Optional configuration
    parser.add_argument('--config-file', type=str, default=None,
                       help='Path to JSON configuration file')
    parser.add_argument('--log-dir', type=str, default=None,
                       help='Custom log directory path')
    parser.add_argument('--skip-validation', action='store_true',
                       help='Skip dependency validation checks (advanced users only)')
    parser.add_argument('--retain-web-server', action='store_true',
                       help='Keep leaderboard viewer web servers running after test completes (default: auto-shutdown)')
    
    # Parse arguments
    args = parser.parse_args()
        
    # Validate argument combinations and ranges
    if args.duration < MIN_TEST_DURATION or args.duration > MAX_TEST_DURATION:
        parser.error(f"--duration must be between {MIN_TEST_DURATION} and {MAX_TEST_DURATION} seconds (1 minute to 24 hours)")
    if args.max_players is not None and (args.max_players < MIN_PLAYERS_PER_INSTANCE or args.max_players > MAX_PLAYERS_PER_INSTANCE):
        parser.error(f"--max-players must be between {MIN_PLAYERS_PER_INSTANCE} and {MAX_PLAYERS_PER_INSTANCE} per instance")
    
    # Validate --test-name is required with --generate-new
    if args.generate_new and not args.test_name:
        parser.error("--test-name is required when using --generate-new")
    
    # Validate --test-name length
    if args.test_name:
        if len(args.test_name) < MIN_TEST_NAME_LENGTH or len(args.test_name) > MAX_TEST_NAME_LENGTH:
            parser.error(f"--test-name must be between {MIN_TEST_NAME_LENGTH} and {MAX_TEST_NAME_LENGTH} characters")
        # Validate test name contains only alphanumeric, hyphens, underscores, and spaces
        if not re.match(r'^[a-zA-Z0-9\s_-]+$', args.test_name):
            parser.error("--test-name can only contain alphanumeric characters, spaces, hyphens, and underscores")
    
    return args


def load_configuration(args):
    """
    Load and merge configuration from JSON file and command-line arguments.
    
    Command-line arguments take priority over JSON file values.
    
    Args:
        args: Parsed command-line arguments
    
    Requirements: 5.4, 5.5, 5.6, 5.7
    
    Returns:
        dict: Merged configuration
    """
    
    config = {}
    
    # Load from JSON file if provided
    if args.config_file:
        print(f"Loading configuration from: {args.config_file}")
        try:
            with open(args.config_file, 'r') as f:
                config = json.load(f)
            print(f"  ✓ Configuration file loaded successfully")
        except FileNotFoundError:
            print(f"  ❌ Configuration file not found: {args.config_file}")
            print()
            print("❌ ERROR: Configuration file does not exist")
            print()
            sys.exit(1)
        except json.JSONDecodeError as e:
            print(f"  ❌ Invalid JSON in configuration file: {e}")
            print()
            print("❌ ERROR: Configuration file is not valid JSON")
            print()
            sys.exit(1)
        except Exception as e:
            print(f"  ❌ Error loading configuration file: {e}")
            print()
            sys.exit(1)
    
    # Override with command-line arguments (CLI takes priority)
    if args.aws_profile:
        config['aws_profile'] = args.aws_profile
    if args.region:
        config['region'] = args.region
    if args.stack_name:
        config['stack_name'] = args.stack_name
    if args.duration:
        config['duration'] = args.duration
    if args.max_players is not None:
        config['max_players'] = args.max_players
    if args.log_dir:
        config['log_dir'] = args.log_dir
    if args.test_name:
        config['test_name'] = args.test_name
    if args.genre:
        config['genre'] = args.genre
    
    # Add boolean flags
    config['retain_web_server'] = args.retain_web_server
    
    # Add mode information
    if args.generate_new:
        config['mode'] = 'generation'
        print()
        print("=" * 80)
        print("🔧 INVOCATION MODE: GENERATION")
        print("=" * 80)
        print("Creating new test configuration and storing in DynamoDB")
        print()
    elif args.test_config_id:
        # Check if dry-run flag is set
        if args.dry_run:
            config['mode'] = 'dry-run'
            print()
            print("=" * 80)
            print("✓ INVOCATION MODE: DRY-RUN VALIDATION")
            print("=" * 80)
            print("Validating configuration without executing test")
            print(f"Test Config ID: {args.test_config_id}")
            print()
        else:
            config['mode'] = 'execution'
            print()
            print("=" * 80)
            print("🚀 INVOCATION MODE: TEST EXECUTION")
            print("=" * 80)
            print("Running load test with existing configuration")
            print(f"Test Config ID: {args.test_config_id}")
            print()
        config['test_config_id'] = args.test_config_id
    elif args.dry_run:
        # Dry-run without test-config-id is an error
        print()
        print("❌ ERROR: --dry-run requires --test-config-id")
        print()
        print("Usage: python test_LoadAndStressTests.py --test-config-id <id> --dry-run")
        print()
        sys.exit(1)
    
    config['skip_validation'] = args.skip_validation
    
    # Validate required configuration
    required_fields = ['region']
    missing_fields = [field for field in required_fields if field not in config]
    
    if missing_fields:
        print()
        print("❌ ERROR: Missing required configuration")
        print()
        print("The following required fields are missing:")
        for field in missing_fields:
            print(f"  - {field}")
        print()
        print("Provide them via command-line arguments or configuration file.")
        print()
        sys.exit(1)
    
    print()
    return config


