def find_test_config_by_name(test_name, region=DEFAULT_AWS_REGION, profile=None):
    """
    Find a test configuration by its human-readable name.
    
    Scans the Test Definitions Table for METADATA records matching the test name.
    Returns the Test Config ID if found, None otherwise.
    
    Args:
        test_name: Human-readable test name to search for
        region: AWS region (default: us-west-2)
        profile: AWS profile name (optional)
    
    Returns:
        str: Test Config ID if found, None otherwise
    
    Requirements: 35.10
    """
    
    try:
        # Create boto3 session
        session_kwargs = {'region_name': region}
        if profile:
            session_kwargs['profile_name'] = profile
        session = boto3.Session(**session_kwargs)
        dynamodb = session.resource('dynamodb')
        table = dynamodb.Table(TEST_DEFINITIONS_TABLE_NAME)
        
        # Scan for METADATA records with matching TestName
        # Note: This is a scan operation, not ideal for large tables
        # But test configs are typically small in number
        response = table.scan(
            FilterExpression='ConfigCategory = :category AND #testName = :name',
            ExpressionAttributeNames={
                '#testName': 'TestName'
            },
            ExpressionAttributeValues={
                ':category': 'METADATA',
                ':name': test_name
            }
        )
        
        items = response.get('Items', [])
        
        if items:
            # Return the first matching Test Config ID
            return items[0].get('TestConfigID')
        
        return None
        
    except ClientError as e:
        error_code = e.response.get('Error', {}).get('Code', 'Unknown')
        
        if error_code == 'AccessDeniedException':
            print(f"⚠ WARNING: Access denied when searching for test configuration")
            return None
        else:
            print(f"⚠ WARNING: Failed to search for test configuration: {e}")
            return None
    
    except Exception as e:
        print(f"⚠ WARNING: Unexpected error searching for test configuration: {e}")
        return None


def list_test_configs():
    """
    List all Test Config IDs with names and status from DynamoDB.
    
    Shows which config is currently RUNNING (if any).
    
    Requirements: 35.11, 35.12
    """
    
    print("=" * 80)
    print("Available Test Configurations")
    print("=" * 80)
    print()
    
    try:
        # Get AWS profile and region from args (will be passed from main)
        # For now, use defaults
        region = DEFAULT_AWS_REGION
        profile = None
        
        # Create boto3 session
        session_kwargs = {'region_name': region}
        if profile:
            session_kwargs['profile_name'] = profile
        session = boto3.Session(**session_kwargs)
        dynamodb = session.resource('dynamodb')
        table = dynamodb.Table(TEST_DEFINITIONS_TABLE_NAME)
        
        # Query for all METADATA records
        response = table.query(
            IndexName='StatusIndex',
            KeyConditionExpression='#status = :status',
            ExpressionAttributeNames={
                '#status': 'Status'
            },
            ExpressionAttributeValues={
                ':status': 'AVAILABLE'
            }
        )
        
        available_configs = response.get('Items', [])
        
        # Query for RUNNING configs
        response = table.query(
            IndexName='StatusIndex',
            KeyConditionExpression='#status = :status',
            ExpressionAttributeNames={
                '#status': 'Status'
            },
            ExpressionAttributeValues={
                ':status': 'RUNNING'
            }
        )
        
        running_configs = response.get('Items', [])
        
        # Get GLOBAL_TEST_LOCK to identify currently running config
        running_test_id = None
        try:
            lock_response = table.get_item(
                Key={
                    'TestConfigID': 'GLOBAL',
                    'ConfigCategory': 'TEST_LOCK'
                }
            )
            
            if 'Item' in lock_response:
                running_test_id = lock_response['Item'].get('ActiveTestConfigID')
        except Exception:
            pass
        
        # Combine all configs
        all_configs = available_configs + running_configs
        
        if not all_configs:
            print("No test configurations found.")
            print()
            print("Create a new test configuration with:")
            print("  python test_LoadAndStressTests.py --generate-new --test-name \"My Test\" --aws-profile <profile>")
            print()
        else:
            # Display configs in table format
            print(f"{'Test Config ID':<40} {'Name':<25} {'Genre':<15} {'Status':<12} {'Created':<20}")
            print("-" * 115)
            
            for config in sorted(all_configs, key=lambda x: x.get('CreatedTime', 0), reverse=True):
                test_id = config.get('TestConfigID', 'Unknown')
                test_name = config.get('TestName', 'Unnamed')
                genre = config.get('Genre', 'Unknown')
                status = config.get('Status', 'Unknown')
                created_time = config.get('CreatedTime', 0)
                
                # Convert Decimal to int
                if isinstance(created_time, Decimal):
                    created_time = int(created_time)
                
                # Format created time
                if created_time > 0:
                    created_str = time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(created_time))
                else:
                    created_str = 'Unknown'
                
                # Mark currently running config
                marker = ' ← RUNNING' if test_id == running_test_id else ''
                
                # Truncate long names
                if len(test_name) > 23:
                    test_name = test_name[:20] + '...'
                if len(test_id) > 38:
                    test_id = test_id[:35] + '...'
                
                print(f"{test_id:<40} {test_name:<25} {genre:<15} {status:<12} {created_str:<20}{marker}")
            
            print()
            print(f"Total configurations: {len(all_configs)}")
            
            if running_test_id:
                print(f"Currently running: {running_test_id}")
        
        print()
        print("=" * 80)
        print()
        
    except ClientError as e:
        error_code = e.response.get('Error', {}).get('Code', 'Unknown')
        
        if error_code == 'AccessDeniedException':
            print()
            print(f"❌ ERROR: Access denied when querying test configurations")
            print()
            print("Required IAM permissions:")
            print("  - dynamodb:Query")
            print("  - dynamodb:GetItem")
            print()
            print(f"Resource ARN: arn:aws:dynamodb:{region}:*:table/{TEST_DEFINITIONS_TABLE_NAME}")
            print(f"Index ARN: arn:aws:dynamodb:{region}:*:table/{TEST_DEFINITIONS_TABLE_NAME}/index/StatusIndex")
            print()
        else:
            print(f"❌ ERROR: Failed to list test configurations: {e}")
            traceback.print_exc()
    
    except Exception as e:
        print(f"❌ Unexpected error listing test configurations: {e}")
        traceback.print_exc()


def delete_test_config(config_id):
    """
    Delete a Test Config ID from DynamoDB.
    
    Only allows deletion of configs with Status='AVAILABLE' (not RUNNING).
    Requires user confirmation.
    
    Args:
        config_id: Test Config ID to delete
    
    Requirements: 35.18, 35.19, 35.20
    """
    
    print("=" * 80)
    print(f"Delete Test Configuration: {config_id}")
    print("=" * 80)
    print()
    
    try:
        # Get AWS profile and region from args (will be passed from main)
        # For now, use defaults
        region = DEFAULT_AWS_REGION
        profile = None
        
        # Create boto3 session
        session_kwargs = {'region_name': region}
        if profile:
            session_kwargs['profile_name'] = profile
        session = boto3.Session(**session_kwargs)
        dynamodb = session.resource('dynamodb')
        table = dynamodb.Table(TEST_DEFINITIONS_TABLE_NAME)
        
        # Load test configuration METADATA
        response = table.get_item(
            Key={
                'TestConfigID': config_id,
                'ConfigCategory': 'METADATA'
            }
        )
        
        if 'Item' not in response:
            print(f"❌ ERROR: Test configuration '{config_id}' not found")
            print()
            print("Use --list to see available configurations.")
            print()
            return
        
        metadata = response['Item']
        status = metadata.get('Status', 'Unknown')
        test_name = metadata.get('TestName', 'Unnamed')
        genre = metadata.get('Genre', 'Unknown')
        created_time = metadata.get('CreatedTime', 0)
        
        # Convert Decimal to int
        if isinstance(created_time, Decimal):
            created_time = int(created_time)
        
        # Verify status is AVAILABLE (not RUNNING)
        if status == 'RUNNING':
            print(f"❌ ERROR: Cannot delete a RUNNING test configuration")
            print()
            print(f"Test '{test_name}' is currently running.")
            print("Wait for the test to complete, or use --force-unlock if it has crashed.")
            print()
            return
        
        # Display configuration details
        print("Configuration Details:")
        print(f"  Test Config ID: {config_id}")
        print(f"  Name: {test_name}")
        print(f"  Genre: {genre}")
        print(f"  Status: {status}")
        if created_time > 0:
            print(f"  Created: {time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(created_time))}")
        print()
        
        # Request user confirmation
        response = input("Are you sure you want to delete this configuration? (yes/no): ").strip().lower()
        if response not in ['yes', 'y']:
            print("Deletion cancelled.")
            print()
            return
        
        print()
        print("Deleting configuration...")
        
        # Query all categories for this config
        response = table.query(
            KeyConditionExpression='TestConfigID = :id',
            ExpressionAttributeValues={
                ':id': config_id
            }
        )
        
        items = response.get('Items', [])
        
        # Delete all configuration categories
        deleted_count = 0
        for item in items:
            table.delete_item(
                Key={
                    'TestConfigID': item['TestConfigID'],
                    'ConfigCategory': item['ConfigCategory']
                }
            )
            deleted_count += 1
            print(f"  ✓ Deleted category: {item['ConfigCategory']}")
        
        print()
        print(f"✓ Successfully deleted test configuration '{test_name}'")
        print(f"  Deleted {deleted_count} configuration records")
        print()
        
    except ClientError as e:
        error_code = e.response.get('Error', {}).get('Code', 'Unknown')
        
        if error_code == 'AccessDeniedException':
            print()
            print(f"❌ ERROR: Access denied when deleting test configuration")
            print()
            print("Required IAM permissions:")
            print("  - dynamodb:GetItem")
            print("  - dynamodb:Query")
            print("  - dynamodb:DeleteItem")
            print()
            print(f"Resource ARN: arn:aws:dynamodb:{region}:*:table/{TEST_DEFINITIONS_TABLE_NAME}")
            print()
        else:
            print(f"❌ ERROR: Failed to delete test configuration: {e}")
            traceback.print_exc()
    
    except Exception as e:
        print(f"❌ Unexpected error deleting test configuration: {e}")
        traceback.print_exc()
    
    print("=" * 80)
    print()


def force_unlock_global_lock(region=DEFAULT_AWS_REGION, profile=None):
    """
    Force remove GLOBAL_TEST_LOCK from DynamoDB.
    
    Emergency use only - removes the lock without deleting any test config.
    Use when a test has crashed and the lock is stuck.
    
    Args:
        region: AWS region
        profile: AWS profile name (optional)
    
    Requirements: 35.21, 35.22
    """
    
    print("=" * 80)
    print("Force Unlock Global Test Lock")
    print("=" * 80)
    print()
    
    print("⚠️  WARNING: This is an emergency operation!")
    print()
    print("This will remove the GLOBAL_TEST_LOCK, allowing another test to run.")
    print("Only use this if:")
    print("  - A test has crashed and the lock is stuck")
    print("  - You are certain no test is actually running")
    print()
    
    response = input("Are you sure you want to force unlock? (yes/no): ").strip().lower()
    if response not in ['yes', 'y']:
        print("Aborted.")
        print()
        return
    
    try:
        # Create boto3 session
        session_kwargs = {'region_name': region}
        if profile:
            session_kwargs['profile_name'] = profile
        session = boto3.Session(**session_kwargs)
        dynamodb = session.resource('dynamodb')
        table = dynamodb.Table(TEST_DEFINITIONS_TABLE_NAME)
        
        # Check if lock exists
        lock_response = table.get_item(
            Key={
                'TestConfigID': 'GLOBAL',
                'ConfigCategory': 'TEST_LOCK'
            }
        )
        
        if 'Item' not in lock_response:
            print()
            print("ℹ️  No global test lock found. Nothing to unlock.")
            print()
            return
        
        lock = lock_response['Item']
        locked_test_id = lock.get('ActiveTestConfigID', 'Unknown')
        locked_test_name = lock.get('ActiveTestName', 'Unknown')
        
        print()
        print(f"Removing lock for: {locked_test_name} ({locked_test_id})")
        
        # Delete the GLOBAL_TEST_LOCK record
        table.delete_item(
            Key={
                'TestConfigID': 'GLOBAL',
                'ConfigCategory': 'TEST_LOCK'
            }
        )
        
        print()
        print("✓ Global test lock removed successfully")
        print()
        print("The test configuration status has NOT been changed.")
        print("You may need to manually update the test configuration status if needed.")
        print()
        
    except ClientError as e:
        error_code = e.response.get('Error', {}).get('Code', 'Unknown')
        
        if error_code == 'AccessDeniedException':
            print()
            print(f"❌ ERROR: Access denied when removing global test lock")
            print()
            print("Required IAM permissions:")
            print("  - dynamodb:GetItem")
            print("  - dynamodb:DeleteItem")
            print()
            print(f"Resource ARN: arn:aws:dynamodb:{region}:*:table/{TEST_DEFINITIONS_TABLE_NAME}")
            print()
        else:
            print(f"❌ ERROR: Failed to remove global test lock: {e}")
            traceback.print_exc()
    
    except Exception as e:
        print(f"❌ Unexpected error removing global test lock: {e}")
        traceback.print_exc()
    
    print("=" * 80)
    print()


