def generate_event_schedule(test_duration_seconds, game_modes):
    """
    Generate 5-10 dynamic events with time-bound leaderboards.
    
    Events are scheduled throughout the test duration with start times, durations,
    and event-specific leaderboard configurations including expiry behavior.
    
    Args:
        test_duration_seconds: Total test duration in seconds
        game_modes: List of game mode dictionaries
    
    Returns:
        list: List of event dictionaries with leaderboard configurations
    
    Requirements: 6.10, 7.12, 8.3, 8.4, 8.5, 8.6
    Tasks: 7.5.1, 7.5.2, 7.5.3
    """
    
    print("Generating event schedule...")
    
    # Event duration options (in seconds)
    event_durations = [
        30 * 60,   # 30 minutes
        60 * 60,   # 1 hour
        120 * 60,  # 2 hours
        240 * 60   # 4 hours
    ]
    
    # Event types with expiry behavior
    event_types = [
        {'type': 'tournament', 'read_only_on_expiry': True, 'description': 'Competitive tournament with preserved results'},
        {'type': 'challenge', 'read_only_on_expiry': False, 'description': 'Daily challenge that auto-deletes'},
        {'type': 'seasonal', 'read_only_on_expiry': True, 'description': 'Seasonal event with historical data'},
        {'type': 'daily', 'read_only_on_expiry': False, 'description': 'Daily event that resets'},
        {'type': 'weekend', 'read_only_on_expiry': True, 'description': 'Weekend special with leaderboard preservation'}
    ]
    
    # Generate 5-10 events
    num_events = random.randint(5, 10)
    
    # Distribute event start times across test duration
    # Leave buffer at start (10%) and end (10%)
    buffer = test_duration_seconds * 0.1
    available_duration = test_duration_seconds - (2 * buffer)
    
    events = []
    test_start_time = datetime.now(timezone.utc)
    
    for i in range(num_events):
        # Calculate start time (distributed across available duration)
        offset = buffer + (i * available_duration / num_events) + random.uniform(0, available_duration / (num_events * 2))
        start_time = test_start_time + timedelta(seconds=offset)
        
        # Select event duration
        duration = random.choice(event_durations)
        
        # Ensure event doesn't extend beyond test duration
        if offset + duration > test_duration_seconds:
            duration = min(duration, test_duration_seconds - offset - buffer)
        
        end_time = start_time + timedelta(seconds=duration)
        
        # Select event type
        event_type_info = random.choice(event_types)
        
        # Select target game mode
        target_mode = random.choice(game_modes)
        
        # Generate event name
        event_name = f"{event_type_info['type']}-{i+1}-{target_mode['modeName']}"
        
        # Create event leaderboard configuration
        # Use Unix timestamps for consistency with monitoring code
        start_timestamp = int(start_time.timestamp())
        end_timestamp = int(end_time.timestamp())
        
        # Map game mode scoring types to valid API scoreType values
        # API only accepts: ['score', 'time', 'distance', 'points', 'rank', 'level']
        scoring_type_mapping = {
            'time': 'time',
            'distance': 'distance',
            'points': 'points',
            'rank': 'rank',
            'level': 'level',
            'score': 'score',
            # Map game-specific scoring types to generic API types
            'kills': 'score',
            'objectives': 'points',
            'rounds': 'score',
            'mmr': 'rank',
            'rating': 'rank',
            'experience': 'points',
            'loot': 'points',
            'damage': 'score',
            'goals': 'score',
            'skills': 'points',
            'placement': 'rank'
        }
        
        # Get the valid scoreType for the API
        game_scoring_type = target_mode.get('scoringType', 'score')
        api_score_type = scoring_type_mapping.get(game_scoring_type, 'score')
        
        event = {
            'eventName': event_name,
            'eventType': event_type_info['type'],
            'description': event_type_info['description'],
            'startTime': start_timestamp,
            'endTime': end_timestamp,
            'startTimeISO': start_time.isoformat(),  # Keep ISO for human readability
            'endTimeISO': end_time.isoformat(),
            'durationSeconds': duration,
            'targetGameMode': target_mode['modeName'],
            'leaderboardConfig': {
                'leaderboardName': f"event-{event_name}",
                'gameMode': target_mode['modeName'],
                'statAttributeForLeaderboard': 'score',  # Required field for API
                'leaderboardType': 'DESCENDING_LB',  # Most events are score-based
                'scoreStrategy': 'best',
                'scoreType': api_score_type,  # Use mapped API-compatible scoreType
                # NOTE: No expiry time set during generation - will be set at runtime
                # This allows tests to run at any time without expired leaderboards
                'readOnlyOnExpiry': event_type_info['read_only_on_expiry']  # Store for runtime use
            }
        }
        
        events.append(event)
    
    # Sort events by start time
    events.sort(key=lambda x: x['startTime'])
    
    print(f"  ✓ Generated {len(events)} events:")
    for event in events:
        expiry_behavior = "read-only" if event['leaderboardConfig']['readOnlyOnExpiry'] else "auto-delete"
        print(f"    - {event['eventName']}: {event['durationSeconds']//60}min, {expiry_behavior} (expiry set at runtime)")
    print()
    
    return events


def generate_player_pool_definition(genre_key):
    """
    Generate synthetic player pool definition.
    
    Defines the player pool size, ID patterns, skill distribution, progression curves,
    and session patterns that will be used during test execution.
    
    Args:
        genre_key: The genre identifier
    
    Returns:
        dict: Player pool definition
    
    Requirements: 7.2, 7.3, 7.5, 7.10, 7.14, 9.1-9.12
    Tasks: 7.8.1, 7.8.2, 7.8.3
    """
    
    print("Generating player pool definition...")
    
    # Define pool size - fixed at 100,000 for consistent, realistic simulation
    # Large pool ensures good distribution and minimal ID collisions
    pool_size = 100000
    
    # Player ID pattern - 6 digits to accommodate 100K players
    # Format: player_000001, player_000002, ... player_100000
    id_pattern = "player_{:06d}"
    id_prefix = "player"  # Prefix for ID generation
    
    # Skill level distribution (percentages)
    skill_distribution = {
        'beginner': 0.30,      # 30% beginners
        'intermediate': 0.40,  # 40% intermediate
        'advanced': 0.20,      # 20% advanced
        'expert': 0.10         # 10% experts
    }
    
    # Progression curves per skill level
    progression_curves = {
        'beginner': {
            'starting_level': 1,
            'max_level': 20,
            'xp_per_level': 100,
            'level_up_rate': 1.2  # Multiplier per level
        },
        'intermediate': {
            'starting_level': 10,
            'max_level': 50,
            'xp_per_level': 200,
            'level_up_rate': 1.15
        },
        'advanced': {
            'starting_level': 30,
            'max_level': 80,
            'xp_per_level': 300,
            'level_up_rate': 1.1
        },
        'expert': {
            'starting_level': 50,
            'max_level': 100,
            'xp_per_level': 500,
            'level_up_rate': 1.05
        }
    }
    
    # Session patterns (duration ranges in seconds)
    session_patterns = {
        'beginner': {
            'min_session_duration': 300,    # 5 minutes
            'max_session_duration': 1200,   # 20 minutes
            'sessions_per_day': (1, 3),
            'idle_time_range': (3600, 14400)  # 1-4 hours between sessions
        },
        'intermediate': {
            'min_session_duration': 600,    # 10 minutes
            'max_session_duration': 2400,   # 40 minutes
            'sessions_per_day': (2, 5),
            'idle_time_range': (1800, 7200)  # 30min-2hours between sessions
        },
        'advanced': {
            'min_session_duration': 1200,   # 20 minutes
            'max_session_duration': 3600,   # 1 hour
            'sessions_per_day': (3, 8),
            'idle_time_range': (900, 3600)  # 15min-1hour between sessions
        },
        'expert': {
            'min_session_duration': 1800,   # 30 minutes
            'max_session_duration': 7200,   # 2 hours
            'sessions_per_day': (4, 12),
            'idle_time_range': (300, 1800)  # 5min-30min between sessions
        }
    }
    
    # Score modifiers per skill level (multipliers for base scores)
    score_modifiers = {
        'beginner': {'min': 0.5, 'max': 0.8, 'variance': 0.3},
        'intermediate': {'min': 0.7, 'max': 1.0, 'variance': 0.2},
        'advanced': {'min': 0.9, 'max': 1.2, 'variance': 0.15},
        'expert': {'min': 1.1, 'max': 1.5, 'variance': 0.1}
    }
    
    player_pool = {
        'poolSize': pool_size,
        'idPattern': id_pattern,
        'idPrefix': id_prefix,  # Add prefix for easy ID generation
        'skillDistribution': skill_distribution,
        'progressionCurves': progression_curves,
        'sessionPatterns': session_patterns,
        'scoreModifiers': score_modifiers,
        'genre': genre_key
    }
    
    print(f"  ✓ Player pool size: {pool_size:,} players")
    print(f"  ✓ Skill distribution: {skill_distribution}")
    print(f"  ✓ Session patterns defined for all skill levels")
    print()
    
    return player_pool


def generate_game_report_template(genre_key, selected_stats):
    """
    Generate fullRawGameReport template based on selected stats.
    
    Creates a comprehensive game report structure that defines what data
    worker threads will generate and submit during test execution. The template
    includes all selected stats with appropriate data types, ranges, and metadata.
    
    This template will be stored in DynamoDB and used by worker threads to:
    1. Generate realistic synthetic game data
    2. Submit stats via POST /leaderboards/stats (gameReportBody wrapper)
    3. Submit batch stats via POST /leaderboards/stats/batch (batchGameReportBody wrapper)
    
    Args:
        genre_key: The genre identifier (e.g., "racing-circuit")
        selected_stats: List of selected stat names
    
    Returns:
        dict: fullRawGameReport template with field definitions and data generation rules
    
    Requirements: 7.8, 35.8
    
    Design Reference: Section 3.3.3 (Player Stats Submission APIs)
    """
    
    print("Generating fullRawGameReport template...")
    
    print(f"  Genre: {genre_key}")
    print(f"  Stats to include: {len(selected_stats)}")
    print()
    
    # Build the game report template
    game_report_template = {
        # Metadata about the template
        "_template_metadata": {
            "genre": genre_key,
            "version": "1.0",
            "generated_stats_count": len(selected_stats),
            "description": f"Game report template for {genre_key} genre"
        },
        
        # Core fields that are always present in game reports
        "core_fields": {
            "playerID": {
                "type": "string",
                "required": True,
                "description": "Player identifier",
                "generation_rule": "use_claimed_player_id"
            },
            "sessionID": {
                "type": "string",
                "required": True,
                "description": "Unique session identifier",
                "generation_rule": "generate_uuid"
            },
            "timestamp": {
                "type": "number",
                "required": True,
                "description": "Unix timestamp of game completion",
                "generation_rule": "current_timestamp"
            },
            "gameMode": {
                "type": "string",
                "required": True,
                "description": "Game mode identifier",
                "generation_rule": "select_from_game_modes"
            },
            "sessionDuration": {
                "type": "number",
                "required": True,
                "description": "Session duration in seconds",
                "generation_rule": "random_range",
                "min_value": 60,
                "max_value": 3600
            },
            "playerLevel": {
                "type": "number",
                "required": True,
                "description": "Player level at time of game",
                "generation_rule": "use_player_progression_level"
            }
        },
        
        # Dynamic stat fields based on selected stats
        "stat_fields": {}
    }
    
    # Generate field definitions for each selected stat
    print("  Generating field definitions for stats:")
    
    for stat_name in selected_stats:
        # Determine data type and range based on stat name patterns
        field_def = _infer_stat_field_definition(stat_name, genre_key)
        
        game_report_template["stat_fields"][stat_name] = field_def
        
        print(f"    - {stat_name}: {field_def['type']} ({field_def['generation_rule']})")
    
    print()
    print(f"✓ Generated fullRawGameReport template with {len(selected_stats)} stat fields")
    print(f"✓ Template includes core fields + stat fields")
    print(f"✓ Ready for DynamoDB storage and worker thread usage")
    print()
    
    return game_report_template


def _infer_stat_field_definition(stat_name, genre_key):
    """
    Infer field definition for a stat based on its name and genre.
    
    Uses intelligent pattern matching to determine appropriate data types,
    ranges, and generation rules for each stat.
    
    Args:
        stat_name: Name of the stat (e.g., "lap_time", "kills_count")
        genre_key: Genre identifier for context
    
    Returns:
        dict: Field definition with type, range, and generation rules
    """
    stat_lower = stat_name.lower()
    
    # Time-based stats (seconds, milliseconds)
    if any(keyword in stat_lower for keyword in ['time', 'duration', 'latency']):
        if 'lap' in stat_lower or 'best' in stat_lower:
            return {
                "type": "number",
                "format": "float",
                "required": False,
                "description": f"{stat_name} in seconds",
                "generation_rule": "random_range",
                "min_value": 30.0,
                "max_value": 600.0,
                "precision": 3
            }
        else:
            return {
                "type": "number",
                "format": "float",
                "required": False,
                "description": f"{stat_name} in seconds",
                "generation_rule": "random_range",
                "min_value": 1.0,
                "max_value": 3600.0,
                "precision": 2
            }
    
    # Count-based stats (kills, deaths, attempts, etc.)
    elif any(keyword in stat_lower for keyword in ['count', 'kills', 'deaths', 'attempts', 'wins', 'losses', 'defeats']):
        return {
            "type": "number",
            "format": "integer",
            "required": False,
            "description": f"{stat_name} count",
            "generation_rule": "random_range",
            "min_value": 0,
            "max_value": 1000
        }
    
    # Percentage/Rate stats (0-100)
    elif any(keyword in stat_lower for keyword in ['percentage', 'rate', 'accuracy', 'efficiency']):
        return {
            "type": "number",
            "format": "float",
            "required": False,
            "description": f"{stat_name} percentage",
            "generation_rule": "random_range",
            "min_value": 0.0,
            "max_value": 100.0,
            "precision": 2
        }
    
    # Score/Points stats (large positive numbers)
    elif any(keyword in stat_lower for keyword in ['score', 'points', 'damage', 'healing', 'gold', 'currency', 'experience']):
        return {
            "type": "number",
            "format": "integer",
            "required": False,
            "description": f"{stat_name} value",
            "generation_rule": "random_range",
            "min_value": 0,
            "max_value": 1000000
        }
    
    # Speed stats (mph, kph, m/s)
    elif any(keyword in stat_lower for keyword in ['speed', 'velocity']):
        return {
            "type": "number",
            "format": "float",
            "required": False,
            "description": f"{stat_name} value",
            "generation_rule": "random_range",
            "min_value": 0.0,
            "max_value": 500.0,
            "precision": 2
        }
    
    # Distance stats (meters, kilometers, miles)
    elif any(keyword in stat_lower for keyword in ['distance', 'range']):
        return {
            "type": "number",
            "format": "float",
            "required": False,
            "description": f"{stat_name} in meters",
            "generation_rule": "random_range",
            "min_value": 0.0,
            "max_value": 100000.0,
            "precision": 2
        }
    
    # Level/Rank stats (1-100)
    elif any(keyword in stat_lower for keyword in ['level', 'rank', 'tier']):
        return {
            "type": "number",
            "format": "integer",
            "required": False,
            "description": f"{stat_name} value",
            "generation_rule": "random_range",
            "min_value": 1,
            "max_value": 100
        }
    
    # Streak/Combo stats (0-50)
    elif any(keyword in stat_lower for keyword in ['streak', 'combo', 'chain']):
        return {
            "type": "number",
            "format": "integer",
            "required": False,
            "description": f"{stat_name} count",
            "generation_rule": "random_range",
            "min_value": 0,
            "max_value": 50
        }
    
    # Boolean/Flag stats (perfect, flawless, etc.)
    elif any(keyword in stat_lower for keyword in ['perfect', 'flawless', 'clean']):
        return {
            "type": "boolean",
            "required": False,
            "description": f"{stat_name} flag",
            "generation_rule": "random_boolean",
            "probability": 0.1  # 10% chance of true
        }
    
    # Default: generic numeric stat
    else:
        return {
            "type": "number",
            "format": "integer",
            "required": False,
            "description": f"{stat_name} value",
            "generation_rule": "random_range",
            "min_value": 0,
            "max_value": 10000
        }


def generate_test_config_id():
    """
    Generate a unique Test Config ID.
    
    Format: test-YYYYMMDD-HHMMSS-{random}
    Example: test-20250108-143022-a7f3
    
    Returns:
        str: Unique Test Config ID
    
    Requirements: 6.2, 6.3
    """
    
    # Get current timestamp
    now = datetime.now()
    
    # Format: YYYYMMDD-HHMMSS
    timestamp_str = now.strftime("%Y%m%d-%H%M%S")
    
    # Generate random suffix (4 characters)
    random_suffix = ''.join(random.choices(string.ascii_lowercase + string.digits, k=4))
    
    # Combine into Test Config ID
    test_config_id = f"test-{timestamp_str}-{random_suffix}"
    
    return test_config_id


def create_metadata_record(test_config_id, test_name, genre_key):
    """
    Create METADATA record for test configuration.
    
    The METADATA record stores high-level information about the test configuration
    including the human-readable name, genre, status, timestamps, and infrastructure flags.
    
    NOTE: max_players and duration are NOT stored here - they are process-specific
    runtime parameters passed via command-line to each test instance.
    
    This record will be stored in the Test Definitions Table with:
    - PK = TestConfigID
    - SK = 'METADATA'
    
    Args:
        test_config_id: Unique Test Config ID
        test_name: Human-readable test name
        genre_key: Selected genre identifier
    
    Returns:
        dict: METADATA record ready for DynamoDB storage
    
    Requirements: 35.10, 12.1-12.13 (Distributed Testing Coordination)
    
    Design Reference: Section 38 (Test Configuration Management)
    """
    
    print("Creating METADATA record...")
    
    # Get current timestamp
    created_time = int(time.time())
    
    # Build METADATA record
    metadata_record = {
        # DynamoDB keys
        "TestConfigID": test_config_id,
        "ConfigCategory": "METADATA",
        
        # Test identification
        "TestName": test_name,
        "Genre": genre_key,
        
        # Status tracking
        "Status": "AVAILABLE",  # AVAILABLE | RUNNING
        "CreatedTime": created_time,
        "LastRunTime": None,  # Will be set when test runs
        
        # Infrastructure tracking
        "GameBackendSetupCreated": False,  # Will be set to True when setup is created
        
        # Versioning
        "Version": 1
    }
    
    print(f"  ✓ Test Config ID: {test_config_id}")
    print(f"  ✓ Test Name: {test_name}")
    print(f"  ✓ Genre: {genre_key}")
    print(f"  ✓ Status: AVAILABLE")
    print(f"  ✓ Created Time: {created_time}")
    print(f"  ✓ Game Backend Setup Created: False")
    print()
    
    return metadata_record


