def generate_studio_and_game_identifiers(genre_key):
    """
    Generate unique studio name and game title based on genre.
    
    Creates genre-appropriate names that will be used for developer registration.
    
    Args:
        genre_key: The genre identifier
    
    Returns:
        tuple: (studio_name, game_title, contact_email)
    
    Requirements: 6.7
    Tasks: 7.9.1
    """
    
    print("Generating studio and game identifiers...")
    
    # Genre-specific studio name templates
    studio_templates = {
        'racing-circuit': ['Speed', 'Racing', 'Velocity', 'Turbo', 'Circuit', 'Track', 'Drift'],
        'fps-tactical': ['Tactical', 'Combat', 'Strike', 'Warfare', 'Elite', 'Special', 'Ops'],
        'moba-arena': ['Arena', 'Battle', 'Champions', 'Legends', 'Heroes', 'Nexus', 'Rift'],
        'rpg-action': ['Quest', 'Adventure', 'Fantasy', 'Epic', 'Realm', 'Saga', 'Chronicles'],
        'sports-soccer': ['Sports', 'Soccer', 'Football', 'League', 'Championship', 'United', 'FC'],
        'battle-royale': ['Battle', 'Survival', 'Royale', 'Last', 'Victory', 'Apex', 'Zone']
    }
    
    # Genre-specific game title templates
    game_templates = {
        'racing-circuit': ['Racing', 'Circuit', 'Championship', 'Grand Prix', 'Speed', 'Turbo', 'Ultimate'],
        'fps-tactical': ['Strike', 'Warfare', 'Combat', 'Ops', 'Tactical', 'Elite', 'Special'],
        'moba-arena': ['Arena', 'Legends', 'Champions', 'Battle', 'Heroes', 'Nexus', 'Rift'],
        'rpg-action': ['Quest', 'Adventure', 'Chronicles', 'Saga', 'Realm', 'Fantasy', 'Epic'],
        'sports-soccer': ['Soccer', 'Football', 'League', 'Championship', 'Manager', 'Ultimate', 'Pro'],
        'battle-royale': ['Royale', 'Survival', 'Battle', 'Last Stand', 'Victory', 'Arena', 'Zone']
    }
    
    # Get templates for genre or use generic
    studio_words = studio_templates.get(genre_key, ['Game', 'Studio', 'Interactive', 'Digital', 'Creative'])
    game_words = game_templates.get(genre_key, ['Game', 'Challenge', 'Experience', 'Adventure', 'Quest'])
    
    # Generate studio name
    studio_word1 = random.choice(studio_words)
    studio_word2 = random.choice(['Studios', 'Games', 'Interactive', 'Entertainment', 'Digital'])
    studio_name = f"{studio_word1} {studio_word2}"
    
    # Generate game title
    game_word1 = random.choice(game_words)
    game_word2 = random.choice(['Champions', 'Masters', 'Legends', 'Ultimate', 'Pro', 'Elite', '2024'])
    game_title = f"{game_word1} {game_word2}"
    
