def create_test_metrics_table(region=DEFAULT_AWS_REGION, profile=None):
    """
    Create Test Metrics Table for storing instance metrics and aggregates.
    
    Table Schema:
    - PK: TestConfigID (String) - Test configuration ID
    - SK: MetricTimestamp (Number) - Epoch timestamp in seconds
    - Attributes: InstanceID, MetricType, metrics data, TTL
    - TTL: Enabled on TTL attribute (7 days default)
    
    Args:
        region: AWS region (default: us-west-2)
        profile: AWS profile name (optional)
    
    Returns:
        bool: True if table created or already exists, False on error
    
    Requirements: Phase 3 - Enhanced Metrics Collection
    """
    
    table_name = TEST_METRICS_TABLE_NAME
    
    print(f"Creating Test Metrics Table: {table_name}")
    
    # Check if table already exists
    status = check_table_exists(table_name, region, profile)
    
    if status == 'ACTIVE':
        print(f"  ✓ Table already exists and is ACTIVE")
        
        # Verify TTL is enabled
        try:
            session_kwargs = {'region_name': region}
            if profile:
                session_kwargs['profile_name'] = profile
            session = boto3.Session(**session_kwargs)
            dynamodb = session.client('dynamodb')
            
            ttl_response = dynamodb.describe_time_to_live(TableName=table_name)
            ttl_status = ttl_response.get('TimeToLiveDescription', {}).get('TimeToLiveStatus', 'DISABLED')
            
            if ttl_status == 'ENABLED':
                print(f"  ✓ TTL is enabled on TTL attribute")
            else:
                print(f"  ⚠ TTL is not enabled, enabling now...")
                dynamodb.update_time_to_live(
                    TableName=table_name,
                    TimeToLiveSpecification={
                        'Enabled': True,
                        'AttributeName': 'TTL'
                    }
                )
                print(f"  ✓ TTL enabled successfully")
        except Exception as e:
            print(f"  ⚠ Could not verify/enable TTL: {e}")
        
        return True
    elif status in ['CREATING', 'UPDATING']:
        print(f"  ⚠ Table is currently {status}, waiting for ACTIVE status...")
        return wait_for_table_active(table_name, region, profile)
    
    # Create table
    try:
        session_kwargs = {'region_name': region}
        if profile:
            session_kwargs['profile_name'] = profile
        session = boto3.Session(**session_kwargs)
        dynamodb = session.client('dynamodb')
        
        print(f"  Creating table with on-demand billing mode...")
        
        response = dynamodb.create_table(
            TableName=table_name,
            KeySchema=[
                {'AttributeName': 'TestConfigID', 'KeyType': 'HASH'},      # Partition key
                {'AttributeName': 'MetricTimestamp', 'KeyType': 'RANGE'}   # Sort key
            ],
            AttributeDefinitions=[
                {'AttributeName': 'TestConfigID', 'AttributeType': 'S'},
                {'AttributeName': 'MetricTimestamp', 'AttributeType': 'N'}
            ],
            BillingMode='PAY_PER_REQUEST',  # On-demand billing
            Tags=[
                {'Key': 'Purpose', 'Value': 'LoadTesting'},
                {'Key': 'System', 'Value': 'StatsAndLeaderboards'},
                {'Key': 'DataType', 'Value': 'Metrics'}
            ]
        )
        
        print(f"  ✓ Table creation initiated")
        print(f"  Waiting for table to become ACTIVE...")
        
        # Wait for table to become active
        if not wait_for_table_active(table_name, region, profile):
            return False
        
        # Enable TTL on the TTL attribute (7 days)
        print(f"  Enabling TTL on TTL attribute...")
        try:
            dynamodb.update_time_to_live(
                TableName=table_name,
                TimeToLiveSpecification={
                    'Enabled': True,
                    'AttributeName': 'TTL'
                }
            )
            print(f"  ✓ TTL enabled successfully (7 day default)")
        except ClientError as e:
            print(f"  ⚠ Warning: Could not enable TTL: {e}")
        
        print(f"  ✓ Test Metrics Table created successfully")
        return True
        
    except ClientError as e:
        if e.response['Error']['Code'] == 'AccessDeniedException':
            print(f"❌ ERROR: Access denied when creating table '{table_name}'")
            print("Required IAM permissions: dynamodb:CreateTable, dynamodb:UpdateTimeToLive")
        else:
            print(f"❌ ERROR: Failed to create table: {e}")
        return False
    except Exception as e:
        print(f"❌ ERROR: Unexpected error creating table: {e}")
        return False


