# SECTION 7A: GLOBAL TEST LOCK OPERATIONS
# ============================================================================

def cleanup_stale_instance_records(test_config_id, aws_session, region):
    """
    Clean up stale instance records from previous test runs.
    
    This ensures instance IDs start fresh from 1 for each new test run.
    Only called by PRIMARY instance when acquiring global lock.
    
    Deletes all INSTANCE#* records for this TestConfigID.
    
    Args:
        test_config_id: Test Config ID
        aws_session: boto3 Session object
        region: AWS region
    
    Returns:
        int: Number of records deleted
    """
    try:
        dynamodb = aws_session.resource('dynamodb', region_name=region)
        table = dynamodb.Table(TEST_DEFINITIONS_TABLE_NAME)
        
        # Query for all INSTANCE records for this test
        from boto3.dynamodb.conditions import Key
        
        response = table.query(
            KeyConditionExpression=Key('TestConfigID').eq(test_config_id) & Key('ConfigCategory').begins_with('INSTANCE#')
        )
        
        instance_records = response.get('Items', [])
        
        # Handle pagination if there are many records
        while 'LastEvaluatedKey' in response:
            response = table.query(
                KeyConditionExpression=Key('TestConfigID').eq(test_config_id) & Key('ConfigCategory').begins_with('INSTANCE#'),
                ExclusiveStartKey=response['LastEvaluatedKey']
            )
            instance_records.extend(response.get('Items', []))
        
        if not instance_records:
            print(f"  ✓ No stale instance records found")
            return 0
        
        # Delete all instance records
        deleted_count = 0
        with table.batch_writer() as batch:
            for record in instance_records:
                batch.delete_item(
                    Key={
                        'TestConfigID': record['TestConfigID'],
                        'ConfigCategory': record['ConfigCategory']
                    }
                )
                deleted_count += 1
        
        # Reset the atomic instance counter to 0 so IDs start from 1
        try:
            table.delete_item(
                Key={
                    'TestConfigID': test_config_id,
                    'ConfigCategory': 'INSTANCE_COUNTER'
                }
            )
        except Exception:
            pass  # OK if it doesn't exist
        
        print(f"  ✓ Cleaned up {deleted_count} stale instance record(s) and reset counter")
        return deleted_count
        
    except Exception as e:
        print(f"  ⚠ Warning: Failed to cleanup stale instance records: {e}")
        print(f"     Continuing anyway - instance allocation will still work")
        return 0


def acquire_global_test_lock(test_config_id, test_name, instance_id, region=DEFAULT_AWS_REGION, profile=None):
    """
    Acquire the global test lock to ensure only one test configuration runs at a time.
    
    IMPORTANT: Multiple instances of the SAME test config ID are allowed (horizontal scaling).
    Only prevents DIFFERENT test configs from running simultaneously.
    
    Creates a GLOBAL_TEST_LOCK record in the Test Definitions Table with:
    - LockKey='GLOBAL_TEST_LOCK'
    - ActiveTestConfigID, ActiveTestName, Status='RUNNING'
    - StartTime, LastHeartbeat, InstanceCount
    - TTL set to LastHeartbeat + 4 hours
    
    Uses conditional write to prevent race conditions.
    
    ALSO: Cleans up stale instance records from previous test runs (PRIMARY only).
    
    Args:
        test_config_id: Test Config ID to lock
        test_name: Human-readable test name
        instance_id: Current instance identifier
        region: AWS region (default: us-west-2)
        profile: AWS profile name (optional)
    
    Returns:
        tuple: (success: bool, is_owner: bool)
            - success: True if lock acquired/joined, False if another test is running
            - is_owner: True if this instance created the lock (first instance), False if joined existing
    
    Requirements: 35.13, 35.14
    """
    
    try:
        # Create boto3 session
        session_kwargs = {'region_name': region}
        if profile:
            session_kwargs['profile_name'] = profile
        session = boto3.Session(**session_kwargs)
        dynamodb = session.resource('dynamodb')
        table = dynamodb.Table(TEST_DEFINITIONS_TABLE_NAME)
        
        current_time = int(time.time())
        ttl = current_time + LOCK_TTL_DURATION
        
        # First, check if a lock already exists
        try:
            response = table.get_item(
                Key={
                    'TestConfigID': 'GLOBAL',
                    'ConfigCategory': 'TEST_LOCK'
                }
            )
            
            if 'Item' in response:
                lock = response['Item']
                existing_test_id = lock.get('ActiveTestConfigID')
                
                # If it's the SAME test config ID, allow it (horizontal scaling)
                if existing_test_id == test_config_id:
                    # Update instance count and add this instance
                    instance_count = lock.get('InstanceCount', 0) + 1
                    instance_ids = lock.get('InstanceIDs', [])
                    if instance_id not in instance_ids:
                        instance_ids.append(instance_id)
                    
                    table.update_item(
                        Key={
                            'TestConfigID': 'GLOBAL',
                            'ConfigCategory': 'TEST_LOCK'
                        },
                        UpdateExpression='SET InstanceCount = :count, InstanceIDs = :ids, LastHeartbeat = :time, #ttl = :ttl',
                        ExpressionAttributeNames={
                            '#ttl': 'TTL'
                        },
                        ExpressionAttributeValues={
                            ':count': instance_count,
                            ':ids': instance_ids,
                            ':time': current_time,
                            ':ttl': ttl
                        }
                    )
                    
                    print(f"✓ Joined existing test: {test_name} ({test_config_id})")
                    print(f"  Instance count: {instance_count}")
                    print(f"  Role: Worker-only instance (lock owned by first instance)")
                    return (True, False)  # Success, but not owner
                else:
                    # Different test config ID - not allowed
                    print()
                    print("❌ ERROR: Another test is already running")
                    print()
                    print(f"  Running Test: {lock.get('ActiveTestName', 'Unknown')}")
                    print(f"  Test Config ID: {existing_test_id}")
                    print(f"  Started: {time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(lock.get('StartTime', 0)))}")
                    print(f"  Instance Count: {lock.get('InstanceCount', 0)}")
                    print()
                    print(f"  Your Test: {test_name}")
                    print(f"  Your Test Config ID: {test_config_id}")
                    print()
                    print("Wait for the current test to complete, or use --force-unlock if the test has crashed.")
                    print()
                    return (False, False)  # Failed to acquire
        
        except ClientError as e:
            if e.response['Error']['Code'] != 'ResourceNotFoundException':
                raise
            # Lock doesn't exist, continue to create it
        
        # No lock exists, create it (PRIMARY instance)
        try:
            table.put_item(
                Item={
                    'TestConfigID': 'GLOBAL',
                    'ConfigCategory': 'TEST_LOCK',
                    'LockKey': 'GLOBAL_TEST_LOCK',
                    'ActiveTestConfigID': test_config_id,
                    'ActiveTestName': test_name,
                    'Status': 'RUNNING',
                    'StartTime': current_time,
                    'LastHeartbeat': current_time,
                    'InstanceCount': 1,
                    'InstanceIDs': [instance_id],
                    'TTL': ttl
                },
                ConditionExpression='attribute_not_exists(LockKey)'
            )
            
            # CRITICAL: Update METADATA status to RUNNING immediately after lock creation
            # This prevents race condition where workers join and see AVAILABLE status
            try:
                table.update_item(
                    Key={
                        'TestConfigID': test_config_id,
                        'ConfigCategory': 'METADATA'
                    },
                    UpdateExpression='SET #status = :status, LastModified = :time',
                    ExpressionAttributeNames={
                        '#status': 'Status'
                    },
                    ExpressionAttributeValues={
                        ':status': 'RUNNING',
                        ':time': current_time
                    }
                )
            except Exception as metadata_error:
                # Log warning but don't fail - status will be updated later in main()
                print(f"  ⚠ Warning: Failed to update METADATA status: {metadata_error}")
                print(f"     Status will be updated in main execution flow")
            
            print(f"✓ Global test lock acquired for: {test_name} ({test_config_id})")
            print(f"  Role: Primary instance (owns lock)")
            return (True, True)  # Success and owner
            
        except ClientError as e:
            if e.response['Error']['Code'] == 'ConditionalCheckFailedException':
                # Race condition - lock was created between our check and put
                # Retry the whole function
                print("  Lock race condition detected, retrying...")
                time.sleep(0.5)
                return acquire_global_test_lock(test_config_id, test_name, instance_id, region, profile)
            else:
                raise
    
    except ClientError as e:
        error_code = e.response.get('Error', {}).get('Code', 'Unknown')
        
        if error_code == 'AccessDeniedException':
            print()
            print(f"❌ ERROR: Access denied when acquiring global test lock")
            print()
            print("Required IAM permissions:")
            print("  - dynamodb:PutItem")
            print("  - dynamodb:GetItem")
            print("  - dynamodb:UpdateItem")
            print()
            print(f"Resource ARN: arn:aws:dynamodb:{region}:*:table/{TEST_DEFINITIONS_TABLE_NAME}")
            print()
            return False
        else:
            raise
    
    except Exception as e:
        print(f"❌ Unexpected error acquiring global test lock: {e}")
        traceback.print_exc()
        return False


def update_lock_heartbeat(test_config_id, instance_id, aws_session=None, region=DEFAULT_AWS_REGION, profile=None):
    """
    Update the global test lock heartbeat to indicate the test is still running.
    
    Should be called every 60 seconds from a background thread.
    Updates LastHeartbeat and refreshes TTL to current time + 4 hours.
    
    Args:
        test_config_id: Test Config ID
        instance_id: Current instance identifier
        aws_session: boto3 Session object (optional, will create new if not provided)
        region: AWS region (default: us-west-2)
        profile: AWS profile name (optional)
    
    Returns:
        tuple: (success: bool, instance_count: int)
               success: True if heartbeat updated successfully
               instance_count: Total number of instances (0 if failed)
    
    Requirements: 35.15
    """
    
    try:
        # Reuse existing session if provided, otherwise create new one
        if aws_session:
            dynamodb = aws_session.resource('dynamodb')
        else:
            session_kwargs = {'region_name': region}
            if profile:
                session_kwargs['profile_name'] = profile
            session = boto3.Session(**session_kwargs)
            dynamodb = session.resource('dynamodb')
        
        table = dynamodb.Table(TEST_DEFINITIONS_TABLE_NAME)
        
        current_time = int(time.time())
        ttl = current_time + LOCK_TTL_DURATION
        
        # Update heartbeat and get current instance count
        response = table.update_item(
            Key={
                'TestConfigID': 'GLOBAL',
                'ConfigCategory': 'TEST_LOCK'
            },
            UpdateExpression='SET LastHeartbeat = :heartbeat, #ttl = :ttl',
            ExpressionAttributeNames={
                '#ttl': 'TTL'
            },
            ExpressionAttributeValues={
                ':heartbeat': current_time,
                ':ttl': ttl
            },
            ReturnValues='ALL_NEW'
        )
        
        # Extract instance count from response
        instance_count = response.get('Attributes', {}).get('InstanceCount', 1)
        
        return (True, instance_count)
        
    except ClientError as e:
        error_code = e.response.get('Error', {}).get('Code', 'Unknown')
        
        if error_code == 'AccessDeniedException':
            print(f"⚠ WARNING: Access denied when updating lock heartbeat")
            return (False, 0)
        else:
            print(f"⚠ WARNING: Failed to update lock heartbeat: {e}")
            return (False, 0)
    
    except Exception as e:
        print(f"⚠ WARNING: Unexpected error updating lock heartbeat: {e}")
        return (False, 0)


def release_global_test_lock(test_config_id, region=DEFAULT_AWS_REGION, profile=None):
    """
    Release the global test lock when test completes.
    
    Deletes the GLOBAL_TEST_LOCK record and updates the test configuration
    Status to AVAILABLE with LastRunTime timestamp.
    
    Args:
        test_config_id: Test Config ID
        region: AWS region (default: DEFAULT_AWS_REGION)
        profile: AWS profile name (optional)
    
    Returns:
        bool: True if lock released successfully, False otherwise
    
    Requirements: 35.16, 35.17
    """
    
    try:
        # Create boto3 session
        session_kwargs = {'region_name': region}
        if profile:
            session_kwargs['profile_name'] = profile
        session = boto3.Session(**session_kwargs)
        dynamodb = session.resource('dynamodb')
        table = dynamodb.Table(TEST_DEFINITIONS_TABLE_NAME)
        
        current_time = int(time.time())
        
        # Delete the lock record
        table.delete_item(
            Key={
                'TestConfigID': 'GLOBAL',
                'ConfigCategory': 'TEST_LOCK'
            }
        )
        
        # Update test configuration status to AVAILABLE
        table.update_item(
            Key={
                'TestConfigID': test_config_id,
                'ConfigCategory': 'METADATA'
            },
            UpdateExpression='SET #status = :status, LastRunTime = :time',
            ExpressionAttributeNames={
                '#status': 'Status'
            },
            ExpressionAttributeValues={
                ':status': 'AVAILABLE',
                ':time': current_time
            }
        )
        
        print(f"✓ Global test lock released for: {test_config_id}")
        return True
        
    except ClientError as e:
        error_code = e.response.get('Error', {}).get('Code', 'Unknown')
        
        if error_code == 'AccessDeniedException':
            print()
            print(f"❌ ERROR: Access denied when releasing global test lock")
            print()
            print("Required IAM permissions:")
            print("  - dynamodb:DeleteItem")
            print("  - dynamodb:UpdateItem")
            print()
            print(f"Resource ARN: arn:aws:dynamodb:{region}:*:table/{TEST_DEFINITIONS_TABLE_NAME}")
            print()
            return False
        else:
            raise
    
    except Exception as e:
        print(f"❌ Unexpected error releasing global test lock: {e}")
        traceback.print_exc()
        return False


def create_game_backend_setup(test_config_id, region, aws_profile=None, logger=None, api_logger=None):
    """
    Create game backend setup for a test configuration.
    
    This function creates all necessary game backend setup including:
    1. Developer/studio registration
    2. All permanent leaderboards
    3. All event leaderboards (if applicable)
    
    The function checks if setup has already been created and skips
    creation if the GameBackendSetupCreated flag is True.
    
    Args:
        test_config_id: Test configuration ID
        region: AWS region
        aws_profile: AWS profile name (optional)
        logger: ThreadSafeLogger instance (optional)
        api_logger: WorkerLogger instance (optional)
    
    Returns:
        bool: True if setup created successfully, False otherwise
    
    Requirements: 35.26, 35.27, 35.28, 35.29
    Design: Section 38
    """
    
    print("=" * 80)
    print("Game Backend Setup Creation")
    print("=" * 80)
    print()
    
    try:
        # Create AWS session
        session_kwargs = {}
        if aws_profile:
            session_kwargs['profile_name'] = aws_profile
        if region:
            session_kwargs['region_name'] = region
        
        session = boto3.Session(**session_kwargs)
        dynamodb = session.resource('dynamodb')
        ssm = session.client('ssm')
        table = dynamodb.Table(TEST_DEFINITIONS_TABLE_NAME)
        
        # Load METADATA record to check if setup already created
        print("Checking if game backend setup already exists...")
        metadata_response = table.get_item(
            Key={
                'TestConfigID': test_config_id,
                'ConfigCategory': 'METADATA'
            }
        )
        
        if 'Item' not in metadata_response:
            print(f"❌ ERROR: Test configuration not found: {test_config_id}")
            return False
        
        metadata = metadata_response['Item']
        
        # Check if setup already created (check both top-level and ConfigData for backward compatibility)
        setup_created = metadata.get('GameBackendSetupCreated', False)
        if not setup_created and 'ConfigData' in metadata:
            setup_created = metadata['ConfigData'].get('GameBackendSetupCreated', False)
        
        if setup_created:
            print(f"✓ Game backend setup already exists for: {metadata.get('TestName', test_config_id)}")
            print()
            return True
        
        print(f"Creating game backend setup for: {metadata.get('TestName', test_config_id)}")
        print()
        
        # Load leaderboard configurations
        print("Loading leaderboard configurations from DynamoDB...")
        lb_response = table.get_item(
            Key={
                'TestConfigID': test_config_id,
                'ConfigCategory': 'LEADERBOARD_CONFIG'
            }
        )
        
        if 'Item' not in lb_response or 'ConfigData' not in lb_response['Item']:
            print("❌ ERROR: Leaderboard configurations not found")
            return False
        
        leaderboard_configs = lb_response['Item']['ConfigData']
        print(f"✓ Loaded {len(leaderboard_configs)} leaderboard configurations")
        print()
        
        # Get studio and game metadata from METADATA record
        # These values come from SSM Parameter Store (loaded during generation)
        config_data = metadata.get('ConfigData', {})
        studio_name = config_data.get('StudioName')
        game_title = config_data.get('GameTitle')
        contact_email = config_data.get('ContactEmail')
        genre = config_data.get('GameGenre') or config_data.get('Genre', 'generic')
        # Strip trailing slash from API base URL to avoid double slashes in endpoint URLs
        api_base_url_raw = config_data.get('ApiBaseUrl', '')
        api_base_url = api_base_url_raw.rstrip('/') if api_base_url_raw else ''
        api_key = config_data.get('ApiKey')
        studio_id = config_data.get('StudioId')
        game_id = config_data.get('GameId')
        
        # Validate all required metadata is present
        if not all([studio_name, game_title, contact_email, genre, api_base_url, api_key, studio_id, game_id]):
            print("❌ ERROR: METADATA record is missing required studio information")
            print()
            print("Missing fields:")
            if not studio_name: print("  - StudioName")
            if not game_title: print("  - GameTitle")
            if not contact_email: print("  - ContactEmail")
            if not genre: print("  - GameGenre")
            if not api_base_url: print("  - ApiBaseUrl")
            if not api_key: print("  - ApiKey")
            if not studio_id: print("  - StudioId")
            if not game_id: print("  - GameId")
            print()
            print("The test configuration must be regenerated with proper SSM metadata.")
            print("Please run generation mode again to retrieve metadata from SSM Parameter Store.")
            return False
        
        print("Studio Metadata (from SSM Parameter Store):")
        print(f"  Studio ID: {studio_id}")
        print(f"  Game ID: {game_id}")
        print(f"  Studio Name: {studio_name}")
        print(f"  Game Title: {game_title}")
        print(f"  Contact Email: {contact_email}")
        print(f"  Genre: {genre}")
        print(f"  API Key: {'*' * 20}")
        print()
        
        # Since we already have valid SSM metadata with API key,
        # we don't need to call /developer/register
        # The registration already exists in SSM Parameter Store
        print("✓ Developer registration already exists (loaded from SSM)")
        print("  Skipping /developer/register API call")
        print()
        
        # Create permanent leaderboards
        print("Step 1: Create permanent leaderboards")
        print()
        
        lb_configs = leaderboard_configs.get('leaderboards', [])
        if not lb_configs:
            print("⚠ No leaderboards to create")
        else:
            creation_results = create_permanent_leaderboards(
                api_base_url,
                api_key,  # Use API key from SSM
                lb_configs,
                game_id,  # Use game_id from SSM
                logger=logger,
                api_logger=api_logger
            )
            
            if creation_results['failed'] > 0:
                print(f"⚠ Some leaderboards failed to create ({creation_results['failed']}/{creation_results['total']})")
                print("  Continuing anyway...")
            
            # Update LEADERBOARD_CONFIG with actual names used (in case of retries with modified names)
            if creation_results['created'] > 0:
                print("Updating leaderboard configurations with actual names used...")
                
                # Create a mapping of original names to actual names
                name_mapping = {}
                for created_lb in creation_results['created_leaderboards']:
                    if created_lb.get('originalName') != created_lb.get('leaderboardName'):
                        name_mapping[created_lb['originalName']] = created_lb['leaderboardName']
                
                if name_mapping:
                    # Update the leaderboard configs with actual names
                    for lb_config in lb_configs:
                        original_name = lb_config.get('leaderboardName')
                        if original_name in name_mapping:
                            lb_config['leaderboardName'] = name_mapping[original_name]
                            lb_config['_originalName'] = original_name
                    
                    # Store updated configs back to DynamoDB
                    table.put_item(
                        Item={
                            'TestConfigID': test_config_id,
                            'ConfigCategory': 'LEADERBOARD_CONFIG',
                            'TestName': metadata.get('TestName', 'Unknown'),  # Add for consistency
                            'Version': 1,
                            'LastModified': int(time.time()),
                            'ConfigData': {
                                'leaderboards': lb_configs
                            }
                        }
                    )
                    print(f"✓ Updated {len(name_mapping)} leaderboard name(s) in configuration")
                    for orig, actual in name_mapping.items():
                        print(f"  • {orig} → {actual}")
                    print()
            
            # Store leaderboard creation metadata
            print("Storing leaderboard creation metadata...")
            table.put_item(
                Item={
                    'TestConfigID': test_config_id,
                    'ConfigCategory': 'LEADERBOARD_CREATION',
                    'TestName': metadata.get('TestName', 'Unknown'),  # Add for consistency
                    'Version': 1,
                    'LastModified': int(time.time()),
                    'Status': 'ACTIVE',
                    'ConfigData': creation_results
                }
            )
            print("✓ Leaderboard creation metadata stored")
            print()
        
        # Mark setup as created
        table.update_item(
            Key={
                'TestConfigID': test_config_id,
                'ConfigCategory': 'METADATA'
            },
            UpdateExpression='SET GameBackendSetupCreated = :val, LastModified = :timestamp',
            ExpressionAttributeValues={
                ':val': True,
                ':timestamp': int(time.time())
            }
        )
        
        print("✅ Game backend setup completed successfully")
        print()
        return True
        
    except ClientError as e:
        error_code = e.response.get('Error', {}).get('Code', 'Unknown')
        
        if error_code == 'AccessDeniedException':
            print()
            print(f"❌ ERROR: Access denied when creating game backend setup")
            print()
            print("Required IAM permissions:")
            print("  - dynamodb:GetItem")
            print("  - dynamodb:UpdateItem")
            print("  - ssm:GetParameter")
            print()
            print(f"Resource ARNs:")
            print(f"  - arn:aws:dynamodb:{region}:*:table/{TEST_DEFINITIONS_TABLE_NAME}")
            print(f"  - arn:aws:ssm:{region}:*:parameter/game-leaderboards/*")
            print()
            return False
        else:
            raise
    
    except Exception as e:
        print(f"❌ Unexpected error creating game backend setup: {e}")
        traceback.print_exc()
        return False


