    def _summarize_resource_metrics(self, resource_metrics_history):
        """
        Summarize resource utilization metrics.
        
        Returns:
            dict: Summary of resource metrics
        """
        if not resource_metrics_history:
            return {}
        
        cpu_values = [m['cpu_percent'] for m in resource_metrics_history]
        memory_values = [m['memory_percent'] for m in resource_metrics_history]
        thread_values = [m['active_threads'] for m in resource_metrics_history]
        
        return {
            'cpu': {
                'avg': sum(cpu_values) / len(cpu_values),
                'max': max(cpu_values),
                'min': min(cpu_values)
            },
            'memory': {
                'avg': sum(memory_values) / len(memory_values),
                'max': max(memory_values),
                'min': min(memory_values)
            },
            'threads': {
                'avg': sum(thread_values) / len(thread_values),
                'max': max(thread_values),
                'min': min(thread_values)
            }
        }

    def _fetch_aws_pricing(self, aws_session, region):
        """
        Fetch current AWS pricing for cost estimation using the Pricing API.
        Falls back to known us-west-2 defaults if the API is unavailable.
        
        Sources: aws.amazon.com/lambda/pricing, aws.amazon.com/api-gateway/pricing,
        aws.amazon.com/dynamodb/pricing/on-demand, aws.amazon.com/memorydb/pricing
        """
        # Defaults for us-west-2 (fallback)
        prices = {
            'lambda_request': 0.20 / 1_000_000,
            'lambda_gb_sec': 0.0000166667,
            'apigw_request': 3.50 / 1_000_000,
            'ddb_wru': 1.25 / 1_000_000,
            'ddb_rru': 0.25 / 1_000_000,
            'memorydb_per_node_hr': 0.259,
            'source': 'defaults (us-west-2)'
        }
        
        try:
            # Pricing API is only available in us-east-1 and ap-south-1
            pricing_client = aws_session.client('pricing', region_name='us-east-1')
            
            # Lambda request price
            try:
                resp = pricing_client.get_products(
                    ServiceCode='AWSLambda',
                    Filters=[
                        {'Type': 'TERM_MATCH', 'Field': 'regionCode', 'Value': region},
                        {'Type': 'TERM_MATCH', 'Field': 'group', 'Value': 'AWS-Lambda-Requests'}
                    ],
                    MaxResults=1
                )
                if resp.get('PriceList'):
                    price_data = json.loads(resp['PriceList'][0]) if isinstance(resp['PriceList'][0], str) else resp['PriceList'][0]
                    for term in price_data.get('terms', {}).get('OnDemand', {}).values():
                        for dim in term.get('priceDimensions', {}).values():
                            prices['lambda_request'] = float(dim['pricePerUnit']['USD'])
            except Exception as e:
                self.logger.debug(f"Could not fetch Lambda request pricing: {e}")
            
            # Lambda duration price (Tier 1)
            try:
                resp = pricing_client.get_products(
                    ServiceCode='AWSLambda',
                    Filters=[
                        {'Type': 'TERM_MATCH', 'Field': 'regionCode', 'Value': region},
                        {'Type': 'TERM_MATCH', 'Field': 'group', 'Value': 'AWS-Lambda-Duration'}
                    ],
                    MaxResults=5
                )
                if resp.get('PriceList'):
                    for item in resp['PriceList']:
                        price_data = json.loads(item) if isinstance(item, str) else item
                        desc = ''
                        for term in price_data.get('terms', {}).get('OnDemand', {}).values():
                            for dim in term.get('priceDimensions', {}).values():
                                desc = dim.get('description', '')
                                if 'Tier-1' in desc or 'Total Compute' in desc:
                                    prices['lambda_gb_sec'] = float(dim['pricePerUnit']['USD'])
                                    break
            except Exception as e:
                self.logger.debug(f"Could not fetch Lambda duration pricing: {e}")
            
            # API Gateway REST API price
            try:
                resp = pricing_client.get_products(
                    ServiceCode='AmazonApiGateway',
                    Filters=[
                        {'Type': 'TERM_MATCH', 'Field': 'regionCode', 'Value': region},
                        {'Type': 'TERM_MATCH', 'Field': 'usagetype', 'Value': f'{region.replace("-", "").upper().replace("USWEST2","USW2").replace("USEAST1","USE1").replace("USEAST2","USE2")}-ApiGatewayRequest'}
                    ],
                    MaxResults=1
                )
                if resp.get('PriceList'):
                    price_data = json.loads(resp['PriceList'][0]) if isinstance(resp['PriceList'][0], str) else resp['PriceList'][0]
                    for term in price_data.get('terms', {}).get('OnDemand', {}).values():
                        for dim in term.get('priceDimensions', {}).values():
                            prices['apigw_request'] = float(dim['pricePerUnit']['USD'])
            except Exception as e:
                self.logger.debug(f"Could not fetch API Gateway pricing: {e}")
            
            # DynamoDB on-demand pricing
            try:
                for usage_suffix, price_key in [('WriteRequestUnits', 'ddb_wru'), ('ReadRequestUnits', 'ddb_rru')]:
                    resp = pricing_client.get_products(
                        ServiceCode='AmazonDynamoDB',
                        Filters=[
                            {'Type': 'TERM_MATCH', 'Field': 'regionCode', 'Value': region},
                            {'Type': 'TERM_MATCH', 'Field': 'group', 'Value': 'DDB-' + usage_suffix}
                        ],
                        MaxResults=1
                    )
                    if resp.get('PriceList'):
                        price_data = json.loads(resp['PriceList'][0]) if isinstance(resp['PriceList'][0], str) else resp['PriceList'][0]
                        for term in price_data.get('terms', {}).get('OnDemand', {}).values():
                            for dim in term.get('priceDimensions', {}).values():
                                prices[price_key] = float(dim['pricePerUnit']['USD'])
            except Exception as e:
                self.logger.debug(f"Could not fetch DynamoDB pricing: {e}")
            
            prices['source'] = f'AWS Pricing API ({region})'
            self.logger.info(f"Fetched pricing from AWS Pricing API for {region}")
            
        except Exception as e:
            self.logger.warning(f"Could not access AWS Pricing API, using defaults: {e}")
        
        return prices

    def _collect_cost_estimation(self, aws_insights, aws_session, region, test_hours):
        """
        Compute cost estimation from CloudWatch consumption data and AWS pricing.
        """
        prices = self._fetch_aws_pricing(aws_session, region)
        
        costs = {
            'prices': prices,
            'test_hours': test_hours,
            'lambda': {'invocations': 0, 'gb_seconds': 0, 'request_cost': 0, 'compute_cost': 0, 'total': 0},
            'apigw': {'requests': 0, 'cost': 0},
            'dynamodb': {'wcu': 0, 'rcu': 0, 'write_cost': 0, 'read_cost': 0, 'total': 0},
            'memorydb': {'nodes': 0, 'node_type': 'unknown', 'cost': 0},
            'total_test': 0,
            'projected_24h': 0,
            'projected_monthly': 0,
            'memorydb_monthly': 0
        }
        
        try:
            lambda_client = aws_session.client('lambda', region_name=region)
            
            # Lambda costs
            lambda_metrics = aws_insights.get('cloudwatch', {}).get('lambda', {})
            total_gb_sec = 0
            total_invocations = 0
            for func_name, fm in lambda_metrics.items():
                inv = fm.get('invocations', 0)
                avg_dur = fm.get('avg_duration_ms', 0)
                total_invocations += inv
                try:
                    cfg = lambda_client.get_function_configuration(FunctionName=func_name)
                    mem_mb = cfg.get('MemorySize', 512)
                except Exception:
                    mem_mb = 512
                total_gb_sec += inv * (avg_dur / 1000.0) * (mem_mb / 1024.0)
            
            costs['lambda']['invocations'] = total_invocations
            costs['lambda']['gb_seconds'] = total_gb_sec
            costs['lambda']['request_cost'] = total_invocations * prices['lambda_request']
            costs['lambda']['compute_cost'] = total_gb_sec * prices['lambda_gb_sec']
            costs['lambda']['total'] = costs['lambda']['request_cost'] + costs['lambda']['compute_cost']
            
            # API Gateway costs
            apigw_reqs = aws_insights.get('cloudwatch', {}).get('api_gateway', {}).get('total_requests', 0)
            costs['apigw']['requests'] = apigw_reqs
            costs['apigw']['cost'] = apigw_reqs * prices['apigw_request']
            
            # DynamoDB costs
            ddb_metrics = aws_insights.get('cloudwatch', {}).get('dynamodb', {})
            total_wcu = sum(tm.get('total_write_capacity', 0) for tm in ddb_metrics.values())
            total_rcu = sum(tm.get('total_read_capacity', 0) for tm in ddb_metrics.values())
            costs['dynamodb']['wcu'] = total_wcu
            costs['dynamodb']['rcu'] = total_rcu
            costs['dynamodb']['write_cost'] = total_wcu * prices['ddb_wru']
            costs['dynamodb']['read_cost'] = total_rcu * prices['ddb_rru']
            costs['dynamodb']['total'] = costs['dynamodb']['write_cost'] + costs['dynamodb']['read_cost']
            
            # MemoryDB costs
            memdb_nodes = 0
            memdb_node_type = 'unknown'
            try:
                memdb_client = aws_session.client('memorydb', region_name=region)
                clusters = memdb_client.describe_clusters(ShowShardDetails=True)
                for cl in clusters.get('Clusters', []):
                    memdb_node_type = cl.get('NodeType', 'db.r6g.large')
                    for shard in cl.get('Shards', []):
                        memdb_nodes += shard.get('NumberOfNodes', 0)
            except Exception:
                memdb_nodes = 0
            
            costs['memorydb']['nodes'] = memdb_nodes
            costs['memorydb']['node_type'] = memdb_node_type
            costs['memorydb']['cost'] = memdb_nodes * prices['memorydb_per_node_hr'] * test_hours
            
            # Totals
            costs['total_test'] = costs['lambda']['total'] + costs['apigw']['cost'] + costs['dynamodb']['total'] + costs['memorydb']['cost']
            costs['memorydb_monthly'] = memdb_nodes * prices['memorydb_per_node_hr'] * 24 * 30
            
            # Realistic production estimates
            # Test uses aggressive pattern (~0.76 calls/player/sec). Real games are 20-60x lower.
            test_rps = costs['apigw']['requests'] / max(test_hours * 3600, 1)
            peak_players = aws_insights.get('peak_values', {}).get('peak_players', 0) or 1
            calls_per_player_sec = test_rps / max(peak_players, 1)
            costs['test_rps'] = test_rps
            costs['calls_per_player_sec'] = calls_per_player_sec
            costs['peak_players'] = peak_players
            
            pay_per_use_test = costs['lambda']['total'] + costs['apigw']['cost'] + costs['dynamodb']['total']
            monthly_hours_ratio = (24 * 30) / max(test_hours, 0.1)
            
            # Scenario A: Competitive (1 call / player / 30s)
            ratio_a = (peak_players / 30.0) / max(test_rps, 1)
            costs['scenario_a'] = {
                'description': 'Competitive game (1 API call per player every 30 seconds)',
                'example': 'PvP arena with live leaderboards, frequent score submissions after short matches',
                'rps': peak_players / 30.0,
                'ratio': ratio_a,
                'monthly': pay_per_use_test * ratio_a * monthly_hours_ratio + costs['memorydb_monthly']
            }
            
            # Scenario B: Casual (1 call / player / 2 min)
            ratio_b = (peak_players / 120.0) / max(test_rps, 1)
            costs['scenario_b'] = {
                'description': 'Casual game (1 API call per player every 2 minutes)',
                'example': 'Story-driven RPG, leaderboard checked between sessions, stats submitted at end of longer play sessions',
                'rps': peak_players / 120.0,
                'ratio': ratio_b,
                'monthly': pay_per_use_test * ratio_b * monthly_hours_ratio + costs['memorydb_monthly']
            }
            
        except Exception as e:
            self.logger.warning(f"Cost estimation failed: {e}")
            self.logger.warning(traceback.format_exc())
        
        return costs


