# SECTION: DRY RUN VALIDATOR
# ============================================================================

class DryRunValidator:
    """
    Validates test configuration without executing actual tests.
    
    Performs:
    - Configuration parameter validation
    - AWS connectivity verification
    - DynamoDB table checks
    - API endpoint accessibility tests
    - Cost estimation
    - Player pool size validation
    
    Requirements: 24.1, 24.2, 24.3, 24.4, 24.5, 24.6, 24.7, 24.8, 24.9, 24.10, 24.11, 24.12
    Design: Section 20
    """
    
    def __init__(self, config, aws_session, logger):
        """
        Initialize dry run validator.
        
        Args:
            config: Test configuration dictionary
            aws_session: boto3 Session object
            logger: ThreadSafeLogger instance
        
        Requirements: 24.1
        """
        self.config = config
        self.aws_session = aws_session
        self.logger = logger
        self.validation_passed = True
        self.validation_results = []
    
    def validate_all(self):
        """
        Run all validation checks.
        
        Returns:
            bool: True if all validations passed, False otherwise
        
        Requirements: 24.2, 24.11
        """
        self.logger.print_and_log("=" * 80)
        self.logger.print_and_log("DRY RUN MODE - Validation")
        self.logger.print_and_log("=" * 80)
        self.logger.print_and_log("")
        
        # Validate configuration parameters (Requirements 24.2)
        self._validate_configuration()
        
        # Verify AWS connectivity (Requirements 24.3)
        self._verify_aws_connectivity()
        
        # Verify DynamoDB tables (Requirements 24.4)
        self._verify_dynamodb_tables()
        
        # Verify API endpoints (Requirements 24.5)
        self._verify_api_endpoints()
        
        # Verify API Gateway authorizer configuration
        self._verify_api_gateway_authorizer()
        
        # Verify Lambda authorizer concurrency
        self._verify_lambda_authorizer_concurrency()
        
        # Validate Test Definitions Table (Requirements 24.6)
        self._validate_test_definitions()
        
        # Estimate AWS costs (Requirements 24.7, 24.8)
        self._estimate_costs()
        
        # Display execution summary (Requirements 24.9)
        self._display_execution_summary()
        
        # Validate player pool size (Requirements 24.10)
        self._validate_player_pool()
        
        self.logger.print_and_log("")
        self.logger.print_and_log("=" * 80)
        self.logger.print_and_log(f"Dry Run Validation: {'PASS' if self.validation_passed else 'FAIL'}")
        self.logger.print_and_log("=" * 80)
        self.logger.print_and_log("")
        
        return self.validation_passed
    
    def _validate_configuration(self):
        """
        Validate configuration parameters.
        
        NOTE: This validates the TEST CONFIGURATION (leaderboards, stats, game modes),
        NOT runtime parameters like max_players or duration which are process-specific.
        
        Requirements: 24.2, 24.12
        """
        self.logger.print_and_log("Validating test configuration...")
        
        # Check required fields for test configuration
        required_fields = ['region']
        missing_fields = [f for f in required_fields if f not in self.config]
        
        if missing_fields:
            self.validation_passed = False
            self.logger.print_and_log(f"  ✗ Missing required fields: {', '.join(missing_fields)}", level='ERROR')
            self.validation_results.append({
                'check': 'Configuration Parameters',
                'status': 'FAIL',
                'reason': f"Missing fields: {', '.join(missing_fields)}"
            })
        else:
            self.logger.print_and_log(f"  ✓ All required configuration fields present")
        
        # Validate test configuration structure (not runtime parameters)
        if 'METADATA' in self.config:
            metadata = self.config['METADATA']
            self.logger.print_and_log(f"  ✓ Test Name: {metadata.get('TestName', 'Unknown')}")
            self.logger.print_and_log(f"  ✓ Genre: {metadata.get('Genre', 'Unknown')}")
        
        if 'LEADERBOARD_CONFIG' in self.config:
            lb_count = len(self.config['LEADERBOARD_CONFIG'].get('leaderboards', []))
            self.logger.print_and_log(f"  ✓ Leaderboards configured: {lb_count}")
        
        if 'GAME_MODES' in self.config:
            mode_count = len(self.config['GAME_MODES'].get('game_modes', []))
            self.logger.print_and_log(f"  ✓ Game modes configured: {mode_count}")
        
        self.logger.print_and_log("")
        self.logger.print_and_log("ℹ️  Runtime parameters (max_players, duration) are process-specific")
        self.logger.print_and_log("ℹ️  Each test instance specifies these via command-line arguments")
        self.logger.print_and_log("")
        
        # Validate max_players if provided (optional during dry-run)
        max_players = self.config.get('max_players')
        if max_players is not None:
            if max_players < MIN_PLAYERS_PER_INSTANCE or max_players > MAX_PLAYERS_PER_INSTANCE:
                self.validation_passed = False
                self.logger.error(f"  ✗ Max players {max_players} outside valid range ({MIN_PLAYERS_PER_INSTANCE}-{MAX_PLAYERS_PER_INSTANCE})")
            else:
                self.logger.info(f"  ✓ Max players: {max_players}")
        else:
            self.logger.info(f"  ℹ️  Max players not specified (will use default: {DEFAULT_PLAYERS_PER_INSTANCE})")
        
        self.logger.info("")
    
    def _verify_aws_connectivity(self):
        """
        Verify AWS connectivity and credentials.
        
        Requirements: 24.3, 24.12
        """
        self.logger.print_and_log("Verifying AWS connectivity...")
        
        try:
            sts = self.aws_session.client('sts')
            identity = sts.get_caller_identity()
            
            self.logger.print_and_log(f"  ✓ AWS credentials valid")
            self.logger.print_and_log(f"  ✓ Account: {identity['Account']}")
            self.logger.print_and_log(f"  ✓ Region: {self.config.get('region', 'Unknown')}")
            
            self.validation_results.append({
                'check': 'AWS Connectivity',
                'status': 'PASS',
                'details': f"Account {identity['Account']}"
            })
            
        except Exception as e:
            self.validation_passed = False
            self.logger.error(f"  ✗ AWS connectivity failed: {e}")
            self.validation_results.append({
                'check': 'AWS Connectivity',
                'status': 'FAIL',
                'reason': str(e)
            })
        
        self.logger.print_and_log("")
    
    def _verify_dynamodb_tables(self):
        """
        Verify DynamoDB tables exist or can be created.
        
        Requirements: 24.4, 24.12
        """
        self.logger.print_and_log("Verifying DynamoDB tables...")
        
        dynamodb = self.aws_session.client('dynamodb')
        
        tables_to_check = [
            TEST_DEFINITIONS_TABLE_NAME,
            PLAYER_STATE_TABLE_NAME
        ]
        
        for table_name in tables_to_check:
            try:
                response = dynamodb.describe_table(TableName=table_name)
                status = response['Table']['TableStatus']
                
                if status == 'ACTIVE':
                    self.logger.print_and_log(f"  ✓ Table {table_name}: ACTIVE")
                else:
                    self.logger.warning(f"  ⚠ Table {table_name}: {status}")
                
            except ClientError as e:
                if e.response['Error']['Code'] == 'ResourceNotFoundException':
                    self.logger.print_and_log(f"  ⚠ Table {table_name}: Not found (will be created)")
                else:
                    self.validation_passed = False
                    self.logger.error(f"  ✗ Table {table_name}: Error - {e}")
        
        self.logger.print_and_log("")
    
    def _verify_api_endpoints(self):
        """
        Verify API endpoints are accessible.
        
        Requirements: 24.5, 24.12
        """
        self.logger.print_and_log("Verifying API endpoints...")
        
        api_base_url = self.config.get('api_base_url')
        
        if not api_base_url:
            self.logger.warning("  ⚠ API base URL not configured, skipping endpoint checks")
            self.logger.print_and_log("")
            return
        
        # Test endpoints with simple GET/HEAD requests
        endpoints_to_test = [
            '/developer/register',
            '/leaderboards/config',
            '/leaderboards/stats',
            '/leaderboards/scores'
        ]
        
        for endpoint in endpoints_to_test:
            try:
                url = f"{api_base_url}{endpoint}"
                # Use HEAD request to avoid triggering actual operations
                response = requests.head(url, timeout=API_TIMEOUT_VALIDATION)
                
                # Interpret status codes
                if response.status_code == 403:
                    # 403 is expected - authorizer rejecting request without valid API key
                    self.logger.print_and_log(f"  ✓ Endpoint {endpoint}: Reachable (HTTP {response.status_code} - as expected)")
                elif response.status_code in [200, 201, 204]:
                    # Success codes - endpoint is working
                    self.logger.print_and_log(f"  ✓ Endpoint {endpoint}: Reachable (HTTP {response.status_code})")
                elif response.status_code == 404:
                    # 404 is a problem - endpoint doesn't exist
                    self.validation_passed = False
                    self.logger.error(f"  ✗ Endpoint {endpoint}: Not Found (HTTP 404)")
                    self.logger.error(f"     This endpoint may not be deployed or the URL is incorrect")
                elif response.status_code >= 500:
                    # 5xx errors are critical - server-side issues
                    self.validation_passed = False
                    self.logger.error(f"  ✗ Endpoint {endpoint}: Server Error (HTTP {response.status_code})")
                    self.logger.error(f"     The API Gateway or Lambda function may be experiencing issues")
                else:
                    # Other status codes - log as warning but don't fail
                    self.logger.warning(f"  ⚠ Endpoint {endpoint}: Unexpected status (HTTP {response.status_code})")
                
            except requests.exceptions.Timeout:
                self.validation_passed = False
                self.logger.error(f"  ✗ Endpoint {endpoint}: Timeout (no response within {API_TIMEOUT_VALIDATION}s)")
            except requests.exceptions.ConnectionError:
                self.validation_passed = False
                self.logger.error(f"  ✗ Endpoint {endpoint}: Connection failed (API Gateway may be down)")
            except Exception as e:
                self.logger.warning(f"  ⚠ Endpoint {endpoint}: {e}")
        
        self.logger.print_and_log("")
    
    def _verify_api_gateway_authorizer(self):
        """
        Verify API Gateway authorizer cache configuration.
        
        Checks that the authorizer cache TTL is sufficient for high-load scenarios.
        Recommended: 300-600 seconds for production workloads.
        """
        self.logger.print_and_log("Verifying API Gateway authorizer configuration...")
        
        api_base_url = self.config.get('api_base_url')
        
        if not api_base_url:
            self.logger.warning("  ⚠ API base URL not configured, skipping authorizer checks")
            self.logger.print_and_log("")
            return
        
        try:
            # Extract API Gateway ID from URL
            # Format: https://{api-id}.execute-api.{region}.amazonaws.com/{stage}
            import re
            match = re.search(r'https://([a-z0-9]+)\.execute-api\.([a-z0-9-]+)\.amazonaws\.com', api_base_url)
            
            if not match:
                self.logger.warning("  ⚠ Could not extract API Gateway ID from URL")
                self.logger.print_and_log("")
                return
            
            api_id = match.group(1)
            region = match.group(2)
            
            # Get authorizers for this API
            apigw = self.aws_session.client('apigateway', region_name=region)
            response = apigw.get_authorizers(restApiId=api_id)
            
            if not response.get('items'):
                self.logger.warning("  ⚠ No authorizers found for API Gateway")
                self.logger.print_and_log("")
                return
            
            # Check each authorizer
            for authorizer in response['items']:
                auth_name = authorizer.get('name', 'Unknown')
                auth_ttl = authorizer.get('authorizerResultTtlInSeconds', 0)
                
                # Recommended TTL for high-load: 300-600 seconds
                # Warning if < 300, critical if < 60
                if auth_ttl < 60:
                    self.validation_passed = False
                    self.logger.error(f"  ✗ Authorizer '{auth_name}': Cache TTL is {auth_ttl}s (CRITICAL: < 60s)")
                    self.logger.error(f"     This will cause rate limit errors under high load!")
                    self.logger.error(f"     Recommended: 300-600 seconds")
                elif auth_ttl < 300:
                    self.logger.warning(f"  ⚠ Authorizer '{auth_name}': Cache TTL is {auth_ttl}s (WARNING: < 300s)")
                    self.logger.warning(f"     Consider increasing to 300-600s for better performance")
                else:
                    self.logger.print_and_log(f"  ✓ Authorizer '{auth_name}': Cache TTL is {auth_ttl}s (Good)")
                
                self.validation_results.append({
                    'check': f'API Gateway Authorizer Cache ({auth_name})',
                    'status': 'PASS' if auth_ttl >= 300 else ('WARN' if auth_ttl >= 60 else 'FAIL'),
                    'details': f"TTL: {auth_ttl}s"
                })
        
        except Exception as e:
            self.logger.warning(f"  ⚠ Could not verify authorizer configuration: {e}")
        
        self.logger.print_and_log("")
    
    def _verify_lambda_authorizer_concurrency(self):
        """
        Verify Lambda authorizer configuration for high-load scenarios.
        
        NOTE: Reserved concurrency checks have been REMOVED as all functions now
        share the unreserved concurrency pool for maximum flexibility.
        
        This function now only verifies that the authorizer Lambda exists and is accessible.
        """
        self.logger.print_and_log("Verifying Lambda authorizer configuration...")
        
        api_base_url = self.config.get('api_base_url')
        
        if not api_base_url:
            self.logger.warning("  ⚠ API base URL not configured, skipping Lambda checks")
            self.logger.print_and_log("")
            return
        
        try:
            # Extract region from URL
            import re
            match = re.search(r'https://[a-z0-9]+\.execute-api\.([a-z0-9-]+)\.amazonaws\.com', api_base_url)
            
            if not match:
                self.logger.warning("  ⚠ Could not extract region from API URL")
                self.logger.print_and_log("")
                return
            
            region = match.group(1)
            
            # List Lambda functions to find authorizer
            lambda_client = self.aws_session.client('lambda', region_name=region)
            
            # Look for authorizer Lambda (common naming patterns)
            authorizer_patterns = ['authorizer', 'auth']
            authorizer_functions = []
            
            paginator = lambda_client.get_paginator('list_functions')
            for page in paginator.paginate():
                for func in page['Functions']:
                    func_name = func['FunctionName'].lower()
                    if any(pattern in func_name for pattern in authorizer_patterns):
                        authorizer_functions.append(func['FunctionName'])
            
            if not authorizer_functions:
                self.logger.warning("  ⚠ No authorizer Lambda functions found")
                self.logger.print_and_log("")
                return
            
            # Verify authorizer functions exist and are accessible
            for func_name in authorizer_functions:
                try:
                    # Just verify the function exists and is accessible
                    lambda_client.get_function(FunctionName=func_name)
                    self.logger.print_and_log(f"  ✓ Lambda '{func_name}': Found and accessible")
                    self.logger.print_and_log(f"     Using unreserved concurrency pool (shared across all functions)")
                    
                    self.validation_results.append({
                        'check': f'Lambda Authorizer Configuration ({func_name})',
                        'status': 'PASS',
                        'details': 'Function accessible, using unreserved concurrency pool'
                    })
                
                except lambda_client.exceptions.ResourceNotFoundException:
                    self.validation_passed = False
                    self.logger.error(f"  ✗ Lambda '{func_name}': Function not found")
                    self.validation_results.append({
                        'check': f'Lambda Authorizer Configuration ({func_name})',
                        'status': 'FAIL',
                        'details': 'Function not found'
                    })
        
        except Exception as e:
            self.logger.warning(f"  ⚠ Could not verify Lambda configuration: {e}")
        
        self.logger.print_and_log("")
    
    def _validate_test_definitions(self):
        """
        Validate Test Definitions Table or generate sample configuration.
        
        Requirements: 24.6, 24.12
        """
        self.logger.info("Validating test definitions...")
        
        test_config_id = self.config.get('test_config_id')
        
        if test_config_id:
            # Validate existing configuration
            try:
                
                dynamodb = self.aws_session.resource('dynamodb')
                table = dynamodb.Table(TEST_DEFINITIONS_TABLE_NAME)
                
                response = table.get_item(
                    Key={
                        'TestConfigID': test_config_id,
                        'ConfigCategory': 'METADATA'
                    }
                )
                
                if 'Item' in response:
                    self.logger.info(f"  ✓ Test configuration found: {test_config_id}")
                    self.logger.info(f"    Name: {response['Item'].get('TestName', 'Unknown')}")
                    self.logger.info(f"    Genre: {response['Item'].get('Genre', 'Unknown')}")
                else:
                    self.validation_passed = False
                    self.logger.error(f"  ✗ Test configuration not found: {test_config_id}")
                
            except ClientError as e:
                self.validation_passed = False
                self.logger.error(f"  ✗ Error loading test configuration: {e}")
        else:
            self.logger.info("  ⚠ No test configuration specified (generation mode)")
        
        self.logger.info("")
    
    def _estimate_costs(self):
        """
        Estimate AWS costs for the test.
        
        Requirements: 24.7, 24.8, 24.12
        """
        self.logger.info("Estimating AWS costs...")
        
        duration_hours = self.config.get('duration', 0) / 3600
        max_players = self.config.get('max_players', 0)
        
        # Estimate API calls
        # Assume average 1 API call per player per 10 seconds
        estimated_api_calls = (max_players * duration_hours * 3600) / 10
        
        # DynamoDB costs (rough estimates)
        # Write units: ~1 per API call for stats storage
        # Read units: ~0.5 per API call for queries
        write_units = estimated_api_calls
        read_units = estimated_api_calls * 0.5
        
        # On-demand pricing (approximate)
        write_cost = (write_units / 1_000_000) * 1.25  # $1.25 per million writes
        read_cost = (read_units / 1_000_000) * 0.25    # $0.25 per million reads
        
        # CloudWatch metrics (approximate)
        # ~20 metrics every 30 seconds
        metrics_per_hour = (3600 / 30) * 20
        total_metrics = metrics_per_hour * duration_hours
        metrics_cost = (total_metrics / 1_000_000) * 0.30  # $0.30 per million metrics
        
        # Data transfer (approximate, minimal for testing)
        data_transfer_cost = 0.10 * duration_hours  # Rough estimate
        
        total_cost = write_cost + read_cost + metrics_cost + data_transfer_cost
        
        self.logger.info(f"  Duration: {duration_hours:.2f} hours")
        self.logger.info(f"  Estimated API calls: {estimated_api_calls:,.0f}")
        self.logger.info(f"  DynamoDB writes: {write_units:,.0f} units (${write_cost:.2f})")
        self.logger.info(f"  DynamoDB reads: {read_units:,.0f} units (${read_cost:.2f})")
        self.logger.info(f"  CloudWatch metrics: {total_metrics:,.0f} (${metrics_cost:.2f})")
        self.logger.info(f"  Data transfer: ~${data_transfer_cost:.2f}")
        self.logger.info(f"  Estimated total cost: ${total_cost:.2f}")
        self.logger.info("")
        self.logger.info("  Note: This is a rough estimate. Actual costs may vary.")
        self.logger.info("")
    
    def _display_execution_summary(self):
        """
        Display summary of what would be executed.
        
        Requirements: 24.9, 24.12
        """
        self.logger.info("Execution summary (what would run)...")
        
        max_players = self.config.get('max_players', 0)
        duration = self.config.get('duration', 0)
        
        # Calculate worker thread distribution
        num_player_workers = int(max_players * 0.95)
        num_batch_workers = int(max_players * 0.05)
        
        self.logger.info(f"  Test duration: {duration}s ({duration/60:.1f} minutes)")
        self.logger.info(f"  Max concurrent players: {max_players}")
        self.logger.info(f"  Worker threads:")
        self.logger.info(f"    - Event manager: 1")
        self.logger.info(f"    - Player workers: {num_player_workers}")
        self.logger.info(f"    - Batch workers: {num_batch_workers} (spawned during events)")
        self.logger.info(f"    - Total: {1 + num_player_workers}")
        self.logger.info(f"  API call distribution:")
        self.logger.info(f"    - Store stats: {API_DISTRIBUTION_STORE_STATS}%")
        self.logger.info(f"    - Get leaderboard: {API_DISTRIBUTION_GET_LEADERBOARD}%")
        self.logger.info(f"    - Get player stats: {API_DISTRIBUTION_GET_PLAYER_STATS}%")
        self.logger.info(f"    - Get standing: {API_DISTRIBUTION_GET_STANDING}%")
        self.logger.info("")
    
    def _validate_player_pool(self):
        """
        Validate player pool size is sufficient.
        
        Requirements: 24.10, 24.12
        """
        self.logger.print_and_log("Validating player pool size...")
        
        max_players = self.config.get('max_players', 0)
        player_pool = self.config.get('PLAYER_POOL', {})
        pool_size = player_pool.get('total_players', 0)
        
        if pool_size == 0:
            self.logger.print_and_log("  ℹ️  Player pool not configured (will be generated dynamically)")
        elif pool_size < max_players:
            self.validation_passed = False
            self.logger.error(f"  ✗ Player pool size ({pool_size}) < max players ({max_players})")
        else:
            self.logger.print_and_log(f"  ✓ Player pool size: {pool_size} (sufficient for {max_players} concurrent)")
        
        self.logger.print_and_log("")


