class CloudWatchMetricsPublisher:
    """
    Publishes custom metrics to CloudWatch for monitoring and alerting.
    
    Publishes:
    - API latency metrics (p50, p95, p99)
    - Throughput metrics (RPS)
    - Error rate metrics
    - Resource utilization metrics
    
    Uses batching for efficiency and handles publish errors gracefully.
    
    Requirements: 20.1, 20.2, 20.3, 20.4, 20.5, 20.6, 20.7
    Design: Section 16
    """
    
    def __init__(self, aws_session, test_config_id, region, logger):
        """
        Initialize CloudWatch metrics publisher.
        
        Args:
            aws_session: boto3 Session object
            test_config_id: Test Config ID for metric dimensions
            region: AWS region
            logger: ThreadSafeLogger instance
        
        Requirements: 20.1
        """
        self.aws_session = aws_session
        self.test_config_id = test_config_id
        self.region = region
        self.logger = logger
        
        # Create CloudWatch client
        self.cloudwatch = aws_session.client('cloudwatch', region_name=region)
        
        # Metric namespace
        self.namespace = 'LoadTesting/StatsLeaderboards'
        
        # Batch storage for efficiency
        self.metric_batch = []
        self.max_batch_size = 20  # CloudWatch limit is 20 metrics per PutMetricData call
        
        # Instance ID for dimensions
        import socket
        self.instance_id = socket.gethostname()
        
        self.logger.info(f"CloudWatch metrics publisher initialized (namespace: {self.namespace})")
    
    def publish_metrics(self, metrics_data):
        """
        Publish metrics to CloudWatch.
        
        Batches metrics for efficiency and handles errors gracefully.
        
        Args:
            metrics_data: Dictionary containing metrics from MetricsCollector
        
        Requirements: 20.2, 20.3, 20.6, 20.7
        """
        if not metrics_data:
            return
        
        try:
            
            timestamp = datetime.now(timezone.utc)
            
            # Common dimensions for all metrics
            dimensions = [
                {'Name': 'TestConfigID', 'Value': self.test_config_id},
                {'Name': 'InstanceID', 'Value': self.instance_id}
            ]
            
            # Build metric data list
            metric_data = []
            
            # Throughput metrics (Requirements 20.4, 20.5)
            metric_data.append({
                'MetricName': 'RequestsPerSecond',
                'Value': metrics_data.get('rps', 0),
                'Unit': 'Count/Second',
                'Timestamp': timestamp,
                'Dimensions': dimensions
            })
            
            # Success rate metrics
            metric_data.append({
                'MetricName': 'SuccessRate',
                'Value': metrics_data.get('success_rate', 0) * 100,  # Convert to percentage
                'Unit': 'Percent',
                'Timestamp': timestamp,
                'Dimensions': dimensions
            })
            
            # Error rate metrics
            metric_data.append({
                'MetricName': 'ErrorRate',
                'Value': metrics_data.get('error_rate', 0) * 100,  # Convert to percentage
                'Unit': 'Percent',
                'Timestamp': timestamp,
                'Dimensions': dimensions
            })
            
            # Latency metrics (Requirements 20.4, 20.5)
            metric_data.append({
                'MetricName': 'AverageLatency',
                'Value': metrics_data.get('avg_latency', 0),
                'Unit': 'Milliseconds',
                'Timestamp': timestamp,
                'Dimensions': dimensions
            })
            
            metric_data.append({
                'MetricName': 'P50Latency',
                'Value': metrics_data.get('p50_latency', 0),
                'Unit': 'Milliseconds',
                'Timestamp': timestamp,
                'Dimensions': dimensions
            })
            
            metric_data.append({
                'MetricName': 'P95Latency',
                'Value': metrics_data.get('p95_latency', 0),
                'Unit': 'Milliseconds',
                'Timestamp': timestamp,
                'Dimensions': dimensions
            })
            
            metric_data.append({
                'MetricName': 'P99Latency',
                'Value': metrics_data.get('p99_latency', 0),
                'Unit': 'Milliseconds',
                'Timestamp': timestamp,
                'Dimensions': dimensions
            })
            
            # Active sessions and threads
            metric_data.append({
                'MetricName': 'ActiveThreads',
                'Value': metrics_data.get('active_threads', 0),
                'Unit': 'Count',
                'Timestamp': timestamp,
                'Dimensions': dimensions
            })
            
            metric_data.append({
                'MetricName': 'ActiveSessions',
                'Value': metrics_data.get('active_sessions', 0),
                'Unit': 'Count',
                'Timestamp': timestamp,
                'Dimensions': dimensions
            })
            
            # Total request counts
            metric_data.append({
                'MetricName': 'TotalRequests',
                'Value': metrics_data.get('total_requests', 0),
                'Unit': 'Count',
                'Timestamp': timestamp,
                'Dimensions': dimensions
            })
            
            metric_data.append({
                'MetricName': 'SuccessfulRequests',
                'Value': metrics_data.get('successful_requests', 0),
                'Unit': 'Count',
                'Timestamp': timestamp,
                'Dimensions': dimensions
            })
            
            metric_data.append({
                'MetricName': 'FailedRequests',
                'Value': metrics_data.get('failed_requests', 0),
                'Unit': 'Count',
                'Timestamp': timestamp,
                'Dimensions': dimensions
            })
            
            # Per-endpoint metrics (Requirements 20.5)
            by_endpoint = metrics_data.get('by_endpoint', {})
            for endpoint, endpoint_data in by_endpoint.items():
                # Create endpoint-specific dimensions
                endpoint_dimensions = dimensions + [
                    {'Name': 'Endpoint', 'Value': endpoint}
                ]
                
                metric_data.append({
                    'MetricName': 'EndpointRequests',
                    'Value': endpoint_data.get('requests', 0),
                    'Unit': 'Count',
                    'Timestamp': timestamp,
                    'Dimensions': endpoint_dimensions
                })
                
                metric_data.append({
                    'MetricName': 'EndpointSuccessRate',
                    'Value': endpoint_data.get('success_rate', 0) * 100,
                    'Unit': 'Percent',
                    'Timestamp': timestamp,
                    'Dimensions': endpoint_dimensions
                })
                
                metric_data.append({
                    'MetricName': 'EndpointAverageLatency',
                    'Value': endpoint_data.get('avg_latency', 0),
                    'Unit': 'Milliseconds',
                    'Timestamp': timestamp,
                    'Dimensions': endpoint_dimensions
                })
                
                metric_data.append({
                    'MetricName': 'EndpointP95Latency',
                    'Value': endpoint_data.get('p95_latency', 0),
                    'Unit': 'Milliseconds',
                    'Timestamp': timestamp,
                    'Dimensions': endpoint_dimensions
                })
            
            # Publish metrics in batches (CloudWatch limit: 20 metrics per call)
            # Requirements: 20.2, 20.3
            for i in range(0, len(metric_data), self.max_batch_size):
                batch = metric_data[i:i + self.max_batch_size]
                
                try:
                    self.cloudwatch.put_metric_data(
                        Namespace=self.namespace,
                        MetricData=batch
                    )
                    self.logger.debug(f"Published {len(batch)} metrics to CloudWatch")
                    
                except ClientError as e:
                    error_code = e.response.get('Error', {}).get('Code', 'Unknown')
                    self.logger.warning(f"Failed to publish metrics batch to CloudWatch: {error_code} - {e}")
                    # Continue with next batch even if one fails
                    
                except Exception as e:
                    self.logger.warning(f"Unexpected error publishing metrics to CloudWatch: {e}")
                    # Continue with next batch
            
            self.logger.debug(f"Successfully published {len(metric_data)} metrics to CloudWatch")
            
        except Exception as e:
            self.logger.error(f"Error preparing metrics for CloudWatch: {e}")
            self.logger.error(traceback.format_exc())


