class CloudWatchMetricsCollector:
    """
    Collects real-time metrics from CloudWatch for display in visualization webpage.
    
    Queries CloudWatch for:
    - API Gateway: Request count, error count, latency (for RPS and error rate)
    - Lambda: Invocation count, error count, throttles
    - DynamoDB: Consumed read/write capacity, throttled requests
    
    Caches metrics for 10 seconds to avoid excessive CloudWatch API calls.
    
    Requirements: 32.15
    Task: 29.10.1
    """
    
    def __init__(self, aws_session, region, stack_outputs, logger):
        """
        Initialize CloudWatch metrics collector.
        
        Args:
            aws_session: boto3 Session object
            region: AWS region
            stack_outputs: Dict of CloudFormation stack outputs (API Gateway ID, Lambda names, etc.)
            logger: Logger instance
        """
        self.aws_session = aws_session
        self.region = region
        self.stack_outputs = stack_outputs
        self.logger = logger
        
        # Create CloudWatch client
        self.cloudwatch = aws_session.client('cloudwatch', region_name=region)
        
        # Cache for metrics (10 second TTL)
        self.metrics_cache = None
        self.cache_timestamp = 0
        self.cache_ttl = 10  # seconds
        
        self.logger.info("CloudWatch metrics collector initialized")
    
    def get_metrics(self):
        """
        Get current metrics from CloudWatch (with caching).
        
        Returns:
            dict: Metrics data including RPS, error rate, latency, etc.
        
        Requirements: 32.15
        """
        
        # Check cache
        now = time.time()
        if self.metrics_cache and (now - self.cache_timestamp) < self.cache_ttl:
            return self.metrics_cache
        
        # Fetch fresh metrics
        try:
            metrics = self._fetch_metrics()
            self.metrics_cache = metrics
            self.cache_timestamp = now
            return metrics
        except Exception as e:
            self.logger.error(f"Error fetching CloudWatch metrics: {e}")
            # Return cached data if available, otherwise empty metrics
            return self.metrics_cache if self.metrics_cache else self._empty_metrics()
    
    def _fetch_metrics(self):
        """
        Fetch metrics from CloudWatch.
        
        Returns:
            dict: Metrics data
        """
        
        # Time range: last 5 minutes
        end_time = datetime.now(timezone.utc)
        start_time = end_time - timedelta(minutes=5)
        
        metrics = {
            'timestamp': end_time.isoformat(),
            'api_gateway': {},
            'lambda': {},
            'dynamodb': {},
            'summary': {}
        }
        
        try:
            # Get API Gateway metrics
            api_gateway_id = self.stack_outputs.get('ApiGatewayRestApiId')
            if api_gateway_id:
                metrics['api_gateway'] = self._get_api_gateway_metrics(
                    api_gateway_id, start_time, end_time
                )
            
            # Get Lambda metrics
            lambda_functions = self.stack_outputs.get('LambdaFunctionNames', [])
            if lambda_functions:
                metrics['lambda'] = self._get_lambda_metrics(
                    lambda_functions, start_time, end_time
                )
            
            # Get DynamoDB metrics
            dynamodb_tables = self.stack_outputs.get('DynamoDBTableNames', [])
            if dynamodb_tables:
                metrics['dynamodb'] = self._get_dynamodb_metrics(
                    dynamodb_tables, start_time, end_time
                )
            
            # Calculate summary metrics
            metrics['summary'] = self._calculate_summary(metrics)
            
        except Exception as e:
            self.logger.error(f"Error in _fetch_metrics: {e}")
            self.logger.error(traceback.format_exc())
        
        return metrics
    
    def _get_api_gateway_metrics(self, api_id, start_time, end_time):
        """
        Get API Gateway metrics from CloudWatch.
        
        Args:
            api_id: API Gateway REST API ID
            start_time: Start time for metrics
            end_time: End time for metrics
        
        Returns:
            dict: API Gateway metrics
        """
        
        metrics = {
            'request_count': 0,
            'error_count': 0,
            'latency_avg': 0,
            'latency_p95': 0,
            'rps': 0,
            'error_rate': 0
        }
        
        try:
            # Get request count
            response = self.cloudwatch.get_metric_statistics(
                Namespace='AWS/ApiGateway',
                MetricName='Count',
                Dimensions=[
                    {'Name': 'ApiName', 'Value': api_id}
                ],
                StartTime=start_time,
                EndTime=end_time,
                Period=60,  # 1 minute
                Statistics=['Sum']
            )
            
            if response['Datapoints']:
                total_requests = sum(dp['Sum'] for dp in response['Datapoints'])
                metrics['request_count'] = int(total_requests)
                
                # Calculate RPS (requests per second over the period)
                duration_seconds = (end_time - start_time).total_seconds()
                metrics['rps'] = total_requests / duration_seconds if duration_seconds > 0 else 0
            
            # Get 4XX errors
            response_4xx = self.cloudwatch.get_metric_statistics(
                Namespace='AWS/ApiGateway',
                MetricName='4XXError',
                Dimensions=[
                    {'Name': 'ApiName', 'Value': api_id}
                ],
                StartTime=start_time,
                EndTime=end_time,
                Period=60,
                Statistics=['Sum']
            )
            
            # Get 5XX errors
            response_5xx = self.cloudwatch.get_metric_statistics(
                Namespace='AWS/ApiGateway',
                MetricName='5XXError',
                Dimensions=[
                    {'Name': 'ApiName', 'Value': api_id}
                ],
                StartTime=start_time,
                EndTime=end_time,
                Period=60,
                Statistics=['Sum']
            )
            
            errors_4xx = sum(dp['Sum'] for dp in response_4xx.get('Datapoints', []))
            errors_5xx = sum(dp['Sum'] for dp in response_5xx.get('Datapoints', []))
            metrics['error_count'] = int(errors_4xx + errors_5xx)
            
            # Calculate error rate
            if metrics['request_count'] > 0:
                metrics['error_rate'] = (metrics['error_count'] / metrics['request_count']) * 100
            
            # Get latency
            response_latency = self.cloudwatch.get_metric_statistics(
                Namespace='AWS/ApiGateway',
                MetricName='Latency',
                Dimensions=[
                    {'Name': 'ApiName', 'Value': api_id}
                ],
                StartTime=start_time,
                EndTime=end_time,
                Period=60,
                Statistics=['Average', 'p95']
            )
            
            if response_latency['Datapoints']:
                # Get most recent datapoint
                latest = sorted(response_latency['Datapoints'], key=lambda x: x['Timestamp'])[-1]
                metrics['latency_avg'] = latest.get('Average', 0)
                metrics['latency_p95'] = latest.get('ExtendedStatistics', {}).get('p95', 0)
        
        except ClientError as e:
            self.logger.warning(f"Error fetching API Gateway metrics: {e}")
        except Exception as e:
            self.logger.error(f"Unexpected error in _get_api_gateway_metrics: {e}")
        
        return metrics
    
    def _get_lambda_metrics(self, function_names, start_time, end_time):
        """
        Get Lambda metrics from CloudWatch.
        
        Args:
            function_names: List of Lambda function names
            start_time: Start time for metrics
            end_time: End time for metrics
        
        Returns:
            dict: Lambda metrics
        """
        metrics = {
            'invocation_count': 0,
            'error_count': 0,
            'throttle_count': 0,
            'error_rate': 0
        }
        
        try:
            for function_name in function_names:
                # Get invocations
                response = self.cloudwatch.get_metric_statistics(
                    Namespace='AWS/Lambda',
                    MetricName='Invocations',
                    Dimensions=[
                        {'Name': 'FunctionName', 'Value': function_name}
                    ],
                    StartTime=start_time,
                    EndTime=end_time,
                    Period=60,
                    Statistics=['Sum']
                )
                
                if response['Datapoints']:
                    metrics['invocation_count'] += sum(dp['Sum'] for dp in response['Datapoints'])
                
                # Get errors
                response_errors = self.cloudwatch.get_metric_statistics(
                    Namespace='AWS/Lambda',
                    MetricName='Errors',
                    Dimensions=[
                        {'Name': 'FunctionName', 'Value': function_name}
                    ],
                    StartTime=start_time,
                    EndTime=end_time,
                    Period=60,
                    Statistics=['Sum']
                )
                
                if response_errors['Datapoints']:
                    metrics['error_count'] += sum(dp['Sum'] for dp in response_errors['Datapoints'])
                
                # Get throttles
                response_throttles = self.cloudwatch.get_metric_statistics(
                    Namespace='AWS/Lambda',
                    MetricName='Throttles',
                    Dimensions=[
                        {'Name': 'FunctionName', 'Value': function_name}
                    ],
                    StartTime=start_time,
                    EndTime=end_time,
                    Period=60,
                    Statistics=['Sum']
                )
                
                if response_throttles['Datapoints']:
                    metrics['throttle_count'] += sum(dp['Sum'] for dp in response_throttles['Datapoints'])
            
            # Calculate error rate
            if metrics['invocation_count'] > 0:
                metrics['error_rate'] = (metrics['error_count'] / metrics['invocation_count']) * 100
        
        except Exception as e:
            self.logger.error(f"Error in _get_lambda_metrics: {e}")
        
        return metrics
    
    def _get_dynamodb_metrics(self, table_names, start_time, end_time):
        """
        Get DynamoDB metrics from CloudWatch.
        
        Args:
            table_names: List of DynamoDB table names
            start_time: Start time for metrics
            end_time: End time for metrics
        
        Returns:
            dict: DynamoDB metrics
        """
        metrics = {
            'consumed_read_capacity': 0,
            'consumed_write_capacity': 0,
            'throttled_requests': 0
        }
        
        try:
            for table_name in table_names:
                # Get consumed read capacity
                response_read = self.cloudwatch.get_metric_statistics(
                    Namespace='AWS/DynamoDB',
                    MetricName='ConsumedReadCapacityUnits',
                    Dimensions=[
                        {'Name': 'TableName', 'Value': table_name}
                    ],
                    StartTime=start_time,
                    EndTime=end_time,
                    Period=60,
                    Statistics=['Sum']
                )
                
                if response_read['Datapoints']:
                    metrics['consumed_read_capacity'] += sum(dp['Sum'] for dp in response_read['Datapoints'])
                
                # Get consumed write capacity
                response_write = self.cloudwatch.get_metric_statistics(
                    Namespace='AWS/DynamoDB',
                    MetricName='ConsumedWriteCapacityUnits',
                    Dimensions=[
                        {'Name': 'TableName', 'Value': table_name}
                    ],
                    StartTime=start_time,
                    EndTime=end_time,
                    Period=60,
                    Statistics=['Sum']
                )
                
                if response_write['Datapoints']:
                    metrics['consumed_write_capacity'] += sum(dp['Sum'] for dp in response_write['Datapoints'])
                
                # Get throttled requests
                response_throttles = self.cloudwatch.get_metric_statistics(
                    Namespace='AWS/DynamoDB',
                    MetricName='UserErrors',
                    Dimensions=[
                        {'Name': 'TableName', 'Value': table_name}
                    ],
                    StartTime=start_time,
                    EndTime=end_time,
                    Period=60,
                    Statistics=['Sum']
                )
                
                if response_throttles['Datapoints']:
                    metrics['throttled_requests'] += sum(dp['Sum'] for dp in response_throttles['Datapoints'])
        
        except Exception as e:
            self.logger.error(f"Error in _get_dynamodb_metrics: {e}")
        
        return metrics
    
    def _calculate_summary(self, metrics):
        """
        Calculate summary metrics across all services.
        
        Args:
            metrics: Dict containing all service metrics
        
        Returns:
            dict: Summary metrics
        """
        summary = {
            'total_rps': 0,
            'total_error_rate': 0,
            'avg_latency': 0,
            'status': 'healthy'
        }
        
        try:
            # Get RPS from API Gateway
            summary['total_rps'] = metrics['api_gateway'].get('rps', 0)
            
            # Get error rate from API Gateway
            summary['total_error_rate'] = metrics['api_gateway'].get('error_rate', 0)
            
            # Get latency from API Gateway
            summary['avg_latency'] = metrics['api_gateway'].get('latency_avg', 0)
            
            # Determine status
            if summary['total_error_rate'] > 5:
                summary['status'] = 'degraded'
            elif summary['total_error_rate'] > 10:
                summary['status'] = 'unhealthy'
            elif metrics['lambda'].get('throttle_count', 0) > 0:
                summary['status'] = 'throttled'
        
        except Exception as e:
            self.logger.error(f"Error in _calculate_summary: {e}")
        
        return summary
    
    def _empty_metrics(self):
        """
        Return empty metrics structure.
        
        Returns:
            dict: Empty metrics
        """
        return {
            'timestamp': None,
            'api_gateway': {},
            'lambda': {},
            'dynamodb': {},
            'summary': {
                'total_rps': 0,
                'total_error_rate': 0,
                'avg_latency': 0,
                'status': 'unknown'
            }
        }




# ============================================================================
# REALISTIC GAMEPLAY SIMULATOR
# ============================================================================

class RealisticGameplaySimulator:
    """
    Simulates realistic player behavior with natural pauses and varied API call patterns.
    
    Manages behavior profiles (casual, competitive, hardcore) and session progression
    (early, mid, late) to create authentic gameplay patterns that accurately represent
    real-world player interactions.
    
    Requirements: 30.1, 30.2, 30.8, 30.11-30.14
    Design: Section 33.1
    """
    
    def __init__(self, player_id, behavior_profile=None):
        """
        Initialize realistic gameplay simulator.
        
        Args:
            player_id: Player identifier
            behavior_profile: Behavior profile name ('casual', 'competitive', 'hardcore')
                            If None, uses DEFAULT_BEHAVIOR_PROFILE
        
        Requirements: 30.11
        """
        self.player_id = player_id
        
        # Select behavior profile
        if behavior_profile is None:
            behavior_profile = DEFAULT_BEHAVIOR_PROFILE
        
        if behavior_profile not in BEHAVIOR_PROFILES:
            raise ValueError(
                f"Invalid behavior profile: {behavior_profile}. "
                f"Must be one of: {list(BEHAVIOR_PROFILES.keys())}"
            )
        
        self.behavior_profile_name = behavior_profile
        self.profile = BEHAVIOR_PROFILES[behavior_profile]
        
        # Session state
        self.session_phase = 'early'  # early, mid, late
        self.session_start_time = None
        self.session_duration = None
        self.personal_best_score = None
        
        # Behavior tracking for logging (Requirement 30.15)
        self.action_history = []
        self.pause_history = []
    
    def start_session(self, duration_seconds):
        """
        Start a gameplay session.
        
        Args:
            duration_seconds: Total session duration in seconds
        
        Requirements: 30.1
        """
        self.session_start_time = time.time()
        self.session_duration = duration_seconds
        self.session_phase = 'early'
        self.action_history = []
        self.pause_history = []
    
    def update_session_phase(self):
        """
        Update session phase based on elapsed time.
        
        Phases:
        - early: 0-30% of session (focus on gameplay)
        - mid: 30-70% of session (balanced)
        - late: 70-100% of session (more checking)
        
        Requirements: 30.6
        """
        if self.session_start_time is None or self.session_duration is None:
            return
        
        elapsed = time.time() - self.session_start_time
        progress = elapsed / self.session_duration
        
        if progress < 0.3:
            self.session_phase = 'early'
        elif progress < 0.7:
            self.session_phase = 'mid'
        else:
            self.session_phase = 'late'
    
    def select_next_action(self):
        """
        Select next action based on current session phase and behavior profile.
        
        Returns:
            str: Action type ('submit_stats', 'check_leaderboard', 'check_standing')
        
        Requirements: 30.1, 30.6
        """
        # Get weights for current session phase
        phase_pattern = SESSION_BEHAVIOR_PATTERNS[self.session_phase]
        
        # Select action using weighted random choice
        actions = ['submit_stats', 'check_leaderboard', 'check_standing']
        weights = [
            phase_pattern['submit_stats_weight'],
            phase_pattern['check_leaderboard_weight'],
            phase_pattern['check_standing_weight']
        ]
        
        action = random.choices(actions, weights=weights)[0]
        
        # Log action for analysis (Requirement 30.15)
        self.action_history.append({
            'action': action,
            'timestamp': time.time(),
            'session_phase': self.session_phase
        })
        
        return action
    
    def generate_pause_duration(self, action_type='general'):
        """
        Generate realistic pause duration based on action type and behavior profile.
        
        Args:
            action_type: Type of action ('general', 'rapid', 'deliberate', 'refresh')
        
        Returns:
            float: Pause duration in seconds
        
        Requirements: 30.2, 30.8
        """
        if action_type == 'rapid':
            # Rapid actions: 100-500ms (Requirement 30.8)
            pause_ms = random.randint(*self.profile['rapid_action_pause_ms'])
        elif action_type == 'deliberate':
            # Deliberate actions: 1-3 seconds (Requirement 30.8)
            pause_ms = random.randint(*self.profile['deliberate_action_pause_ms'])
        elif action_type == 'refresh':
            # Between leaderboard refreshes: 2-5 seconds (Requirement 30.4)
            pause_seconds = random.uniform(*self.profile['refresh_interval_seconds'])
            pause_ms = pause_seconds * 1000
        else:
            # General pause between actions (Requirement 30.2)
            pause_ms = random.randint(*self.profile['pause_range_ms'])
        
        pause_seconds = pause_ms / 1000.0
        
        # Log pause for analysis (Requirement 30.15)
        self.pause_history.append({
            'duration_ms': pause_ms,
            'action_type': action_type,
            'timestamp': time.time()
        })
        
        return pause_seconds
    
    def should_check_leaderboard(self):
        """
        Determine if player should check leaderboard based on behavior profile.
        
        Returns:
            bool: True if should check leaderboard
        
        Requirements: 30.11, 30.12, 30.13, 30.14
        """
        return random.random() < self.profile['leaderboard_check_probability']
    
    def get_consecutive_refresh_count(self):
        """
        Get number of consecutive leaderboard refreshes to perform.
        
        Returns:
            int: Number of refreshes (1-5 depending on profile)
        
        Requirements: 30.3, 30.4
        """
        min_refreshes, max_refreshes = self.profile['consecutive_refreshes']
        return random.randint(min_refreshes, max_refreshes)
    
    def check_for_personal_best(self, new_score):
        """
        Check if new score is a personal best.
        
        Args:
            new_score: New score achieved
        
        Returns:
            bool: True if new personal best
        
        Requirements: 30.7
        """
        if self.personal_best_score is None:
            self.personal_best_score = new_score
            return True
        
        if new_score > self.personal_best_score:
            self.personal_best_score = new_score
            return True
        
        return False
    
    def get_next_action(self):
        """
        Get next action for the player (alias for select_next_action for compatibility).
        
        Returns:
            str: Action type ('submit_score', 'check_leaderboard', 'check_stats', 'check_standing', 'pause')
        
        Requirements: 35.3
        """
        # Update session phase
        self.update_session_phase()
        
        # Select action based on current phase
        action = self.select_next_action()
        
        # Map action names to match API call expectations
        action_mapping = {
            'submit_stats': 'submit_score',
            'check_leaderboard': 'check_leaderboard',
            'check_standing': 'check_standing'
        }
        
        return action_mapping.get(action, action)
    
    def get_action_interval(self):
        """
        Get interval until next action in milliseconds.
        
        Returns:
            int: Interval in milliseconds (respects MIN/MAX_ACTION_INTERVAL_MS bounds)
        
        Requirements: 35.4
        """
        # Generate pause duration based on general action type
        pause_seconds = self.generate_pause_duration('general')
        pause_ms = int(pause_seconds * 1000)
        
        # Return interval (will be clamped by caller to MIN/MAX_ACTION_INTERVAL_MS)
        return pause_ms
    
    def get_behavior_summary(self):
        """
        Get summary of behavior patterns for logging and analysis.
        
        Returns:
            dict: Behavior summary with action counts, pause statistics
        
        Requirements: 30.15
        """
        if not self.action_history:
            return {
                'profile': self.behavior_profile_name,
                'total_actions': 0,
                'action_breakdown': {},
                'pause_statistics': {}
            }
        
        # Count actions by type
        action_counts = {}
        for entry in self.action_history:
            action = entry['action']
            action_counts[action] = action_counts.get(action, 0) + 1
        
        # Calculate pause statistics
        if self.pause_history:
            pause_durations = [p['duration_ms'] for p in self.pause_history]
            avg_pause = sum(pause_durations) / len(pause_durations)
            min_pause = min(pause_durations)
            max_pause = max(pause_durations)
        else:
            avg_pause = 0
            min_pause = 0
            max_pause = 0
        
        return {
            'profile': self.behavior_profile_name,
            'total_actions': len(self.action_history),
            'action_breakdown': action_counts,
            'pause_statistics': {
                'avg_ms': avg_pause,
                'min_ms': min_pause,
                'max_ms': max_pause,
                'total_pauses': len(self.pause_history)
            },
            'session_phase': self.session_phase,
            'personal_best': self.personal_best_score
        }


# ============================================================================
# SECTION: TEST PAUSE AND RESUME MANAGEMENT
# ============================================================================

class TestPauseResumeManager:
    """
    Test Pause and Resume Manager - handles pausing and resuming test execution.
    
    Monitors Test Definitions Table for status changes and coordinates
    pause/resume operations across all worker threads.
    
    Requirements: 33.1, 33.2, 33.7, 33.16
    Design: Section 36.1
    """
    
    def __init__(self, test_config_id, region, profile, logger):
        """
        Initialize the pause/resume manager.
        
        Args:
            test_config_id: Test Config ID
            region: AWS region
            profile: AWS profile name (optional)
            logger: Logger instance
        
        Requirements: 33.1
        """
        self.test_config_id = test_config_id
        self.region = region
        self.profile = profile
        self.logger = logger
        
        # Pause/resume state tracking
        self.current_status = 'RUNNING'  # Test starts in RUNNING state
        self.pause_start_time = None
        self.total_pause_duration = 0.0  # in seconds
        self.pause_count = 0
        
        # Status polling
        self.last_poll_time = None
        self.poll_interval = STATUS_POLL_INTERVAL  # seconds (Requirement 33.7)
        
        self.logger.info("TestPauseResumeManager initialized")
    
    def check_status_change(self):
        """
        Poll Test Definitions Table to check for status changes.
        
        Returns:
            tuple: (status_changed: bool, new_status: str, reason: str)
        
        Requirements: 33.2, 33.7
        """
        
        # Check if it's time to poll
        current_time = time.time()
        if self.last_poll_time and (current_time - self.last_poll_time) < self.poll_interval:
            return (False, self.current_status, None)
        
        self.last_poll_time = current_time
        
        try:
            # Create boto3 session
            session_kwargs = {'region_name': self.region}
            if self.profile:
                session_kwargs['profile_name'] = self.profile
            
            session = boto3.Session(**session_kwargs)
            dynamodb = session.resource('dynamodb')
            table = dynamodb.Table(TEST_DEFINITIONS_TABLE_NAME)
            
            # Query METADATA record for current status
            response = table.get_item(
                Key={
                    'TestConfigID': self.test_config_id,
                    'ConfigCategory': 'METADATA'
                }
            )
            
            if 'Item' not in response:
                self.logger.warning(f"METADATA record not found for Test Config ID: {self.test_config_id}")
                return (False, self.current_status, None)
            
            item = response['Item']
            new_status = item.get('Status', 'RUNNING')  # Default to RUNNING during execution
            pause_reason = item.get('PauseReason', None)
            
            # Check if status changed
            if new_status != self.current_status:
                self.logger.info(f"Status change detected: {self.current_status} → {new_status}")
                if pause_reason:
                    self.logger.info(f"  Reason: {pause_reason}")
                
                old_status = self.current_status
                self.current_status = new_status
                
                return (True, new_status, pause_reason)
            
            return (False, self.current_status, None)
            
        except ClientError as e:
            self.logger.error(f"Error checking status: {e}")
            return (False, self.current_status, None)
        except Exception as e:
            self.logger.error(f"Unexpected error checking status: {e}")
            return (False, self.current_status, None)
    
    def record_pause_start(self):
        """
        Record the start of a pause period.
        
        Requirements: 33.9, 33.16
        """
        
        self.pause_start_time = time.time()
        self.pause_count += 1
        
        self.logger.info(f"Pause started at {time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(self.pause_start_time))}")
        self.logger.info(f"  Pause count: {self.pause_count}")
    
    def record_pause_end(self):
        """
        Record the end of a pause period and calculate duration.
        
        Requirements: 33.15, 33.16
        """
        
        if self.pause_start_time is None:
            self.logger.warning("Pause end recorded but no pause start time found")
            return
        
        pause_end_time = time.time()
        pause_duration = pause_end_time - self.pause_start_time
        self.total_pause_duration += pause_duration
        
        self.logger.info(f"Pause ended at {time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(pause_end_time))}")
        self.logger.info(f"  Pause duration: {pause_duration:.2f} seconds ({pause_duration/60:.2f} minutes)")
        self.logger.info(f"  Total pause duration: {self.total_pause_duration:.2f} seconds ({self.total_pause_duration/60:.2f} minutes)")
        
        self.pause_start_time = None
    
    def get_total_pause_duration(self):
        """
        Get the total pause duration in seconds.
        
        Returns:
            float: Total pause duration in seconds
        
        Requirements: 33.16
        """
        return self.total_pause_duration
    
    def get_pause_statistics(self):
        """
        Get pause statistics for reporting.
        
        Returns:
            dict: Pause statistics including count, total duration, etc.
        
        Requirements: 33.16
        """
        return {
            'pause_count': self.pause_count,
            'total_pause_duration_seconds': self.total_pause_duration,
            'total_pause_duration_minutes': self.total_pause_duration / 60,
            'total_pause_duration_hours': self.total_pause_duration / 3600,
            'current_status': self.current_status,
            'currently_paused': self.pause_start_time is not None
        }


# ============================================================================
# SECTION: MAIN CONTROLLER
# ============================================================================

class MainController:
    """
    Main Controller Thread that orchestrates the entire test execution.
    
    Responsibilities:
    - Load and manage test configuration
    - Spawn and manage worker threads
    - Monitor system resources
    - Handle graceful shutdown
    - Generate final reports
    
    Requirements: 10.1, 10.2, 10.3, 10.4, 10.5, 10.6
    Design: Section 4.1
    """
    
    def __init__(self, test_config_id, config, aws_session, logger, api_logger, instance_id=None, owns_global_lock=False):
        """
        Initialize Main Controller.
        
        Args:
            test_config_id: Test Config ID
            config: Test configuration dictionary
            aws_session: boto3 Session object
            logger: ThreadSafeLogger instance
            api_logger: WorkerLogger instance for centralized API logging
            instance_id: Unique instance identifier (optional)
            owns_global_lock: Whether this instance owns the global test lock (optional)
        
        Requirements: 10.1, 10.2
        """
        self.test_config_id = test_config_id
        self.config = config
        self.aws_session = aws_session
        self.logger = logger
        self.api_logger = api_logger  # Centralized API logger for priming phase
        self.region = config.get('region', DEFAULT_AWS_REGION)
        self.instance_id = instance_id
        self.owns_global_lock = owns_global_lock  # Track if this instance owns the lock
        self.lock_released = False  # Track if lock has been released
        
        # Worker thread management
        self.event_manager = None
        self.batch_workers = []
        self.player_workers = []
        self.worker_threads = []
        
        # Web server process tracking
        self.http_server_process = None
        self.cors_proxy_process = None
        
        # Shutdown control
        self.shutdown_event = threading.Event()
        self.shutdown_requested = False
        
        # Resource monitoring
        self.resource_monitor_thread = None
        self.config_reload_thread = None
        self.lock_heartbeat_thread = None  # Global test lock heartbeat thread
        
        # Metrics collection (Requirements 19.4, 19.5, 19.6)
        self.metrics_collector = MetricsCollector()
        
        # Console status tracking
        self._status_line_printed = False  # Track if we've printed status line before
        
        # CloudWatch metrics publisher (Requirements 20.1, 20.2, 20.3)
        self.cloudwatch_publisher = CloudWatchMetricsPublisher(
            aws_session=aws_session,
            test_config_id=test_config_id,
            region=self.region,
            logger=logger
        )
        
        # SNS alert publisher (Requirements 21.1, 21.2, 21.5, 21.6, 21.7, 21.8, 21.11)
        sns_topic_arn = config.get('sns_topic_arn')  # Optional SNS topic for alerts
        self.alert_publisher = SNSAlertPublisher(
            aws_session=aws_session,
            sns_topic_arn=sns_topic_arn,
            test_config_id=test_config_id,
            logger=logger,
            suppression_window=config.get('alert_suppression_window', 300)
        )
        
        # Alert monitor (Requirements 21.1, 21.3, 21.4, 21.5)
        self.alert_monitor = AlertMonitor(
            alert_publisher=self.alert_publisher,
            logger=logger,
            config=config
        )
        
        # Setup adaptive scaling config based on max_players (if not already set)
        # Respect MIN_PLAYERS_PER_INSTANCE and MAX_PLAYERS_PER_INSTANCE constants
        max_players = config.get('max_players') or DEFAULT_PLAYERS_PER_INSTANCE
        
        # Ensure max_players is within valid range
        max_players = max(MIN_PLAYERS_PER_INSTANCE, min(max_players, MAX_PLAYERS_PER_INSTANCE))
        
        # Calculate player worker count (95% of max_players)
        player_worker_count = int(max_players * 0.95)
        
        if 'initial_player_threads' not in config:
            # Initial threads: 15% of player workers (but at least MIN_PLAYERS_PER_INSTANCE)
            config['initial_player_threads'] = max(MIN_PLAYERS_PER_INSTANCE, int(player_worker_count * 0.15))
        if 'min_player_threads' not in config:
            # Min threads: 5% of player workers (but at least MIN_PLAYERS_PER_INSTANCE)
            config['min_player_threads'] = max(MIN_PLAYERS_PER_INSTANCE, int(player_worker_count * 0.05))
        if 'max_player_threads' not in config:
            # Max threads: all player workers (95% of max_players)
            config['max_player_threads'] = player_worker_count
        
        # Adaptive concurrency scaler (Requirements 15.1-15.11)
        self.adaptive_scaler = AdaptiveConcurrencyScaler(
            config=config,
            logger=logger
        )
        
        # Performance monitor (Requirements 28.1-28.15)
        self.performance_monitor = PerformanceMonitor(config=config)
        
        # Consistency validator (Requirements 29.1-29.14)
        # Check if consistency validation is enabled (default: True)
        consistency_validation_enabled = config.get('consistency_validation_enabled', True)
        if consistency_validation_enabled:
            self.consistency_validator = ConsistencyValidator(
                logger=logger,
                sampling_rate=config.get('consistency_sampling_rate', CONSISTENCY_SAMPLING_RATE),
                failure_threshold=config.get('consistency_failure_threshold', CONSISTENCY_FAILURE_THRESHOLD),
                validation_timeout=config.get('consistency_validation_timeout', CONSISTENCY_VALIDATION_TIMEOUT)
            )
            self.logger.info("Consistency validation enabled")
        else:
            self.consistency_validator = None
            self.logger.info("Consistency validation disabled")
        
        # Pause/Resume manager (Requirements 33.1-33.18, Task 30.1)
        self.pause_resume_manager = TestPauseResumeManager(
            test_config_id=test_config_id,
            region=self.region,
            profile=config.get('aws_profile'),
            logger=logger
        )
        self.is_paused = False
        
        # Event expiry cache (shared across all workers to avoid redundant checks)
        # Maps event_name -> {'expired': bool, 'end_time': int, 'last_check': float}
        self._event_expiry_cache = {}
        self._event_expiry_cache_lock = threading.Lock()
        self._event_expiry_cache_ttl = 5  # Cache TTL in seconds (check every 5s max)
        
        # Metrics and statistics
        self.start_time = None
        self.end_time = None
        self.total_api_calls = 0
        self.total_errors = 0
        
        # Track maximum worker counts for PRIMARY instance (for accurate reporting)
        # PRIMARY doesn't publish to DynamoDB, so we track maximums locally
        self.max_player_workers = 0
        self.max_batch_workers = 0
        
        # Data generator factory
        self.generator_factory = None
        
        self.logger.info(f"Main Controller initialized for Test Config ID: {test_config_id}")
    
    def initialize(self):
        """
        Initialize test execution environment.
        
        Sets up:
        - Data generator factory
        - Signal handlers for graceful shutdown
        - Resource monitoring
        - Configuration hot-reload
        - Leaderboard visualization webpage
        
        Requirements: 10.1, 25.1, 32.1
        """
        self.logger.info("Initializing test execution environment...")
        
        # Create data generator factory
        self.generator_factory = DataGeneratorFactory(self.config)
        self.logger.info("✓ Data generator factory created")
        
        # Generate leaderboard visualization webpage (Requirements 25.1, 32.1, 32.2, 32.3)
        # Only PRIMARY instance should generate webpage and launch servers
        if self.owns_global_lock:
            try:
                webpage_generator = LeaderboardWebpageGenerator(
                    test_config_id=self.test_config_id,
                    config=self.config,
                    logger=self.logger,
                    instance_id=self.instance_id
                )
                # Use reports directory relative to test script location
                reports_dir = Path(__file__).parent / 'reports'
                webpage_path = webpage_generator.generate_webpage(output_dir=str(reports_dir))
                self.logger.info(f"✓ Leaderboard visualization webpage generated: {webpage_path}")
                
                # Launch HTTP server and CORS proxy for the leaderboard viewer
                try:
                    self._launch_leaderboard_servers(reports_dir, webpage_path)
                except Exception as server_error:
                    self.logger.warning(f"Failed to launch leaderboard servers: {server_error}")
                    self.logger.warning("You can manually start servers with:")
                    self.logger.warning(f"  python3 -m http.server 8000 --directory {reports_dir}")
                    self.logger.warning(f"  python3 {reports_dir}/cors-proxy.py")
            except Exception as e:
                self.logger.warning(f"Failed to generate leaderboard webpage: {e}")
                # Continue initialization even if webpage generation fails
        else:
            self.logger.info("Skipping webpage generation and server launch (WORKER instance)")
        
        # Set up signal handlers for graceful shutdown
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)
        self.logger.info("✓ Signal handlers registered")
        
        # Start resource monitoring thread
        self.resource_monitor_thread = threading.Thread(
            target=self._resource_monitor_loop,
            name="ResourceMonitor",
            daemon=True
        )
        self.resource_monitor_thread.start()
        self.logger.info("✓ Resource monitoring started")
        
        # Start configuration hot-reload thread
        self.config_reload_thread = threading.Thread(
            target=self._config_reload_loop,
            name="ConfigReload",
            daemon=True
        )
        self.config_reload_thread.start()
        self.logger.info("✓ Configuration hot-reload started")
        
        # Start global test lock heartbeat thread (only if this instance owns the lock)
        if self.owns_global_lock:
            self.lock_heartbeat_thread = threading.Thread(
                target=self._lock_heartbeat_loop,
                name="LockHeartbeat",
                daemon=True
            )
            self.lock_heartbeat_thread.start()
            self.logger.info("✓ Global test lock heartbeat started")
        
        self.logger.info("Test execution environment initialized successfully")
    
    def prime_leaderboards(self):
        """
        Prime ALL leaderboards with initial data to avoid "player not found" errors.
        
        Submits initial scores for a subset of players to EVERY leaderboard
        before starting the main test execution. This ensures:
        - Every leaderboard has players for aroundPlayer queries
        - Standing checks don't return 404 errors
        - More realistic test conditions from the start
        
        Priming strategy:
        - Number of players: 10% of max_players (min 10, max 100)
        - Scores per leaderboard: 2-3 per player
        - Covers ALL leaderboards, not just random selection
        
        IMPORTANT: Skips priming if leaderboards already contain data (from previous runs).
        
        Requirements: Reduces API errors, improves test realism
        """
        
        self.logger.info("=" * 80)
        self.logger.info("PRIMING LEADERBOARDS WITH INITIAL DATA")
        self.logger.info("=" * 80)
        
        # Get configuration
        api_base_url = self.config.get('api_base_url')
        api_key = self.config.get('api_key')
        game_id = self.config.get('game_id')
        player_pool = self.config.get('player_pool', {})
        pool_size = int(player_pool.get('poolSize', 10000))  # Ensure integer
        all_leaderboard_configs = self.config.get('leaderboard_configs', [])
        max_players = int(self.config.get('max_players') or DEFAULT_PLAYERS_PER_INSTANCE)  # Ensure integer
        
        if not api_base_url or not api_key or not game_id:
            self.logger.warning("⚠ Skipping leaderboard priming: Missing API configuration")
            return
        
        if not all_leaderboard_configs:
            self.logger.warning("⚠ Skipping leaderboard priming: No leaderboards configured")
            return
        
        # Filter out event leaderboards - they don't exist yet and will be created dynamically
        leaderboard_configs = [lb for lb in all_leaderboard_configs if not lb.get('leaderboardName', '').startswith('event-')]
        
        if not leaderboard_configs:
            self.logger.warning("⚠ Skipping leaderboard priming: Only event leaderboards configured (will be created dynamically)")
            return
        
        self.logger.info(f"Filtered leaderboards for priming: {len(leaderboard_configs)} standard (excluded {len(all_leaderboard_configs) - len(leaderboard_configs)} event leaderboards)")
        
        # CRITICAL: Check if leaderboards already have data (from previous runs)
        # If they do, skip priming to avoid unnecessary API calls and duplicate data
        self.logger.info("Checking if leaderboards already contain data...")
        
        try:
            # Check standard leaderboards (not event leaderboards) to see if they have data
            # We only check standard leaderboards because event leaderboards are temporary
            # Stop checking as soon as we find one with data
            leaderboards_to_check = leaderboard_configs[:min(5, len(leaderboard_configs))]
            
            self.logger.info(f"  Will check up to {len(leaderboards_to_check)} leaderboards...")
            
            for lb in leaderboards_to_check:
                check_endpoint = f"{api_base_url}/leaderboards/scores"
                
                # Simple API call - just needs leaderboardName and pageSize
                check_body = {
                    "leaderboardScoresRequest": {
                        "leaderboardName": lb.get('leaderboardName'),
                        "queryType": "top",
                        "pageSize": 1  # Just check if any scores exist
                    }
                }
                
                headers = {
                    'Content-Type': 'application/json',
                    'Authorization': f'Bearer {api_key}'
                }
                
                try:
                    check_response = requests.post(
                        check_endpoint,
                        json=check_body,
                        headers=headers,
                        timeout=API_TIMEOUT_READ
                    )
                    
                    if check_response.status_code == 200:
                        check_data = check_response.json()
                        scores_response = check_data.get('leaderboardScoresResponse', {})
                        metadata = scores_response.get('metadata', {})
                        total_players = metadata.get('totalPlayers', 0)
                        
                        if total_players > 0:
                            self.logger.info(f"  ✓ '{lb.get('leaderboardName')}' has {total_players} players")
                            self.logger.info(f"✓ Found leaderboard with existing data - skipping priming phase")
                            self.logger.info("=" * 80)
                            return
                        else:
                            self.logger.info(f"  ✗ '{lb.get('leaderboardName')}' is empty (totalPlayers: {total_players})")
                    elif check_response.status_code == 404:
                        # Leaderboard config doesn't exist yet - will be created during test
                        self.logger.info(f"  ✗ '{lb.get('leaderboardName')}' not found (config will be created)")
                    else:
                        self.logger.warning(f"  ? '{lb.get('leaderboardName')}' check failed (HTTP {check_response.status_code})")
                        
                except Exception as check_ex:
                    self.logger.warning(f"  ? '{lb.get('leaderboardName')}' check error: {check_ex}")
            
            # If we get here, none of the checked leaderboards have data
            self.logger.info(f"  All checked leaderboards are empty - proceeding with priming")
                
        except Exception as check_error:
            self.logger.warning(f"  Failed to check existing data: {check_error}")
            self.logger.warning("  Proceeding with priming anyway...")
        
        # Calculate number of priming players based on test size
        # Use 10% of max_players, but at least 10 and at most 100
        num_priming_players = max(10, min(100, int(max_players * 0.10)))
        
        # Get ID prefix from player pool config
        id_prefix = player_pool.get('idPrefix', 'player')
        
        # Select random players from the pool using correct format
        priming_players = [f"{id_prefix}_{random.randint(1, pool_size):06d}" for _ in range(num_priming_players)]
        
        self.logger.info(f"Priming strategy:")
        self.logger.info(f"  Players: {num_priming_players} (10% of {max_players} max_players)")
        self.logger.info(f"  Leaderboards: {len(leaderboard_configs)} (ALL will be primed)")
        self.logger.info(f"  Scores per player per leaderboard: 2-3")
        self.logger.info(f"  Estimated total submissions: {num_priming_players * len(leaderboard_configs) * 2.5:.0f}")
        
        total_submissions = 0
        total_errors = 0
        start_time = time.time()
        
        # Prime EACH leaderboard with scores from ALL priming players
        for lb_idx, leaderboard in enumerate(leaderboard_configs, 1):
            leaderboard_name = leaderboard.get('leaderboardName')
            game_mode = leaderboard.get('gameMode')
            
            self.logger.info(f"[{lb_idx}/{len(leaderboard_configs)}] Priming leaderboard: {leaderboard_name} (mode: {game_mode})")
            
            lb_submissions = 0
            lb_errors = 0
            
            # Submit scores from each priming player to this leaderboard
            for player_id in priming_players:
                # Submit 2-3 scores per player to this leaderboard
                num_scores = random.randint(2, 3)
                
                for _ in range(num_scores):
                    try:
                        # Generate score
                        score_generator = self.generator_factory.get_score_generator()
                        player_score = score_generator.generate_score(leaderboard_name, 'intermediate')
                        
                        # Generate game report with correct parameters
                        game_report_generator = self.generator_factory.get_game_report_generator()
                        session_id = f"priming_{player_id}_{int(time.time())}"
                        player_state = {'level': 1}
                        full_raw_game_report = game_report_generator.generate_game_report(
                            player_id,
                            game_mode,
                            session_id,
                            player_state
                        )
                        
                        # Submit score
                        endpoint = f"{api_base_url}/leaderboards/stats"
                        request_body = {
                            "gameReportBody": {
                                "playerID": player_id,
                                "gameID": game_id,
                                "gameMode": game_mode,
                                "playerScore": player_score,
                                "leaderboardName": leaderboard_name,
                                "fullRawGameReport": full_raw_game_report
                            }
                        }
                        
                        headers = {
                            'Authorization': f'Bearer {api_key}',
                            'Content-Type': 'application/json'
                        }
                        
                        response = requests.post(
                            endpoint,
                            json=request_body,
                            headers=headers,
                            timeout=10
                        )
                        
                        # Generate event ID for log correlation
                        event_id = generate_event_id()
                        
                        # Calculate latency
                        latency_ms = 0  # We don't track latency for priming, but include for consistency
                        
                        # Log priming request to api-calls.log
                        try:
                            response_data = response.json() if response.headers.get('content-type', '').startswith('application/json') else response.text
                        except:
                            response_data = response.text
                        
                        self.api_logger.log_api_call(
                            endpoint=endpoint,
                            method='POST',
                            request_data=request_body,
                            response_data=response_data,
                            latency_ms=latency_ms,
                            status_code=response.status_code,
                            event_id=event_id,
                            request_headers=headers,
                            response_headers=dict(response.headers)
                        )
                        
                        if response.status_code == 200:
                            total_submissions += 1
                            lb_submissions += 1
                        else:
                            total_errors += 1
                            lb_errors += 1
                            self.logger.debug(f"Priming error for {player_id} on {leaderboard_name}: {response.status_code}")
                        
                        # Small delay to avoid overwhelming the API (100ms between requests)
                        time.sleep(0.1)
                        
                    except Exception as e:
                        total_errors += 1
                        lb_errors += 1
                        self.logger.debug(f"Priming exception for {player_id} on {leaderboard_name}: {e}")
            
            # Report progress for this leaderboard
            elapsed = time.time() - start_time
            rate = total_submissions / elapsed if elapsed > 0 else 0
            self.logger.info(
                f"  ✓ {leaderboard_name}: {lb_submissions} submissions, {lb_errors} errors "
                f"(Overall: {total_submissions} total, {rate:.1f} req/s)"
            )
        
        elapsed_time = time.time() - start_time
        success_rate = (total_submissions / (total_submissions + total_errors) * 100) if (total_submissions + total_errors) > 0 else 0
        
        self.logger.info("=" * 80)
        self.logger.info("LEADERBOARD PRIMING COMPLETE")
        self.logger.info("=" * 80)
        self.logger.info(f"Leaderboards primed: {len(leaderboard_configs)}")
        self.logger.info(f"Players used: {num_priming_players}")
        self.logger.info(f"Total submissions: {total_submissions}")
        self.logger.info(f"Total errors: {total_errors}")
        self.logger.info(f"Success rate: {success_rate:.1f}%")
        self.logger.info(f"Duration: {elapsed_time:.1f}s")
        self.logger.info(f"Average rate: {total_submissions / elapsed_time:.1f} req/s")
        self.logger.info("=" * 80)
        print()
    
    def spawn_worker_threads(self):
        """
        Spawn all worker threads based on configuration.
        
        Spawns:
        - 1 Event Manager Thread (if this instance claims the role)
        - Batch Worker Threads (5% of total, during events)
        - Player Worker Threads (95% of total)
        
        Requirements: 10.2, 10.3, 10.4
        """
        self.logger.info("Spawning worker threads...")
        
        # Get max_players, ensuring it's never None
        max_players = self.config.get('max_players') or DEFAULT_PLAYERS_PER_INSTANCE
        
        # Debug logging
        self.logger.info(f"Configuration max_players value: {self.config.get('max_players')}")
        self.logger.info(f"Using max_players: {max_players} (after None check)")
        
        # Spawn Event Manager Thread (only one across all instances)
        self.logger.info("Checking if Event Manager is already active...")
        event_manager_active = self._check_event_manager_active()
        
        if not event_manager_active:
            self.logger.info("Spawning Event Manager Thread...")
            self.event_manager = EventManagerThread(
                test_config_id=self.test_config_id,
                config=self.config,
                aws_session=self.aws_session,
                logger=self.logger,
                shutdown_event=self.shutdown_event,
                instance_id=self.instance_id,
                consistency_validator=self.consistency_validator
            )
            self.event_manager.start()
            self.worker_threads.append(self.event_manager)
            self.logger.info("✓ Event Manager Thread spawned")
        else:
            self.logger.info("Event Manager already active in another instance, skipping spawn")
            self.event_manager = None  # No event manager for this instance
        
        # Calculate worker thread distribution
        # MULTI-PLAYER THREADING: Each thread manages PLAYERS_PER_THREAD players (3)
        # Thread count = max_players / PLAYERS_PER_THREAD
        # Example: 300 players = 100 threads × 3 players per thread
        num_player_workers = max(1, int(max_players / PLAYERS_PER_THREAD))
        actual_player_capacity = num_player_workers * PLAYERS_PER_THREAD
        
        # Batch workers: 5% of total capacity (spawned during events)
        # These are separate additional threads that run ONLY during events
        # Example: 300 players → 15 batch workers
        num_batch_workers = max(1, int(actual_player_capacity * 0.05))
        
        self.logger.info(f"Multi-Player Threading Configuration:")
        self.logger.info(f"  Players per thread: {PLAYERS_PER_THREAD}")
        self.logger.info(f"  Player worker threads: {num_player_workers}")
        self.logger.info(f"  Total player capacity: {actual_player_capacity} ({num_player_workers} threads × {PLAYERS_PER_THREAD} players)")
        self.logger.info(f"  Batch workers (during events): {num_batch_workers} (5% of capacity)")
        
        self.logger.print_and_log(f"Spawning {num_player_workers} player worker threads (managing {actual_player_capacity} players)...")
        self.logger.print_and_log(f"Each thread manages {PLAYERS_PER_THREAD} players in round-robin fashion")
        
        for i in range(num_player_workers):
            worker = PlayerWorkerThread(
                worker_id=i,
                test_config_id=self.test_config_id,
                config=self.config,
                aws_session=self.aws_session,
                logger=self.logger,
                events_logger=self.api_logger,  # Pass events logger for centralized logging
                shutdown_event=self.shutdown_event,
                generator_factory=self.generator_factory,
                instance_id=self.instance_id,  # Pass instance_id for log file naming
                metrics_collector=self.metrics_collector,  # Pass metrics collector (Requirements 19.4, 19.5)
                consistency_validator=self.consistency_validator  # Pass consistency validator (Requirements 29.1-29.14)
            )
            worker.start()
            self.player_workers.append(worker)
            self.worker_threads.append(worker)
            
            # Stagger worker spawning to prevent thundering herd (DNS overload, file descriptor spikes)
            # Pause every 10 workers to allow boto3 clients to initialize gracefully
            if (i + 1) % 10 == 0:
                print(f"  Pausing 20s...\r")
                time.sleep(20)                      # 20s pause every 10 workers
                # Show progress every 10 workers
                print(f"  Spawned {i + 1}/{num_player_workers} player workers...\r")

        print(f"\n")

        # Final console update
        self.logger.print_and_log(f"[✓] Spawned {num_player_workers} player worker threads successfully!")
        self.logger.print_and_log(f"    Managing {actual_player_capacity} concurrent players ({PLAYERS_PER_THREAD} per thread)")
        self.logger.info(f"✓ {num_player_workers} Player Worker Threads spawned (capacity: {actual_player_capacity} players)")
        
        # Batch Workers are spawned dynamically during events
        # For now, log the planned count
        self.logger.info(f"Batch Workers will be spawned during events (planned: {num_batch_workers})")
        
        # Store planned batch worker count and actual player capacity for later use
        self.planned_batch_worker_count = num_batch_workers
        self.actual_player_capacity = actual_player_capacity
        
        self.logger.info(f"Worker thread spawning complete")
        self.logger.info(f"  Event Managers: 1")
        self.logger.info(f"  Player Workers: {num_player_workers} threads ({actual_player_capacity} players)")
        self.logger.info(f"  Batch Workers: {num_batch_workers} (spawned during events)")
        self.logger.info(f"  Player Workers: {len(self.player_workers)}")
        self.logger.info(f"  Batch Workers: {len(self.batch_workers)} (will spawn during events)")
        self.logger.info(f"  Total Active: {len(self.worker_threads)}")
    
    def is_event_expired(self, event_name, end_time):
        """
        Check if event has expired using cached status to avoid redundant checks.
        
        Uses a 5-second cache TTL to balance between:
        - Avoiding redundant checks by hundreds of workers
        - Detecting expiry reasonably quickly (within 5 seconds)
        
        Args:
            event_name: Name of the event
            end_time: Event end time (Unix timestamp)
        
        Returns:
            bool: True if event has expired, False otherwise
        """
        current_time = time.time()
        
        # Check cache first
        with self._event_expiry_cache_lock:
            if event_name in self._event_expiry_cache:
                cache_entry = self._event_expiry_cache[event_name]
                
                # If already marked as expired, return immediately (no need to recheck)
                if cache_entry['expired']:
                    return True
                
                # If cache is still fresh (within TTL), use cached result
                if current_time - cache_entry['last_check'] < self._event_expiry_cache_ttl:
                    return cache_entry['expired']
            
            # Cache miss or stale - check expiry
            current_timestamp = int(current_time)
            is_expired = current_timestamp >= end_time
            
            # Update cache
            self._event_expiry_cache[event_name] = {
                'expired': is_expired,
                'end_time': end_time,
                'last_check': current_time
            }
            
            return is_expired
    
    def _check_and_manage_batch_workers(self):
        """
        Check for active events and spawn/terminate batch workers accordingly.
        
        Polls DynamoDB for ACTIVE_EVENT record and:
        - Spawns batch workers when event becomes active
        - Terminates batch workers when event completes
        
        Called periodically from resource monitor loop.
        """
        try:
            # Reuse cached DynamoDB resource to prevent file descriptor leaks
            if not hasattr(self, '_dynamodb_cached'):
                self._dynamodb_cached = self.aws_session.resource('dynamodb')
            table = self._dynamodb_cached.Table(TEST_DEFINITIONS_TABLE_NAME)
            
            # Check for active event
            response = table.get_item(
                Key={
                    'TestConfigID': self.test_config_id,
                    'ConfigCategory': 'ACTIVE_EVENT'
                }
            )
            
            if 'Item' in response:
                # Active event found
                active_event = response['Item']
                event_status = active_event.get('Status', 'UNKNOWN')
                event_name = active_event.get('EventName', 'unknown')
                end_time = active_event.get('EndTime', 0)
                current_time = int(time.time())
                
                # Ensure end_time is an integer (handle Decimal from DynamoDB)
                if hasattr(end_time, '__int__'):
                    end_time = int(end_time)
                elif not isinstance(end_time, int):
                    self.logger.warning(f"[BATCH-CHECK] Invalid EndTime type: {type(end_time)}, value: {end_time}")
                    end_time = 0
                
                # Convert end_time to float if it's a Decimal (from DynamoDB)
                end_time_float = float(end_time) if isinstance(end_time, Decimal) else end_time
                current_time_float = float(current_time)
                
                self.logger.debug(f"[BATCH-CHECK] Found ACTIVE_EVENT: {event_name}, Status: {event_status}, EndTime: {end_time_float}, CurrentTime: {current_time_float}, Diff: {end_time_float - current_time_float}s")
                
                # Check if event has actually expired (even if Status is still 'ACTIVE')
                if current_time >= end_time:
                    self.logger.warning(f"[BATCH-CHECK] ⚠️  Event {event_name} has EXPIRED (ended at {end_time}, current: {current_time}, diff: {current_time - end_time}s ago), cleaning up...")
                    
                    # Delete the expired ACTIVE_EVENT record
                    table.delete_item(
                        Key={
                            'TestConfigID': self.test_config_id,
                            'ConfigCategory': 'ACTIVE_EVENT'
                        }
                    )
                    self.logger.info(f"[BATCH-CHECK] Cleaned up expired ACTIVE_EVENT record for {event_name}")
                    
                    # Terminate batch workers if running
                    if self.batch_workers:
                        self.logger.info(f"[BATCH-CHECK] Terminating batch workers for expired event...")
                        self._terminate_batch_workers()
                    
                elif event_status == 'ACTIVE' and not self.batch_workers:
                    # Event is truly active (not expired) and no batch workers spawned yet
                    # Convert end_time to float for comparison
                    end_time_float = float(end_time) if isinstance(end_time, Decimal) else end_time
                    current_time_float = float(current_time)
                    self.logger.info(f"[BATCH-CHECK] ✓ Event {event_name} is ACTIVE and NOT expired (ends at {end_time_float}, current: {current_time_float}, {end_time_float - current_time_float}s remaining), spawning batch workers...")
                    self._spawn_batch_workers(active_event)
                
                elif event_status == 'ACTIVE' and self.batch_workers:
                    # Event is active and batch workers already running
                    alive_count = len([w for w in self.batch_workers if w.is_alive()])
                    self.logger.info(f"[BATCH-CHECK] Event {event_name} is ACTIVE, batch workers already running ({alive_count}/{len(self.batch_workers)} alive)")
                
                else:
                    # Other status or condition
                    self.logger.info(f"[BATCH-CHECK] Event {event_name} status: {event_status}, batch_workers: {len(self.batch_workers)}, no action taken")
                    
            else:
                # No active event
                self.logger.debug(f"[BATCH-CHECK] No ACTIVE_EVENT found in DynamoDB")
                if self.batch_workers:
                    # Batch workers are running but event is over
                    self.logger.info(f"[BATCH-CHECK] No active event but batch workers running, terminating...")
                    self._terminate_batch_workers()
                    
        except Exception as e:
            self.logger.debug(f"Error checking active events: {e}")
            # Don't raise - this is a background check
    
    def _spawn_batch_workers(self, active_event):
        """
        Spawn batch worker threads for active event.
        
        Args:
            active_event: Active event dictionary from DynamoDB
        """
        event_name = active_event.get('EventName', 'unknown')
        event_type = active_event.get('EventType', 'unknown')
        
        self.logger.info("=" * 80)
        self.logger.info(f"SPAWNING BATCH WORKERS FOR EVENT: {event_name}")
        self.logger.info("=" * 80)
        self.logger.info(f"  Event Type: {event_type}")
        self.logger.info(f"  Batch Workers: {self.planned_batch_worker_count}")
        
        # Update config with active event info
        self.config['active_event'] = {
            'eventName': event_name,
            'eventType': event_type,
            'leaderboardConfig': active_event.get('LeaderboardConfig', {}),
            'startTime': active_event.get('StartTime'),
            'endTime': active_event.get('EndTime')
        }
        
        # Spawn batch workers
        for i in range(self.planned_batch_worker_count):
            worker = BatchWorkerThread(
                worker_id=i,
                test_config_id=self.test_config_id,
                config=self.config,
                aws_session=self.aws_session,
                logger=self.logger,
                shutdown_event=self.shutdown_event,
                generator_factory=self.generator_factory,
                metrics_collector=self.metrics_collector,  # Pass metrics collector for RPS tracking
                main_controller=self  # Pass MainController for cached event expiry checks
            )
            worker.start()
            self.batch_workers.append(worker)
            self.worker_threads.append(worker)
            
            # Stagger batch worker spawning to prevent thundering herd
            if (i + 1) % 5 == 0:
                time.sleep(0.1)  # 100ms pause every 5 workers

        
        self.logger.info(f"✓ Spawned {len(self.batch_workers)} Batch Worker Threads")
        self.logger.info("=" * 80)
    
    def _terminate_batch_workers(self):
        """
        Terminate batch worker threads when event completes.
        """
        if not self.batch_workers:
            return
        
        self.logger.info("=" * 80)
        self.logger.info("TERMINATING BATCH WORKERS (Event Completed)")
        self.logger.info("=" * 80)
        self.logger.info(f"  Batch Workers to terminate: {len(self.batch_workers)}")
        
        # Signal batch workers to stop by setting their shutdown events
        # Batch workers check shutdown_event in their loops
        for worker in self.batch_workers:
            if hasattr(worker, 'worker_shutdown_event'):
                worker.worker_shutdown_event.set()
        
        # Wait for workers to complete gracefully
        for worker in self.batch_workers:
            if worker.is_alive():
                worker.join(timeout=10)
                if worker.is_alive():
                    self.logger.warning(f"Batch worker {worker.worker_id} did not terminate within timeout")
        
        # Remove from worker lists
        for worker in self.batch_workers:
            if worker in self.worker_threads:
                self.worker_threads.remove(worker)
        
        terminated_count = len(self.batch_workers)
        self.batch_workers.clear()
        
        # Clear active event from config
        if 'active_event' in self.config:
            del self.config['active_event']
        
        self.logger.info(f"✓ Terminated {terminated_count} Batch Worker Threads")
        self.logger.info("=" * 80)
    
    def _cleanup_stale_active_events(self):
        """
        Clean up EXPIRED ACTIVE_EVENT and ADMIN_LOCK records from previous test runs.
        
        Only deletes ACTIVE_EVENT records where EndTime is in the past.
        This prevents deleting fresh ACTIVE_EVENT records created during priming.
        """
        try:
            if not hasattr(self, '_dynamodb_cached'):
                self._dynamodb_cached = self.aws_session.resource('dynamodb')
            table = self._dynamodb_cached.Table(TEST_DEFINITIONS_TABLE_NAME)
            
            current_time = int(time.time())
            
            # Clean up ACTIVE_EVENT record ONLY if expired
            response = table.get_item(
                Key={
                    'TestConfigID': self.test_config_id,
                    'ConfigCategory': 'ACTIVE_EVENT'
                }
            )
            
            if 'Item' in response:
                event_name = response['Item'].get('EventName', 'unknown')
                end_time = response['Item'].get('EndTime', 0)
                
                # Ensure end_time is an integer (handle Decimal from DynamoDB)
                if hasattr(end_time, '__int__'):
                    end_time = int(end_time)
                elif not isinstance(end_time, int):
                    end_time = 0
                
                # Only delete if event has EXPIRED (EndTime is in the past)
                if current_time >= end_time:
                    self.logger.info(f"Found EXPIRED ACTIVE_EVENT record for '{event_name}' from previous test run")
                    self.logger.info(f"Cleaning up ACTIVE_EVENT record (EndTime was: {end_time}, current: {current_time}, expired {current_time - end_time}s ago)...")
                    
                    # Delete the expired record
                    table.delete_item(
                        Key={
                            'TestConfigID': self.test_config_id,
                            'ConfigCategory': 'ACTIVE_EVENT'
                        }
                    )
                    self.logger.info("✓ Expired ACTIVE_EVENT record cleaned up")
                else:
                    # Event is still active (EndTime is in the future) - keep it!
                    # Convert end_time to float for comparison
                    end_time_float = float(end_time) if isinstance(end_time, Decimal) else end_time
                    current_time_float = float(current_time)
                    self.logger.info(f"Found ACTIVE ACTIVE_EVENT record for '{event_name}' (EndTime: {end_time_float}, current: {current_time_float}, {end_time_float - current_time_float}s remaining)")
                    self.logger.info("✓ Keeping ACTIVE_EVENT record (event is still active)")
            else:
                self.logger.debug("No ACTIVE_EVENT record found (clean state)")
            
            # Clean up ADMIN_LOCK record from previous test runs
            response = table.get_item(
                Key={
                    'TestConfigID': self.test_config_id,
                    'ConfigCategory': 'ADMIN_LOCK'
                }
            )
            
            if 'Item' in response:
                admin_instance = response['Item'].get('InstanceID', 'unknown')
                last_heartbeat = response['Item'].get('LastHeartbeat', 0)
                
                self.logger.info(f"Found ADMIN_LOCK record from previous test run (instance: {admin_instance})")
                self.logger.info(f"Cleaning up ADMIN_LOCK record...")
                
                # Delete the stale admin lock
                table.delete_item(
                    Key={
                        'TestConfigID': self.test_config_id,
                        'ConfigCategory': 'ADMIN_LOCK'
                    }
                )
                self.logger.info("✓ ADMIN_LOCK record cleaned up")
            else:
                self.logger.debug("No ADMIN_LOCK record found (clean state)")
                
        except Exception as e:
            self.logger.warning(f"Failed to cleanup stale records: {e}")
            # Don't fail test start if cleanup fails
    
    def _reset_event_leaderboards(self):
        """
        Regenerate event times and update DynamoDB for this test run.
        
        This ensures:
        1. Events from config file are rescheduled relative to current time
        2. Updated schedule is written to DynamoDB EVENT_SCHEDULE
        3. All workers can see the new event times
        4. Events activate properly during this test run
        """
        try:
            # Get event schedule from config
            event_schedule = self.config.get('event_schedule', [])
            
            if not event_schedule:
                self.logger.debug("No event schedule configured, skipping event time regeneration")
                return
            
            self.logger.info(f"Regenerating event times for {len(event_schedule)} events...")
            
            current_time = int(time.time())
            test_duration = self.config.get('duration', DEFAULT_TEST_DURATION)
            
            # Buffer at start (10%) and end (10%) of test
            buffer = test_duration * 0.1
            available_duration = test_duration - (2 * buffer)
            
            regenerated_count = 0
            for i, event in enumerate(event_schedule):
                event_name = event.get('eventName', 'unknown')
                # Convert Decimal to int (DynamoDB returns Decimal for numeric values)
                original_duration = int(event.get('durationSeconds', 3600))
                
                # Calculate new start time (distributed across test duration)
                offset = buffer + (i * available_duration / len(event_schedule))
                new_start_time = current_time + int(offset)
                
                # Ensure event doesn't extend beyond test duration
                if offset + original_duration > test_duration:
                    duration = int(min(original_duration, test_duration - offset - buffer))
                else:
                    duration = original_duration
                
                new_end_time = new_start_time + duration
                
                # Update event times
                event['startTime'] = new_start_time
                event['endTime'] = new_end_time
                
                # Update ISO timestamps for readability
                from datetime import datetime, timezone
                event['startTimeISO'] = datetime.fromtimestamp(new_start_time, tz=timezone.utc).isoformat()
                event['endTimeISO'] = datetime.fromtimestamp(new_end_time, tz=timezone.utc).isoformat()
                
                # Reset status if it exists from previous run
                if 'status' in event:
                    del event['status']
                if 'completedAt' in event:
                    del event['completedAt']
                
                regenerated_count += 1
                self.logger.debug(f"  ✓ Rescheduled '{event_name}': starts in {int(offset/60)}min, duration {int(duration/60)}min")
            
            self.logger.info(f"✓ Regenerated times for {regenerated_count} events")
            
            # Update EVENT_SCHEDULE in DynamoDB so all workers see the new times
            self.logger.info("Writing updated EVENT_SCHEDULE to DynamoDB...")
            
            try:
                if not hasattr(self, '_dynamodb_cached'):
                    self._dynamodb_cached = self.aws_session.resource('dynamodb')
                table = self._dynamodb_cached.Table(TEST_DEFINITIONS_TABLE_NAME)
                
                # Convert floats to Decimal for DynamoDB
                from decimal import Decimal
                def convert_floats(obj):
                    if isinstance(obj, float):
                        return Decimal(str(obj))
                    elif isinstance(obj, dict):
                        return {k: convert_floats(v) for k, v in obj.items()}
                    elif isinstance(obj, list):
                        return [convert_floats(item) for item in obj]
                    return obj
                
                config_data = {'events': convert_floats(event_schedule)}
                
                table.update_item(
                    Key={
                        'TestConfigID': self.test_config_id,
                        'ConfigCategory': 'EVENT_SCHEDULE'
                    },
                    UpdateExpression='SET ConfigData = :data, LastModified = :time',
                    ExpressionAttributeValues={
                        ':data': config_data,
                        ':time': current_time
                    }
                )
                
                self.logger.info("✓ Updated EVENT_SCHEDULE in DynamoDB - all workers will see new event times")
                
            except Exception as e:
                self.logger.warning(f"Failed to update EVENT_SCHEDULE in DynamoDB: {e}")
                self.logger.warning("Events will still work from in-memory config, but workers may not see updates")
            
        except Exception as e:
            self.logger.warning(f"Failed to regenerate event times: {e}")
            # Don't fail test start if regeneration fails
    
    def run(self):
        """
        Main execution loop.
        
        Runs until:
        - Test duration expires
        - Shutdown signal received
        - Fatal error occurs
        
        Supports pause/resume via Test Definitions Table status updates.
        
        Requirements: 10.1, 10.6, 33.1-33.18
        """
        self.logger.info("=" * 80)
        self.logger.info("Starting test execution")
        self.logger.info("=" * 80)
        
        # Clean up stale ACTIVE_EVENT records from previous test runs
        # This prevents batch workers from spawning for expired events
        self._cleanup_stale_active_events()
        
        # Regenerate event times to be in the near future for this test run
        # This ensures events activate properly during this test instead of using stale timestamps
        self._reset_event_leaderboards()
        
        self.start_time = time.time()
        test_duration = self.config.get('duration', DEFAULT_TEST_DURATION)
        end_time = self.start_time + test_duration
        
        self.logger.info(f"Test will run for {test_duration} seconds")
        self.logger.info(f"Start time: {time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(self.start_time))}")
        self.logger.info(f"End time: {time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(end_time))}")
        
        try:
            # Main execution loop
            loop_counter = 0
            while not self.shutdown_requested and time.time() < end_time:
                # Check for pause/resume status changes (Task 30.2, Requirements 33.2, 33.7)
                status_changed, new_status, reason = self.pause_resume_manager.check_status_change()
                
                if status_changed:
                    if new_status == 'PAUSED' and not self.is_paused:
                        # Handle pause (Task 30.3, Requirements 33.3-33.9)
                        self._handle_pause(reason)
                    elif new_status == 'RUNNING' and self.is_paused:
                        # Handle resume (Task 30.4, Requirements 33.10-33.15)
                        self._handle_resume()
                    elif new_status == 'AVAILABLE':
                        # Handle coordinated shutdown from PRIMARY instance
                        # Status changed from RUNNING to AVAILABLE means test ended
                        self.logger.info("Status changed to AVAILABLE - initiating coordinated shutdown")
                        self.logger.print_and_log("")
                        self.logger.print_and_log("=" * 80)
                        self.logger.print_and_log("COORDINATED SHUTDOWN REQUESTED")
                        self.logger.print_and_log("=" * 80)
                        self.logger.print_and_log("PRIMARY instance has ended test - shutting down...")
                        self.logger.print_and_log("")
                        self.shutdown_requested = True
                        break
                
                # Sleep for short intervals to check shutdown status
                time.sleep(SLEEP_INTERVAL_SHORT)
                loop_counter += 1
                
                # Only check worker health if not paused AND not shutting down
                if not self.is_paused and not self.shutdown_requested:
                    # Check if any worker threads have died unexpectedly
                    self._check_worker_health()
            
            # Test duration completed or shutdown requested
            if self.shutdown_requested:
                self.logger.info("Shutdown requested, stopping test execution")
            else:
                self.logger.info("Test duration completed")
            
        except Exception as e:
            self.logger.error(f"Fatal error in main execution loop: {e}")
            self.logger.error(traceback.format_exc())
        
        finally:
            self.end_time = time.time()
            self.shutdown()
    
    def _display_console_status(self):
        """
        Display current test status on console using clean block-based output.
        
        Instead of overwriting lines with carriage returns, prints a timestamped
        status block that doesn't interfere with other output.
        
        Shows: Timestamp, status, elapsed time, workers, API metrics, resources
        
        Requirements: 33.18
        Task: 30.8
        """
        
        # Get current timestamp
        timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
        
        # Get current status
        status = self.pause_resume_manager.current_status
        
        # Calculate elapsed time
        if self.start_time:
            elapsed = time.time() - self.start_time
            elapsed_str = f"{int(elapsed//3600)}h {int((elapsed%3600)//60)}m {int(elapsed%60)}s"
        else:
            elapsed_str = "N/A"
        
        # Get pause statistics
        pause_stats = self.pause_resume_manager.get_pause_statistics()
        
        # Status indicator
        if status == "RUNNING":
            status_indicator = "�"
        elif status == "PAUSED":
            status_indicator = "🟡"
        elif status == "STALE":
            status_indicator = "🟠"
        elif status == "AVAILABLE":
            status_indicator = "⚪"
        else:
            status_indicator = "🔴"
        
        # Show instance role
        role = "PRIMARY" if self.owns_global_lock else "WORKER"
        instance_short = self.instance_id if self.instance_id else "unknown"
        
        # Worker counts
        active_player_workers = len([t for t in self.player_workers if t.is_alive()])
        active_batch_workers = len([t for t in self.batch_workers if t.is_alive()])
        active_workers = len([t for t in self.worker_threads if t.is_alive()])
        
        # Count actual active players
        active_players = sum(
            worker.get_active_player_count() 
            for worker in self.player_workers 
            if hasattr(worker, 'get_active_player_count') and worker.is_alive()
        )
        
        # Get API metrics
        api_metrics = self.metrics_collector.get_current_metrics()
        
        # Get resource metrics
        cpu_percent = psutil.cpu_percent(interval=0.1)
        memory = psutil.virtual_memory()
        memory_percent = memory.percent
        active_threads = threading.active_count()
        
        # Build clean status block
        print(f"\n{'='*80}")
        print(f"[{timestamp}] Test Status Update")
        print(f"{'='*80}")
        print(f"Instance:  [{role}] {instance_short}")
        print(f"Status:    {status_indicator} {status} | Elapsed: {elapsed_str}")
        
        if pause_stats['pause_count'] > 0:
            pause_duration_str = f"{int(pause_stats['total_pause_duration_minutes'])}m"
            print(f"Pauses:    {pause_stats['pause_count']} pauses ({pause_duration_str} total)")
        
        player_capacity = active_player_workers * PLAYERS_PER_THREAD
        worker_info = f"{active_player_workers} player"
        if active_batch_workers > 0:
            worker_info += f" + {active_batch_workers} batch"
        print(f"Workers:   {worker_info} | Players: {active_players}/{player_capacity} active")
        print(f"Resources: CPU {cpu_percent:.1f}% | Memory {memory_percent:.1f}% | Threads {active_threads}")
        
        if api_metrics and api_metrics.get('total_requests', 0) > 0:
            # Calculate expected RPS based on actual active players
            expected_rps = active_players * BASELINE_MIN_RPS_PER_WORKER if active_players > 0 else player_capacity * BASELINE_MIN_RPS_PER_WORKER
            rps_percentage = (api_metrics['rps'] / expected_rps * 100) if expected_rps > 0 else 0
            
            print(f"API:       RPS {api_metrics['rps']:.1f} ({rps_percentage:.0f}% of {expected_rps:.0f} expected) | "
                  f"Success {api_metrics['success_rate']*100:.1f}% | "
                  f"Latency {api_metrics['avg_latency']:.0f}ms | "
                  f"Total {api_metrics['total_requests']}")
        
        print(f"{'='*80}\n")
        sys.stdout.flush()
        
        self._status_line_printed = True
    
    def shutdown(self):
        """
        Gracefully shutdown all worker threads and generate reports.
        
        Requirements: 10.4, 10.6
        """
        self.logger.print_and_log("")  # New line after console status
        self.logger.print_and_log("=" * 80)
        self.logger.print_and_log("SHUTDOWN INITIATED")
        self.logger.print_and_log("=" * 80)
        self.logger.print_and_log("")
        self.logger.print_and_log("Gracefully stopping all worker threads...")
        self.logger.print_and_log(f"Total workers to stop: {len(self.worker_threads)}")
        self.logger.print_and_log("")
        
        self.logger.info("=" * 80)
        self.logger.info("Initiating graceful shutdown")
        self.logger.info("=" * 80)
        
        # Set shutdown event to signal all threads
        self.shutdown_event.set()
        self.shutdown_requested = True
        
        # Stop spawning new sessions
        self.logger.info("Stopping new session creation...")
        self.logger.print_and_log("[✓] Shutdown signal sent to all workers")
        self.logger.print_and_log("")
        
        # Wait for active worker threads to complete (with timeout)
        self.logger.info("Waiting for active worker threads to complete...")
        self.logger.print_and_log("Waiting for workers to complete current operations...")
        self.logger.print_and_log(f"Timeout: Waiting {SHUTDOWN_TIMEOUT} seconds")
        self.logger.print_and_log("")
        
        shutdown_timeout = SHUTDOWN_TIMEOUT  # Max wait time for graceful shutdown
        shutdown_start = time.time()
        
        total_workers = len(self.worker_threads)
        stopped_count = 0
        
        for thread in self.worker_threads:
            if thread.is_alive():
                remaining_time = shutdown_timeout - (time.time() - shutdown_start)
                if remaining_time > 0:
                    thread.join(timeout=remaining_time)
                    if not thread.is_alive():
                        stopped_count += 1
                        # Clean progress display every 10 workers
                        if stopped_count % 10 == 0 or stopped_count == total_workers:
                            print(f"  Stopped {stopped_count}/{total_workers} workers...")
                    else:
                        self.logger.warning(f"Thread {thread.name} did not complete within timeout")
                else:
                    self.logger.warning(f"Shutdown timeout exceeded, forcing termination")
                    break
            else:
                stopped_count += 1
        
        self.logger.print_and_log(f"[✓] Stopped {stopped_count}/{total_workers} workers successfully")
        self.logger.print_and_log("")
        
        # Only release lock if this instance owns it AND it wasn't already released by signal handler
        if self.owns_global_lock and not self.lock_released:
            self.logger.info("Releasing global test lock...")
            self.logger.print_and_log("Releasing global test lock...")
            try:
                # Normal shutdown - reset status to AVAILABLE
                release_global_test_lock(
                    self.test_config_id, 
                    self.region, 
                    self.config.get('aws_profile')
                )
                self.lock_released = True  # Mark as released
                self.logger.info("✓ Global test lock released")
                self.logger.print_and_log("[✓] Global test lock released")
            except Exception as e:
                self.logger.error(f"Failed to release global test lock: {e}")
                self.logger.print_and_log(f"[!] Failed to release global test lock: {e}")
            self.logger.print_and_log("")
        elif self.owns_global_lock:
            self.logger.info("Global test lock already released by signal handler")
            self.logger.print_and_log("(Global test lock already released)")
            self.logger.print_and_log("")
        else:
            self.logger.info("This instance does not own the global lock")
            self.logger.print_and_log("(This instance does not own the global lock)")
            self.logger.print_and_log("")
        
        # Generate final reports (only if lock owner)
        if self.owns_global_lock:
            self.logger.info("Generating final reports (primary instance)...")
            self.logger.print_and_log("Generating final reports...")
            self._generate_final_report()
            self.logger.print_and_log("[✓] Reports generated")
        else:
            self.logger.info("Skipping report generation (worker instance)")
            self.logger.print_and_log("(Skipping report generation - primary instance will generate reports)")
        self.logger.print_and_log("")
        
        # Shutdown web servers (only if lock owner and not retaining)
        self.servers_actually_stopped = False
        if self.owns_global_lock and not self.config.get('retain_web_server', False):
            self.logger.info("Shutting down leaderboard viewer servers...")
            self.servers_actually_stopped = self._shutdown_leaderboard_servers()
            self.logger.print_and_log("")
        elif self.owns_global_lock:
            self.logger.info("Retaining leaderboard viewer servers (--retain-web-server)")
            self.logger.print_and_log("(Leaderboard viewer servers still running)")
            self.logger.print_and_log("")
        
        self.logger.info("=" * 80)
        self.logger.info("Shutdown complete")
        self.logger.info("=" * 80)
        
        self.logger.print_and_log("=" * 80)
        self.logger.print_and_log("SHUTDOWN COMPLETE")
        self.logger.print_and_log("=" * 80)
        self.logger.print_and_log("")
    
    def _handle_pause(self, reason=None):
        """
        Handle test pause request.
        
        Stops spawning new sessions and allows active sessions to complete.
        
        Args:
            reason: Optional reason for pause
        
        Requirements: 33.3, 33.4, 33.5, 33.6, 33.9
        Task: 30.3
        """
        self.logger.info("=" * 80)
        self.logger.info("PAUSING TEST EXECUTION")
        if reason:
            self.logger.info(f"Reason: {reason}")
        self.logger.info("=" * 80)
        
        # Record pause start time
        self.pause_resume_manager.record_pause_start()
        
        # Set paused flag
        self.is_paused = True
        
        # Stop Event Manager Thread from creating new events (Requirement 33.5)
        if self.event_manager:
            self.logger.info("Stopping Event Manager Thread...")
            self.event_manager.pause()
            self.logger.info("✓ Event Manager Thread paused")
        
        # Terminate Batch Worker Threads gracefully (Requirement 33.6)
        if self.batch_workers:
            self.logger.info(f"Terminating {len(self.batch_workers)} Batch Worker Threads...")
            for batch_worker in self.batch_workers:
                batch_worker.shutdown()
            self.logger.info("✓ Batch Worker Threads terminated")
        
        # Stop spawning new Player Worker Thread sessions (Requirement 33.3)
        # Note: Active sessions will complete naturally (Requirement 33.4)
        self.logger.info("Stopped spawning new Player Worker Thread sessions")
        self.logger.info("Active Player Worker sessions will complete current operations")
        
        # Log pause statistics
        stats = self.pause_resume_manager.get_pause_statistics()
        self.logger.info(f"Pause count: {stats['pause_count']}")
        
        self.logger.info("=" * 80)
        self.logger.info("TEST PAUSED - Monitoring for resume signal")
        self.logger.info("=" * 80)
    
    def _handle_resume(self):
        """
        Handle test resume request.
        
        Reloads configuration and restarts worker threads.
        
        Requirements: 33.10, 33.11, 33.12, 33.13, 33.14, 33.15
        Task: 30.4
        """
        self.logger.info("=" * 80)
        self.logger.info("RESUMING TEST EXECUTION")
        self.logger.info("=" * 80)
        
        # Record pause end time
        self.pause_resume_manager.record_pause_end()
        
        # Reload configuration from Test Definitions Table (Requirement 33.11)
        self.logger.info("Reloading configuration from Test Definitions Table...")
        try:
            updated_config = load_test_configuration_from_dynamodb(
                self.test_config_id,
                self.region,
                self.config.get('aws_profile')
            )
            if updated_config:
                self.config = updated_config
                self.logger.info("✓ Configuration reloaded successfully")
            else:
                self.logger.warning("Failed to reload configuration, using existing config")
        except Exception as e:
            self.logger.error(f"Error reloading configuration: {e}")
            self.logger.warning("Continuing with existing configuration")
        
        # Restart Event Manager Thread (Requirement 33.12)
        if self.event_manager:
            self.logger.info("Restarting Event Manager Thread...")
            self.event_manager.resume()
            self.logger.info("✓ Event Manager Thread resumed")
        
        # Resume spawning Player Worker Threads (Requirement 33.13)
        self.logger.info("Resuming Player Worker Thread spawning...")
        # Note: Player workers will naturally spawn as needed by existing logic
        
        # Spawn Batch Worker Threads if events are active (Requirement 33.14)
        self.logger.info("Checking for active events...")
        # Note: Batch workers will be spawned by Event Manager if events are active
        
        # Clear paused flag
        self.is_paused = False
        
        # Log resume statistics
        stats = self.pause_resume_manager.get_pause_statistics()
        self.logger.info(f"Total pause duration: {stats['total_pause_duration_minutes']:.2f} minutes")
        self.logger.info(f"Total pauses: {stats['pause_count']}")
        
        self.logger.info("=" * 80)
        self.logger.info("TEST RESUMED - Execution continuing")
        self.logger.info("=" * 80)
    
    def _launch_leaderboard_servers(self, reports_dir, webpage_path):
        """
        Launch HTTP server and CORS proxy for the leaderboard viewer.
        
        Args:
            reports_dir: Path to reports directory
            webpage_path: Path to the generated HTML file
        """
        import subprocess
        import socket
        
        # Check if servers are already running
        def is_port_in_use(port):
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                return s.connect_ex(('localhost', port)) == 0
        
        # Launch HTTP server on port 8000
        if not is_port_in_use(8000):
            try:
                self.http_server_process = subprocess.Popen(
                    ['python3', '-m', 'http.server', '8000', '--directory', str(reports_dir)],
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    start_new_session=True
                )
                self.logger.info(f"✓ HTTP server started on port 8000 (PID: {self.http_server_process.pid})")
                # Give it a moment to start
                time.sleep(0.5)
            except Exception as e:
                self.logger.warning(f"Failed to start HTTP server: {e}")
        else:
            self.logger.info("✓ HTTP server already running on port 8000")
        
        # Ensure CORS proxy script exists
        cors_proxy_path = Path(reports_dir) / 'cors-proxy.py'
        if not cors_proxy_path.exists():
            # Get API base URL from config
            api_base_url = self.config.get('api_base_url', '')
            
            # Create the CORS proxy script
            cors_proxy_content = f'''#!/usr/bin/env python3
"""
Simple CORS proxy server for leaderboard viewer.
Forwards requests to API Gateway and adds CORS headers.
"""

from http.server import HTTPServer, BaseHTTPRequestHandler
import urllib.request
import json

API_BASE_URL = "{api_base_url}"

class CORSProxyHandler(BaseHTTPRequestHandler):
    def do_OPTIONS(self):
        """Handle preflight requests"""
        self.send_response(200)
        self.send_header('Access-Control-Allow-Origin', '*')
        self.send_header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS')
        self.send_header('Access-Control-Allow-Headers', 'Content-Type, Authorization')
        self.send_header('Access-Control-Max-Age', '86400')
        self.end_headers()
    
    def do_POST(self):
        """Proxy POST requests"""
        # Read request body
        content_length = int(self.headers.get('Content-Length', 0))
        body = self.rfile.read(content_length) if content_length > 0 else b''
        
        # Get authorization header
        auth_header = self.headers.get('Authorization', '')
        
        # Forward to API Gateway
        target_url = f"{{API_BASE_URL}}{{self.path}}"
        
        try:
            req = urllib.request.Request(
                target_url,
                data=body,
                headers={{
                    'Content-Type': 'application/json',
                    'Authorization': auth_header
                }},
                method='POST'
            )
            
            with urllib.request.urlopen(req) as response:
                response_body = response.read()
                
                # Send response with CORS headers
                self.send_response(response.status)
                self.send_header('Access-Control-Allow-Origin', '*')
                self.send_header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS')
                self.send_header('Access-Control-Allow-Headers', 'Content-Type, Authorization')
                self.send_header('Content-Type', 'application/json')
                self.send_header('Content-Length', str(len(response_body)))
                self.end_headers()
                self.wfile.write(response_body)
                
        except urllib.error.HTTPError as e:
            # Forward error response with CORS headers
            error_body = e.read()
            self.send_response(e.code)
            self.send_header('Access-Control-Allow-Origin', '*')
            self.send_header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS')
            self.send_header('Access-Control-Allow-Headers', 'Content-Type, Authorization')
            self.send_header('Content-Type', 'application/json')
            self.send_header('Content-Length', str(len(error_body)))
            self.end_headers()
            self.wfile.write(error_body)
        except Exception as e:
            # Internal error
            error_response = json.dumps({{'error': str(e)}}).encode()
            self.send_response(500)
            self.send_header('Access-Control-Allow-Origin', '*')
            self.send_header('Content-Type', 'application/json')
            self.send_header('Content-Length', str(len(error_response)))
            self.end_headers()
            self.wfile.write(error_response)
    
    def log_message(self, format, *args):
        """Log requests"""
        print(f"[PROXY] {{self.address_string()}} - {{format % args}}")

if __name__ == '__main__':
    PORT = 8001
    server = HTTPServer(('localhost', PORT), CORSProxyHandler)
    print(f"CORS Proxy server running on http://localhost:{{PORT}}")
    print(f"Proxying requests to: {{API_BASE_URL}}")
    print("Press Ctrl+C to stop")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\\nShutting down...")
        server.shutdown()
'''
            with open(cors_proxy_path, 'w') as f:
                f.write(cors_proxy_content)
            cors_proxy_path.chmod(0o755)
            self.logger.info(f"✓ Created CORS proxy script: {cors_proxy_path}")
        
        # Launch CORS proxy on port 8001
        if not is_port_in_use(8001):
            try:
                self.cors_proxy_process = subprocess.Popen(
                    ['python3', str(cors_proxy_path)],
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    start_new_session=True
                )
                self.logger.info(f"✓ CORS proxy started on port 8001 (PID: {self.cors_proxy_process.pid})")
                # Give it a moment to start
                time.sleep(0.5)
            except Exception as e:
                self.logger.warning(f"Failed to start CORS proxy: {e}")
        else:
            self.logger.info("✓ CORS proxy already running on port 8001")
        
        # Log access URL and open in browser
        filename = Path(webpage_path).name
        viewer_url = f"http://localhost:8000/{filename}"
        
        self.logger.info("")
        self.logger.info("=" * 80)
        self.logger.info("🌐 LEADERBOARD VIEWER READY")
        self.logger.info("=" * 80)
        self.logger.info(f"  📊 Viewer URL: {viewer_url}")
        self.logger.info(f"  🖥️  HTTP Server: http://localhost:8000 (serving reports)")
        self.logger.info(f"  🔄 CORS Proxy:  http://localhost:8001 (API requests)")
        self.logger.info("")
        
        # Check if servers should be retained after test
        retain_servers = self.config.get('retain_web_server', False)
        if retain_servers:
            self.logger.info("� Servers will continue running after test completes (--retain-web-server)")
            self.logger.info("   This allows you to view results even after the test ends.")
            self.logger.info("")
            self.logger.info("🛑 To stop the servers when done:")
            
            # Build kill command with actual PIDs
            pids = []
            if hasattr(self, 'http_server_process') and self.http_server_process:
                pids.append(str(self.http_server_process.pid))
            if hasattr(self, 'cors_proxy_process') and self.cors_proxy_process:
                pids.append(str(self.cors_proxy_process.pid))
            
            if pids:
                self.logger.info(f"   kill -9 {' '.join(pids)}")
            else:
                self.logger.info("   kill -9 <http_pid> <cors_pid>  # PIDs not available")
        else:
            self.logger.info("💡 Servers will automatically shutdown when test completes")
            self.logger.info("   Use --retain-web-server to keep them running")
        self.logger.info("=" * 80)
        self.logger.info("")
        
        # Open in default browser (only if this instance owns the lock)
        if self.owns_global_lock:
            try:
                import webbrowser
                webbrowser.open(viewer_url)
                self.logger.info("✓ Opened leaderboard viewer in browser")
            except Exception as e:
                self.logger.warning(f"Could not auto-open browser: {e}")
                self.logger.info(f"Please manually open: {viewer_url}")
        else:
            self.logger.info("ℹ️  Leaderboard viewer available (browser not opened - primary instance handles this)")
            self.logger.info(f"   URL: {viewer_url}")
    
    def _shutdown_leaderboard_servers(self):
        """
        Shutdown HTTP server and CORS proxy if they were started by this instance.
        
        Returns:
            bool: True if servers were successfully stopped, False otherwise
        """
        servers_stopped = False
        http_stopped = False
        cors_stopped = False
        
        if self.http_server_process and self.http_server_process.poll() is None:
            try:
                self.logger.info("Stopping HTTP server...")
                self.http_server_process.terminate()
                self.http_server_process.wait(timeout=5)
                
                # Verify it's actually dead
                if self.http_server_process.poll() is not None:
                    self.logger.info("✓ HTTP server stopped")
                    http_stopped = True
                    servers_stopped = True
                else:
                    self.logger.warning("⚠ HTTP server did not stop gracefully, forcing kill...")
                    self.http_server_process.kill()
                    self.http_server_process.wait(timeout=2)
                    if self.http_server_process.poll() is not None:
                        self.logger.info("✓ HTTP server killed")
                        http_stopped = True
                        servers_stopped = True
            except Exception as e:
                self.logger.warning(f"Failed to stop HTTP server: {e}")
                try:
                    self.http_server_process.kill()
                    self.http_server_process.wait(timeout=2)
                    if self.http_server_process.poll() is not None:
                        http_stopped = True
                        servers_stopped = True
                except:
                    pass
        
        if self.cors_proxy_process and self.cors_proxy_process.poll() is None:
            try:
                self.logger.info("Stopping CORS proxy...")
                self.cors_proxy_process.terminate()
                self.cors_proxy_process.wait(timeout=5)
                
                # Verify it's actually dead
                if self.cors_proxy_process.poll() is not None:
                    self.logger.info("✓ CORS proxy stopped")
                    cors_stopped = True
                    servers_stopped = True
                else:
                    self.logger.warning("⚠ CORS proxy did not stop gracefully, forcing kill...")
                    self.cors_proxy_process.kill()
                    self.cors_proxy_process.wait(timeout=2)
                    if self.cors_proxy_process.poll() is not None:
                        self.logger.info("✓ CORS proxy killed")
                        cors_stopped = True
                        servers_stopped = True
            except Exception as e:
                self.logger.warning(f"Failed to stop CORS proxy: {e}")
                try:
                    self.cors_proxy_process.kill()
                    self.cors_proxy_process.wait(timeout=2)
                    if self.cors_proxy_process.poll() is not None:
                        cors_stopped = True
                        servers_stopped = True
                except:
                    pass
        
        if servers_stopped:
            self.logger.print_and_log("[✓] Leaderboard viewer servers stopped")
        
        return servers_stopped
    
    def _publish_instance_metrics(self, cpu_percent, memory_percent, cpu_cores, memory_total_gb, active_players, api_metrics, fd_used=0, fd_limit=0, player_workers=0, batch_workers=0):
        """
        Publish instance metrics to DynamoDB Test Metrics Table.
        
        Includes machine specs and per-player derived metrics for proper aggregation.
        
        Args:
            cpu_percent: Current CPU usage percentage
            memory_percent: Current memory usage percentage
            cpu_cores: Total CPU cores on this machine
            memory_total_gb: Total memory in GB on this machine
            active_players: Number of active player sessions
            api_metrics: Dictionary of API metrics from MetricsCollector
            fd_used: File descriptors in use
            fd_limit: File descriptor limit
            player_workers: Number of active player worker threads
            batch_workers: Number of active batch worker threads
        
        Requirements: Phase 3 - Enhanced Metrics Collection
        """
        try:
            from decimal import Decimal
            
            # Reuse cached DynamoDB resource to prevent file descriptor leaks
            if not hasattr(self, '_dynamodb_cached'):
                self._dynamodb_cached = self.aws_session.resource('dynamodb')
            table = self._dynamodb_cached.Table(TEST_METRICS_TABLE_NAME)
            
            current_time = int(time.time())
            
            # Calculate per-player derived metrics
            cpu_per_player = cpu_percent / max(active_players, 1)
            memory_per_player = memory_percent / max(active_players, 1)
            requests_per_player = api_metrics['total_requests'] / max(active_players, 1) if active_players > 0 else 0
            
            # Helper function to convert float to Decimal (DynamoDB requirement)
            def to_decimal(value):
                if isinstance(value, float):
                    return Decimal(str(round(value, 4)))
                return value
            
            # Build comprehensive metrics record
            metrics_item = {
                'TestConfigID': self.test_config_id,
                'MetricTimestamp': current_time,
                'InstanceID': self.instance_id,
                'MetricType': 'INSTANCE_METRICS',
                
                # Test timing
                'TestStartTime': int(self.start_time) if self.start_time else current_time,
                
                # Timezone information for accurate time interpretation
                'TimezoneOffset': time.strftime('%z'),  # e.g., '+0000', '-0800'
                'TimezoneName': time.strftime('%Z'),    # e.g., 'UTC', 'PST'
                
                # Resource utilization
                'CPUPercent': to_decimal(cpu_percent),
                'MemoryPercent': to_decimal(memory_percent),
                
                # Machine capacity
                'CPUCores': cpu_cores,
                'MemoryTotalGB': to_decimal(memory_total_gb),
                
                # File descriptor usage (for leak detection)
                'FDUsed': fd_used,
                'FDLimit': fd_limit,
                
                # Workload
                'ActivePlayers': active_players,
                'PlayerWorkers': player_workers,
                'BatchWorkers': batch_workers,
                'TotalRequests': api_metrics['total_requests'],
                'RPS': to_decimal(api_metrics['rps']),
                'SuccessRate': to_decimal(api_metrics['success_rate']),
                'AvgLatency': to_decimal(api_metrics['avg_latency']),
                'P95Latency': to_decimal(api_metrics['p95_latency']),
                'P99Latency': to_decimal(api_metrics['p99_latency']),
                
                # Derived per-player metrics
                'CPUPerPlayer': to_decimal(cpu_per_player),
                'MemoryPerPlayer': to_decimal(memory_per_player),
                'RequestsPerPlayer': to_decimal(requests_per_player),
                
                # TTL for auto-cleanup (7 days)
                'TTL': current_time + (7 * 24 * 3600)
            }
            
            # Write to DynamoDB
            table.put_item(Item=metrics_item)
            self.logger.debug(f"✓ Published instance metrics: {self.instance_id} at {current_time} (TestConfigID: {self.test_config_id})")
            
        except Exception as e:
            # Log but don't raise - metrics publishing should not break monitoring
            self.logger.warning(f"❌ Error publishing instance metrics: {e}")
            import traceback
            self.logger.debug(traceback.format_exc())
    
    def _set_test_status_available(self):
        """
        Set test status to AVAILABLE in DynamoDB Test Definitions Table.
        
        This signals all WORKER instances to shutdown gracefully when PRIMARY terminates.
        Workers poll status and shutdown when they see AVAILABLE (meaning test is no longer RUNNING).
        """
        try:
            table = self.aws_session.resource('dynamodb').Table(TEST_DEFINITIONS_TABLE_NAME)
            
            # Update METADATA record with AVAILABLE status
            table.update_item(
                Key={
                    'TestConfigID': self.test_config_id,
                    'ConfigCategory': 'METADATA'
                },
                UpdateExpression='SET #status = :available, LastModified = :timestamp',
                ExpressionAttributeNames={
                    '#status': 'Status'
                },
                ExpressionAttributeValues={
                    ':available': 'AVAILABLE',
                    ':timestamp': int(time.time())
                }
            )
            
            self.logger.info("✓ Test status set to AVAILABLE in DynamoDB")
            
        except Exception as e:
            self.logger.error(f"Failed to set AVAILABLE status: {e}")
            raise
    
    def _get_all_instance_statuses(self):
        """
        Retrieve status information for all active instances.
        
        For PRIMARY instance: Uses local metrics (no DynamoDB read needed)
        For WORKER instances: Queries Test Metrics Table for recent metrics (last 90 seconds)
        
        Returns:
            list: List of dicts with instance status info, sorted by role (PRIMARY first)
                  Each dict contains: instance_id, role, status, elapsed, metric_timestamp,
                  metric_age, source_tz_offset, source_tz_name, workers, rps, 
                  success_rate, latency, total_requests
        
        Requirements: Phase 3 - Cross-Instance Status Display
        """
        try:
            statuses = []
            current_time = int(time.time())
            
            # ALWAYS add PRIMARY instance status first (from local data)
            if self.owns_global_lock:
                # Get current API metrics from local collector
                api_metrics = self.metrics_collector.get_current_metrics()
                
                # Use local metrics if available, otherwise zeros
                if api_metrics:
                    rps = api_metrics['rps']
                    success_rate = api_metrics['success_rate'] * 100
                    latency = api_metrics['avg_latency']
                    total_requests = api_metrics['total_requests']
                else:
                    rps = 0.0
                    success_rate = 0.0
                    latency = 0.0
                    total_requests = 0
                
                # Count active players
                active_players = sum(
                    worker.get_active_player_count() 
                    for worker in self.player_workers 
                    if hasattr(worker, 'get_active_player_count') and worker.is_alive()
                )
                
                # Get file descriptor usage
                fd_used = 0
                fd_limit = 0
                try:
                    import psutil
                    import resource
                    process = psutil.Process()
                    fd_used = process.num_fds() if hasattr(process, 'num_fds') else len(process.open_files())
                    soft_limit, hard_limit = resource.getrlimit(resource.RLIMIT_NOFILE)
                    fd_limit = soft_limit
                except Exception:
                    pass
                
                # Calculate elapsed time
                elapsed = current_time - int(self.start_time) if self.start_time else 0
                
                # Add PRIMARY instance status
                statuses.append({
                    'instance_id': self.instance_id,
                    'role': 'PRIMARY',
                    'status': self.pause_resume_manager.current_status,
                    'elapsed': elapsed,
                    'metric_timestamp': current_time,
                    'metric_age': 0,  # Local data is always fresh
                    'source_tz_offset': time.strftime('%z'),
                    'source_tz_name': time.strftime('%Z'),
                    'workers': active_players,
                    'rps': rps,
                    'success_rate': success_rate,
                    'latency': latency,
                    'total_requests': total_requests,
                    'fd_used': fd_used,
                    'fd_limit': fd_limit
                })
            
            # Now add WORKER instances from DynamoDB
            # Reuse cached DynamoDB resource to prevent file descriptor leaks
            if not hasattr(self, '_dynamodb_cached'):
                self._dynamodb_cached = self.aws_session.resource('dynamodb')
            table = self._dynamodb_cached.Table(TEST_METRICS_TABLE_NAME)
            
            # Initialize persistent cache for instance statuses
            # This ensures instances that stop reporting still appear with stale data
            if not hasattr(self, '_instance_status_cache'):
                self._instance_status_cache = {}
            
            # Query for all instance metrics in last 90 seconds (fresh data)
            cutoff_time = current_time - 90
            
            from boto3.dynamodb.conditions import Key, Attr
            
            # Query with pagination support to handle multiple instances
            all_instance_metrics = []
            last_evaluated_key = None
            
            while True:
                query_params = {
                    'KeyConditionExpression': Key('TestConfigID').eq(self.test_config_id) & Key('MetricTimestamp').between(cutoff_time, current_time),
                    'FilterExpression': Attr('MetricType').eq('INSTANCE_METRICS')
                }
                
                if last_evaluated_key:
                    query_params['ExclusiveStartKey'] = last_evaluated_key
                
                response = table.query(**query_params)
                all_instance_metrics.extend(response.get('Items', []))
                
                last_evaluated_key = response.get('LastEvaluatedKey')
                if not last_evaluated_key:
                    break
            
            # Group by instance_id and get most recent metric for each
            instance_latest = {}
            for metric in all_instance_metrics:
                instance_id = metric.get('InstanceID')
                timestamp = int(metric.get('MetricTimestamp', 0))
                
                # Skip PRIMARY instance (already added from local data above)
                if instance_id == self.instance_id:
                    continue
                
                if instance_id not in instance_latest or timestamp > instance_latest[instance_id]['MetricTimestamp']:
                    instance_latest[instance_id] = metric
            
            # Update cache with fresh data
            for instance_id, metric in instance_latest.items():
                self._instance_status_cache[instance_id] = metric
            
            # Build status list from cache (includes both fresh and stale instances)
            for instance_id, metric in self._instance_status_cache.items():
                # Infer status from metrics freshness
                metric_age = current_time - int(metric.get('MetricTimestamp', 0))
                if metric_age < 30:
                    status = "RUNNING"
                elif metric_age < 60:
                    status = "AVAILABLE"
                else:
                    status = "STALE"
                
                # Calculate elapsed time from test start time
                test_start_time = int(metric.get('TestStartTime', current_time))
                elapsed = current_time - test_start_time
                
                # Get metric timestamp (when this data was recorded)
                metric_timestamp = int(metric.get('MetricTimestamp', 0))
                
                # Get timezone info from the metric (where it was recorded)
                source_tz_offset = metric.get('TimezoneOffset', 'unknown')
                source_tz_name = metric.get('TimezoneName', 'unknown')
                
                # Extract metrics
                workers = int(metric.get('ActivePlayers', 0))
                rps = float(metric.get('RPS', 0))
                success_rate = float(metric.get('SuccessRate', 0)) * 100
                latency = float(metric.get('AvgLatency', 0))
                total_requests = int(metric.get('TotalRequests', 0))
                fd_used = int(metric.get('FDUsed', 0))
                fd_limit = int(metric.get('FDLimit', 0))
                
                statuses.append({
                    'instance_id': instance_id,
                    'role': 'WORKER',
                    'status': status,
                    'elapsed': elapsed,
                    'metric_timestamp': metric_timestamp,
                    'metric_age': metric_age,
                    'source_tz_offset': source_tz_offset,
                    'source_tz_name': source_tz_name,
                    'workers': workers,
                    'rps': rps,
                    'success_rate': success_rate,
                    'latency': latency,
                    'total_requests': total_requests,
                    'fd_used': fd_used,
                    'fd_limit': fd_limit
                })
            
            # Sort: PRIMARY first (already is), then WORKERs by instance_id
            statuses.sort(key=lambda x: (0 if x['role'] == 'PRIMARY' else 1, x['instance_id']))
            
            self.logger.debug(f"Retrieved {len(statuses)} instance statuses (PRIMARY: {sum(1 for s in statuses if s['role'] == 'PRIMARY')}, WORKERS: {sum(1 for s in statuses if s['role'] == 'WORKER')})")
            
            return statuses
            
        except Exception as e:
            self.logger.warning(f"Failed to retrieve instance statuses: {e}")
            return []
    
    def _aggregate_instance_metrics(self):
        """
        Aggregate metrics from all instances (lock owner only).
        
        Queries Test Metrics Table for recent instance metrics and creates aggregate snapshots.
        Returns comprehensive view with multiple aggregation strategies INCLUDING
        aggregated API metrics (RPS, latencies, success rate) for performance display.
        
        Uses RELIABLE worker counts: tracks maximum workers ever seen from each instance
        to avoid under-reporting when instances temporarily don't report (STALE status).
        
        Requirements: Phase 4 - Metrics Aggregation
        """
        if not self.owns_global_lock:
            return None  # Only lock owner aggregates
        
        try:
            # Reuse cached DynamoDB resource to prevent file descriptor leaks
            if not hasattr(self, '_dynamodb_cached'):
                self._dynamodb_cached = self.aws_session.resource('dynamodb')
            table = self._dynamodb_cached.Table(TEST_METRICS_TABLE_NAME)
            
            # Initialize reliable worker count cache if not exists
            if not hasattr(self, '_reliable_worker_counts'):
                self._reliable_worker_counts = {}  # {instance_id: {'player_workers': max, 'batch_workers': max}}
            
            # Query for all instance metrics in last 60 seconds
            current_time = int(time.time())
            cutoff_time = current_time - 60
            
            from boto3.dynamodb.conditions import Key, Attr
            
            response = table.query(
                KeyConditionExpression=Key('TestConfigID').eq(self.test_config_id) & Key('MetricTimestamp').between(cutoff_time, current_time),
                FilterExpression=Attr('MetricType').eq('INSTANCE_METRICS')
            )
            
            all_instance_metrics = response.get('Items', [])
            
            if not all_instance_metrics:
                return None
            
            # Get most recent metric per instance (for current state)
            instance_latest = {}
            for metric in all_instance_metrics:
                instance_id = metric.get('InstanceID')
                timestamp = int(metric.get('MetricTimestamp', 0))
                
                if instance_id not in instance_latest or timestamp > instance_latest[instance_id].get('MetricTimestamp', 0):
                    instance_latest[instance_id] = metric
            
            latest_metrics = list(instance_latest.values())
            
            # Update reliable worker counts cache with maximum values seen
            for metric in latest_metrics:
                instance_id = metric.get('InstanceID')
                player_workers = int(metric.get('PlayerWorkers', 0))
                batch_workers = int(metric.get('BatchWorkers', 0))
                
                if instance_id not in self._reliable_worker_counts:
                    self._reliable_worker_counts[instance_id] = {
                        'player_workers': player_workers,
                        'batch_workers': batch_workers
                    }
                else:
                    # Update to maximum ever seen
                    self._reliable_worker_counts[instance_id]['player_workers'] = max(
                        self._reliable_worker_counts[instance_id]['player_workers'],
                        player_workers
                    )
                    self._reliable_worker_counts[instance_id]['batch_workers'] = max(
                        self._reliable_worker_counts[instance_id]['batch_workers'],
                        batch_workers
                    )
            
            # Calculate reliable total worker counts (sum of maximums from all known instances)
            # This includes PRIMARY's maximum workers + all WORKER instances' maximum counts
            # Use PRIMARY's max_player_workers and max_batch_workers (never decreases)
            reliable_total_player_workers = sum(
                counts['player_workers'] 
                for counts in self._reliable_worker_counts.values()
            ) + self.max_player_workers  # Add PRIMARY's maximum workers (tracked throughout test)
            
            reliable_total_batch_workers = sum(
                counts['batch_workers'] 
                for counts in self._reliable_worker_counts.values()
            ) + self.max_batch_workers  # Add PRIMARY's maximum batch workers (tracked throughout test)
            
            # Calculate aggregates from latest metrics
            total_players = sum(int(m.get('ActivePlayers', 0)) for m in latest_metrics)
            total_requests = sum(int(m.get('TotalRequests', 0)) for m in latest_metrics)
            total_cpu_cores = sum(int(m.get('CPUCores', 0)) for m in latest_metrics)
            total_memory_gb = sum(float(m.get('MemoryTotalGB', 0)) for m in latest_metrics)
            
            # Calculate aggregated RPS (sum of all instances' RPS)
            total_rps = sum(float(m.get('RPS', 0)) for m in latest_metrics)
            
            # Calculate weighted average success rate (by requests)
            if total_requests > 0:
                weighted_success_rate = sum(
                    float(m.get('SuccessRate', 0)) * int(m.get('TotalRequests', 0))
                    for m in latest_metrics
                ) / total_requests
            else:
                weighted_success_rate = 0
            
            # Calculate weighted average latencies (by requests)
            if total_requests > 0:
                weighted_avg_latency = sum(
                    float(m.get('AvgLatency', 0)) * int(m.get('TotalRequests', 0))
                    for m in latest_metrics
                ) / total_requests
                
                weighted_p95_latency = sum(
                    float(m.get('P95Latency', 0)) * int(m.get('TotalRequests', 0))
                    for m in latest_metrics
                ) / total_requests
                
                weighted_p99_latency = sum(
                    float(m.get('P99Latency', 0)) * int(m.get('TotalRequests', 0))
                    for m in latest_metrics
                ) / total_requests
            else:
                weighted_avg_latency = 0
                weighted_p95_latency = 0
                weighted_p99_latency = 0
            
            # Weighted averages for resources (by active players)
            if total_players > 0:
                weighted_cpu = sum(
                    float(m.get('CPUPercent', 0)) * int(m.get('ActivePlayers', 0))
                    for m in latest_metrics
                ) / total_players
                
                weighted_memory = sum(
                    float(m.get('MemoryPercent', 0)) * int(m.get('ActivePlayers', 0))
                    for m in latest_metrics
                ) / total_players
            else:
                weighted_cpu = 0
                weighted_memory = 0
            
            # Capacity-weighted CPU (by CPU cores)
            if total_cpu_cores > 0:
                capacity_weighted_cpu = sum(
                    float(m.get('CPUPercent', 0)) * int(m.get('CPUCores', 0))
                    for m in latest_metrics
                ) / total_cpu_cores
            else:
                capacity_weighted_cpu = 0
            
            # Helper function to convert float to Decimal (DynamoDB requirement)
            from decimal import Decimal
            def to_decimal(value):
                if isinstance(value, float):
                    return Decimal(str(round(value, 4)))
                return value
            
            # Build aggregate snapshot for DynamoDB
            aggregate_db = {
                'TestConfigID': self.test_config_id,
                'MetricTimestamp': current_time,
                'MetricType': 'AGGREGATE_SNAPSHOT',
                
                # Totals
                'TotalPlayers': total_players,
                'TotalRequests': total_requests,
                'TotalInstances': len(latest_metrics),
                'TotalCPUCores': total_cpu_cores,
                'TotalMemoryGB': to_decimal(total_memory_gb),
                
                # Aggregated API metrics
                'TotalRPS': to_decimal(total_rps),
                'AvgSuccessRate': to_decimal(weighted_success_rate),
                'AvgLatency': to_decimal(weighted_avg_latency),
                'P95Latency': to_decimal(weighted_p95_latency),
                'P99Latency': to_decimal(weighted_p99_latency),
                
                # Weighted resource averages
                'AvgCPUPerPlayer': to_decimal(weighted_cpu),
                'AvgMemoryPerPlayer': to_decimal(weighted_memory),
                'AvgCPUByCapacity': to_decimal(capacity_weighted_cpu),
                
                # TTL
                'TTL': current_time + (7 * 24 * 3600)
            }
            
            # Write aggregate snapshot to DynamoDB
            table.put_item(Item=aggregate_db)
            
            self.logger.debug(f"Aggregated metrics from {len(latest_metrics)} instances")
            
            # Return aggregated metrics in format compatible with MetricsCollector.get_current_metrics()
            # This can be used for performance assessment
            aggregated_metrics = {
                'rps': total_rps,
                'success_rate': weighted_success_rate,
                'error_rate': 1.0 - weighted_success_rate,
                'avg_latency': weighted_avg_latency,
                'p50_latency': weighted_avg_latency,  # Approximation (we don't have true p50 across instances)
                'p95_latency': weighted_p95_latency,
                'p99_latency': weighted_p99_latency,
                'active_threads': sum(int(m.get('ActivePlayers', 0)) for m in latest_metrics),  # Total active players
                'active_sessions': total_players,  # Total active players (for backward compatibility)
                'total_requests': total_requests,
                'successful_requests': int(total_requests * weighted_success_rate),
                'failed_requests': int(total_requests * (1.0 - weighted_success_rate)),
                'by_endpoint': {},  # Not aggregated per-endpoint
                # Worker counts - use RELIABLE counts (maximum ever seen from each instance)
                # This prevents under-reporting when instances are temporarily STALE
                'total_player_workers': reliable_total_player_workers,
                'total_batch_workers': reliable_total_batch_workers
            }
            
            return aggregated_metrics
            
        except Exception as e:
            self.logger.warning(f"Failed to aggregate instance metrics: {e}")
            return None
    
    def _check_event_manager_active(self):
        """
        Check if event manager is already active in any instance.
        
        Queries Test Definitions Table for ADMIN_LOCK record (event manager heartbeat).
        Returns True if event manager active in last 120 seconds.
        
        This prevents multiple event managers from running across instances.
        
        Requirements: Phase 5 - Event Manager Coordination
        """
        try:
            table = self.aws_session.resource('dynamodb').Table(TEST_DEFINITIONS_TABLE_NAME)
            
            # Query for ADMIN_LOCK record (event manager uses this)
            response = table.get_item(
                Key={
                    'TestConfigID': self.test_config_id,
                    'ConfigCategory': 'ADMIN_LOCK'
                }
            )
            
            if 'Item' in response:
                last_heartbeat = response['Item'].get('LastHeartbeat', 0)
                current_time = int(time.time())
                heartbeat_age = current_time - last_heartbeat
                
                # Consider active if heartbeat within last 120 seconds (2 minutes)
                if heartbeat_age < 120:
                    instance_id = response['Item'].get('InstanceID', 'unknown')
                    self.logger.info(f"Event manager already active in instance {instance_id} (heartbeat {heartbeat_age}s ago)")
                    return True
                else:
                    self.logger.info(f"Event manager heartbeat stale ({heartbeat_age}s ago), considering inactive")
                    return False
            
            self.logger.info("No active event manager found")
            return False
            
        except Exception as e:
            self.logger.warning(f"Failed to check event manager status: {e}")
            # If check fails, assume not active to allow this instance to try
            return False
    
    def _signal_handler(self, signum, frame):
        """
        Handle shutdown signals (SIGINT, SIGTERM).
        
        Requirements: 10.4
        """
        signal_name = 'SIGINT' if signum == signal.SIGINT else 'SIGTERM'
        
        # Print to console immediately
        print()
        print()
        print("=" * 80)
        print(f"RECEIVED {signal_name} - INITIATING GRACEFUL SHUTDOWN")
        print("=" * 80)
        print()
        print("Please wait while workers complete current operations...")
        print("(This may take up to 60 seconds)")
        print()
        
        self.logger.info(f"Received {signal_name}, initiating graceful shutdown...")
        
        # CRITICAL: Only release global test lock if THIS instance owns it
        # This prevents worker-only instances from clearing the lock
        if self.owns_global_lock and not self.lock_released:
            print("Releasing global test lock immediately (this instance owns it)...")
            self.logger.info("Releasing global test lock immediately...")
            try:
                # Set test status to AVAILABLE in DynamoDB FIRST to signal other instances
                print("Setting test status to AVAILABLE to signal other instances...")
                self.logger.info("Setting test status to AVAILABLE in DynamoDB...")
                try:
                    self._set_test_status_available()
                    self.logger.info("✓ Test status set to AVAILABLE")
                    print("✓ Test status set to AVAILABLE - other instances will shutdown")
                except Exception as term_error:
                    self.logger.error(f"Failed to set AVAILABLE status: {term_error}")
                    print(f"⚠ Failed to set AVAILABLE status: {term_error}")
                
                # Now release lock (status already set to AVAILABLE above)
                release_global_test_lock(
                    self.test_config_id, 
                    self.region, 
                    self.config.get('aws_profile')
                )
                self.lock_released = True  # Mark as released
                self.logger.info("✓ Global test lock released")
                print("✓ Global test lock released")
            except Exception as e:
                self.logger.error(f"Failed to release global test lock: {e}")
                print(f"⚠ Failed to release global test lock: {e}")
            print()
        else:
            self.logger.info("This instance does not own the global lock (worker-only instance)")
            print("(This is a worker-only instance, lock not released)")
            print()
        
        # Now signal shutdown to all threads
        self.shutdown_requested = True
        self.shutdown_event.set()  # Signal all worker threads to stop
    
    def _resource_monitor_loop(self):
        """
        Monitor system resources periodically.
        
        Monitors:
        - CPU usage (percentage)
        - Memory usage (percentage and bytes)
        - Network usage (bytes sent/received, if available)
        - Active thread count
        
        Logs metrics every 30 seconds for balanced real-time analysis and adaptive scaling.
        Publishes to CloudWatch every 30 seconds (synced with query periods for optimal visualization).
        
        Requirements: 10.3, 10.5, 20.6
        """
        import psutil
        
        self.logger.info("Resource monitoring thread started")
        
        # Track network baseline for calculating deltas
        try:
            net_io_start = psutil.net_io_counters()
            network_available = True
        except Exception:
            network_available = False
            self.logger.warning("Network monitoring not available on this system")
        
        while not self.shutdown_event.is_set():
            try:
                # Get CPU metrics
                cpu_percent = psutil.cpu_percent(interval=SLEEP_INTERVAL_SHORT)
                
                # Get memory metrics
                memory = psutil.virtual_memory()
                memory_percent = memory.percent
                memory_used_gb = memory.used / (1024 ** 3)  # Convert to GB
                memory_total_gb = memory.total / (1024 ** 3)
                
                # Get network metrics (if available)
                network_info = ""
                if network_available:
                    try:
                        net_io_current = psutil.net_io_counters()
                        bytes_sent_mb = net_io_current.bytes_sent / (1024 ** 2)  # MB
                        bytes_recv_mb = net_io_current.bytes_recv / (1024 ** 2)  # MB
                        network_info = f", Network: Sent={bytes_sent_mb:.1f}MB Recv={bytes_recv_mb:.1f}MB"
                    except Exception:
                        network_available = False
                
                # Get active thread count
                active_threads = threading.active_count()
                
                # Get file descriptor usage (macOS/Linux)
                fd_used = 0
                fd_limit = 0
                try:
                    import resource
                    # Get current process file descriptor count
                    process = psutil.Process()
                    fd_used = process.num_fds() if hasattr(process, 'num_fds') else len(process.open_files())
                    # Get system limit
                    soft_limit, hard_limit = resource.getrlimit(resource.RLIMIT_NOFILE)
                    fd_limit = soft_limit
                except Exception:
                    # FD monitoring not available on this system
                    pass
                
                # Count actual active players across all worker threads
                # Each PlayerWorkerThread manages up to PLAYERS_PER_THREAD players
                # Sum the actual player count from each worker
                active_players = sum(
                    worker.get_active_player_count() 
                    for worker in self.player_workers 
                    if hasattr(worker, 'get_active_player_count') and worker.is_alive()
                )
                
                # For backward compatibility, also track worker count
                active_sessions = len(self.player_workers)
                
                # Update metrics collector with active counts (Requirements 19.3)
                self.metrics_collector.update_active_counts(active_threads, active_players)
                
                # Get current API metrics from collector
                api_metrics = self.metrics_collector.get_current_metrics()
                
                # Log comprehensive metrics (INFO level for visibility)
                fd_info = f", FDs={fd_used}/{fd_limit}" if fd_limit > 0 else ""
                self.logger.info(
                    f"Resources: CPU={cpu_percent:.1f}%, "
                    f"Memory={memory_percent:.1f}% ({memory_used_gb:.2f}/{memory_total_gb:.2f}GB), "
                    f"Threads={active_threads}{fd_info}{network_info}"
                )
                
                # Log API metrics if available (Requirements 19.4, 19.5, 19.6)
                if api_metrics:
                    self.logger.info(
                        f"API Metrics: RPS={api_metrics['rps']:.1f}, "
                        f"Success={api_metrics['success_rate']*100:.1f}%, "
                        f"Latency: Avg={api_metrics['avg_latency']:.1f}ms "
                        f"P95={api_metrics['p95_latency']:.1f}ms "
                        f"P99={api_metrics['p99_latency']:.1f}ms, "
                        f"Total={api_metrics['total_requests']}"
                    )
                    
                    # Publish metrics to CloudWatch (Requirements 20.6, 20.7)
                    try:
                        self.cloudwatch_publisher.publish_metrics(api_metrics)
                    except Exception as e:
                        self.logger.warning(f"Failed to publish metrics to CloudWatch: {e}")
                        # Continue monitoring even if CloudWatch publish fails
                    
                    # Publish instance metrics to DynamoDB Test Metrics Table
                    # ONLY for WORKER instances (PRIMARY uses local metrics)
                    if not self.owns_global_lock:
                        try:
                            active_player_workers = len([t for t in self.player_workers if t.is_alive()])
                            active_batch_workers = len([t for t in self.batch_workers if t.is_alive()])
                            
                            self._publish_instance_metrics(
                                cpu_percent=cpu_percent,
                                memory_percent=memory_percent,
                                cpu_cores=psutil.cpu_count(),
                                memory_total_gb=memory_total_gb,
                                active_players=active_players,
                                api_metrics=api_metrics,
                                fd_used=fd_used,
                                fd_limit=fd_limit,
                                player_workers=active_player_workers,
                                batch_workers=active_batch_workers
                            )
                        except Exception as e:
                            self.logger.warning(f"Failed to publish instance metrics to DynamoDB: {e}")
                            # Continue monitoring even if DynamoDB publish fails
                
                # Check for active events and manage batch workers (every 60 seconds)
                # MOVED OUTSIDE api_metrics check - must run even if no API metrics yet
                # Only check every 4th iteration (60 seconds = 4 * 15s)
                if not hasattr(self, '_batch_worker_check_counter'):
                    self._batch_worker_check_counter = 0
                
                self._batch_worker_check_counter += 1
                if self._batch_worker_check_counter >= 4:  # Every 60 seconds
                    self._batch_worker_check_counter = 0
                    self.logger.info(f"[BATCH-CHECK] Running batch worker check (counter reset)")
                    try:
                        self._check_and_manage_batch_workers()
                    except Exception as e:
                        self.logger.warning(f"Failed to check/manage batch workers: {e}")
                        self.logger.warning(traceback.format_exc())
                    
                    # PHASE 4: Aggregate metrics from all instances (lock owner only)
                    aggregated_metrics = None
                    if self.owns_global_lock:
                        try:
                            aggregated_metrics = self._aggregate_instance_metrics()
                        except Exception as e:
                            self.logger.warning(f"Failed to aggregate instance metrics: {e}")
                            # Continue monitoring even if aggregation fails
                    
                    # Check metrics against alert thresholds (Requirements 21.2, 21.3, 21.4, 21.5)
                    try:
                        resource_metrics_for_alerts = {
                            'memory_percent': memory_percent,
                            'cpu_percent': cpu_percent
                        }
                        self.alert_monitor.check_metrics(api_metrics, resource_metrics_for_alerts)
                    except Exception as e:
                        self.logger.warning(f"Failed to check alert conditions: {e}")
                        # Continue monitoring even if alert check fails
                    
                    # Assess performance against baseline targets (Requirements 28.10, 28.11, 28.12, 28.15)
                    # ONLY on PRIMARY instance (lock owner) using AGGREGATED metrics
                    if self.owns_global_lock:
                        try:
                            # Use aggregated metrics if available, otherwise fall back to local metrics
                            metrics_for_assessment = aggregated_metrics if aggregated_metrics else api_metrics
                            
                            # Get total worker count from aggregated metrics if available
                            # Note: active_sessions now contains player count, not worker count
                            # Use total_player_workers for RPS calculation
                            total_workers = None
                            total_batch_workers = None
                            if aggregated_metrics and 'total_player_workers' in aggregated_metrics:
                                total_workers = aggregated_metrics['total_player_workers']
                            if aggregated_metrics and 'total_batch_workers' in aggregated_metrics:
                                total_batch_workers = aggregated_metrics['total_batch_workers']
                            
                            # Fallback to local counts if aggregated metrics not available
                            if total_workers is None:
                                total_workers = len([t for t in self.player_workers if t.is_alive()])
                            if total_batch_workers is None:
                                total_batch_workers = len([t for t in self.batch_workers if t.is_alive()])
                            
                            resource_metrics_for_performance = {
                                'cpu_percent': cpu_percent,
                                'memory_percent': memory_percent
                            }
                            
                            self.logger.debug(f"Calling assess_performance with metrics: {bool(metrics_for_assessment)}, workers: {total_workers}, batch: {total_batch_workers}")
                            
                            performance_assessment = self.performance_monitor.assess_performance(
                                metrics_for_assessment, resource_metrics_for_performance, total_workers, total_batch_workers
                            )
                            
                            # Store for later display (synchronized with Instance Status)
                            self._last_performance_assessment = performance_assessment
                            
                        except Exception as e:
                            self.logger.warning(f"Failed to assess performance: {e}")
                            self.logger.warning(f"Traceback: {traceback.format_exc()}")
                            # Continue monitoring even if performance assessment fails
                
                # Store metrics for reporting (optional enhancement)
                # This allows final report generation to include resource usage trends
                if not hasattr(self, 'resource_metrics_history'):
                    self.resource_metrics_history = []
                
                # Get current API performance metrics from collector
                current_metrics = self.metrics_collector.get_current_metrics()
                
                # Handle case where metrics collector has no data yet (e.g., during priming)
                if current_metrics is None:
                    current_metrics = {
                        'rps': 0,
                        'error_rate': 0,
                        'avg_latency': 0,
                        'p95_latency': 0,
                        'p99_latency': 0
                    }
                
                self.resource_metrics_history.append({
                    'timestamp': time.time(),
                    'cpu_percent': cpu_percent,
                    'memory_percent': memory_percent,
                    'memory_used_gb': memory_used_gb,
                    'active_threads': active_threads,
                    'active_sessions': len(self.player_workers),
                    'player_workers': len([t for t in self.player_workers if t.is_alive()]),
                    'batch_workers': len([t for t in self.batch_workers if t.is_alive()]),
                    'rps': current_metrics.get('rps', 0),
                    'error_rate': current_metrics.get('error_rate', 0),
                    'avg_latency': current_metrics.get('avg_latency', 0),
                    'p95_latency': current_metrics.get('p95_latency', 0),
                    'p99_latency': current_metrics.get('p99_latency', 0)
                })
                
                # Track maximum worker counts for PRIMARY instance (never decreases)
                current_player_workers = len([t for t in self.player_workers if t.is_alive()])
                current_batch_workers = len([t for t in self.batch_workers if t.is_alive()])
                self.max_player_workers = max(self.max_player_workers, current_player_workers)
                self.max_batch_workers = max(self.max_batch_workers, current_batch_workers)
                
                # Keep only last 100 samples to avoid memory bloat
                if len(self.resource_metrics_history) > 100:
                    self.resource_metrics_history.pop(0)
                
                # Adaptive concurrency scaling (Requirements 15.1-15.11)
                # Add resource sample to scaler (Requirement 15.2)
                current_time = time.time()
                self.adaptive_scaler.add_resource_sample(cpu_percent, memory_percent, current_time)
                
                # Check if scaling is needed (Requirements 15.3, 15.4, 15.5)
                threads_to_add = self.adaptive_scaler.execute_scale_up(current_time)
                
                if threads_to_add > 0:
                    # Spawn additional player worker threads (Requirement 15.7, 15.8)
                    self.logger.info(f"Spawning {threads_to_add} additional Player Worker Threads...")
                    
                    for i in range(threads_to_add):
                        try:
                            worker = PlayerWorkerThread(
                                worker_id=len(self.player_workers) + 1,
                                test_config_id=self.test_config_id,
                                config=self.config,
                                aws_session=self.aws_session,
                                logger=self.logger,
                                events_logger=self.api_logger,  # Pass events logger
                                shutdown_event=self.shutdown_event,
                                generator_factory=self.generator_factory,
                                instance_id=self.instance_id,  # Pass instance_id for log file naming
                                metrics_collector=self.metrics_collector,
                                consistency_validator=self.consistency_validator
                            )
                            worker.daemon = True
                            worker.start()
                            
                            self.player_workers.append(worker)
                            self.worker_threads.append(worker)
                            
                            # Stagger spawning to prevent thundering herd
                            if (i + 1) % 5 == 0:
                                time.sleep(0.2)  # 200ms pause every 5 workers
                            
                        except Exception as e:
                            self.logger.error(f"Failed to spawn Player Worker Thread: {e}")
                            break
                    
                    self.logger.info(f"✓ Successfully spawned {threads_to_add} new Player Worker Threads")
                    self.logger.info(f"  Total Player Workers: {len(self.player_workers)}")
                
                # Display instance status lines (all instances from DynamoDB)
                # PRIMARY ONLY - Workers just write to DynamoDB/CloudWatch
                # Show every 60 seconds (every 4th iteration of 15-second loop)
                # Only show after workers have been spawned (not during priming phase)
                if self.owns_global_lock and (self.player_workers or self.batch_workers):
                    if not hasattr(self, '_instance_status_display_counter'):
                        self._instance_status_display_counter = 0
                    
                    self._instance_status_display_counter += 1
                    if self._instance_status_display_counter >= 4:  # Every 60 seconds (4 * 15s)
                        self._instance_status_display_counter = 0
                        
                        # Display Performance Status FIRST (if available)
                        # This ensures it always appears right before Instance Status
                        # Use the performance_assessment that was calculated earlier in the monitoring loop
                        if hasattr(self, '_last_performance_assessment') and self._last_performance_assessment:
                            try:
                                console_display = self.performance_monitor.get_console_display(self._last_performance_assessment)
                                print(console_display)
                                # Don't add blank line - Instance Status will follow immediately
                            except Exception as e:
                                self.logger.debug(f"Failed to display performance status: {e}")
                        
                        # Now display Instance Status
                        # Retrieve all instance statuses from DynamoDB
                        instance_statuses = self._get_all_instance_statuses()
                        
                        if instance_statuses:
                            # Print timestamp for this status block (local time for convenience)
                            print(f"\n[{time.strftime('%H:%M:%S')}] Instance Statuses:")
                            
                            # Print each instance on its own line
                            for inst in instance_statuses:
                                # Status indicator
                                if inst['status'] == "RUNNING":
                                    status_indicator = "🟢"
                                elif inst['status'] == "PAUSED":
                                    status_indicator = "🟡"
                                elif inst['status'] == "STALE":
                                    status_indicator = "🟠"
                                elif inst['status'] == "AVAILABLE":
                                    status_indicator = "⚪"
                                else:
                                    status_indicator = "🔴"
                                
                                # Format elapsed time
                                elapsed = inst['elapsed']
                                elapsed_str = f"{int(elapsed//3600)}h {int((elapsed%3600)//60)}m {int(elapsed%60)}s"
                                
                                # Format metric timestamp (24-hour format)
                                # Always show local time first, then source timezone time if different
                                metric_time_local = time.strftime('%H:%M:%S', time.localtime(inst['metric_timestamp']))
                                current_tz = time.strftime('%Z')
                                source_tz = inst['source_tz_name']
                                source_offset = inst['source_tz_offset']
                                metric_age = inst['metric_age']
                                
                                # Build timezone indicator
                                if source_tz != 'unknown' and source_tz != current_tz:
                                    # Different timezone: calculate time in source timezone
                                    try:
                                        # Parse offset like '+0000' or '-0800'
                                        if source_offset and len(source_offset) == 5:
                                            sign = 1 if source_offset[0] == '+' else -1
                                            hours = int(source_offset[1:3])
                                            minutes = int(source_offset[3:5])
                                            offset_seconds = sign * (hours * 3600 + minutes * 60)
                                            
                                            # Calculate time in source timezone (UTC + offset)
                                            source_time_utc = time.gmtime(inst['metric_timestamp'])
                                            source_time_local = time.gmtime(inst['metric_timestamp'] + offset_seconds)
                                            source_time_str = time.strftime('%H:%M:%S', source_time_local)
                                            
                                            tz_indicator = f" ({source_time_str} {source_tz})"
                                        else:
                                            # Fallback if offset parsing fails
                                            tz_indicator = f" ({source_tz})"
                                    except:
                                        # Fallback on any error
                                        tz_indicator = f" ({source_tz})"
                                else:
                                    # Same timezone or unknown: no indicator
                                    tz_indicator = ""
                                
                                # Add age indicator if metric is stale
                                if metric_age > 30:
                                    age_indicator = f" [{metric_age}s ago]"
                                else:
                                    age_indicator = ""
                                
                                # Instance ID - show full ID (e.g., "instance-1", "instance-12")
                                instance_short = inst['instance_id'] if inst['instance_id'] else "unknown"
                                
                                # Format FD info if available
                                fd_info = ""
                                if inst.get('fd_limit', 0) > 0:
                                    fd_used = inst.get('fd_used', 0)
                                    fd_limit = inst.get('fd_limit', 0)
                                    fd_percent = (fd_used / fd_limit * 100) if fd_limit > 0 else 0
                                    fd_info = f" | FDs: {fd_used}/{fd_limit} ({fd_percent:.1f}%)"
                                
                                # Format error info if errors detected
                                error_info = ""
                                error_rate = 100.0 - inst['success_rate']
                                if error_rate > 0.1:  # Show if error rate > 0.1%
                                    error_info = f" | ❌ Errors: {error_rate:.2f}%"
                                
                                # Print single-line status with metric timestamp
                                print(f"{status_indicator} [{inst['role']}:{instance_short}] "
                                      f"Status: {inst['status']} | "
                                      f"Elapsed: {elapsed_str} | "
                                      f"Players: {inst['workers']} | "
                                      f"RPS: {inst['rps']:.1f} | "
                                      f"Success: {inst['success_rate']:.1f}%{error_info} | "
                                      f"Latency: {inst['latency']:.0f}ms | "
                                      f"Reqs: {inst['total_requests']}{fd_info} | "
                                      f"@{metric_time_local}{tz_indicator}{age_indicator}")
                            
                            # Add blank line after Instance Status for readability
                            print()
                            # Reset status line flag so next status update starts on a new line
                            self._status_line_printed = False
                
                # Sleep for monitoring interval (15 seconds for balanced real-time visibility)
                # Requirements: 20.6 - Balanced publishing interval (15s), while CloudWatch query periods are 30s
                # This provides good granularity
                self.shutdown_event.wait(15)
                
            except Exception as e:
                self.logger.error(f"Error in resource monitoring: {e}")
                self.logger.error(traceback.format_exc())
                self.shutdown_event.wait(60)
        
        self.logger.info("Resource monitoring thread stopped")
    
    def _lock_heartbeat_loop(self):
        """
        Maintain global test lock heartbeat to prevent expiry during long-running tests.
        
        Updates LastHeartbeat and refreshes TTL every 60 seconds.
        Also reads InstanceCount and updates performance monitor RPS baseline.
        Only runs if this instance owns the global test lock.
        
        Requirements: 35.15
        """
        self.logger.info("Global test lock heartbeat thread started")
        
        while not self.shutdown_event.is_set():
            try:
                # Sleep first (60 seconds between heartbeats)
                self.shutdown_event.wait(LOCK_HEARTBEAT_INTERVAL)
                
                if self.shutdown_event.is_set():
                    break
                
                # Update lock heartbeat and get instance count
                # Pass aws_session to reuse existing connection
                success, instance_count = update_lock_heartbeat(
                    test_config_id=self.test_config_id,
                    instance_id=self.instance_id,
                    aws_session=self.aws_session,  # Reuse session to prevent file descriptor leaks
                    region=self.region,
                    profile=self.config.get('aws_profile')
                )
                
                if success:
                    self.logger.debug(f"Global test lock heartbeat updated (instances: {instance_count})")
                    
                    # Update performance monitor with current instance count
                    # This scales the RPS baseline: N instances = N * 100 RPS minimum
                    if instance_count > 0:
                        self.performance_monitor.update_total_instances(instance_count)
                else:
                    self.logger.warning("Failed to update global test lock heartbeat")
                
            except Exception as e:
                self.logger.error(f"Error in lock heartbeat loop: {e}")
                self.logger.error(traceback.format_exc())
        
        self.logger.info("Global test lock heartbeat thread stopped")
    
    def _config_reload_loop(self):
        """
        Poll Test Definitions Table for configuration changes.
        
        Checks for updates every 30 seconds and applies changes without restart.
        Supports hot-reloading of:
        - Event schedules
        - API call distributions
        - Worker thread ratios
        - Resource monitoring intervals
        - Adaptive scaling thresholds
        
        Does NOT support hot-reloading of:
        - Test Config ID
        - AWS credentials
        - API endpoints
        - Game genre
        
        Requirements: 10.5, 16.1, 16.2, 16.3, 16.4, 16.5, 16.6, 16.7, 16.8, 16.9, 16.10, 16.11, 16.12
        """
        self.logger.info("Configuration hot-reload thread started")
        
        # Initialize version cache for tracking changes
        if not hasattr(self, 'config_versions'):
            self.config_versions = {}
            # Store initial versions from loaded config
            for category in ['event_schedule', 'api_call_distribution', 'worker_ratios']:
                self.config_versions[category] = self.config.get(f'{category}_version', 0)
        
        # Polling interval (default 30 seconds, configurable)
        poll_interval = self.config.get('config_reload_interval', CONFIG_RELOAD_POLL_INTERVAL)
        
        # CRITICAL: Reuse DynamoDB resource to prevent file descriptor leaks
        # Create once outside the loop instead of every iteration
        try:
            dynamodb = self.aws_session.resource('dynamodb')
            table = dynamodb.Table(TEST_DEFINITIONS_TABLE_NAME)
        except Exception as e:
            self.logger.error(f"Failed to initialize DynamoDB resource for config reload: {e}")
            return
        
        while not self.shutdown_event.is_set():
            try:
                # Sleep first (30 seconds between checks)
                self.shutdown_event.wait(poll_interval)
                
                if self.shutdown_event.is_set():
                    break
                
                # Query Test Definitions Table for version numbers
                self.logger.debug(f"Polling Test Definitions Table for configuration changes...")
                
                try:
                    
                    # Query for configuration categories with consistent read
                    categories_to_check = ['EVENT_SCHEDULE', 'API_SCHEMAS', 'WORKER_CONFIG']
                    
                    for category in categories_to_check:
                        try:
                            response = table.get_item(
                                Key={
                                    'TestConfigID': self.test_config_id,
                                    'ConfigCategory': category
                                },
                                ConsistentRead=True  # Ensure latest data
                            )
                            
                            if 'Item' in response:
                                item = response['Item']
                                current_version = item.get('Version', 0)
                                cached_version = self.config_versions.get(category, 0)
                                
                                # Check if version has changed
                                if current_version > cached_version:
                                    self.logger.info(f"Configuration change detected in {category}: v{cached_version} -> v{current_version}")
                                    
                                    # Reload the specific category
                                    self._reload_configuration_category(category, item)
                                    
                                    # Update cached version
                                    self.config_versions[category] = current_version
                                    
                                    self.logger.info(f"✓ Configuration category {category} reloaded successfully")
                        
                        except ClientError as e:
                            error_code = e.response.get('Error', {}).get('Code', 'Unknown')
                            if error_code != 'ResourceNotFoundException':
                                self.logger.warning(f"Error querying {category}: {error_code}")
                        
                        except Exception as e:
                            self.logger.warning(f"Error processing {category}: {e}")
                
                except Exception as e:
                    self.logger.error(f"Error in configuration reload: {e}")
                    # Continue using previous valid configuration
                
            except Exception as e:
                self.logger.error(f"Unexpected error in configuration reload loop: {e}")
                self.logger.error(traceback.format_exc())
        
        self.logger.info("Configuration hot-reload thread stopped")
    
    def _reload_configuration_category(self, category, item):
        """
        Reload a specific configuration category and apply changes.
        
        Args:
            category: Configuration category name
            item: DynamoDB item containing new configuration
        
        Requirements: 16.4, 16.5, 16.6, 16.7, 16.8, 16.9
        """
        try:
            config_data = item.get('ConfigData', {})
            
            if category == 'EVENT_SCHEDULE':
                # Reload event schedule
                new_events = config_data.get('events', [])
                self.config['event_schedule'] = new_events
                self.logger.info(f"  Updated event schedule: {len(new_events)} events")
                
                # Notify Event Manager Thread of new events (if it exists)
                if self.event_manager and hasattr(self.event_manager, 'reload_event_schedule'):
                    self.event_manager.reload_event_schedule(new_events)
            
            elif category == 'API_SCHEMAS':
                # Reload API call distributions
                new_distribution = config_data.get('api_call_distribution', {})
                if new_distribution:
                    self.config['api_call_distribution'] = new_distribution
                    self.logger.info(f"  Updated API call distribution")
                    
                    # Player Workers will gradually adopt new distribution
                    # No immediate action needed - they check config periodically
            
            elif category == 'WORKER_CONFIG':
                # Reload worker thread ratios
                new_ratios = config_data.get('worker_ratios', {})
                if new_ratios:
                    self.config['worker_ratios'] = new_ratios
                    self.logger.info(f"  Updated worker thread ratios: {new_ratios}")
                    
                    # Note: Worker thread mix will adjust as threads complete tasks
                    # No immediate spawning/termination to avoid disruption
            
            else:
                self.logger.warning(f"  Unknown configuration category: {category}")
        
        except Exception as e:
            self.logger.error(f"Error reloading configuration category {category}: {e}")
            self.logger.error(traceback.format_exc())
            # Continue using previous valid configuration
    
    def _check_worker_health(self):
        """
        Check if any worker threads have died unexpectedly.
        
        Requirements: 10.3
        """
        # Check all worker threads
        dead_threads = []
        
        for thread in self.worker_threads:
            if not thread.is_alive():
                dead_threads.append(thread)
        
        if dead_threads:
            self.logger.warning(f"Detected {len(dead_threads)} dead worker threads")
            for thread in dead_threads:
                self.logger.warning(f"  - {thread.name} (dead)")
                self.worker_threads.remove(thread)
    
    def _generate_final_report(self):
        """
        Generate final test report with metrics and statistics.
        
        Includes:
        - Test duration and configuration
        - API call statistics
        - Resource utilization summary
        - Worker thread statistics
        
        Requirements: 10.6, 23.1, 23.2, 23.3
        """
        self.logger.info("Generating final test report...")
        
        # Calculate test duration
        if self.start_time and self.end_time:
            duration = self.end_time - self.start_time
            duration_str = f"{duration:.2f} seconds ({duration/60:.1f} minutes)"
        else:
            duration = 0
            duration_str = "Unknown"
        
        # Calculate resource utilization summary
        resource_summary = "Not available"
        if hasattr(self, 'resource_metrics_history') and self.resource_metrics_history:
            cpu_values = [m['cpu_percent'] for m in self.resource_metrics_history]
            memory_values = [m['memory_percent'] for m in self.resource_metrics_history]
            thread_values = [m['active_threads'] for m in self.resource_metrics_history]
            
            avg_cpu = sum(cpu_values) / len(cpu_values)
            max_cpu = max(cpu_values)
            avg_memory = sum(memory_values) / len(memory_values)
            max_memory = max(memory_values)
            avg_threads = sum(thread_values) / len(thread_values)
            max_threads = max(thread_values)
            
            resource_summary = (
                f"CPU: Avg={avg_cpu:.1f}% Max={max_cpu:.1f}%, "
                f"Memory: Avg={avg_memory:.1f}% Max={max_memory:.1f}%, "
                f"Threads: Avg={avg_threads:.0f} Max={max_threads}"
            )
        
        # Log comprehensive summary
        self.logger.info("=" * 80)
        self.logger.info("Test Execution Summary")
        self.logger.info("=" * 80)
        self.logger.info("")
        self.logger.info("Test Configuration:")
        self.logger.info(f"  Test Config ID: {self.test_config_id}")
        self.logger.info(f"  Test Name: {self.config.get('test_name', 'Unknown')}")
        self.logger.info(f"  Genre: {self.config.get('selected_genre_key', 'Unknown')}")
        self.logger.info(f"  Region: {self.region}")
        self.logger.info("")
        self.logger.info("Test Execution:")
        self.logger.info(f"  Duration: {duration_str}")
        self.logger.info(f"  Start Time: {time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(self.start_time)) if self.start_time else 'Unknown'}")
        self.logger.info(f"  End Time: {time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(self.end_time)) if self.end_time else 'Unknown'}")
        self.logger.info("")
        self.logger.info("API Statistics:")
        self.logger.info(f"  Total API Calls: {self.total_api_calls:,}")
        self.logger.info(f"  Total Errors: {self.total_errors:,}")
        self.logger.info(f"  Success Rate: {((self.total_api_calls - self.total_errors) / max(self.total_api_calls, 1) * 100):.2f}%")
        if duration > 0:
            rps = self.total_api_calls / duration
            self.logger.info(f"  Average RPS: {rps:.2f}")
        self.logger.info("")
        self.logger.info("Worker Threads:")
        self.logger.info(f"  Event Managers: {1 if self.event_manager and self.event_manager.is_alive() else 0}")
        self.logger.info(f"  Batch Workers: {len([w for w in self.batch_workers if w.is_alive()])}/{len(self.batch_workers)}")
        self.logger.info(f"  Player Workers: {len([w for w in self.player_workers if w.is_alive()])}/{len(self.player_workers)}")
        self.logger.info(f"  Total Active: {len([w for w in self.worker_threads if w.is_alive()])}/{len(self.worker_threads)}")
        self.logger.info("")
        self.logger.info("Resource Utilization:")
        self.logger.info(f"  {resource_summary}")
        self.logger.info("")
        
        # Alert summary (Requirements 21.8)
        alert_counts = self.alert_publisher.get_alert_counts()
        if alert_counts:
            self.logger.info("Alerts:")
            total_warnings = sum(counts['WARNING'] for counts in alert_counts.values())
            total_critical = sum(counts['CRITICAL'] for counts in alert_counts.values())
            self.logger.info(f"  Total Warnings: {total_warnings}")
            self.logger.info(f"  Total Critical: {total_critical}")
            self.logger.info("")
            self.logger.info("  By Metric:")
            for metric_name, counts in sorted(alert_counts.items()):
                if counts['WARNING'] > 0 or counts['CRITICAL'] > 0:
                    self.logger.info(f"    {metric_name}: {counts['WARNING']} warnings, {counts['CRITICAL']} critical")
            self.logger.info("")
        
        # Adaptive scaling summary (Requirements 15.9, 15.11)
        scaling_stats = self.adaptive_scaler.get_statistics()
        self.logger.info("Adaptive Concurrency Scaling:")
        self.logger.info(f"  Enabled: {scaling_stats['enabled']}")
        if scaling_stats['enabled']:
            self.logger.info(f"  Initial thread count: {self.config.get('initial_player_threads', 150)}")
            self.logger.info(f"  Final thread count: {scaling_stats['current_thread_count']}")
            self.logger.info(f"  Total scaling events: {scaling_stats['total_scaling_events']}")
            self.logger.info(f"  Total threads added: {scaling_stats['total_threads_added']}")
            self.logger.info(f"  Min threads: {scaling_stats['min_threads']}")
            self.logger.info(f"  Max threads: {scaling_stats['max_threads']}")
            self.logger.info(f"  Resource samples collected: {scaling_stats['samples_collected']}")
        else:
            self.logger.info(f"  Fixed thread count: {scaling_stats['current_thread_count']}")
        self.logger.info("")
        
        # Consistency validation summary (Requirements 29.9)
        if self.consistency_validator:
            consistency_metrics = self.consistency_validator.get_validation_metrics()
            self.logger.info("Data Consistency Validation:")
            self.logger.info(f"  Total Validations: {consistency_metrics.get('total_validations', 0):,}")
            
            if consistency_metrics.get('total_validations', 0) > 0:
                self.logger.info(f"  Successful: {consistency_metrics.get('successful_validations', 0):,}")
                self.logger.info(f"  Failed: {consistency_metrics.get('failed_validations', 0):,}")
                
                success_rate = consistency_metrics.get('success_rate', 0.0) * 100
                failure_rate = consistency_metrics.get('failure_rate', 0.0) * 100
                self.logger.info(f"  Success Rate: {success_rate:.2f}%")
                self.logger.info(f"  Failure Rate: {failure_rate:.2f}%")
                
                # Display latency statistics
                if consistency_metrics.get('p50_latency_ms', 0) > 0:
                    self.logger.info(f"  Validation Latency:")
                    self.logger.info(f"    p50: {consistency_metrics.get('p50_latency_ms', 0):.1f}ms")
                    self.logger.info(f"    p95: {consistency_metrics.get('p95_latency_ms', 0):.1f}ms")
                    self.logger.info(f"    p99: {consistency_metrics.get('p99_latency_ms', 0):.1f}ms")
                
                # Display breakdown by endpoint
                if consistency_metrics.get('by_endpoint'):
                    self.logger.info(f"  By Endpoint:")
                    for endpoint, endpoint_metrics in consistency_metrics['by_endpoint'].items():
                        endpoint_success_rate = endpoint_metrics.get('success_rate', 0.0) * 100
                        self.logger.info(f"    {endpoint}:")
                        self.logger.info(f"      Total: {endpoint_metrics.get('total', 0):,}")
                        self.logger.info(f"      Success Rate: {endpoint_success_rate:.2f}%")
                
                # Display breakdown by leaderboard
                if consistency_metrics.get('by_leaderboard'):
                    self.logger.info(f"  By Leaderboard:")
                    for leaderboard, lb_metrics in consistency_metrics['by_leaderboard'].items():
                        lb_success_rate = lb_metrics.get('success_rate', 0.0) * 100
                        self.logger.info(f"    {leaderboard}:")
                        self.logger.info(f"      Total: {lb_metrics.get('total', 0):,}")
                        self.logger.info(f"      Success Rate: {lb_success_rate:.2f}%")
            else:
                self.logger.info(f"  No validations performed")
            
            self.logger.info("")
        
        self.logger.info("=" * 80)
        
        # Generate performance assessment report (Requirements 28.13)
        self.logger.info("")
        self.logger.info("Generating performance assessment report...")
        try:
            performance_report = self.performance_monitor.generate_assessment_report()
            
            self.logger.info("=" * 80)
            self.logger.info("Performance Assessment Report")
            self.logger.info("=" * 80)
            self.logger.info("")
            
            # Display summary
            summary = performance_report['summary']
            if isinstance(summary, dict):
                self.logger.info("Summary:")
                self.logger.info(f"  Overall Status: {summary['overall_status'].upper()}")
                self.logger.info(f"  Total Metrics: {summary['total_metrics']}")
                self.logger.info(f"  Meeting Targets: {summary['meeting_targets']}")
                self.logger.info(f"  Warning Status: {summary['warning_status']}")
                self.logger.info(f"  Failing Status: {summary['failing_status']}")
                self.logger.info("")
            else:
                self.logger.info(f"Summary: {summary}")
                self.logger.info("")
            
            # Display recommendations
            if performance_report['recommendations']:
                self.logger.info("Recommendations:")
                for recommendation in performance_report['recommendations']:
                    self.logger.info(f"  • {recommendation}")
                self.logger.info("")
            
            self.logger.info("=" * 80)
            self.logger.info("")
            
        except Exception as e:
            self.logger.error(f"Failed to generate performance assessment report: {e}")
        
        # Generate comprehensive reports (Phase 12: Requirements 23.1-23.12)
        self.logger.info("")
        self.logger.info("Generating comprehensive test reports...")
        try:
            # Collect all metrics for report generation
            current_metrics = self.metrics_collector.get_current_metrics()
            
            # Prepare report data
            report_data = {
                'test_config_id': self.test_config_id,
                'test_name': self.config.get('test_name', 'Unknown'),
                'genre': self.config.get('selected_genre_key', 'Unknown'),
                'region': self.region,
                'duration': duration,
                'start_time': self.start_time,
                'end_time': self.end_time,
                'total_api_calls': self.total_api_calls,
                'total_errors': self.total_errors,
                'metrics': current_metrics,
                'resource_metrics_history': getattr(self, 'resource_metrics_history', []),
                'alert_counts': alert_counts,
                'scaling_stats': self.adaptive_scaler.get_statistics(),
                'performance_assessment': self.performance_monitor.generate_assessment_report(),
                'consistency_metrics': self.consistency_validator.get_validation_metrics() if self.consistency_validator else None,
                'worker_counts': {
                    'event_manager': 1 if self.event_manager and self.event_manager.is_alive() else 0,
                    'batch': len([w for w in self.batch_workers if w.is_alive()]),
                    'player': len([w for w in self.player_workers if w.is_alive()]),
                    'total': len([w for w in self.worker_threads if w.is_alive()])
                },
                'config': self.config
            }
            
            # Initialize report generator
            report_generator = ReportGenerator(
                test_config_id=self.test_config_id,
                config=self.config,
                logger=self.logger
            )
            
            # Collect AWS insights (CloudWatch metrics and DynamoDB data)
            self.logger.info("Collecting AWS insights for comprehensive report...")
            
            # Get PRIMARY's maximum worker counts (tracked throughout test)
            # PRIMARY doesn't publish to DynamoDB, so we use dedicated max tracking
            primary_max_player_workers = self.max_player_workers
            primary_max_batch_workers = self.max_batch_workers
            self.logger.info(f"PRIMARY's maximum workers: {primary_max_player_workers} player, {primary_max_batch_workers} batch")
            
            aws_insights = report_generator.collect_aws_insights(
                test_start_time=report_data.get('start_time'),
                test_end_time=report_data.get('end_time'),
                aws_session=self.aws_session,
                region=self.config.get('region', DEFAULT_AWS_REGION)
            )
            
            # Add PRIMARY's maximum worker counts to peak values
            # (PRIMARY doesn't publish to DynamoDB, so these aren't in the query results)
            if aws_insights and 'peak_values' in aws_insights:
                aws_insights['peak_values']['peak_player_workers'] += primary_max_player_workers
                aws_insights['peak_values']['peak_batch_workers'] += primary_max_batch_workers
                
                # Add PRIMARY's peak players from resource_metrics_history
                # PRIMARY tracks active_sessions (player worker count) locally
                primary_resource_history = getattr(self, 'resource_metrics_history', [])
                if primary_resource_history:
                    # active_players is tracked via metrics_collector.update_active_counts
                    # but resource_metrics_history stores active_sessions (worker count)
                    # Each worker manages PLAYERS_PER_THREAD players
                    primary_peak_sessions = max(
                        (sample.get('active_sessions', 0) or 0) for sample in primary_resource_history
                    )
                    primary_peak_players = primary_peak_sessions * PLAYERS_PER_THREAD
                    aws_insights['peak_values']['peak_players'] += primary_peak_players
                    self.logger.info(f"Added PRIMARY's peak players to peak values: +{primary_peak_players} ({primary_peak_sessions} workers × {PLAYERS_PER_THREAD} players/thread)")
                
                self.logger.info(f"Added PRIMARY's workers to peak values: +{primary_max_player_workers} player workers, +{primary_max_batch_workers} batch workers")
            
            # Add PRIMARY's workers to reliable worker counts
            if aws_insights and 'dynamodb' in aws_insights and 'reliable_worker_counts' in aws_insights['dynamodb']:
                aws_insights['dynamodb']['reliable_worker_counts']['total_player_workers'] += primary_max_player_workers
                aws_insights['dynamodb']['reliable_worker_counts']['total_batch_workers'] += primary_max_batch_workers
                aws_insights['dynamodb']['reliable_worker_counts']['by_instance'][self.instance_id] = {
                    'player_workers': primary_max_player_workers,
                    'batch_workers': primary_max_batch_workers
                }
            
            # Generate all report formats
            report_paths = report_generator.generate_all_reports(
                test_results=report_data,
                metrics_collector=self.metrics_collector,
                resource_metrics_history=getattr(self, 'resource_metrics_history', []),
                alert_counts=alert_counts,
                validation_results=self.consistency_validator.get_validation_metrics() if self.consistency_validator else None,
                aws_insights=aws_insights,
                aws_session=self.aws_session,
                region=self.config.get('region', 'us-west-2')
            )
            
            # Display report paths
            self.logger.info("")
            self.logger.info("Reports generated successfully:")
            for report_type, path in report_paths.items():
                self.logger.info(f"  {report_type}: {path}")
            self.logger.info("")
            
        except Exception as e:
            self.logger.error(f"Failed to generate reports: {e}")
            self.logger.error(traceback.format_exc())


class EventManagerThread(threading.Thread):
    """
    Event Manager Thread - manages dynamic event lifecycle.
    
    Responsibilities:
    - Monitor event schedule
    - Create event leaderboards when events start
    - Handle event completion/expiry
    - Coordinate across instances (only one event manager globally)
    
    NOTE: Permanent leaderboards are created by main thread during setup.
    This thread only handles time-bound event leaderboards.
    
    Only ONE Event Manager exists across all test instances.
    Uses DynamoDB conditional write for coordination.
    
    Requirements: 8.8, 8.9, 8.10, 10.7-10.12
    Design: Section 4.2
    """
    
    def __init__(self, test_config_id, config, aws_session, logger, shutdown_event, instance_id=None, consistency_validator=None):
        """
        Initialize Event Manager Thread.
        
        Args:
            test_config_id: Test Config ID
            config: Test configuration dictionary
            aws_session: boto3 Session object
            logger: ThreadSafeLogger instance
            shutdown_event: threading.Event for shutdown coordination
            instance_id: Unique instance identifier for log file naming (optional)
            consistency_validator: ConsistencyValidator instance for data validation (optional)
        """
        super().__init__(name="EventManager", daemon=False)
        
        self.test_config_id = test_config_id
        self.config = config
        self.aws_session = aws_session
        self.logger = logger
        self.shutdown_event = shutdown_event
        self.consistency_validator = consistency_validator
        
        self.is_admin = False  # Will be set to True if this instance claims admin role
        
        # Create event manager log file for detailed logging
        log_dir = logger.get_log_dir()
        worker_log_dir = log_dir / "workers"
        worker_log_dir.mkdir(exist_ok=True)
        
        # Create CloudWatch handler for event manager
        event_manager_cloudwatch_handler = None
        try:
            log_stream_name = f"event-manager-{instance_id}" if instance_id else "event-manager"
            event_manager_cloudwatch_handler = CloudWatchLogHandler(
                log_group_name=CLOUDWATCH_LOG_GROUP_PREFIX,
                log_stream_name=log_stream_name,
                region=config.get('region', DEFAULT_AWS_REGION),
                aws_session=aws_session,
                logger=logger
            )
        except Exception as e:
            logger.warning(f"Failed to initialize CloudWatch handler for event manager: {e}")
        
        # Include instance_id in log file name if provided
        if instance_id:
            event_log_file = worker_log_dir / f"event-manager-{instance_id}.log"
        else:
            event_log_file = worker_log_dir / "event-manager.log"
        self.worker_logger = WorkerLogger(event_log_file, "EventManager", logger, cloudwatch_handler=event_manager_cloudwatch_handler)
        self.worker_logger.info("Event Manager initialized")
        
        self.logger.info("Event Manager Thread initialized")
        
        # Cache DynamoDB resource to prevent file descriptor leaks
        self._dynamodb = None
    
    @property
    def dynamodb(self):
        """Cached DynamoDB resource to prevent file descriptor leaks."""
        if self._dynamodb is None:
            self._dynamodb = self.aws_session.resource('dynamodb')
        return self._dynamodb
    
    def run(self):
        """
        Main execution loop for Event Manager.
        
        Attempts to claim admin role using DynamoDB conditional write.
        If successful, monitors event schedule and creates event leaderboards.
        If unsuccessful, exits gracefully (another instance is admin).
        
        Requirements: 10.7, 10.8, 10.9
        """
        self.logger.info("Event Manager Thread starting...")
        self.worker_logger.info("Event Manager Thread starting...")
        
        # Attempt to claim admin role
        if not self._claim_admin_role():
            self.logger.info("Event manager role already claimed by another instance, exiting gracefully")
            self.worker_logger.info("Event manager role already claimed by another instance, exiting gracefully")
            return
        
        self.logger.info("✓ Event manager role claimed successfully - this instance is the Event Manager")
        self.worker_logger.info("✓ Event manager role claimed successfully - this instance is the Event Manager")
        self.is_admin = True
        
        # Start heartbeat thread
        heartbeat_thread = threading.Thread(
            target=self._heartbeat_loop,
            name="AdminHeartbeat",
            daemon=True
        )
        heartbeat_thread.start()
        self.logger.info("✓ Admin heartbeat thread started")
        self.worker_logger.info("✓ Admin heartbeat thread started")
        
        # Main admin loop - monitor events and create leaderboards
        try:
            # Load event schedule from configuration
            event_schedule = self.config.get('event_schedule', [])
            self.logger.info(f"Loaded event schedule: {len(event_schedule)} events")
            self.worker_logger.info(f"Loaded event schedule: {len(event_schedule)} events")
            
            # Track which events have been created
            self.created_events = set()
            
            # Track which events have been completed
            self.completed_events = set()
            
            # Monitor event schedule
            self._monitor_event_schedule()
            
        except Exception as e:
            self.logger.error(f"Error in Event Manager main loop: {e}")
            self.worker_logger.error(f"Error in Event Manager main loop: {e}")
            self.logger.error(traceback.format_exc())
            self.worker_logger.error(traceback.format_exc())
        
        finally:
            # Release admin role on shutdown
            self._release_admin_role()
            self.logger.info("Event Manager Thread stopped")
            self.worker_logger.info("Event Manager Thread stopped")
    
    def _monitor_event_schedule(self):
        """
        Monitor event schedule and create leaderboards at appropriate times.
        
        Checks event schedule every 60 seconds and creates event leaderboards
        when their start time is reached.
        
        Requirements: 10.10, 10.11
        """
        self.logger.info("Starting event schedule monitoring...")
        self.worker_logger.info("Starting event schedule monitoring...")
        
        event_schedule = self.config.get('event_schedule', [])
        
        if not event_schedule:
            self.logger.info("No events scheduled, monitoring loop idle")
            self.worker_logger.info("No events scheduled, monitoring loop idle")
        
        # Monitoring interval (60 seconds)
        check_interval = EVENT_MANAGER_CHECK_INTERVAL
        
        while not self.shutdown_event.is_set() and self.is_admin:
            try:
                current_time = int(time.time())
                
                # Check each event in schedule
                for event in event_schedule:
                    event_name = event.get('eventName', 'unknown')
                    
                    # Skip if already created
                    if event_name in self.created_events:
                        continue
                    
                    # Get event timing (Unix timestamps)
                    start_time = event.get('startTime', 0)
                    end_time = event.get('endTime', 0)
                    
                    # Check if event should be created now
                    # Create events slightly before start time (5 minutes early)
                    creation_time = start_time - (5 * 60)
                    
                    if current_time >= creation_time and current_time < end_time:
                        self.logger.info(f"Event {event_name} is ready to be created")
                        self.worker_logger.info(f"Event {event_name} is ready to be created")
                        
                        # Create event leaderboard (Task 11.3)
                        success = self._create_event_leaderboard(event)
                        
                        if success:
                            # Verify leaderboard is ready in Valkey before marking as active
                            # This prevents workers from hitting non-existent sorted lists
                            lb_ready = self._verify_event_leaderboard_ready(event)
                            
                            if lb_ready:
                                self.created_events.add(event_name)
                                self.logger.info(f"✓ Event {event_name} leaderboard created and verified")
                                self.worker_logger.info(f"✓ Event {event_name} leaderboard created and verified")
                                
                                # Write active event status to DynamoDB for worker coordination
                                self.logger.info(f"[EVENT-ACTIVATION] Marking event {event_name} as ACTIVE in DynamoDB")
                                self._write_active_event_status(event, 'ACTIVE')
                                self.logger.info(f"[EVENT-ACTIVATION] Event {event_name} is now ACTIVE - batch workers should spawn")
                            else:
                                self.logger.warning(f"⚠ Event {event_name} leaderboard created but not ready yet")
                                self.worker_logger.warning(f"⚠ Event {event_name} leaderboard created but not ready yet")
                                self.logger.warning(f"[EVENT-ACTIVATION] Event {event_name} NOT marked as ACTIVE - verification failed")
                                # Don't add to created_events so we can retry verification on next iteration
                        else:
                            self.logger.error(f"✗ Failed to create event {event_name} leaderboard")
                            self.worker_logger.error(f"✗ Failed to create event {event_name} leaderboard")
                            # Don't add to created_events so we can retry on next iteration
                    
                    # Check if event has expired
                    elif current_time >= end_time:
                        if event_name not in self.created_events:
                            # Event expired before we could create it (shouldn't happen)
                            self.logger.warning(f"Event {event_name} expired before creation")
                            self.worker_logger.warning(f"Event {event_name} expired before creation")
                            self.created_events.add(event_name)
                            self.completed_events.add(event_name)
                        elif event_name not in self.completed_events:
                            # Event has completed - handle completion (Task 11.4)
                            self._handle_event_completion(event)
                            self.completed_events.add(event_name)
                            
                            # Mark event as COMPLETED in DynamoDB
                            self._write_active_event_status(event, 'COMPLETED')
                
                # Log monitoring status periodically
                active_events = len([e for e in event_schedule if e.get('startTime', 0) <= current_time < e.get('endTime', float('inf'))])
                pending_events = len([e for e in event_schedule if e.get('startTime', 0) > current_time])
                
                self.logger.debug(f"Event monitoring: {active_events} active, {pending_events} pending, {len(self.created_events)} created")
                self.worker_logger.debug(f"Event monitoring: {active_events} active, {pending_events} pending, {len(self.created_events)} created")
                
                # Sleep until next check
                self.shutdown_event.wait(check_interval)
                
            except Exception as e:
                self.logger.error(f"Error in event schedule monitoring: {e}")
                self.worker_logger.error(f"Error in event schedule monitoring: {e}")
                self.logger.error(traceback.format_exc())
                self.worker_logger.error(traceback.format_exc())
                self.shutdown_event.wait(check_interval)
        
        self.logger.info("Event schedule monitoring stopped")
        self.worker_logger.info("Event schedule monitoring stopped")
    
    def reload_event_schedule(self, new_events):
        """
        Reload event schedule when configuration is updated.
        
        Called by MainController when hot-reload detects event schedule changes.
        
        Args:
            new_events: Updated event schedule list
        
        Requirements: 16.7
        """
        self.logger.info(f"Reloading event schedule: {len(new_events)} events")
        
        # Update configuration
        self.config['event_schedule'] = new_events
        
        # Note: Monitoring loop will pick up new events on next iteration
        self.logger.info("✓ Event schedule reloaded")
    
    def _create_event_leaderboard(self, event):
        """
        Create event leaderboard via POST /leaderboards/config API.
        
        Creates a time-bound leaderboard with expiry timestamp and behavior.
        Checks if leaderboard already exists before attempting creation.
        
        Args:
            event: Event dictionary containing leaderboard configuration
        
        Returns:
            bool: True if creation successful or already exists, False otherwise
        
        Requirements: 10.11, 10.12
        Tasks: 11.3
        """
        
        event_name = event.get('eventName', 'unknown')
        event_type = event.get('eventType', 'unknown')
        
        self.logger.info(f"Creating event leaderboard: {event_name} ({event_type})")
        
        try:
            # Get API endpoint and credentials from configuration
            # These should be loaded from INFRASTRUCTURE and STUDIO_REGISTRATION categories
            api_base_url = self.config.get('api_base_url')
            api_key = self.config.get('api_key')
            game_id = self.config.get('game_id')
            
            if not api_base_url:
                self.logger.error("API base URL not found in configuration")
                self.logger.error("Ensure INFRASTRUCTURE category is loaded with 'apiGatewayEndpoint'")
                return False
            
            if not api_key:
                self.logger.error("API key not found in configuration")
                self.logger.error("Ensure STUDIO_REGISTRATION category is loaded with 'apiKey'")
                return False
            
            if not game_id:
                self.logger.error("Game ID not found in configuration")
                self.logger.error("Ensure STUDIO_REGISTRATION category is loaded with 'gameId'")
                return False
            
            # Extract leaderboard configuration from event
            lb_config = event.get('leaderboardConfig', {})
            
            if not lb_config:
                self.logger.error(f"No leaderboard configuration found for event {event_name}")
                return False
            
            leaderboard_name = lb_config.get('leaderboardName')
            game_mode = lb_config.get('gameMode')
            
            # CRITICAL: Check if leaderboard already exists before attempting creation
            # This prevents "leaderboard already exists" errors on retry or multi-instance scenarios
            self.logger.info(f"  Checking if leaderboard '{leaderboard_name}' already exists...")
            
            # Use GET /leaderboards/configs to retrieve all configs for this game mode
            check_endpoint = f"{api_base_url}/leaderboards/configs"
            
            headers = {
                'Content-Type': 'application/json',
                'Authorization': f'Bearer {api_key}'
            }
            
            # Use query parameters for GET request
            check_params = {
                'gameID': game_id,
                'gameMode': game_mode
            }
            
            try:
                check_response = requests.get(
                    check_endpoint,
                    params=check_params,
                    headers=headers,
                    timeout=API_TIMEOUT_READ
                )
                
                if check_response.status_code == 200:
                    check_data = check_response.json()
                    # Note: Response key is singular 'gameLeaderboardConfigResponse', not plural
                    configs_response = check_data.get('gameLeaderboardConfigResponse', {})
                    existing_configs = configs_response.get('leaderboardConfigs', [])
                    
                    # Check if our leaderboard already exists
                    for existing_lb in existing_configs:
                        if existing_lb.get('leaderboardName') == leaderboard_name:
                            self.logger.info(f"  ✓ Leaderboard '{leaderboard_name}' already exists")
                            self.logger.info(f"  Sorted List Name: {existing_lb.get('sortedListName', 'N/A')}")
                            self.logger.info(f"  Created At: {existing_lb.get('createdAt', 'N/A')}")
                            
                            # Check if expiry time needs to be updated (event may have been extended)
                            existing_expiry = existing_lb.get('optionalLBExpiryDateTimeStamp')
                            event_end_iso = event.get('endTimeISO')
                            
                            if existing_expiry and event_end_iso and existing_expiry != event_end_iso:
                                self.logger.info(f"  ⚠ {existing_lb.get('sortedListName', 'N/A')} --\n  ⚠ Leaderboard expiry mismatch identified. This is test related, fixing... Current expiry: {existing_expiry} - Event end time: {event_end_iso}")
                                
                                # Check if leaderboard has already expired
                                from datetime import datetime, timezone
                                import dateutil.parser
                                
                                try:
                                    expiry_dt = dateutil.parser.isoparse(existing_expiry)
                                    current_dt = datetime.now(timezone.utc)
                                    is_expired = current_dt >= expiry_dt
                                except Exception as parse_error:
                                    self.logger.warning(f"  Could not parse expiry time: {parse_error}")
                                    is_expired = False
                                
                                if is_expired:
                                    self.logger.info(f"  ⚠ As Leaderboard has already expired, API will reject updates, as expected.")
                                    self.logger.info(f"  >> Workaround: To delete and recreate leaderboard with new expiry, will do that now...")
                                    
                                    # Delete the expired leaderboard
                                    delete_success = self._delete_event_leaderboard(leaderboard_name, game_mode, api_base_url, api_key, game_id)
                                    
                                    if not delete_success:
                                        self.logger.error(f"  ✗ Failed to delete expired leaderboard")
                                        return False
                                    
                                    self.logger.info(f"  ✓ Deleted expired leaderboard, will recreate with new expiry")
                                    # Break out of the loop to proceed with creation below
                                    break
                                else:
                                    # Not expired yet, try to update
                                    self.logger.info(f"  >> Updating leaderboard expiry to match extended event...")
                                    
                                    update_success = self._update_event_leaderboard_expiry(event, api_base_url, api_key, game_id)
                                    
                                    if update_success:
                                        self.logger.info(f"  ✓ Expiry time synchronized successfully")
                                    else:
                                        self.logger.error(f"  ✗ Failed to synchronize expiry time")
                                        return False
                                    
                                    # Mark as created in our tracking set
                                    self.created_events.add(event_name)
                                    return True
                            else:
                                self.logger.info(f"  Expiry time is current: {existing_expiry}")
                            
                            # Mark as created in our tracking set
                            self.created_events.add(event_name)
                            return True  # Already exists, consider this success
                    
                    self.logger.info(f"  Leaderboard does not exist yet, proceeding with creation...")
                    
            except Exception as check_error:
                self.logger.warning(f"  Failed to check existing leaderboards: {check_error}")
                self.logger.warning(f"  Proceeding with creation attempt anyway...")
            
            # Prepare request body following the same pattern as create_permanent_leaderboards
            request_body = {
                "gameLeaderboardConfigRequest": {
                    "gameID": game_id,
                    "gameMode": game_mode,
                    "leaderboardName": leaderboard_name,
                    "statAttributeForLeaderboard": lb_config.get('statAttributeForLeaderboard'),
                    "leaderboardType": lb_config.get('leaderboardType'),
                    "scoreStrategy": lb_config.get('scoreStrategy')
                }
            }
            
            # Add optional fields if present
            optional_fields = [
                'scoreType', 'timeFormat', 'minValidScore', 'maxValidScore',
                'minValidTimeInSeconds', 'maxValidTimeInSeconds', 'optionalLBExpiryDateTimeStamp',
                'optionalLBReadOnlyOnExpiry'
            ]
            
            for field in optional_fields:
                if field in lb_config and lb_config[field] is not None:
                    request_body["gameLeaderboardConfigRequest"][field] = lb_config[field]
            
            # Convert time validation ranges from user units to seconds for backend
            # Users specify minValidTimeInSeconds/maxValidTimeInSeconds in the same units as timeFormat (intuitive)
            # Backend expects these values in seconds (internal standard)
            # So we convert here before sending to backend
            if 'minValidTimeInSeconds' in request_body["gameLeaderboardConfigRequest"]:
                time_format = request_body["gameLeaderboardConfigRequest"].get('timeFormat', 'seconds')
                user_min_time = request_body["gameLeaderboardConfigRequest"]['minValidTimeInSeconds']
                
                if time_format == 'milliseconds':
                    # Convert milliseconds to seconds
                    request_body["gameLeaderboardConfigRequest"]['minValidTimeInSeconds'] = user_min_time / 1000.0
                # For 'seconds', 'minutes_seconds', 'hours_minutes_seconds': already in seconds
            
            if 'maxValidTimeInSeconds' in request_body["gameLeaderboardConfigRequest"]:
                time_format = request_body["gameLeaderboardConfigRequest"].get('timeFormat', 'seconds')
                user_max_time = request_body["gameLeaderboardConfigRequest"]['maxValidTimeInSeconds']
                
                if time_format == 'milliseconds':
                    # Convert milliseconds to seconds
                    request_body["gameLeaderboardConfigRequest"]['maxValidTimeInSeconds'] = user_max_time / 1000.0
                # For 'seconds', 'minutes_seconds', 'hours_minutes_seconds': already in seconds
            
            # Log the leaderboard configuration
            self.logger.info(f"  Leaderboard: {lb_config.get('leaderboardName')}")
            self.logger.info(f"  Game Mode: {lb_config.get('gameMode')}")
            
            # Note: Expiry is NOT set during creation for event leaderboards
            # It will be set via UPDATE API after creation (see _update_event_leaderboard_expiry)
            expiry_timestamp = lb_config.get('optionalLBExpiryDateTimeStamp')
            if expiry_timestamp:
                read_only_on_expiry = lb_config.get('optionalLBReadOnlyOnExpiry', False)
                expiry_behavior = "read-only" if read_only_on_expiry else "auto-delete"
                self.logger.info(f"  Expiry: {expiry_timestamp} ({expiry_behavior})")
            else:
                self.logger.info(f"  Expiry: Will be set after creation via UPDATE API")
            
            # Call POST /leaderboards/config
            endpoint = f"{api_base_url}/leaderboards/config"
            
            self.logger.debug(f"Calling: POST {endpoint}")
            
            headers = {
                'Content-Type': 'application/json',
                'Authorization': f'Bearer {api_key}'
            }
            
            start_time = time.time()
            response = requests.post(
                endpoint,
                json=request_body,
                headers=headers,
                timeout=API_TIMEOUT_WRITE
            )
            latency_ms = (time.time() - start_time) * 1000
            
            # Parse response
            try:
                response_data = response.json()
            except:
                response_data = response.text
            
            # Generate event ID for log correlation
            event_id = generate_event_id()
            
            # Log to event worker log with full details
            self.worker_logger.log_api_call(
                endpoint=endpoint,
                method='POST',
                request_data=request_body,
                response_data=response_data,
                latency_ms=latency_ms,
                status_code=response.status_code,
                event_id=event_id,
                request_headers=headers,
                response_headers=dict(response.headers)
            )
            
            # Check response status - but first check if it's an "already exists" error
            if response.status_code not in [200, 201]:
                # Parse response to check for "already exists" error
                try:
                    error_response = response.json()
                    error_message = error_response.get('gameLeaderboardConfigResponse', {}).get('message', '')
                    
                    # Check if error is "already exists" - treat as success
                    if 'already exists' in error_message.lower():
                        self.logger.info(f"  ✓ Leaderboard already exists (detected from API response)")
                        return True
                except:
                    pass  # If we can't parse JSON, continue with error handling
                
                # Not an "already exists" error - this is a real failure
                self.logger.error(f"Failed to create event leaderboard: HTTP {response.status_code}")
                self.logger.error(f"Response: {response.text[:500]}")
                return False
            
            # Parse successful response
            response_data = response.json()
            lb_response = response_data.get('gameLeaderboardConfigResponse', {})
            
            if not lb_response.get('success'):
                error_message = lb_response.get('message', 'Unknown error')
                self.logger.error(f"Failed to create event leaderboard: {error_message}")
                return False
            
            # Log success with details
            lb_details = lb_response.get('leaderboardConfig', {})
            sorted_list_name = lb_details.get('sortedListName', 'N/A')
            created_at = lb_details.get('createdAt', 'N/A')
            
            self.logger.info(f"  ✓ Created successfully")
            self.logger.info(f"  Sorted List Name: {sorted_list_name}")
            self.logger.info(f"  Created At: {created_at}")
            
            # Verify leaderboard creation if consistency validator is available (Requirement 29.11, 29.12)
            if self.consistency_validator:
                verification_success = self._verify_leaderboard_creation(
                    api_base_url=api_base_url,
                    api_key=api_key,
                    leaderboard_name=lb_config.get('leaderboardName'),
                    expected_config=lb_config,
                    game_id=game_id
                )
                
                if verification_success:
                    self.logger.info(f"  ✓ Verification passed")
                else:
                    self.logger.warning(f"  ⚠ Verification failed")
            
            # Update leaderboard with runtime expiry time
            # This ensures events work correctly regardless of when test runs
            self.logger.info(f"  Updating leaderboard with runtime expiry time...")
            update_success = self._update_event_leaderboard_expiry(event, api_base_url, api_key, game_id)
            
            if update_success:
                self.logger.info(f"  ✓ Expiry time updated successfully")
            else:
                self.logger.warning(f"  ⚠ Failed to update expiry time - event may expire prematurely")
            
            return True
            
        except requests.exceptions.Timeout:
            self.logger.error(f"Timeout creating event leaderboard (30s)")
            return False
        
        except requests.exceptions.RequestException as e:
            self.logger.error(f"Network error creating event leaderboard: {e}")
            return False
        
        except Exception as e:
            self.logger.error(f"Unexpected error creating event leaderboard: {e}")
            self.logger.error(traceback.format_exc())
            return False
    
    def _update_event_leaderboard_expiry(self, event, api_base_url, api_key, game_id):
        """
        Update event leaderboard expiry time via PUT /leaderboards/config API.
        
        This is called after creating an event leaderboard to set the expiry time
        based on the actual test execution time, not the config generation time.
        
        DESIGN RATIONALE:
        - Event leaderboards are created WITHOUT expiry during generation
        - This allows test configs to be reused at any time without expired leaderboards
        - After creation, this method sets expiry via UPDATE API using adjusted event times
        - This ensures events don't expire prematurely during test execution
        
        Args:
            event: Event dictionary containing leaderboard configuration and adjusted times
            api_base_url: API base URL
            api_key: API key for authentication
            game_id: Game ID
        
        Returns:
            bool: True if update successful, False otherwise
        """
        try:
            lb_config = event.get('leaderboardConfig', {})
            leaderboard_name = lb_config.get('leaderboardName')
            game_mode = lb_config.get('gameMode')
            
            # Get event end time (adjusted for test runtime)
            end_time_iso = event.get('endTimeISO')
            read_only_on_expiry = lb_config.get('readOnlyOnExpiry', True)
            
            if not end_time_iso:
                self.logger.warning(f"  No end time found for event, skipping expiry update")
                return False
            
            # Prepare update request - must include ALL fields from original config
            # The Lambda's validate_update_request reuses validate_create_request which requires all mandatory fields
            update_body = {
                "gameLeaderboardConfigRequest": {
                    # Required fields
                    "gameID": game_id,
                    "gameMode": game_mode,
                    "leaderboardName": leaderboard_name,
                    "statAttributeForLeaderboard": lb_config.get('statAttributeForLeaderboard', 'score'),
                    "leaderboardType": lb_config.get('leaderboardType', 'DESCENDING_LB'),
                    "scoreStrategy": lb_config.get('scoreStrategy', 'best'),
                    # Expiry fields (what we're updating)
                    "optionalLBExpiryDateTimeStamp": end_time_iso,
                    "optionalLBReadOnlyOnExpiry": read_only_on_expiry
                }
            }
            
            # Include optional fields if present in original config
            optional_fields = [
                'scoreType', 'timeFormat', 'timePrecision', 
                'minValidScore', 'maxValidScore',
                'minValidTimeInSeconds', 'maxValidTimeInSeconds',
                'maxEntries', 'sortOrder'
            ]
            
            for field in optional_fields:
                if field in lb_config and lb_config[field] is not None:
                    update_body["gameLeaderboardConfigRequest"][field] = lb_config[field]
            
            headers = {
                'Content-Type': 'application/json',
                'Authorization': f'Bearer {api_key}'
            }
            
            endpoint = f"{api_base_url}/leaderboards/config"
            
            self.logger.info(f"  Updating leaderboard expiry via PUT {endpoint}")
            self.logger.info(f"  Leaderboard: {leaderboard_name}, Mode: {game_mode}")
            self.logger.info(f"  Setting expiry to: {end_time_iso} ({'read-only' if read_only_on_expiry else 'auto-delete'})")
            self.logger.debug(f"  Update body: {json.dumps(update_body, indent=2)}")
            
            start_time = time.time()
            response = requests.put(
                endpoint,
                json=update_body,
                headers=headers,
                timeout=API_TIMEOUT_WRITE
            )
            latency_ms = (time.time() - start_time) * 1000
            
            # Parse response
            try:
                response_data = response.json()
            except:
                response_data = response.text
            
            # Generate event ID for log correlation
            event_id = generate_event_id()
            
            # Log to event worker log
            self.worker_logger.log_api_call(
                endpoint=endpoint,
                method='PUT',
                request_data=update_body,
                response_data=response_data,
                latency_ms=latency_ms,
                status_code=response.status_code,
                event_id=event_id,
                request_headers=headers,
                response_headers=dict(response.headers)
            )
            
            if response.status_code not in [200, 201]:
                self.logger.error(f"  ❌ Failed to update expiry: HTTP {response.status_code}")
                self.logger.error(f"  Response: {response.text[:500]}")
                self.logger.error(f"  Request body was: {json.dumps(update_body, indent=2)}")
                return False
            
            # Parse successful response
            response_data = response.json()
            lb_response = response_data.get('gameLeaderboardConfigResponse', {})
            
            if not lb_response.get('success'):
                error_message = lb_response.get('message', 'Unknown error')
                self.logger.error(f"  ❌ Failed to update expiry: {error_message}")
                self.logger.error(f"  Full response: {json.dumps(response_data, indent=2)}")
                return False
            
            self.logger.info(f"  ✓ Successfully updated expiry time")
            return True
            
        except Exception as e:
            self.logger.error(f"  ❌ Error updating leaderboard expiry: {e}")
            self.logger.error(traceback.format_exc())
            return False
    
    def _delete_event_leaderboard(self, leaderboard_name, game_mode, api_base_url, api_key, game_id):
        """
        Delete an event leaderboard via DELETE /leaderboards/config API.
        
        This is used when an expired leaderboard needs to be recreated with a new expiry time.
        The Lambda prevents updating expired leaderboards, so we must delete and recreate.
        
        Args:
            leaderboard_name: Name of the leaderboard to delete
            game_mode: Game mode
            api_base_url: API base URL
            api_key: API key for authentication
            game_id: Game ID
        
        Returns:
            bool: True if deletion successful, False otherwise
        """
        try:
            # Prepare delete request
            delete_body = {
                "gameLeaderboardConfigRequest": {
                    "gameID": game_id,
                    "gameMode": game_mode,
                    "leaderboardName": leaderboard_name
                }
            }
            
            headers = {
                'Content-Type': 'application/json',
                'Authorization': f'Bearer {api_key}'
            }
            
            endpoint = f"{api_base_url}/leaderboards/config"
            
            self.logger.info(f"  Deleting expired leaderboard via DELETE {endpoint}")
            self.logger.info(f"  Leaderboard: {leaderboard_name}, Mode: {game_mode}")
            
            start_time = time.time()
            response = requests.delete(
                endpoint,
                json=delete_body,
                headers=headers,
                timeout=API_TIMEOUT_WRITE
            )
            latency_ms = (time.time() - start_time) * 1000
            
            # Parse response
            try:
                response_data = response.json()
            except:
                response_data = response.text
            
            # Generate event ID for log correlation
            event_id = generate_event_id()
            
            # Log to event worker log
            self.worker_logger.log_api_call(
                endpoint=endpoint,
                method='DELETE',
                request_data=delete_body,
                response_data=response_data,
                latency_ms=latency_ms,
                status_code=response.status_code,
                event_id=event_id,
                request_headers=headers,
                response_headers=dict(response.headers)
            )
            
            if response.status_code not in [200, 201]:
                self.logger.error(f"  ❌ Failed to delete leaderboard: HTTP {response.status_code}")
                self.logger.error(f"  Response: {response.text[:500]}")
                return False
            
            # Parse successful response
            response_data = response.json()
            lb_response = response_data.get('gameLeaderboardConfigResponse', {})
            
            if not lb_response.get('success'):
                error_message = lb_response.get('message', 'Unknown error')
                self.logger.error(f"  ❌ Failed to delete leaderboard: {error_message}")
                return False
            
            self.logger.info(f"  ✓ Successfully deleted leaderboard")
            return True
            
        except Exception as e:
            self.logger.error(f"  ❌ Error deleting leaderboard: {e}")
            self.logger.error(traceback.format_exc())
            return False
    
    def _verify_event_leaderboard_ready(self, event):
        """
        Verify event leaderboard is ready in Valkey by querying POST /leaderboards/scores.
        
        After creating an event leaderboard via API, this method verifies that the
        sorted list actually exists in Valkey before marking the event as active.
        This prevents workers from hitting non-existent leaderboards.
        
        Retries up to 3 times with 2-second delays to allow for eventual consistency.
        
        Args:
            event: Event dictionary containing leaderboard configuration
        
        Returns:
            bool: True if leaderboard is ready, False otherwise
        """
        event_name = event.get('eventName', 'unknown')
        lb_config = event.get('leaderboardConfig', {})
        leaderboard_name = lb_config.get('leaderboardName')
        game_mode = lb_config.get('gameMode')
        
        if not leaderboard_name or not game_mode:
            self.logger.error(f"Missing leaderboard name or game mode for event {event_name}")
            return False
        
        api_base_url = self.config.get('api_base_url')
        api_key = self.config.get('api_key')
        game_id = self.config.get('game_id')
        
        if not all([api_base_url, api_key, game_id]):
            self.logger.error("Missing API configuration for leaderboard verification")
            return False
        
        # Retry up to 3 times with 2-second delays
        max_retries = 3
        retry_delay = 2.0
        
        for attempt in range(1, max_retries + 1):
            try:
                # Query POST /leaderboards/scores to check if sorted list exists
                endpoint = f"{api_base_url}/leaderboards/scores"
                
                # Use POST with request body (not GET with query params)
                request_body = {
                    "leaderboardScoresRequest": {
                        "gameID": game_id,
                        "gameMode": game_mode,
                        "leaderboardName": leaderboard_name,
                        "queryType": "top",
                        "limit": 1  # Just need to verify it exists
                    }
                }
                
                headers = {
                    'Authorization': f'Bearer {api_key}',
                    'Content-Type': 'application/json'
                }
                
                self.logger.info(f"[VERIFY] Attempt {attempt}/{max_retries}: Checking leaderboard '{leaderboard_name}'")
                self.logger.info(f"[VERIFY] Endpoint: POST {endpoint}")
                self.logger.info(f"[VERIFY] Request body: {request_body}")
                
                start_time = time.time()
                response = requests.post(
                    endpoint,
                    json=request_body,
                    headers=headers,
                    timeout=5.0
                )
                latency_ms = (time.time() - start_time) * 1000
                
                self.logger.info(f"[VERIFY] Response: HTTP {response.status_code} ({latency_ms:.1f}ms)")
                
                # Check response
                if response.status_code == 200:
                    response_data = response.json()
                    # Response wrapper is 'leaderboardScoresResponse' (not 'gameLeaderboardScoresResponse')
                    lb_response = response_data.get('leaderboardScoresResponse', {})
                    
                    self.logger.info(f"[VERIFY] Response data: success={lb_response.get('success')}, message={lb_response.get('message', 'N/A')}")
                    
                    # If we get a successful response (even with 0 scores), leaderboard exists
                    if lb_response.get('success'):
                        self.logger.info(f"[VERIFY] ✓ Leaderboard verified ready in Valkey (attempt {attempt}, {latency_ms:.1f}ms)")
                        return True
                    else:
                        # Check if error message indicates sorted list doesn't exist
                        error_msg = lb_response.get('message', '')
                        if 'does not exist' in error_msg.lower():
                            self.logger.info(f"[VERIFY] Sorted list not ready yet (attempt {attempt}): {error_msg}")
                        else:
                            # Some other error - might be ready but different issue
                            self.logger.warning(f"[VERIFY] Unexpected response (attempt {attempt}): {error_msg}")
                            return False
                
                elif response.status_code == 404:
                    self.logger.info(f"[VERIFY] Leaderboard not found yet (attempt {attempt})")
                
                elif response.status_code == 403:
                    # HTTP 403 from authorizer - this is NOT about sorted list readiness
                    # This means the API key/authorization is being rejected
                    self.logger.error(f"[VERIFY] HTTP 403 Forbidden (attempt {attempt}) - Authorization issue!")
                    self.logger.error(f"[VERIFY] This indicates API Gateway authorizer is rejecting the request")
                    self.logger.error(f"[VERIFY] Response body: {response.text[:500]}")
                    # Don't retry on auth errors - they won't fix themselves
                    return False
                
                else:
                    self.logger.warning(f"[VERIFY] Unexpected status code (attempt {attempt}): {response.status_code}")
                    self.logger.warning(f"[VERIFY] Response body: {response.text[:500]}")
                
                # If not last attempt, wait before retrying
                if attempt < max_retries:
                    self.logger.info(f"[VERIFY] Waiting {retry_delay}s before retry...")
                    time.sleep(retry_delay)
                
            except requests.exceptions.Timeout:
                self.logger.warning(f"[VERIFY] Timeout verifying leaderboard (attempt {attempt})")
                if attempt < max_retries:
                    time.sleep(retry_delay)
            
            except Exception as e:
                self.logger.error(f"[VERIFY] Error verifying leaderboard (attempt {attempt}): {e}")
                if attempt < max_retries:
                    time.sleep(retry_delay)
        
        # All retries exhausted
        self.logger.error(f"[VERIFY] ✗ Leaderboard not ready after {max_retries} attempts")
        return False
    
    def _verify_leaderboard_creation(self, api_base_url, api_key, leaderboard_name, expected_config, game_id):
        """
        Verify leaderboard creation by querying POST /leaderboards/config/get.
        
        Compares key configuration fields to ensure leaderboard was created correctly.
        Records validation results in ConsistencyValidator for metrics tracking.
        
        Args:
            api_base_url: API Gateway base URL
            api_key: API key for authentication
            leaderboard_name: Name of the leaderboard to verify
            expected_config: Expected leaderboard configuration dictionary
            game_id: Game ID
        
        Returns:
            bool: True if verification passed, False otherwise
        
        Requirements: 29.11, 29.12, 29.14
        Tasks: 26.5
        """
        
        validation_start = time.time()
        
        try:
            # Query POST /leaderboards/config/get to retrieve created leaderboard
            endpoint = f"{api_base_url}/leaderboards/config/get"
            
            request_body = {
                'gameLeaderboardConfigRequest': {
                    'gameID': game_id,
                    'leaderboardName': leaderboard_name
                }
            }
            
            self.logger.debug(f"Verifying leaderboard creation: POST {endpoint}")
            
            headers = {
                'Content-Type': 'application/json',
                'Authorization': f'Bearer {api_key}'
            }
            
            verify_start_time = time.time()
            response = requests.post(
                endpoint,
                json=request_body,
                headers=headers,
                timeout=API_TIMEOUT_SHORT
            )
            verify_latency_ms = (time.time() - verify_start_time) * 1000
            
            # Parse response
            try:
                response_data = response.json()
            except:
                response_data = response.text
            
            # Generate event ID for log correlation
            verify_event_id = generate_event_id()
            
            # Log to event worker log with full details
            self.worker_logger.log_api_call(
                endpoint=endpoint,
                method='POST',
                request_data=request_body,
                response_data=response_data,
                latency_ms=verify_latency_ms,
                status_code=response.status_code,
                event_id=verify_event_id,
                request_headers=headers,
                response_headers=dict(response.headers)
            )
            
            # Check response status
            if response.status_code != 200:
                validation_latency = (time.time() - validation_start) * 1000
                self.consistency_validator.record_validation_result(
                    success=False,
                    latency=validation_latency / 1000,  # Convert ms to seconds
                    endpoint='POST /leaderboards/config',
                    leaderboard_name=leaderboard_name
                )
                self.logger.warning(
                    f"Leaderboard verification failed: HTTP {response.status_code} "
                    f"(leaderboard: {leaderboard_name})"
                )
                return False
            
            # Parse response
            response_data = response.json()
            lb_response = response_data.get('gameLeaderboardConfigResponse', {})
            
            if not lb_response.get('success'):
                validation_latency = (time.time() - validation_start) * 1000
                self.consistency_validator.record_validation_result(
                    success=False,
                    latency=validation_latency / 1000,  # Convert ms to seconds
                    endpoint='POST /leaderboards/config',
                    leaderboard_name=leaderboard_name
                )
                self.logger.warning(
                    f"Leaderboard verification failed: API returned success=false "
                    f"(leaderboard: {leaderboard_name})"
                )
                return False
            
            # Extract actual configuration
            actual_config = lb_response.get('leaderboardConfig', {})
            
            if not actual_config:
                validation_latency = (time.time() - validation_start) * 1000
                self.consistency_validator.record_validation_result(
                    success=False,
                    latency=validation_latency / 1000,  # Convert ms to seconds
                    endpoint='POST /leaderboards/config',
                    leaderboard_name=leaderboard_name
                )
                self.logger.warning(
                    f"Leaderboard verification failed: No leaderboard config in response "
                    f"(leaderboard: {leaderboard_name})"
                )
                return False
            
            # Compare key fields
            fields_to_compare = [
                'leaderboardName',
                'gameMode',
                'leaderboardType',
                'scoreStrategy',
                'statAttributeForLeaderboard'
            ]
            
            mismatches = []
            for field in fields_to_compare:
                expected_value = expected_config.get(field)
                actual_value = actual_config.get(field)
                
                if expected_value != actual_value:
                    mismatches.append({
                        'field': field,
                        'expected': expected_value,
                        'actual': actual_value
                    })
            
            # Record validation result
            validation_latency = (time.time() - validation_start) * 1000
            
            if mismatches:
                # Verification failed - field mismatches
                self.consistency_validator.record_validation_result(
                    success=False,
                    latency=validation_latency / 1000,  # Convert ms to seconds
                    endpoint='POST /leaderboards/config',
                    leaderboard_name=leaderboard_name
                )
                
                self.logger.warning(
                    f"Leaderboard verification failed: Field mismatches detected "
                    f"(leaderboard: {leaderboard_name})"
                )
                for mismatch in mismatches:
                    self.logger.warning(
                        f"  Field '{mismatch['field']}': "
                        f"expected={mismatch['expected']}, actual={mismatch['actual']}"
                    )
                
                return False
            else:
                # Verification passed - all fields match
                self.consistency_validator.record_validation_result(
                    success=True,
                    latency=validation_latency / 1000,  # Convert ms to seconds
                    endpoint='POST /leaderboards/config',
                    leaderboard_name=leaderboard_name
                )
                
                self.logger.debug(
                    f"Leaderboard verification passed: All fields match "
                    f"(leaderboard: {leaderboard_name}, latency: {validation_latency:.1f}ms)"
                )
                
                return True
        
        except requests.exceptions.Timeout:
            validation_latency = (time.time() - validation_start) * 1000
            self.consistency_validator.record_validation_result(
                success=False,
                latency=validation_latency / 1000,  # Convert ms to seconds
                endpoint='POST /leaderboards/config',
                leaderboard_name=leaderboard_name
            )
            self.logger.warning(
                f"Leaderboard verification failed: Timeout (10s) "
                f"(leaderboard: {leaderboard_name})"
            )
            return False
        
        except requests.exceptions.RequestException as e:
            validation_latency = (time.time() - validation_start) * 1000
            self.consistency_validator.record_validation_result(
                success=False,
                latency=validation_latency / 1000,  # Convert ms to seconds
                endpoint='POST /leaderboards/config',
                leaderboard_name=leaderboard_name
            )
            self.logger.warning(
                f"Leaderboard verification failed: Network error - {e} "
                f"(leaderboard: {leaderboard_name})"
            )
            return False
        
        except Exception as e:
            validation_latency = (time.time() - validation_start) * 1000
            self.consistency_validator.record_validation_result(
                success=False,
                latency=validation_latency / 1000,  # Convert ms to seconds
                endpoint='POST /leaderboards/config',
                leaderboard_name=leaderboard_name
            )
            self.logger.warning(
                f"Leaderboard verification failed: Unexpected error - {e} "
                f"(leaderboard: {leaderboard_name})"
            )
            return False
    
    def _handle_event_completion(self, event):
        """
        Handle event completion when event expires.
        
        Logs event completion and updates event status in Test Definitions Table.
        This allows tracking of event lifecycle and coordination with Batch Workers.
        
        Args:
            event: Event dictionary containing event details
        
        Requirements: 10.13
        Tasks: 11.4
        """
        
        event_name = event.get('eventName', 'unknown')
        event_type = event.get('eventType', 'unknown')
        start_time = event.get('startTime', 0)
        end_time = event.get('endTime', 0)
        duration_seconds = event.get('durationSeconds', 0)
        
        current_time = int(time.time())
        
        self.logger.info("=" * 60)
        self.logger.info(f"Event Completion: {event_name}")
        self.logger.info("=" * 60)
        self.logger.info(f"  Event Type: {event_type}")
        self.logger.info(f"  Duration: {duration_seconds // 60} minutes")
        self.logger.info(f"  Start Time: {time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(start_time))}")
        self.logger.info(f"  End Time: {time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(end_time))}")
        self.logger.info(f"  Completed At: {time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(current_time))}")
        
        # Calculate how long after expiry we detected completion
        detection_delay = current_time - end_time
        if detection_delay > 120:  # More than 2 minutes late
            self.logger.warning(f"  ⚠ Late detection: {detection_delay}s after expiry")
        else:
            self.logger.info(f"  Detection delay: {detection_delay}s")
        
        try:
            # Update event status in Test Definitions Table
            table = self.dynamodb.Table(TEST_DEFINITIONS_TABLE_NAME)
            
            # Load current EVENT_SCHEDULE
            response = table.get_item(
                Key={
                    'TestConfigID': self.test_config_id,
                    'ConfigCategory': 'EVENT_SCHEDULE'
                }
            )
            
            if 'Item' not in response:
                self.logger.warning("EVENT_SCHEDULE not found in Test Definitions Table")
                return
            
            event_schedule_item = response['Item']
            config_data = event_schedule_item.get('ConfigData', {})
            events = config_data.get('events', [])
            
            # Find and update the event status
            event_updated = False
            for evt in events:
                if evt.get('eventName') == event_name:
                    evt['status'] = 'COMPLETED'
                    evt['completedAt'] = current_time
                    event_updated = True
                    break
            
            if event_updated:
                # Write back updated event schedule
                table.update_item(
                    Key={
                        'TestConfigID': self.test_config_id,
                        'ConfigCategory': 'EVENT_SCHEDULE'
                    },
                    UpdateExpression='SET ConfigData = :data, LastModified = :time',
                    ExpressionAttributeValues={
                        ':data': config_data,
                        ':time': current_time
                    }
                )
                
                self.logger.info(f"  ✓ Event status updated to COMPLETED in Test Definitions Table")
            else:
                self.logger.warning(f"  ⚠ Event {event_name} not found in EVENT_SCHEDULE")
            
        except ClientError as e:
            error_code = e.response.get('Error', {}).get('Code', 'Unknown')
            self.logger.error(f"  ✗ Failed to update event status: {error_code}")
        
        except Exception as e:
            self.logger.error(f"  ✗ Error handling event completion: {e}")
            self.logger.error(traceback.format_exc())
        
        self.logger.info("=" * 60)
        self.logger.info("")
    
    def _write_active_event_status(self, event, status):
        """
        Write active event status to DynamoDB for worker coordination.
        
        Creates/updates an ACTIVE_EVENT record in Test Definitions Table that
        all instances can read to detect when events are active and spawn batch workers.
        
        Args:
            event: Event dictionary
            status: Event status ('ACTIVE' or 'COMPLETED')
        
        Requirements: Event-Worker Coordination
        """
        try:
            from decimal import Decimal
            
            table = self.dynamodb.Table(TEST_DEFINITIONS_TABLE_NAME)
            
            event_name = event.get('eventName', 'unknown')
            current_time = int(time.time())
            
            # Helper to convert float to int for timestamps
            def to_int_timestamp(value):
                if isinstance(value, (int, float)):
                    return int(value)
                return value
            
            if status == 'ACTIVE':
                # Write active event record
                table.put_item(
                    Item={
                        'TestConfigID': self.test_config_id,
                        'ConfigCategory': 'ACTIVE_EVENT',
                        'EventName': event_name,
                        'EventType': event.get('eventType', 'unknown'),
                        'Status': 'ACTIVE',
                        'StartTime': to_int_timestamp(event.get('startTime', current_time)),
                        'EndTime': to_int_timestamp(event.get('endTime', current_time + 3600)),
                        'LeaderboardConfig': event.get('leaderboardConfig', {}),
                        'LastModified': current_time,
                        'TTL': to_int_timestamp(event.get('endTime', current_time + 3600)) + 3600  # Cleanup 1 hour after event ends
                    }
                )
                self.logger.info(f"✓ Wrote ACTIVE_EVENT status for {event_name} to DynamoDB")
                self.worker_logger.info(f"✓ Wrote ACTIVE_EVENT status for {event_name} to DynamoDB")
                
            elif status == 'COMPLETED':
                # Delete active event record (event is over)
                table.delete_item(
                    Key={
                        'TestConfigID': self.test_config_id,
                        'ConfigCategory': 'ACTIVE_EVENT'
                    }
                )
                self.logger.info(f"✓ Removed ACTIVE_EVENT status for {event_name} from DynamoDB")
                self.worker_logger.info(f"✓ Removed ACTIVE_EVENT status for {event_name} from DynamoDB")
                
        except Exception as e:
            self.logger.error(f"Failed to write active event status: {e}")
            self.worker_logger.error(f"Failed to write active event status: {e}")
    
    def _claim_admin_role(self):
        """
        Attempt to claim admin role using DynamoDB conditional write.
        
        Uses conditional write to ensure only ONE admin across all instances.
        
        Returns:
            bool: True if role claimed successfully, False if already claimed
        
        Requirements: 10.7, 10.8, 12.1, 12.2, 12.3
        """
        
        try:
            table = self.dynamodb.Table(TEST_DEFINITIONS_TABLE_NAME)
            
            # Generate unique instance ID
            instance_id = f"instance-{uuid.uuid4().hex[:8]}"
            current_time = int(time.time())
            
            # Attempt conditional write - only succeeds if ADMIN_LOCK doesn't exist for this test
            # For composite keys, check if the sort key (ConfigCategory) doesn't exist
            # This works because we're writing to a specific partition (TestConfigID)
            try:
                response = table.put_item(
                    Item={
                        'TestConfigID': self.test_config_id,
                        'ConfigCategory': 'ADMIN_LOCK',
                        'TestName': self.config.get('test_name', 'Unknown'),  # Add for consistency
                        'InstanceID': instance_id,
                        'ClaimTime': current_time,
                        'LastHeartbeat': current_time,
                        'Status': 'ACTIVE',
                        'TTL': current_time + LOCK_TTL_DURATION
                    },
                    ConditionExpression='attribute_not_exists(ConfigCategory)'
                )
                
                # Success! This instance is now the admin
                self.instance_id = instance_id
                self.logger.info(f"Admin role claimed with instance ID: {instance_id}")
                self.worker_logger.info(f"Admin role claimed with instance ID: {instance_id}")
                return True
                
            except ClientError as e:
                error_code = e.response.get('Error', {}).get('Code', 'Unknown')
                
                if error_code == 'ConditionalCheckFailedException':
                    # Admin role already claimed by another instance
                    self.logger.info("Admin role already claimed by another instance")
                    
                    # Try to get info about current admin
                    try:
                        response = table.get_item(
                            Key={
                                'TestConfigID': self.test_config_id,
                                'ConfigCategory': 'ADMIN_LOCK'
                            }
                        )
                        
                        if 'Item' in response:
                            item = response['Item']
                            admin_instance = item.get('InstanceID', 'Unknown')
                            last_heartbeat = item.get('LastHeartbeat', 0)
                            heartbeat_age = current_time - last_heartbeat
                            
                            self.logger.info(f"Current admin: {admin_instance}, last heartbeat: {heartbeat_age}s ago")
                            
                            # Check if admin has crashed (no heartbeat for 2 minutes)
                            if heartbeat_age > 120:
                                self.logger.warning(f"Current admin appears crashed (no heartbeat for {heartbeat_age}s)")
                                self.logger.info("Attempting admin role takeover...")
                                
                                # Attempt takeover by deleting stale lock and retrying
                                try:
                                    table.delete_item(
                                        Key={
                                            'TestConfigID': self.test_config_id,
                                            'ConfigCategory': 'ADMIN_LOCK'
                                        },
                                        ConditionExpression='InstanceID = :old_instance',
                                        ExpressionAttributeValues={
                                            ':old_instance': admin_instance
                                        }
                                    )
                                    
                                    self.logger.info("Stale admin lock deleted, retrying claim...")
                                    # Retry claim once
                                    return self._claim_admin_role()
                                    
                                except ClientError:
                                    self.logger.info("Takeover failed - another instance may have claimed role")
                                    return False
                    
                    except Exception as e:
                        self.logger.warning(f"Could not query current admin info: {e}")
                    
                    return False
                else:
                    self.logger.error(f"Unexpected error claiming admin role: {error_code}")
                    return False
        
        except Exception as e:
            self.logger.error(f"Error in admin role claiming: {e}")
            self.logger.error(traceback.format_exc())
            return False
    
    def _heartbeat_loop(self):
        """
        Maintain admin heartbeat to prove this instance is alive.
        
        Updates LastHeartbeat every 30 seconds and refreshes TTL.
        
        Requirements: 10.8, 10.9
        """
        
        self.logger.info("Admin heartbeat loop started")
        self.worker_logger.info("Admin heartbeat loop started")
        
        while not self.shutdown_event.is_set() and self.is_admin:
            try:
                # Sleep first (30 seconds between heartbeats)
                self.shutdown_event.wait(30)
                
                if self.shutdown_event.is_set():
                    break
                
                # Update heartbeat
                table = self.dynamodb.Table(TEST_DEFINITIONS_TABLE_NAME)
                
                current_time = int(time.time())
                
                table.update_item(
                    Key={
                        'TestConfigID': self.test_config_id,
                        'ConfigCategory': 'ADMIN_LOCK'
                    },
                    UpdateExpression='SET LastHeartbeat = :time, #ttl = :ttl',
                    ExpressionAttributeNames={
                        '#ttl': 'TTL'
                    },
                    ExpressionAttributeValues={
                        ':time': current_time,
                        ':ttl': current_time + LOCK_TTL_DURATION
                    }
                )
                
                self.logger.debug(f"Admin heartbeat updated")
                
            except ClientError as e:
                error_code = e.response.get('Error', {}).get('Code', 'Unknown')
                self.logger.warning(f"Failed to update admin heartbeat: {error_code}")
                self.worker_logger.warning(f"Failed to update admin heartbeat: {error_code}")
                
                # If lock is gone, we've lost admin role
                if error_code == 'ResourceNotFoundException':
                    self.logger.error("Admin lock disappeared - losing admin role")
                    self.worker_logger.error("Admin lock disappeared - losing admin role")
                    self.is_admin = False
                    break
            
            except Exception as e:
                self.logger.error(f"Error in admin heartbeat: {e}")
                self.worker_logger.error(f"Error in admin heartbeat: {e}")
        
        self.logger.info("Admin heartbeat loop stopped")
        self.worker_logger.info("Admin heartbeat loop stopped")
    
    def _release_admin_role(self):
        """
        Release admin role on shutdown.
        
        Deletes the ADMIN_LOCK to allow another instance to claim role.
        
        Requirements: 10.9
        """
        if not self.is_admin:
            return
        
        try:
            
            table = self.dynamodb.Table(TEST_DEFINITIONS_TABLE_NAME)
            
            table.delete_item(
                Key={
                    'TestConfigID': self.test_config_id,
                    'ConfigCategory': 'ADMIN_LOCK'
                }
            )
            
            self.logger.info("✓ Admin role released")
            self.worker_logger.info("✓ Admin role released")
            self.is_admin = False
            
        except Exception as e:
            self.logger.error(f"Error releasing admin role: {e}")
            self.worker_logger.error(f"Error releasing admin role: {e}")


# ============================================================================
# TASK 28.2: Batch Worker Coordinator
# ============================================================================

class BatchWorkerCoordinator:
    """
    Coordinates batch worker operations to prevent player conflicts.
    
    Manages player selection across multiple concurrent batch workers by:
    - Filtering out players in active Player Worker sessions
    - Filtering out players in active batch operations
    - Registering batch operations in coordination table
    - Cleaning up completed batch operations
    
    Requirements: 31.1, 31.2, 31.3, 31.4, 31.5, 31.6, 31.7, 31.8
    Design: Section 34.2
    Task: 28.2, 28.3, 28.4, 28.5
    """
    
    def __init__(self, test_config_id, aws_session, logger, event_config=None):
        """
        Initialize Batch Worker Coordinator.
        
        Args:
            test_config_id: Test Config ID
            aws_session: boto3 Session object
            logger: Logger instance
            event_config: Optional event configuration dictionary
        """
        self.test_config_id = test_config_id
        self.aws_session = aws_session
        self.logger = logger
        self.event_config = event_config or {}
        
        # Get DynamoDB tables
        dynamodb = aws_session.resource('dynamodb')
        self.coordination_table = dynamodb.Table(BATCH_COORDINATION_TABLE_NAME)
        self.player_state_table = dynamodb.Table(PLAYER_STATE_TABLE_NAME)
        
        self.logger.debug("BatchWorkerCoordinator initialized")
    
    def select_players_for_batch(self, batch_size, player_pool_config, max_attempts=10):
        """
        Select unique players for batch, avoiding conflicts with active sessions and other batches.
        
        Process:
        1. Oversample candidates (2x batch size)
        2. Filter out players in active Player Worker sessions
        3. Filter out players in active batch operations
        4. Retry with backoff if insufficient players
        
        Args:
            batch_size: Target number of players for batch
            player_pool_config: Player pool configuration dict
            max_attempts: Maximum selection attempts (default: 10)
        
        Returns:
            list: Selected player IDs, or empty list if selection fails
        
        Requirements: 31.1, 31.2, 31.3, 31.6
        Task: 28.3
        """
        
        pool_size = int(player_pool_config.get('poolSize', 10000))  # Convert to int (may be Decimal from DynamoDB)
        id_prefix = player_pool_config.get('idPrefix', 'player')
        
        for attempt in range(max_attempts):
            try:
                # Oversample candidates (2x batch size) - Requirement 31.6
                num_candidates = batch_size * 2
                
                # Generate random player IDs from pool
                candidate_player_ids = []
                for _ in range(num_candidates):
                    player_num = random.randint(1, pool_size)
                    player_id = f"{id_prefix}-{player_num:06d}"
                    candidate_player_ids.append(player_id)
                
                # Remove duplicates
                candidate_player_ids = list(set(candidate_player_ids))
                
                self.logger.debug(
                    f"Attempt {attempt + 1}/{max_attempts}: Generated {len(candidate_player_ids)} candidates"
                )
                
                # Filter out players in active sessions - Requirement 31.3
                available_players = self._filter_active_sessions(candidate_player_ids)
                
                self.logger.debug(
                    f"After session filter: {len(available_players)} available"
                )
                
                # Filter out players in active batches - Requirement 31.6
                available_players = self._filter_active_batches(available_players)
                
                self.logger.debug(
                    f"After batch filter: {len(available_players)} available"
                )
                
                # Take required number
                selected_players = available_players[:batch_size]
                
                if len(selected_players) >= batch_size:
                    self.logger.info(
                        f"Successfully selected {len(selected_players)} players on attempt {attempt + 1}"
                    )
                    return selected_players
                
                # Insufficient players - wait and retry with backoff
                if attempt < max_attempts - 1:
                    backoff_time = min(2 ** attempt, 10)  # Exponential backoff, max 10s
                    self.logger.warning(
                        f"Only found {len(selected_players)}/{batch_size} players. "
                        f"Retrying in {backoff_time}s..."
                    )
                    time.sleep(backoff_time)
            
            except Exception as e:
                self.logger.error(f"Error selecting players (attempt {attempt + 1}): {e}")
                if attempt < max_attempts - 1:
                    time.sleep(SLEEP_INTERVAL_MEDIUM)
        
        # Failed all attempts
        self.logger.error(
            f"Failed to select {batch_size} players after {max_attempts} attempts"
        )
        return []
    
    def _filter_active_sessions(self, player_ids):
        """
        Filter out players currently in active Player Worker Thread sessions.
        
        Args:
            player_ids: List of candidate player IDs
        
        Returns:
            list: Player IDs not in active sessions
        
        Requirements: 31.3
        Task: 28.3
        """
        
        available = []
        
        for player_id in player_ids:
            try:
                # Check if player has an active session
                composite_key = f"{self.test_config_id}_{player_id}"
                
                response = self.player_state_table.get_item(
                    Key={
                        'TestConfigID_PlayerID': composite_key,
                        'SessionStatus': 'ACTIVE'
                    }
                )
                
                # If item doesn't exist, player is available
                if 'Item' not in response:
                    available.append(player_id)
            
            except ClientError as e:
                error_code = e.response.get('Error', {}).get('Code', 'Unknown')
                if error_code != 'ResourceNotFoundException':
                    self.logger.warning(f"Error checking player {player_id} session: {error_code}")
                # Continue checking other players
            
            except Exception as e:
                self.logger.error(f"Error checking player {player_id}: {e}")
        
        return available
    
    def _filter_active_batches(self, player_ids):
        """
        Filter out players currently in active batch operations.
        
        Scans coordination table for active batches and excludes their players.
        
        Args:
            player_ids: List of candidate player IDs
        
        Returns:
            list: Player IDs not in active batches
        
        Requirements: 31.6
        Task: 28.3
        """
        try:
            # Query all active batches from coordination table
            response = self.coordination_table.scan(
                FilterExpression='#status = :active',
                ExpressionAttributeNames={'#status': 'Status'},
                ExpressionAttributeValues={':active': 'active'}
            )
            
            # Collect all players in active batches
            players_in_batches = set()
            for batch in response.get('Items', []):
                batch_players = batch.get('SelectedPlayerIDs', [])
                players_in_batches.update(batch_players)
            
            self.logger.debug(
                f"Found {len(players_in_batches)} players in {len(response.get('Items', []))} active batches"
            )
            
            # Filter out players in active batches
            available = [pid for pid in player_ids if pid not in players_in_batches]
            
            return available
        
        except Exception as e:
            self.logger.error(f"Error filtering active batches: {e}")
            # On error, return all players (fail open to avoid blocking)
            return player_ids
    
    def register_batch_operation(self, batch_id, selected_players, instance_id):
        """
        Register batch operation in coordination table.
        
        Creates a record with:
        - Batch ID
        - Selected player IDs
        - Event information
        - Start time
        - TTL (5 minutes from start)
        - Instance ID
        - Status (active)
        
        Args:
            batch_id: Unique batch operation ID
            selected_players: List of selected player IDs
            instance_id: Current instance ID
        
        Returns:
            bool: True if registration successful, False otherwise
        
        Requirements: 31.5
        Task: 28.4
        """
        try:
            current_time = int(time.time())
            ttl = current_time + 300  # 5 minutes - Requirement 31.5
            
            self.coordination_table.put_item(
                Item={
                    'BatchID': batch_id,
                    'SelectedPlayerIDs': selected_players,
                    'EventID': self.event_config.get('eventID', 'unknown'),
                    'LeaderboardName': self.event_config.get('leaderboardName', 'unknown'),
                    'StartTime': current_time,
                    'TTL': ttl,
                    'InstanceID': instance_id,
                    'Status': 'active'
                }
            )
            
            self.logger.info(
                f"Registered batch operation {batch_id} with {len(selected_players)} players "
                f"(TTL: {ttl})"
            )
            return True
        
        except Exception as e:
            self.logger.error(f"Failed to register batch operation {batch_id}: {e}")
            return False
    
    def complete_batch_operation(self, batch_id):
        """
        Mark batch operation as completed and delete from coordination table.
        
        Deletes the batch record to release players for other batches.
        If this fails, TTL will automatically clean up after 5 minutes.
        
        Args:
            batch_id: Batch operation ID to complete
        
        Requirements: 31.7, 31.8
        Task: 28.5
        """
        try:
            self.coordination_table.delete_item(
                Key={'BatchID': batch_id}
            )
            
            self.logger.info(f"Completed and cleaned up batch operation {batch_id}")
        
        except Exception as e:
            self.logger.warning(
                f"Failed to cleanup batch operation {batch_id}: {e}. "
                f"TTL will clean up automatically after 5 minutes."
            )


class BatchWorkerThread(threading.Thread):
    """
    Batch Worker Thread - submits batch game reports.
    
    Spawned during multiplayer events (5% of active threads).
    Submits batch reports with 10-100 player records per call.
    
    Requirements: 10.14, 10.15, 10.16, 10.17, 10.18
    Design: Section 4.3
    """
    
    def __init__(self, worker_id, test_config_id, config, aws_session, logger, shutdown_event, generator_factory, metrics_collector=None, main_controller=None):
        """
        Initialize Batch Worker Thread.
        
        Args:
            worker_id: Unique worker ID
            test_config_id: Test Config ID
            config: Test configuration dictionary
            aws_session: boto3 Session object
            logger: ThreadSafeLogger instance
            shutdown_event: threading.Event for shutdown coordination
            generator_factory: DataGeneratorFactory instance
            metrics_collector: MetricsCollector instance (optional, for RPS tracking)
            main_controller: MainController instance (optional, for cached event expiry checks)
        """
        super().__init__(name=f"BatchWorker-{worker_id}", daemon=False)
        
        self.worker_id = worker_id
        self.test_config_id = test_config_id
        self.config = config
        self.aws_session = aws_session
        self.logger = logger
        self.shutdown_event = shutdown_event
        self.generator_factory = generator_factory
        self.metrics_collector = metrics_collector  # For recording API metrics in RPS calculation
        self.main_controller = main_controller  # For cached event expiry checks
        
        # Worker-specific shutdown event for graceful termination when event expires
        self.worker_shutdown_event = threading.Event()
        
        # ============================================================================
        # TASK 32.1: Integrate BatchWorkerCoordinator
        # ============================================================================
        # Initialize batch worker coordinator for player selection (Requirements 31.1-31.8)
        self.coordinator = BatchWorkerCoordinator(
            test_config_id=test_config_id,
            aws_session=aws_session,
            logger=logger,
            event_config=config.get('active_event')
        )
        
        self.logger.info(f"Batch Worker Thread {worker_id} initialized with coordinator")
        
        # Cache DynamoDB resource to prevent file descriptor leaks
        self._dynamodb = None
    
    @property
    def dynamodb(self):
        """Cached DynamoDB resource to prevent file descriptor leaks."""
        if self._dynamodb is None:
            self._dynamodb = self.aws_session.resource('dynamodb')
        return self._dynamodb
    
    def run(self):
        """
        Main execution loop for Batch Worker.
        
        Submits batch game reports during active multiplayer events.
        Coordinates with other batch workers to avoid player conflicts.
        
        Requirements: 10.14, 10.15, 10.16, 10.17, 10.18
        Tasks: 12.1, 12.2, 12.3, 12.4, 12.5
        """
        self.logger.info(f"Batch Worker Thread {self.worker_id} starting...")
                
        # Initialize batch worker state
        self.batches_submitted = 0
        self.batches_failed = 0
        self.total_players_processed = 0
        
        # Get active event information from configuration
        active_event = self.config.get('active_event')
        
        if not active_event:
            self.logger.warning(f"No active event found in configuration - Batch Worker {self.worker_id} will idle")
            self.shutdown_event.wait()
            self.logger.info(f"Batch Worker Thread {self.worker_id} stopped")
            return
        
        event_name = active_event.get('eventName', 'unknown')
        event_type = active_event.get('eventType', 'unknown')
        target_leaderboard = active_event.get('leaderboardConfig', {}).get('leaderboardName', 'unknown')
        
        self.logger.info(f"Batch Worker {self.worker_id} assigned to event: {event_name} ({event_type})")
        self.logger.info(f"Target leaderboard: {target_leaderboard}")
        
        # Get API endpoint and credentials
        api_base_url = self.config.get('api_base_url')
        api_key = self.config.get('api_key')
        game_id = self.config.get('game_id')
        
        if not api_base_url or not api_key or not game_id:
            self.logger.error(f"Missing API configuration - Batch Worker {self.worker_id} cannot operate")
            self.logger.error(f"  api_base_url: {'present' if api_base_url else 'MISSING'}")
            self.logger.error(f"  api_key: {'present' if api_key else 'MISSING'}")
            self.logger.error(f"  game_id: {'present' if game_id else 'MISSING'}")
            self.shutdown_event.wait()
            self.logger.info(f"Batch Worker Thread {self.worker_id} stopped")
            return
        
        self.logger.info(f"✓ Batch Worker {self.worker_id} initialized successfully")
        self.logger.info(f"  API Endpoint: {api_base_url}")
        self.logger.info(f"  Game ID: {game_id}")
        
        # Main batch worker loop
        try:
            while not self.shutdown_event.is_set() and not self.worker_shutdown_event.is_set():
                # Select players for batch (Task 12.2)
                selected_players = self._select_batch_players()
                
                if not selected_players:
                    self.logger.warning(f"Batch Worker {self.worker_id}: No players available for batch")
                    # Wait before retrying (check both shutdown events)
                    if self.shutdown_event.wait(10) or self.worker_shutdown_event.wait(0):
                        break
                    continue
                
                self.logger.info(f"Batch Worker {self.worker_id}: Selected {len(selected_players)} players for batch")
                
                # Generate batch report (Task 12.3)
                batch_report = self._generate_batch_report(selected_players)
                
                if not batch_report:
                    self.logger.error(f"Batch Worker {self.worker_id}: Failed to generate batch report")
                    self.batches_failed += 1
                    if self.shutdown_event.wait(10) or self.worker_shutdown_event.wait(0):
                        break
                    continue
                
                self.logger.info(f"Batch Worker {self.worker_id}: Generated batch report with {len(batch_report['batchGameReportBody']['gameReports'])} player records")
                
                # Submit batch report (Task 12.4)
                success = self._submit_batch_report(batch_report)
                
                if success:
                    self.batches_submitted += 1
                    self.total_players_processed += len(selected_players)
                    self.logger.info(f"✓ Batch Worker {self.worker_id}: Batch submitted successfully")
                else:
                    # Check if shutdown was signaled (event expired)
                    if self.worker_shutdown_event.is_set():
                        self.logger.info(f"Batch Worker {self.worker_id}: Stopping due to event expiry")
                        break
                    
                    self.batches_failed += 1
                    self.logger.error(f"✗ Batch Worker {self.worker_id}: Batch submission failed")
                
                # Add realistic pause between submissions (1-3 seconds) - Requirement 31.9
                pause_duration = random.uniform(1.0, 3.0)
                self.logger.debug(f"Batch Worker {self.worker_id}: Pausing {pause_duration:.1f}s before next batch")
                # Check both shutdown events during pause
                if self.shutdown_event.wait(pause_duration) or self.worker_shutdown_event.is_set():
                    break
        
        except Exception as e:
            self.logger.error(f"Error in Batch Worker {self.worker_id}: {e}")
            self.logger.error(traceback.format_exc())
        
        finally:
            # Log final statistics
            self.logger.info(f"Batch Worker {self.worker_id} shutting down...")
            self.logger.info(f"  Batches submitted: {self.batches_submitted}")
            self.logger.info(f"  Batches failed: {self.batches_failed}")
            self.logger.info(f"  Total players processed: {self.total_players_processed}")
            
            if self.batches_submitted > 0:
                success_rate = (self.batches_submitted / (self.batches_submitted + self.batches_failed)) * 100
                avg_players_per_batch = self.total_players_processed / self.batches_submitted
                self.logger.info(f"  Success rate: {success_rate:.1f}%")
                self.logger.info(f"  Avg players per batch: {avg_players_per_batch:.1f}")
            
            self.logger.info(f"Batch Worker Thread {self.worker_id} stopped")
    
    def _select_batch_players(self):
        """
        Select 10-100 unique players for batch submission.
        
        Avoids players in active sessions by checking Player State Table.
        
        Note: Full coordination table support (to avoid players in other batches)
        will be added in Phase 18 (Task 28.1-28.10).
        
        Returns:
            list: List of player ID strings, or empty list if selection fails
        
        Requirements: 10.15, 31.1, 31.2, 31.3
        Tasks: 12.2
        """
        
        try:
            # Determine batch size (10-100 players)
            # Larger events get larger batches
            event_type = self.config.get('active_event', {}).get('eventType', 'challenge')
            
            if event_type == 'tournament':
                batch_size = random.randint(50, 100)  # Larger tournaments
            elif event_type == 'seasonal':
                batch_size = random.randint(30, 70)   # Medium seasonal events
            else:
                batch_size = random.randint(10, 40)   # Smaller challenges/daily events
            
            self.logger.debug(f"Batch Worker {self.worker_id}: Target batch size: {batch_size}")
            
            # Get player pool definition from configuration
            player_pool = self.config.get('player_pool', {})
            pool_size = int(player_pool.get('poolSize', 10000))  # Convert to int (may be Decimal from DynamoDB)
            id_prefix = player_pool.get('idPrefix', 'player')
            
            # Oversample candidates (2x batch size) to account for active sessions
            num_candidates = batch_size * 2
            
            # Generate random player IDs from pool
            candidate_player_ids = []
            for _ in range(num_candidates):
                player_num = random.randint(1, pool_size)
                player_id = f"{id_prefix}-{player_num:06d}"
                candidate_player_ids.append(player_id)
            
            # Remove duplicates
            candidate_player_ids = list(set(candidate_player_ids))
            
            self.logger.debug(f"Batch Worker {self.worker_id}: Generated {len(candidate_player_ids)} candidate players")
            
            # Query Player State Table to filter out players in active sessions
            player_state_table_name = self.config.get('player_state_table', PLAYER_STATE_TABLE_NAME)
            player_state_table = self.dynamodb.Table(player_state_table_name)
            
            available_players = []
            
            # Check each candidate player
            for player_id in candidate_player_ids:
                try:
                    # Check if player has an active session
                    composite_key = f"{self.test_config_id}_{player_id}"
                    response = player_state_table.get_item(
                        Key={
                            'TestConfigID_PlayerID': composite_key,
                            'SessionStatus': 'ACTIVE'
                        }
                    )
                    
                    if 'Item' not in response:
                        # Player not in active session - available for batch
                        available_players.append(player_id)
                        
                        # Stop once we have enough players
                        if len(available_players) >= batch_size:
                            break
                
                except ClientError as e:
                    error_code = e.response.get('Error', {}).get('Code', 'Unknown')
                    if error_code != 'ResourceNotFoundException':
                        self.logger.warning(f"Error checking player {player_id}: {error_code}")
                    # Continue checking other players
            
            if len(available_players) < batch_size:
                self.logger.warning(f"Batch Worker {self.worker_id}: Only found {len(available_players)}/{batch_size} available players")
                
                # If we have at least 10 players, proceed with smaller batch
                if len(available_players) < 10:
                    self.logger.error(f"Batch Worker {self.worker_id}: Insufficient players (need at least 10)")
                    return []
            
            # Trim to exact batch size if we have more than needed
            selected_players = available_players[:batch_size]
            
            self.logger.info(f"Batch Worker {self.worker_id}: Selected {len(selected_players)} players")
            self.logger.debug(f"  Player IDs: {', '.join(selected_players[:5])}{'...' if len(selected_players) > 5 else ''}")
            
            return selected_players
        
        except Exception as e:
            self.logger.error(f"Error selecting batch players: {e}")
            self.logger.error(traceback.format_exc())
            return []
    
    def _generate_batch_report(self, selected_players):
        """
        Generate realistic batch report with competitive score distributions.
        
        Creates match data with:
        - Top 10%: 900-1000 scores (winners)
        - Mid 60%: 500-900 scores (mid-tier performers)
        - Bottom 30%: 100-500 scores (lower performers)
        
        Includes match-specific context: match ID, teams, duration, placement.
        
        Uses thread-local RNG for true randomness across concurrent workers.
        
        Args:
            selected_players: List of player ID strings
        
        Returns:
            dict: Batch report in API format, or None on failure
        
        Requirements: 10.16, 31.10, 31.12
        Tasks: 12.3
        """
        
        try:
            batch_size = len(selected_players)
            
            if batch_size == 0:
                self.logger.error("Cannot generate batch report with 0 players")
                return None
            
            # Get active event configuration
            active_event = self.config.get('active_event', {})
            game_id = self.config.get('game_id')
            
            if not active_event or not game_id:
                self.logger.error("Missing active event or game ID configuration")
                return None
            
            event_name = active_event.get('eventName', 'unknown')
            lb_config = active_event.get('leaderboardConfig', {})
            game_mode = lb_config.get('gameMode', 'default')
            leaderboard_name = lb_config.get('leaderboardName', 'unknown')
            stat_attribute = lb_config.get('statAttributeForLeaderboard', 'score')
            
            # Get thread-local RNG from score generator for true randomness
            score_generator = self.generator_factory.get_score_generator()
            rng = score_generator._get_thread_random()
            
            # Generate unique match ID
            match_id = f"match-{uuid.uuid4().hex[:8]}"
            match_duration = rng.randint(600, 1800)  # 10-30 minutes in seconds
            
            self.logger.debug(f"Generating batch report for match {match_id}")
            self.logger.debug(f"  Event: {event_name}, Mode: {game_mode}, LB: {leaderboard_name}")
            
            # Generate scores with competitive distribution using thread-local RNG
            player_scores = []
            
            for i, player_id in enumerate(selected_players):
                # Determine player tier based on position
                percentile = i / batch_size
                
                # Assign scores based on competitive distribution
                # Use thread-local RNG for true randomness
                if percentile < 0.10:  # Top 10% - winners
                    score = rng.uniform(900, 1000)
                    tier = "winner"
                elif percentile < 0.70:  # Mid 60% - mid-tier performers
                    score = rng.uniform(500, 900)
                    tier = "mid-tier"
                else:  # Bottom 30% - lower performers
                    score = rng.uniform(100, 500)
                    tier = "lower"
                
                # Round score to 2 decimal places
                score = round(score, 2)
                
                # Create player record with match context
                player_record = {
                    'playerID': player_id,
                    'score': score,
                    'tier': tier,
                    'placement': i + 1,
                    'teamAssignment': 'team-' + ('A' if i % 2 == 0 else 'B')
                }
                
                player_scores.append(player_record)
            
            # Shuffle to randomize order (don't submit in sorted order)
            # Use thread-local RNG for shuffle
            rng.shuffle(player_scores)
            
            # Build batch report in API format
            game_reports = []
            
            for player_record in player_scores:
                # Build fullRawGameReport with match-specific context
                full_raw_game_report = {
                    'matchID': match_id,
                    'matchDuration': match_duration,
                    'placement': player_record['placement'],
                    'teamAssignment': player_record['teamAssignment'],
                    'playerTier': player_record['tier'],
                    stat_attribute: player_record['score']
                }
                
                # Build game report for this player
                game_report = {
                    'playerID': player_record['playerID'],
                    'gameID': game_id,
                    'gameMode': game_mode,
                    'playerScore': player_record['score'],
                    'leaderboardName': leaderboard_name,
                    'fullRawGameReport': full_raw_game_report
                }
                
                game_reports.append(game_report)
            
            # Build final batch report structure
            batch_report = {
                'batchGameReportBody': {
                    'gameReports': game_reports
                }
            }
            
            # Log distribution statistics
            winners = sum(1 for p in player_scores if p['tier'] == 'winner')
            mid_tier = sum(1 for p in player_scores if p['tier'] == 'mid-tier')
            lower = sum(1 for p in player_scores if p['tier'] == 'lower')
            
            self.logger.debug(f"  Match {match_id} distribution: {winners} winners, {mid_tier} mid-tier, {lower} lower")
            self.logger.debug(f"  Score range: {min(p['score'] for p in player_scores):.2f} - {max(p['score'] for p in player_scores):.2f}")
            
            return batch_report
        
        except Exception as e:
            self.logger.error(f"Error generating batch report: {e}")
            self.logger.error(traceback.format_exc())
            return None
    
    def _submit_batch_report(self, batch_report):
        """
        Submit batch report to POST /leaderboards/stats/batch API with retry logic.
        
        Implements exponential backoff retry for transient errors:
        - Max 3 retry attempts
        - Backoff: 1s, 2s, 4s
        - Retries on: 5xx errors, network errors, timeouts
        - No retry on: 4xx errors (except 429 throttling)
        
        Targets only the leaderboard associated with the active multiplayer event.
        Uses correct authentication (Authorization: Bearer) as per design.md.
        
        Args:
            batch_report: Batch report dictionary in API format
        
        Returns:
            bool: True if submission successful, False otherwise
        
        Requirements: 10.17, 10.18, 17.1, 17.2, 17.3, 31.9, 31.11
        Tasks: 12.4, 12.5
        """
        
        # Retry configuration
        max_retries = 3
        retry_delays = [1, 2, 4]  # Exponential backoff: 1s, 2s, 4s
        
        # Check if event has expired or is about to expire BEFORE attempting submission
        # Add 10-second safety buffer to prevent race conditions at expiry boundary
        # This prevents hitting 423 errors and avoids wasted API calls
        active_event = self.config.get('active_event', {})
        event_name = active_event.get('eventName', 'unknown')
        end_time = active_event.get('endTime', 0)
        
        if self.main_controller and end_time > 0:
            current_time = time.time()
            # Convert end_time to float if it's a Decimal (from DynamoDB)
            end_time_float = float(end_time) if isinstance(end_time, Decimal) else end_time
            time_until_expiry = end_time_float - current_time
            
            # Stop submissions 10 seconds before expiry to avoid race conditions
            if time_until_expiry <= 10:
                if time_until_expiry > 0:
                    self.logger.info(f"Batch Worker {self.worker_id}: Event '{event_name}' expires in {time_until_expiry:.1f}s, stopping submissions early")
                else:
                    self.logger.info(f"Batch Worker {self.worker_id}: Event '{event_name}' has expired, shutting down gracefully")
                self.worker_shutdown_event.set()
                return False
        
        for attempt in range(max_retries + 1):  # 0, 1, 2, 3 (initial + 3 retries)
            try:
                # Get API configuration
                api_base_url = self.config.get('api_base_url')
                api_key = self.config.get('api_key')
                
                if not api_base_url or not api_key:
                    self.logger.error("Missing API configuration for batch submission")
                    return False
                
                # Extract batch details for logging
                game_reports = batch_report.get('batchGameReportBody', {}).get('gameReports', [])
                num_players = len(game_reports)
                
                if num_players == 0:
                    self.logger.error("Batch report contains no game reports")
                    return False
                
                # Get leaderboard name from first report (all should target same leaderboard)
                leaderboard_name = game_reports[0].get('leaderboardName', 'unknown')
                
                # Verify all reports target the same leaderboard (Requirement 31.11)
                leaderboard_names = set(report.get('leaderboardName') for report in game_reports)
                if len(leaderboard_names) > 1:
                    self.logger.warning(f"Batch contains multiple leaderboards: {leaderboard_names}")
                    self.logger.warning("This may indicate a configuration error")
                
                # Log attempt number if retrying
                if attempt > 0:
                    self.logger.info(f"Retry attempt {attempt}/{max_retries}: Submitting batch to '{leaderboard_name}'")
                else:
                    self.logger.info(f"Submitting batch: {num_players} players to leaderboard '{leaderboard_name}'")
                
                # Build endpoint URL
                endpoint = f"{api_base_url}/leaderboards/stats/batch"
                
                # Record start time for latency measurement
                start_time = time.time()
                
                # Submit batch report
                # CRITICAL: Use Authorization: Bearer header (NOT x-api-key) per design.md lines 50-62
                response = requests.post(
                    endpoint,
                    json=batch_report,
                    headers={
                        'Content-Type': 'application/json',
                        'Authorization': f'Bearer {api_key}'
                    },
                    timeout=API_TIMEOUT_WRITE
                )
                
                # Calculate latency
                latency_ms = (time.time() - start_time) * 1000
                
                # Record API call in metrics collector for RPS tracking
                if self.metrics_collector:
                    endpoint_name = "POST /leaderboards/stats/batch"
                    # Will record success/failure after response validation
                
                # Check response status
                if response.status_code not in [200, 201]:
                    # Determine if error is retryable
                    is_retryable = False
                    
                    if response.status_code == 423:
                        # Leaderboard locked (expired/read-only) - event has ended
                        # This is expected behavior, not an error - log as INFO
                        self.logger.info(f"Batch Worker {self.worker_id}: Event leaderboard expired (423), shutting down gracefully")
                        self.logger.info(f"Batch Worker {self.worker_id}: Leaderboard: {leaderboard_name}")
                        self.logger.debug(f"Batch Worker {self.worker_id}: Response: {response.text[:500]}")
                        
                        # Record failed API call in metrics collector
                        if self.metrics_collector:
                            error_details = {
                                'status_code': 423,
                                'error_type': 'LEADERBOARD_EXPIRED',
                                'message': 'Leaderboard locked - event expired (expected)'
                            }
                            self.metrics_collector.record_request("POST /leaderboards/stats/batch", latency_ms, success=False, error_details=error_details)
                        
                        # Signal this worker to shut down gracefully
                        self.worker_shutdown_event.set()
                        return False
                    elif response.status_code == 429:
                        # Throttling - retryable
                        self.logger.warning(f"Batch Worker {self.worker_id}: Throttling (429) on attempt {attempt + 1}")
                        self.logger.warning(f"Batch Worker {self.worker_id}: Leaderboard: {leaderboard_name}, Players: {num_players}")
                        is_retryable = True
                    elif response.status_code >= 500:
                        # Server error - retryable
                        self.logger.warning(f"Batch Worker {self.worker_id}: Server error ({response.status_code}) on attempt {attempt + 1}")
                        self.logger.warning(f"Batch Worker {self.worker_id}: Leaderboard: {leaderboard_name}, Players: {num_players}")
                        self.logger.warning(f"Batch Worker {self.worker_id}: Endpoint: POST /leaderboards/stats/batch")
                        is_retryable = True
                    else:
                        # Client error (4xx except 429, 423) - not retryable
                        self.logger.error(f"Batch Worker {self.worker_id}: Client error ({response.status_code}) - not retryable")
                        self.logger.error(f"Batch Worker {self.worker_id}: Leaderboard: {leaderboard_name}, Players: {num_players}")
                        self.logger.error(f"Batch Worker {self.worker_id}: Response: {response.text[:500]}")
                        self.logger.error(f"Batch Worker {self.worker_id}: Latency: {latency_ms:.0f}ms")
                        
                        # Record failed API call in metrics collector
                        if self.metrics_collector:
                            error_details = {
                                'status_code': response.status_code,
                                'error_type': 'CLIENT_ERROR',
                                'message': f'HTTP {response.status_code}'
                            }
                            self.metrics_collector.record_request("POST /leaderboards/stats/batch", latency_ms, success=False, error_details=error_details)
                        
                        return False
                    
                    # If retryable and we have retries left, continue to retry logic
                    if is_retryable and attempt < max_retries:
                        retry_delay = retry_delays[attempt]
                        self.logger.warning(f"⚠️  Batch Worker {self.worker_id}: HTTP {response.status_code} attempt {attempt + 1}/{max_retries} | LB: {leaderboard_name} ({num_players} players) | Retry in {retry_delay}s")
                        time.sleep(retry_delay)
                        continue  # Retry
                    else:
                        # No more retries or not retryable
                        self.logger.error(f"❌ FAILED: Batch Worker {self.worker_id}: HTTP {response.status_code} after {attempt + 1} attempts | LB: {leaderboard_name} | LOST {num_players} player scores | {latency_ms:.0f}ms")
                        
                        # Record failed API call in metrics collector (final failure after retries)
                        if self.metrics_collector:
                            error_details = {
                                'status_code': response.status_code,
                                'error_type': 'RETRY_EXHAUSTED',
                                'message': f'Failed after {attempt + 1} attempts'
                            }
                            self.metrics_collector.record_request("POST /leaderboards/stats/batch", latency_ms, success=False, error_details=error_details)
                        
                        return False
                
                # Parse response
                response_data = response.json()
                batch_response = response_data.get('batchGameReportResponse', {})
                
                if not batch_response.get('success'):
                    error_message = batch_response.get('message', 'Unknown error')
                    self.logger.error(f"Batch submission failed: {error_message}")
                    self.logger.error(f"Latency: {latency_ms:.0f}ms")
                    
                    # Record failed API call in metrics collector
                    if self.metrics_collector:
                        error_details = {
                            'status_code': response.status_code,
                            'error_type': 'API_ERROR',
                            'message': error_message
                        }
                        self.metrics_collector.record_request("POST /leaderboards/stats/batch", latency_ms, success=False, error_details=error_details)
                    
                    # API returned success=false - generally not retryable (data validation issue)
                    return False
                
                # Success! Log details
                job_id = batch_response.get('jobId', 'N/A')
                summary = batch_response.get('summary', {})
                total_items = summary.get('totalItems', 0)
                processed_items = summary.get('processedItems', 0)
                validation_errors = summary.get('validationErrors', 0)
                
                if attempt > 0:
                    self.logger.info(f"✅ SUCCESS: Batch Worker {self.worker_id}: Recovered on attempt {attempt + 1} | LB: {leaderboard_name} | {processed_items}/{total_items} items | {validation_errors} errors | {latency_ms:.0f}ms")
                else:
                    self.logger.info(f"✅ SUCCESS: Batch Worker {self.worker_id}: LB: {leaderboard_name} | {processed_items}/{total_items} items | {validation_errors} errors | {latency_ms:.0f}ms")
                
                # Record successful API call in metrics collector
                if self.metrics_collector:
                    self.metrics_collector.record_request("POST /leaderboards/stats/batch", latency_ms, success=True)
                
                # Log warning if there were validation errors
                if validation_errors > 0:
                    self.logger.warning(f"Batch had {validation_errors} validation errors")
                    # Log error details if available
                    error_details = batch_response.get('errorDetails', [])
                    if error_details:
                        for error in error_details[:5]:  # Log first 5 errors
                            self.logger.warning(f"  Error: {error}")
                
                return True
            
            except requests.exceptions.Timeout:
                # Timeout - retryable
                if attempt < max_retries:
                    retry_delay = retry_delays[attempt]
                    self.logger.warning(f"⚠️  Batch Worker {self.worker_id}: Timeout (30s) attempt {attempt + 1}/{max_retries} | LB: {leaderboard_name} ({num_players} players) | Retry in {retry_delay}s")
                    time.sleep(retry_delay)
                    continue  # Retry
                else:
                    self.logger.error(f"❌ FAILED: Batch Worker {self.worker_id}: Timeout after {attempt + 1} attempts (30s each) | LB: {leaderboard_name} | LOST {num_players} player scores")
                    return False
            
            except requests.exceptions.RequestException as e:
                # Network error - retryable
                if attempt < max_retries:
                    retry_delay = retry_delays[attempt]
                    self.logger.warning(f"⚠️  Batch Worker {self.worker_id}: Network error attempt {attempt + 1}/{max_retries} | LB: {leaderboard_name} ({num_players} players) | {str(e)[:50]} | Retry in {retry_delay}s")
                    time.sleep(retry_delay)
                    continue  # Retry
                else:
                    self.logger.error(f"❌ FAILED: Batch Worker {self.worker_id}: Network error after {attempt + 1} attempts | LB: {leaderboard_name} | LOST {num_players} player scores | {str(e)[:100]}")
                    return False
            
            except Exception as e:
                # Unexpected error - log with full context and don't retry
                self.logger.error(f"Batch Worker {self.worker_id}: Unexpected error during batch submission (attempt {attempt + 1}): {e}")
                self.logger.error(f"Batch Worker {self.worker_id}: Leaderboard: {leaderboard_name}, Players: {num_players}")
                self.logger.error(traceback.format_exc())
                return False
        
        # Should never reach here, but just in case
        self.logger.error(f"Batch Worker {self.worker_id}: Batch submission failed: exhausted all retry attempts")
        return False


# ============================================================================
# SECTION: PLAYER PROGRESSION PERSISTENCE
# ============================================================================

class PlayerProgressionManager:
    """
    Player Progression Manager - handles persistent player progression across sessions.
    
    Manages:
    - Player level and experience points
    - Cumulative statistics
    - Achievement unlocking
    - Progression curves (exponential)
    
    Requirements: 34.1-34.18
    Design: Section 37
    """
    
    # Progression configuration (Requirements 34.8, 34.14)
    BASE_XP_PER_LEVEL = 1000
    XP_MULTIPLIER = 1.15
    MAX_LEVEL = 100
    
    # Progression rate profiles (Requirement 34.14)
    PROGRESSION_RATES = {
        'slow': 0.5,      # 50% XP gain
        'normal': 1.0,    # 100% XP gain (default)
        'fast': 2.0       # 200% XP gain
    }
    
    # Achievement definitions (Requirement 34.11)
    ACHIEVEMENTS = {
        # Level-based achievements
        'level_10': {'type': 'level', 'threshold': 10, 'name': 'Novice'},
        'level_25': {'type': 'level', 'threshold': 25, 'name': 'Experienced'},
        'level_50': {'type': 'level', 'threshold': 50, 'name': 'Veteran'},
        'level_75': {'type': 'level', 'threshold': 75, 'name': 'Master'},
        'level_100': {'type': 'level', 'threshold': 100, 'name': 'Legend'},
        
        # Stat-based achievements
        'games_100': {'type': 'games_played', 'threshold': 100, 'name': 'Century'},
        'games_500': {'type': 'games_played', 'threshold': 500, 'name': 'Dedicated'},
        'games_1000': {'type': 'games_played', 'threshold': 1000, 'name': 'Marathon Runner'},
        
        'score_10000': {'type': 'total_score', 'threshold': 10000, 'name': 'High Scorer'},
        'score_50000': {'type': 'total_score', 'threshold': 50000, 'name': 'Score Master'},
        'score_100000': {'type': 'total_score', 'threshold': 100000, 'name': 'Score Legend'}
    }
    
    def __init__(self, test_config_id, region, profile, aws_session, shutdown_event, progression_rate='normal'):
        """
        Initialize the progression manager.
        
        Args:
            test_config_id: Test Config ID
            region: AWS region
            profile: AWS profile name (optional)
            aws_session: boto3 Session object (reused to prevent file descriptor leaks)
            shutdown_event: threading.Event for shutdown coordination
            progression_rate: Progression rate profile ('slow', 'normal', 'fast')
        
        Requirements: 34.14
        """
        self.test_config_id = test_config_id
        self.region = region
        self.profile = profile
        self.aws_session = aws_session
        self.shutdown_event = shutdown_event
        self.progression_rate = self.PROGRESSION_RATES.get(progression_rate, 1.0)
        
        # Cache DynamoDB resource to prevent file descriptor leaks
        self._dynamodb = None
    
    @property
    def dynamodb(self):
        """Cached DynamoDB resource to prevent file descriptor leaks."""
        if self._dynamodb is None:
            self._dynamodb = self.aws_session.resource('dynamodb')
        return self._dynamodb
    
    def calculate_xp_for_level(self, level):
        """
        Calculate total XP required to reach a specific level.
        
        Uses exponential progression curve: XP = BASE * (MULTIPLIER ^ (level - 1))
        
        Args:
            level: Target level (1-100)
        
        Returns:
            int: Total XP required
        
        Requirements: 34.8
        Task: 31.6
        """
        if level <= 1:
            return 0
        
        total_xp = 0
        for lvl in range(1, level):
            xp_for_level = int(self.BASE_XP_PER_LEVEL * (self.XP_MULTIPLIER ** (lvl - 1)))
            total_xp += xp_for_level
        
        return total_xp
    
    def calculate_level_from_xp(self, total_xp):
        """
        Calculate player level from total XP.
        
        Args:
            total_xp: Total experience points
        
        Returns:
            int: Player level (1-100)
        
        Requirements: 34.8
        Task: 31.6
        """
        level = 1
        accumulated_xp = 0
        
        while level < self.MAX_LEVEL:
            xp_for_next_level = int(self.BASE_XP_PER_LEVEL * (self.XP_MULTIPLIER ** (level - 1)))
            if accumulated_xp + xp_for_next_level > total_xp:
                break
            accumulated_xp += xp_for_next_level
            level += 1
        
        return level
    
    def check_achievements(self, progression_data):
        """
        Check for newly unlocked achievements.
        
        Args:
            progression_data: Player progression dictionary
        
        Returns:
            list: List of newly unlocked achievement IDs
        
        Requirements: 34.11, 34.12
        Task: 31.7
        """
        newly_unlocked = []
        
        # Ensure current_achievements contains only strings (achievement IDs)
        current_achievements_raw = progression_data.get('achievements', [])
        current_achievements = set()
        for ach in current_achievements_raw:
            if isinstance(ach, str):
                current_achievements.add(ach)
            elif isinstance(ach, dict) and 'id' in ach:
                current_achievements.add(ach['id'])
            # Skip any other types
        
        level = progression_data.get('level', 1)
        stats = progression_data.get('cumulative_statistics', {})
        games_played = stats.get('games_played', 0)
        total_score = stats.get('total_score', 0)
        
        for achievement_id, achievement in self.ACHIEVEMENTS.items():
            # Skip if already unlocked
            if achievement_id in current_achievements:
                continue
            
            # Check achievement criteria
            unlocked = False
            if achievement['type'] == 'level':
                unlocked = level >= achievement['threshold']
            elif achievement['type'] == 'games_played':
                unlocked = games_played >= achievement['threshold']
            elif achievement['type'] == 'total_score':
                unlocked = total_score >= achievement['threshold']
            
            if unlocked:
                newly_unlocked.append(achievement_id)
        
        return newly_unlocked
    
    def initialize_new_player(self, player_id):
        """
        Initialize persistent progression for a new player.
        
        Args:
            player_id: Player ID
        
        Returns:
            dict: Initial progression data
        
        Requirements: 34.5
        Task: 31.3
        """
        
        try:
            # Create boto3 session
            session_kwargs = {'region_name': self.region}
            if self.profile:
                session_kwargs['profile_name'] = self.profile
            
            session = boto3.Session(**session_kwargs)
            dynamodb = session.resource('dynamodb')
            table = dynamodb.Table(PLAYER_STATE_TABLE_NAME)
            
            # Initial progression data
            progression_data = {
                'TestConfigID_PlayerID': f"{self.test_config_id}_{player_id}",
                'SessionStatus': 'PERSISTENT',  # Sort key
                'level': 1,
                'total_xp': 0,
                'cumulative_statistics': {
                    'games_played': 0,
                    'total_score': 0,
                    'total_playtime_seconds': 0,
                    'sessions_completed': 0
                },
                'achievements': [],
                'last_session_timestamp': int(time.time()),
                'version': 1,
                'created_at': int(time.time())
                # NO TTL - persists for entire test duration (Requirement 34.4)
            }
            
            # Use conditional write to prevent duplicates (Requirement 34.5)
            table.put_item(
                Item=progression_data,
                ConditionExpression='attribute_not_exists(TestConfigID_PlayerID)'
            )
            
            return progression_data
            
        except ClientError as e:
            if e.response['Error']['Code'] == 'ConditionalCheckFailedException':
                # Player already exists, load existing progression
                return self.load_player_progression(player_id)
            else:
                raise
    
    def load_player_progression(self, player_id):
        """
        Load persistent progression for a returning player.
        
        Args:
            player_id: Player ID
        
        Returns:
            dict: Progression data, or None if not found
        
        Requirements: 34.6
        Task: 31.4
        """
        
        try:
            # Reuse existing session instead of creating new one (prevents file descriptor leak)
            table = self.dynamodb.Table(PLAYER_STATE_TABLE_NAME)
            
            # Load persistent progression record
            response = table.get_item(
                Key={
                    'TestConfigID_PlayerID': f"{self.test_config_id}_{player_id}",
                    'SessionStatus': 'PERSISTENT'
                }
            )
            
            if 'Item' in response:
                return dict(response['Item'])
            else:
                return None
                
        except ClientError as e:
            # ResourceNotFoundException is expected for new players - don't print error
            if e.response['Error']['Code'] != 'ResourceNotFoundException':
                print(f"Error loading player progression: {e}")
            return None
    
    def update_player_progression(self, player_id, session_stats, max_retries=3):
        """
        Update persistent progression after a session completes.
        
        Calculates new XP, level, and checks for achievements.
        Uses optimistic locking with version numbers.
        
        Args:
            player_id: Player ID
            session_stats: Dictionary with session statistics
            max_retries: Maximum retry attempts on version conflicts
        
        Returns:
            dict: Updated progression data, or None on failure
        
        Requirements: 34.7, 34.9, 34.12, 34.13
        Task: 31.5, 31.8
        """
        
        # Skip progression updates if shutdown is in progress
        if self.shutdown_event.is_set():
            return None
        
        for attempt in range(max_retries):
            try:
                # Check shutdown again before each retry
                if self.shutdown_event.is_set():
                    return None
                
                # Load current progression
                current_progression = self.load_player_progression(player_id)
                if not current_progression:
                    # Initialize if doesn't exist
                    current_progression = self.initialize_new_player(player_id)
                
                # Calculate XP gain (apply progression rate modifier)
                base_xp_gain = session_stats.get('xp_earned', 100)
                xp_gain = int(base_xp_gain * self.progression_rate)
                
                # Update XP and level
                new_total_xp = current_progression['total_xp'] + xp_gain
                new_level = self.calculate_level_from_xp(new_total_xp)
                
                # Ensure level never decreases (Requirement 34.13, Task 31.8)
                if new_level < current_progression['level']:
                    new_level = current_progression['level']
                
                # Update cumulative statistics (only increase, Requirement 34.13)
                current_stats = current_progression.get('cumulative_statistics', {})
                new_stats = {
                    'games_played': current_stats.get('games_played', 0) + session_stats.get('games_played', 1),
                    'total_score': current_stats.get('total_score', 0) + session_stats.get('score', 0),
                    'total_playtime_seconds': current_stats.get('total_playtime_seconds', 0) + session_stats.get('playtime_seconds', 0),
                    'sessions_completed': current_stats.get('sessions_completed', 0) + 1
                }
                
                # Prepare updated progression data
                updated_progression = {
                    **current_progression,
                    'level': new_level,
                    'total_xp': new_total_xp,
                    'cumulative_statistics': new_stats,
                    'last_session_timestamp': int(time.time()),
                    'version': current_progression['version'] + 1
                }
                
                # Check for new achievements
                newly_unlocked = self.check_achievements(updated_progression)
                if newly_unlocked:
                    # Ensure current_achievements contains only strings (achievement IDs)
                    current_achievements_raw = updated_progression.get('achievements', [])
                    # Handle case where achievements might be stored as dicts or other types
                    current_achievements = set()
                    for ach in current_achievements_raw:
                        if isinstance(ach, str):
                            current_achievements.add(ach)
                        elif isinstance(ach, dict) and 'id' in ach:
                            current_achievements.add(ach['id'])
                        # Skip any other types
                    
                    # Add newly unlocked achievements (these are always strings from check_achievements)
                    current_achievements.update(newly_unlocked)
                    updated_progression['achievements'] = list(current_achievements)
                
                # Update with optimistic locking (reuse existing session)
                table = self.dynamodb.Table(PLAYER_STATE_TABLE_NAME)
                
                table.put_item(
                    Item=updated_progression,
                    ConditionExpression='version = :expected_version',
                    ExpressionAttributeValues={
                        ':expected_version': current_progression['version']
                    }
                )
                
                return updated_progression
                
            except ClientError as e:
                if e.response['Error']['Code'] == 'ConditionalCheckFailedException':
                    # Version conflict - retry
                    if attempt < max_retries - 1:
                        time.sleep(0.1 * (attempt + 1))  # Exponential backoff
                        continue
                    else:
                        print(f"Failed to update progression after {max_retries} attempts (version conflict)")
                        return None
                else:
                    print(f"Error updating player progression: {e}")
                    return None
            except Exception as e:
                print(f"Unexpected error updating progression: {e}")
                traceback.print_exc()
                return None
        
        return None
    
    def get_progression_modifiers(self, progression_data):
        """
        Get behavior modifiers based on player progression.
        
        Higher level players:
        - Check leaderboards more frequently
        - Submit better scores
        - Have longer sessions
        - Use more competitive behavior profiles
        
        Args:
            progression_data: Player progression dictionary
        
        Returns:
            dict: Behavior modifiers
        
        Requirements: 34.10, 34.17
        Task: 31.10
        """
        level = progression_data.get('level', 1)
        
        # Convert Decimal to int/float to avoid type errors with DynamoDB Decimal types
        level = int(level) if isinstance(level, Decimal) else level
        
        # Calculate modifiers based on level (linear scaling)
        level_factor = min(float(level) / 100.0, 1.0)  # 0.0 to 1.0
        
        modifiers = {
            # Leaderboard check probability: 30% at level 1, 70% at level 100
            'leaderboard_check_probability': 0.3 + (0.4 * level_factor),
            
            # Score multiplier: 1.0x at level 1, 1.5x at level 100
            'score_multiplier': 1.0 + (0.5 * level_factor),
            
            # Session duration multiplier: 1.0x at level 1, 1.3x at level 100
            'session_duration_multiplier': 1.0 + (0.3 * level_factor),
            
            # Behavior profile: casual → competitive → hardcore
            'behavior_profile': self._get_behavior_profile_for_level(level),
            
            # Initial pause for returning players (shorter for higher levels)
            'initial_pause_seconds': max(1, 15 - (level * 0.14))  # 15s at level 1, 1s at level 100
        }
        
        return modifiers
    
    def _get_behavior_profile_for_level(self, level):
        """
        Determine behavior profile based on player level.
        
        Args:
            level: Player level
        
        Returns:
            str: Behavior profile name
        
        Requirements: 34.17
        Task: 31.10
        """
        if level < 20:
            return 'casual'
        elif level < 60:
            return 'competitive'
        else:
            return 'hardcore'


class WorkerLogger:
    """
    Per-worker logger for sampled workers (dynamic sampling rate).
    
    Sampling rate adjusts based on worker count as percentage of MAX_PLAYERS_PER_INSTANCE:
    - ≤10% of MAX: 100% sampling (all workers logged)
    - Every +10% of MAX: -10% sampling
    - 100% of MAX: 10% sampling
    
    Example with MAX_PLAYERS_PER_INSTANCE=100:
    - 10 workers (10%): 100% sampling → 10 sampled
    - 20 workers (20%): 90% sampling → 18 sampled
    - 50 workers (50%): 60% sampling → 30 sampled
    - 100 workers (100%): 10% sampling → 10 sampled
    
    Provides detailed logging of all worker activities with event IDs
    for correlation with main.log entries.
    
    Features:
    - Event ID generation for log correlation
    - Full request/response logging
    - Worker-specific log file (optional, controlled by ENABLE_LOCAL_WORKER_LOGS)
    - CloudWatch streaming (always enabled)
    - Thread-safe writes
    """
    
    def __init__(self, log_file, worker_id, main_logger, cloudwatch_handler=None, instance_id=None):
        """
        Initialize Worker Logger.
        
        Args:
            log_file: Path to worker-specific log file (only used if ENABLE_LOCAL_WORKER_LOGS=True)
            worker_id: Worker ID
            main_logger: Reference to main ThreadSafeLogger for cross-logging
            cloudwatch_handler: Optional CloudWatchLogHandler for streaming logs
            instance_id: Instance ID for cross-referencing logs (optional)
        """
        self.log_file = Path(log_file) if ENABLE_LOCAL_WORKER_LOGS else None
        self.worker_id = worker_id
        self.main_logger = main_logger
        self.cloudwatch_handler = cloudwatch_handler
        self.instance_id = instance_id  # Store for cross-reference links
        self.lock = threading.Lock()
        
        # Only create local log file if feature flag is enabled
        if ENABLE_LOCAL_WORKER_LOGS and self.log_file:
            # Add separator if log file already exists
            if self.log_file.exists():
                self._write(f"\n{'='*80}\n")
                self._write(f"NEW TEST RUN STARTED AT: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
                self._write(f"{'='*80}\n\n")
            
            # Write header
            self._write(f"{'='*80}\n")
            self._write(f"Worker {worker_id} Detailed Activity Log\n")
            self._write(f"Started: {datetime.now().isoformat()}\n")
            self._write(f"{'='*80}\n\n")
    
    def _write(self, message):
        """Write message to log file with locking (only if local logging enabled)."""
        if not ENABLE_LOCAL_WORKER_LOGS or not self.log_file:
            return
        
        with self.lock:
            with open(self.log_file, 'a', encoding='utf-8') as f:
                f.write(message)
    
    def _format_message(self, level, message, event_id=None):
        """Format log message with timestamp, level, thread ID, and optional event ID."""
        
        timestamp = datetime.now().isoformat(timespec='milliseconds')
        thread_id = threading.get_ident()
        process_id = os.getpid()
        
        if ENABLE_JSON_LOGGING:
            # Structured JSON format
            log_entry = {
                'timestamp': timestamp,
                'level': level,
                'worker_id': self.worker_id,
                'instance_id': self.instance_id,
                'process_id': process_id,
                'thread_id': thread_id,
                'message': message
            }
            if event_id:
                log_entry['event_id'] = event_id
            return json.dumps(log_entry) + '\n'
        else:
            # Human-readable text format
            event_str = f" [EventID: {event_id}]" if event_id else ""
            # Format: [timestamp] [level] [PID:TID] [EventID] message
            return f"[{timestamp}] [{level:8}] [PID:{process_id}|TID:{thread_id}]{event_str} {message}\n"
    
    def log(self, level, message, event_id=None):
        """Log a message at the specified level."""
        formatted = self._format_message(level, message, event_id)
        
        # Write to local file if enabled
        if ENABLE_LOCAL_WORKER_LOGS:
            self._write(formatted)
        
        # Always stream to CloudWatch if handler available
        if self.cloudwatch_handler:
            try:
                # Include event ID in CloudWatch message
                cw_message = f"[Worker-{self.worker_id}]"
                if event_id:
                    cw_message += f" [EventID: {event_id}]"
                cw_message += f" {message}"
                self.cloudwatch_handler.emit(level, cw_message)
            except Exception:
                # Silently fail - don't disrupt worker operation
                pass
    
    def debug(self, message, event_id=None):
        """Log DEBUG level message."""
        self.log('DEBUG', message, event_id)
    
    def info(self, message, event_id=None):
        """Log INFO level message."""
        self.log('INFO', message, event_id)
    
    def warning(self, message, event_id=None):
        """Log WARNING level message."""
        self.log('WARNING', message, event_id)
    
    def error(self, message, event_id=None):
        """Log ERROR level message."""
        self.log('ERROR', message, event_id)
        # Also log to main logger with event ID for correlation
        self.main_logger.error(f"[Worker-{self.worker_id}] [EventID: {event_id}] {message}")
    
    def critical(self, message, event_id=None):
        """Log CRITICAL level message."""
        self.log('CRITICAL', message, event_id)
        # Also log to main logger with event ID for correlation
        self.main_logger.critical(f"[Worker-{self.worker_id}] [EventID: {event_id}] {message}")
    
    def log_api_call(self, endpoint, method, request_data, response_data, latency_ms, status_code, event_id, request_headers=None, response_headers=None, is_validation=False):
        """
        Log full API call with request/response details.
        
        Args:
            endpoint: API endpoint URL
            method: HTTP method
            request_data: Full request payload
            response_data: Full response payload
            latency_ms: Request latency
            status_code: HTTP status code
            event_id: Event ID for correlation
            request_headers: Request headers (optional)
            response_headers: Response headers (optional)
            is_validation: Whether this is a validation call (optional, default False)
        """
        
        # Get timestamp, PID, and TID
        timestamp = datetime.now().isoformat(timespec='milliseconds')
        thread_id = threading.get_ident()
        process_id = os.getpid()
        
        if ENABLE_JSON_LOGGING:
            # Structured JSON format
            log_entry = {
                'timestamp': timestamp,
                'level': 'INFO',
                'log_type': 'api_call',
                'worker_id': self.worker_id,
                'instance_id': self.instance_id,
                'process_id': process_id,
                'thread_id': thread_id,
                'event_id': event_id,
                'api': {
                    'endpoint': endpoint,
                    'method': method,
                    'status_code': status_code,
                    'latency_ms': round(latency_ms, 2),
                    'is_validation': is_validation
                },
                'request': {
                    'headers': dict(request_headers) if request_headers else None,
                    'body': request_data
                },
                'response': {
                    'headers': dict(response_headers) if response_headers else None,
                    'body': response_data
                }
            }
            
            full_message = json.dumps(log_entry, default=str) + '\n'
        else:
            # Human-readable text format
            def format_json(data):
                """Format data as pretty JSON."""
                try:
                    if isinstance(data, (dict, list)):
                        return json.dumps(data, indent=2, default=str)
                    elif isinstance(data, str):
                        try:
                            parsed = json.loads(data)
                            return json.dumps(parsed, indent=2, default=str)
                        except:
                            return data
                    else:
                        return str(data)
                except:
                    return str(data)
            
            # Build message with timestamp, PID, TID in header
            message_parts = [
                f"\n{'='*80}\n",
                f"[{timestamp}] [API CALL] [PID:{process_id}|TID:{thread_id}] [EventID: {event_id}]\n",
                f"{'='*80}\n",
                f"Endpoint: {method} {endpoint}\n",
                f"Status: {status_code}\n",
                f"Latency: {latency_ms:.2f}ms\n"
            ]
            
            if request_headers:
                message_parts.append(f"\nRequest Headers:\n{format_json(dict(request_headers))}\n")
            
            message_parts.append(f"\nRequest Body:\n{format_json(request_data)}\n")
            
            if response_headers:
                message_parts.append(f"\nResponse Headers:\n{format_json(dict(response_headers))}\n")
            
            message_parts.append(f"\nResponse Body:\n{format_json(response_data)}\n")
            message_parts.append(f"{'='*80}\n\n")
            
            full_message = ''.join(message_parts)
        
        # Write to local file if enabled
        if ENABLE_LOCAL_WORKER_LOGS:
            self._write(full_message)
        
        # CRITICAL: Send FULL detailed log to CloudWatch, not just summary
        # This ensures CloudWatch has complete request/response details for debugging
        if self.cloudwatch_handler:
            try:
                # Send the complete API call log with all details
                cw_message = f"[Worker-{self.worker_id}] [EventID: {event_id}]\n{full_message}"
                self.cloudwatch_handler.emit('INFO', cw_message)
            except Exception:
                # Silently fail - don't disrupt worker operation
                pass
        
        # If error, also log summary to main logger with event ID
        # BUT: Don't log 404 "Player Not Found" errors for getPlayerLBStanding in NON-validation scenarios (expected)
        if status_code >= 400:
            # Check if this is a "Player Not Found" error on getPlayerLBStanding endpoint
            is_player_not_found_404 = False
            if status_code == 404 and '/leaderboards/player/standing' in endpoint and not is_validation:
                # Only suppress if NOT a validation call
                # Check response body for specific error pattern
                if isinstance(response_data, dict):
                    standing_response = response_data.get('playerLBStandingResponse', {})
                    error_field = standing_response.get('error', '')
                    message_field = standing_response.get('message', '')
                    if error_field == 'Player Not Found' and 'not found in leaderboard' in message_field:
                        is_player_not_found_404 = True
            
            # Log all errors EXCEPT player-not-found in non-validation scenarios
            if not is_player_not_found_404:
                # Extract error message from response
                error_msg = 'Unknown error'
                if isinstance(response_data, dict):
                    error_msg = response_data.get('message', response_data.get('error', 'Unknown error'))
                else:
                    error_msg = str(response_data)[:200]
                
                # Log ERROR to worker's own CloudWatch log for easy filtering
                if self.cloudwatch_handler:
                    try:
                        if ENABLE_JSON_LOGGING:
                            # Structured JSON error log
                            error_entry = {
                                'timestamp': timestamp,
                                'level': 'ERROR',
                                'log_type': 'api_error',
                                'worker_id': self.worker_id,
                                'instance_id': self.instance_id,
                                'event_id': event_id,
                                'api': {
                                    'endpoint': endpoint,
                                    'method': method,
                                    'status_code': status_code,
                                    'latency_ms': round(latency_ms, 2)
                                },
                                'error': {
                                    'message': error_msg
                                },
                                'cross_reference': {
                                    'info_log_event_id': event_id,
                                    'note': 'Full request/response details in INFO log with same event_id'
                                }
                            }
                            error_summary = json.dumps(error_entry, default=str)
                        else:
                            # Human-readable error summary
                            error_summary = (
                                f"[ERROR] [EventID: {event_id}]\n"
                                f"{method} {endpoint} returned {status_code}\n"
                                f"Error: {error_msg}\n"
                                f"Latency: {latency_ms:.2f}ms\n"
                                f"→ Full request/response details in INFO log with same EventID above"
                            )
                        self.cloudwatch_handler.emit('ERROR', error_summary)
                    except Exception:
                        pass
                
                # Log to main logger with cross-reference to worker log
                self.main_logger.error(
                    f"[Worker-{self.worker_id}] [EventID: {event_id}] "
                    f"API Error: {method} {endpoint} returned {status_code}\n"
                    f"→ Full details in CloudWatch log stream: worker-{self.worker_id}-{self.instance_id if self.instance_id else 'unknown'}\n"
                    f"→ Search filter: {event_id}"
                )


class PlayerWorkerThread(threading.Thread):
    """
    Multi-Player Worker Thread - simulates multiple players concurrently using round-robin execution.
    
    ARCHITECTURE:
    - Each thread manages PLAYERS_PER_THREAD (3) players concurrently
    - Round-robin execution: switches between players based on action timing
    - No sleep calls except minimal 200ms if absolutely necessary
    - Each thread picks ONE gameplay pattern for all its players (consistency)
    - Different threads use different patterns (variety across test)
    
    EXECUTION FLOW:
    - Assign 3 players at thread start (by ID range, no DynamoDB claiming)
    - Each player has independent session state and action schedule
    - Thread continuously finds next player ready for action
    - Executes action for that player
    - Schedules next action time for that player
    - Moves to next ready player (round-robin)
    
    Requirements: 10.19, 10.20, 10.21, 10.22, 35.1-35.10
    Design: Section 4.4, 5.7 (Multi-Player Threading)
    """
    
    def __init__(self, worker_id, test_config_id, config, aws_session, logger, events_logger, shutdown_event, generator_factory, instance_id=None, metrics_collector=None, consistency_validator=None):
        """
        Initialize Multi-Player Worker Thread.
        
        Args:
            worker_id: Unique worker ID
            test_config_id: Test Config ID
            config: Test configuration dictionary
            aws_session: boto3 Session object
            logger: ThreadSafeLogger instance
            events_logger: WorkerLogger instance for centralized events logging
            shutdown_event: threading.Event for shutdown coordination
            generator_factory: DataGeneratorFactory instance
            instance_id: Unique instance identifier for log file naming (optional)
            metrics_collector: MetricsCollector instance (optional, for metrics recording)
            consistency_validator: ConsistencyValidator instance (optional, for data validation)
        """
        super().__init__(name=f"PlayerWorker-{worker_id}", daemon=False)
        
        self.worker_id = worker_id
        self.test_config_id = test_config_id
        self.config = config
        self.aws_session = aws_session
        self.logger = logger
        self.events_logger = events_logger  # Centralized events logger for ALL workers
        self.shutdown_event = shutdown_event
        self.generator_factory = generator_factory
        self.metrics_collector = metrics_collector  # For recording API metrics
        self.consistency_validator = consistency_validator  # For data consistency validation
        
        # ============================================================================
        # MULTI-PLAYER STATE MANAGEMENT
        # ============================================================================
        # Each thread manages PLAYERS_PER_THREAD players concurrently
        self.players = []  # List of player contexts (max PLAYERS_PER_THREAD)
        self.session_count = 0
        
        # Thread-level gameplay pattern (shared by all players in this thread)
        # This is selected once at thread start for consistency
        self.thread_gameplay_pattern = None  # Will be set in run()
        
        # ============================================================================
        # WORKER LOGGING: ALL workers get their own log file
        # ============================================================================
        log_dir = logger.get_log_dir()
        worker_log_dir = log_dir / "workers"
        worker_log_dir.mkdir(exist_ok=True)
        
        # Create CloudWatch handler for this worker
        worker_cloudwatch_handler = None
        try:
            log_stream_name = f"worker-{worker_id}-{instance_id}" if instance_id else f"worker-{worker_id}"
            worker_cloudwatch_handler = CloudWatchLogHandler(
                log_group_name=CLOUDWATCH_LOG_GROUP_PREFIX,
                log_stream_name=log_stream_name,
                region=config.get('region', DEFAULT_AWS_REGION),
                aws_session=aws_session,
                logger=logger
            )
        except Exception as e:
            logger.warning(f"Failed to initialize CloudWatch handler for worker {worker_id}: {e}")
        
        # Include instance_id in log file name if provided
        if instance_id:
            worker_log_file = worker_log_dir / f"worker-{worker_id}-{instance_id}.log"
        else:
            worker_log_file = worker_log_dir / f"worker-{worker_id}.log"
        self.worker_logger = WorkerLogger(worker_log_file, worker_id, logger, cloudwatch_handler=worker_cloudwatch_handler, instance_id=instance_id)
        self.worker_logger.info(f"Multi-Player Worker {worker_id} initialized (manages {PLAYERS_PER_THREAD} players)")
        
        # ============================================================================
        # PLAYER PROGRESSION MANAGER
        # ============================================================================
        progression_rate = self.config.get('progression_rate', 'normal')
        region = self.config.get('region', DEFAULT_AWS_REGION)
        profile = self.config.get('aws_profile')
        
        self.progression_manager = PlayerProgressionManager(
            test_config_id=test_config_id,
            region=region,
            profile=profile,
            aws_session=self.aws_session,
            shutdown_event=self.shutdown_event,
            progression_rate=progression_rate
        )
        
        # ============================================================================
        # HTTP SESSION WITH CONNECTION POOLING
        # ============================================================================
        self.http_session = requests.Session()
        
        adapter = HTTPAdapter(
            pool_connections=10,
            pool_maxsize=20,
            max_retries=Retry(total=0, backoff_factor=0)
        )
        
        self.http_session.mount('http://', adapter)
        self.http_session.mount('https://', adapter)
        
        self.logger.debug(f"Multi-Player Worker Thread {worker_id} initialized with HTTP connection pooling")
        
        # Cache DynamoDB resource to prevent file descriptor leaks
        self._dynamodb = None
    
    @property
    def dynamodb(self):
        """Cached DynamoDB resource to prevent file descriptor leaks."""
        if self._dynamodb is None:
            self._dynamodb = self.aws_session.resource('dynamodb')
        return self._dynamodb
    
    def get_active_player_count(self):
        """
        Get the number of active players currently managed by this worker.
        
        Returns:
            int: Number of players in self.players list
        """
        return len(self.players)
    
    def run(self):
        """
        Multi-Player Round-Robin Execution Loop.
        
        ARCHITECTURE:
        - Manages PLAYERS_PER_THREAD (3) players at thread start
        - Each player has independent session state and action schedule
        - Round-robin execution: finds next player ready for action
        - NO sleep calls except minimal 200ms if absolutely necessary
        - Thread picks ONE gameplay pattern for all players (consistency)
        
        EXECUTION FLOW:
        1. Assign 3 players (randomly selected from 100K pool)
        2. Select thread-level gameplay pattern (shared by all players)
        3. Initialize each player's session state
        4. Main loop:
           - Find player with earliest next_action_time
           - If action time has arrived, execute action for that player
           - Schedule next action for that player
           - Continue to next ready player
        5. On shutdown: release all players
        
        Requirements: 10.19, 10.20, 10.21, 10.22, 35.1-35.10
        Task: 35.1 - Multi-Player Round-Robin Execution
        """
        self.logger.info(f"Multi-Player Worker Thread {self.worker_id} starting...")
        self.logger.info(f"  Will manage {PLAYERS_PER_THREAD} players concurrently")
        
        if self.worker_logger:
            self.worker_logger.info(f"Multi-Player Worker thread starting - manages {PLAYERS_PER_THREAD} players")
        
        try:
            # ============================================================================
            # CONFIGURATION VALIDATION
            # ============================================================================
            api_base_url = self.config.get('api_base_url')
            api_key = self.config.get('api_key')
            game_id = self.config.get('game_id')
            
            if not api_base_url or not api_key or not game_id:
                self.logger.error(
                    f"Multi-Player Worker {self.worker_id}: Missing required API configuration"
                )
                return
            
            # Load player pool configuration
            player_pool_config = self.config.get('player_pool', {})
            pool_size = int(player_pool_config.get('poolSize', 100000))  # Use poolSize, not total_players
            id_prefix = player_pool_config.get('idPrefix', 'player')
            
            # ============================================================================
            # SELECT THREAD-LEVEL GAMEPLAY PATTERN
            # ============================================================================
            # Each thread picks ONE pattern for all its players (consistency)
            # Different threads will pick different patterns (variety)
            behavior_profiles = ['casual', 'competitive', 'hardcore']
            behavior_weights = [0.5, 0.3, 0.2]  # 50% casual, 30% competitive, 20% hardcore
            self.thread_gameplay_pattern = random.choices(behavior_profiles, weights=behavior_weights)[0]
            
            self.logger.info(
                f"Multi-Player Worker {self.worker_id}: Selected gameplay pattern '{self.thread_gameplay_pattern}' "
                f"for all {PLAYERS_PER_THREAD} players"
            )
            
            # ============================================================================
            # ASSIGN PLAYERS_PER_THREAD PLAYERS
            # ============================================================================
            # Each worker gets a unique set of player IDs randomly selected from the pool
            # This ensures good distribution across the 100K player pool
            # No DynamoDB claiming needed - just assign player IDs
            self.logger.info(f"Multi-Player Worker {self.worker_id}: Assigning {PLAYERS_PER_THREAD} players from pool of {pool_size:,}...")
            
            # Use worker_id as seed offset to ensure different workers get different players
            # but same worker gets same players on restart (deterministic)
            random.seed(self.worker_id * 1000 + int(time.time() / 3600))  # Changes hourly
            
            # Generate unique random player IDs for this worker
            assigned_player_nums = random.sample(range(1, pool_size + 1), PLAYERS_PER_THREAD)
            
            for i, player_num in enumerate(assigned_player_nums):
                # Use consistent format: player_NNNNNN (6 digits, underscore)
                player_id = f"{id_prefix}_{player_num:06d}"
                
                player_context = {
                    'player_id': player_id,
                    'next_action_time': time.time(),  # Ready immediately
                    'session_start_time': time.time(),
                    'session_end_time': None,  # Will be set when session starts
                    'session_active': False,
                    'actions_completed': 0,
                    'api_calls': 0,
                    'api_errors': 0,
                    'gameplay_simulator': None,  # Will be initialized when session starts
                    'progression': None,  # Will be loaded when session starts
                    'game_mode': None,
                    'leaderboard': None,
                    'last_score': None
                }
                self.players.append(player_context)
                
                self.logger.debug(
                    f"Multi-Player Worker {self.worker_id}: Assigned player {player_id} "
                    f"({i+1}/{PLAYERS_PER_THREAD})"
                )
            
            self.logger.info(
                f"Multi-Player Worker {self.worker_id}: Successfully assigned {len(self.players)} players. "
                f"Starting round-robin execution..."
            )
            
            # ============================================================================
            # MAIN ROUND-ROBIN EXECUTION LOOP
            # ============================================================================
            loop_iterations = 0
            total_actions_executed = 0
            
            while not self.shutdown_event.is_set() and len(self.players) > 0:
                loop_iterations += 1
                current_time = time.time()
                
                # Find player with earliest next_action_time that's ready
                ready_player = None
                earliest_time = float('inf')
                
                for player in self.players:
                    if player['next_action_time'] <= current_time:
                        # Player is ready for action NOW
                        ready_player = player
                        break
                    elif player['next_action_time'] < earliest_time:
                        # Track earliest future action
                        earliest_time = player['next_action_time']
                
                if ready_player:
                    # Execute action for this player
                    try:
                        action_executed = self._execute_player_action(
                            ready_player,
                            api_base_url,
                            api_key,
                            game_id
                        )
                        
                        if action_executed:
                            total_actions_executed += 1
                            ready_player['actions_completed'] += 1
                        
                        # Check if player's session has ended
                        if ready_player['session_end_time'] and current_time >= ready_player['session_end_time']:
                            # Session complete - release player and remove from list
                            self.logger.debug(
                                f"Multi-Player Worker {self.worker_id}: Player {ready_player['player_id']} "
                                f"session complete ({ready_player['actions_completed']} actions)"
                            )
                            self._release_player_session(ready_player['player_id'])
                            self.players.remove(ready_player)
                            self.session_count += 1
                            
                            # Try to claim a new player to replace this one
                            new_player_id = self._claim_player_session(pool_size, max_retries=1)
                            if new_player_id:
                                new_player_context = {
                                    'player_id': new_player_id,
                                    'next_action_time': time.time(),
                                    'session_start_time': time.time(),
                                    'session_end_time': None,
                                    'session_active': False,
                                    'actions_completed': 0,
                                    'api_calls': 0,
                                    'api_errors': 0,
                                    'gameplay_simulator': None,
                                    'progression': None,
                                    'game_mode': None,
                                    'leaderboard': None,
                                    'last_score': None
                                }
                                self.players.append(new_player_context)
                                self.logger.debug(
                                    f"Multi-Player Worker {self.worker_id}: Claimed replacement player {new_player_id}"
                                )
                    
                    except Exception as action_error:
                        self.logger.error(
                            f"Multi-Player Worker {self.worker_id}: Error executing action for player "
                            f"{ready_player['player_id']}: {action_error}"
                        )
                        ready_player['api_errors'] += 1
                        # Schedule next action anyway to keep player active
                        ready_player['next_action_time'] = current_time + random.uniform(1.0, 3.0)
                
                else:
                    # No player ready right now
                    # Sleep briefly to avoid overwhelming CPU and backend
                    # Use minimal sleep based on when next player will be ready
                    if earliest_time < float('inf'):
                        sleep_duration = min(0.2, max(0.05, earliest_time - current_time))
                        time.sleep(sleep_duration)
                    else:
                        # No players have scheduled actions (shouldn't happen)
                        time.sleep(0.1)
                
                # Periodic status logging (every 1000 iterations)
                if loop_iterations % 1000 == 0:
                    active_players = len(self.players)
                    total_api_calls = sum(p['api_calls'] for p in self.players)
                    total_errors = sum(p['api_errors'] for p in self.players)
                    
                    self.logger.debug(
                        f"Multi-Player Worker {self.worker_id}: Status - "
                        f"Active players: {active_players}, "
                        f"Actions: {total_actions_executed}, "
                        f"API calls: {total_api_calls}, "
                        f"Errors: {total_errors}"
                    )
            
            # ============================================================================
            # GRACEFUL SHUTDOWN
            # ============================================================================
            self.logger.info(
                f"Multi-Player Worker {self.worker_id}: Shutdown requested. "
                f"Releasing {len(self.players)} active players..."
            )
            
            # Release all remaining players
            for player in self.players:
                try:
                    self._release_player_session(player['player_id'])
                    self.logger.debug(
                        f"Multi-Player Worker {self.worker_id}: Released player {player['player_id']}"
                    )
                except Exception as release_error:
                    self.logger.warning(
                        f"Multi-Player Worker {self.worker_id}: Error releasing player "
                        f"{player['player_id']}: {release_error}"
                    )
            
            # Calculate final statistics
            total_api_calls = sum(p['api_calls'] for p in self.players)
            total_errors = sum(p['api_errors'] for p in self.players)
            error_rate = (total_errors / total_api_calls * 100) if total_api_calls > 0 else 0.0
            
            self.logger.info(
                f"Multi-Player Worker {self.worker_id}: Final Statistics:\n"
                f"  Sessions Completed: {self.session_count}\n"
                f"  Total Actions: {total_actions_executed}\n"
                f"  Total API Calls: {total_api_calls}\n"
                f"  API Errors: {total_errors}\n"
                f"  Error Rate: {error_rate:.2f}%\n"
                f"  Gameplay Pattern: {self.thread_gameplay_pattern}"
            )
            
        except Exception as e:
            self.logger.error(
                f"Multi-Player Worker {self.worker_id}: Fatal error: {e}"
            )
            self.logger.error(traceback.format_exc())
        
        finally:
            # Close HTTP session
            if hasattr(self, 'http_session') and self.http_session:
                try:
                    self.http_session.close()
                except Exception:
                    pass
            
            self.logger.info(f"Multi-Player Worker {self.worker_id}: Thread terminated.")
    
    def _execute_player_action(self, player, api_base_url, api_key, game_id):
        """
        Execute a single action for a player in the round-robin system.
        
        This method handles:
        - Session initialization (first action)
        - Action selection based on gameplay pattern
        - API call execution
        - Next action scheduling
        
        Args:
            player: Player context dictionary
            api_base_url: API Gateway base URL
            api_key: API key for authentication
            game_id: Game ID
        
        Returns:
            bool: True if action executed successfully, False otherwise
        
        Requirements: 35.2, 35.3, 35.4
        Task: 35.2 - Player Action Execution
        """
        player_id = player['player_id']
        current_time = time.time()
        
        try:
            # ============================================================================
            # SESSION INITIALIZATION (First Action)
            # ============================================================================
            if not player['session_active']:
                # Initialize session for this player
                self.logger.debug(
                    f"Multi-Player Worker {self.worker_id}: Initializing session for player {player_id}"
                )
                
                # Load player progression
                player['progression'] = self.progression_manager.load_player_progression(player_id)
                if not player['progression']:
                    player['progression'] = self.progression_manager.initialize_new_player(player_id)
                
                # Get progression modifiers
                progression_modifiers = self.progression_manager.get_progression_modifiers(player['progression'])
                
                # Generate session duration (60-3600s base, modified by progression)
                base_duration = random.randint(60, 3600)
                session_duration = int(base_duration * progression_modifiers['session_duration_multiplier'])
                player['session_end_time'] = current_time + session_duration
                
                # Select game mode
                game_modes = self.config.get('game_modes', [])
                player['game_mode'] = select_game_mode_by_popularity(game_modes)
                
                # Validate game mode selection
                if not player['game_mode']:
                    self.logger.error(
                        f"Multi-Player Worker {self.worker_id}: Player {player_id} failed to select game mode. "
                        f"Available game modes: {len(game_modes)}"
                    )
                    # Clear player state and schedule retry after 10 seconds
                    player['game_mode'] = None
                    player['leaderboard'] = None
                    player['session_end_time'] = current_time
                    player['next_action_time'] = current_time + 10.0
                    return False
                
                # Select leaderboard
                event_schedule = self.config.get('event_schedule', [])
                leaderboard_configs = self.config.get('leaderboard_configs', [])
                active_leaderboards = select_active_leaderboards(event_schedule, leaderboard_configs, int(current_time))
                matching_leaderboards = get_leaderboards_for_game_mode(active_leaderboards, player['game_mode'])
                
                if matching_leaderboards:
                    player['leaderboard'] = random.choice(matching_leaderboards)
                else:
                    # No matching leaderboards - end session
                    self.logger.warning(
                        f"Multi-Player Worker {self.worker_id}: Player {player_id} found no matching leaderboards. "
                        f"Game mode: {player['game_mode'].get('modeName') if isinstance(player['game_mode'], dict) else player['game_mode']}, "
                        f"Active leaderboards: {len(active_leaderboards)}"
                    )
                    player['leaderboard'] = None
                    player['session_end_time'] = current_time
                    player['next_action_time'] = current_time + 10.0
                    return False
                
                # Initialize gameplay simulator with thread's pattern
                player['gameplay_simulator'] = RealisticGameplaySimulator(
                    player_id=player_id,
                    behavior_profile=self.thread_gameplay_pattern
                )
                player['gameplay_simulator'].start_session(session_duration)
                
                player['session_active'] = True
                
                self.logger.debug(
                    f"Multi-Player Worker {self.worker_id}: Player {player_id} session initialized - "
                    f"Duration: {session_duration}s, Pattern: {self.thread_gameplay_pattern}"
                )
            
            # ============================================================================
            # ACTION SELECTION AND EXECUTION
            # ============================================================================
            # Use gameplay simulator to determine next action
            action_type = player['gameplay_simulator'].get_next_action()
            
            # Extract game mode and leaderboard name safely
            game_mode_str = player['game_mode'].get('modeName') if isinstance(player['game_mode'], dict) else player['game_mode']
            leaderboard_name = player['leaderboard'].get('leaderboardName') if isinstance(player['leaderboard'], dict) else player['leaderboard']
            
            # Validate required fields
            if not game_mode_str or not leaderboard_name:
                self.logger.error(
                    f"Multi-Player Worker {self.worker_id}: Player {player_id} missing game_mode or leaderboard. "
                    f"game_mode={game_mode_str}, leaderboard={leaderboard_name}"
                )
                # Schedule retry after 5 seconds
                player['next_action_time'] = current_time + 5.0
                return False
            
            success = False
            latency_ms = 0
            
            if action_type == 'submit_score':
                # Submit player stats and scores
                success, latency_ms = self._make_api_call(
                    'storePlayerStatsAndScores',
                    player_id,
                    game_id,
                    game_mode_str,
                    leaderboard_name,
                    api_base_url,
                    api_key
                )
                player['api_calls'] += 1
                if not success:
                    player['api_errors'] += 1
                # Rate limiting: minimum interval between requests
                time.sleep(WORKER_MIN_REQUEST_INTERVAL)
            
            elif action_type == 'check_leaderboard':
                # Query leaderboard
                # Randomly choose between 'top' or 'aroundPlayer'
                query_type = random.choice(['top', 'aroundPlayer'])
                
                if query_type == 'aroundPlayer':
                    # Fetch current leaderboard to get a random player
                    success_fetch, latency_fetch, leaderboard_players = self._fetch_leaderboard_players(
                        game_id,
                        game_mode_str,
                        leaderboard_name,
                        api_base_url,
                        api_key,
                        limit=100  # Fetch up to 100 players, pick one randomly
                    )
                    
                    if success_fetch and leaderboard_players:
                        # Pick a random player from the leaderboard
                        target_player_id = random.choice(leaderboard_players)
                    else:
                        # No players in leaderboard yet, fall back to 'top' query
                        query_type = 'top'
                        target_player_id = None
                else:
                    target_player_id = None
                
                query_limit = random.choice([10, 25, 50, 100])
                
                success, latency_ms = self._make_api_call(
                    'getLeaderboardScores',
                    target_player_id if target_player_id else player_id,
                    game_id,
                    game_mode_str,
                    leaderboard_name,
                    api_base_url,
                    api_key,
                    query_type=query_type,
                    query_limit=query_limit
                )
                player['api_calls'] += 1
                if not success:
                    player['api_errors'] += 1
                # Rate limiting: minimum interval between requests
                time.sleep(WORKER_MIN_REQUEST_INTERVAL)
            
            elif action_type == 'check_stats':
                # Query player stats
                success, latency_ms = self._make_api_call(
                    'getPlayerStatsAndScores',
                    player_id,
                    game_id,
                    game_mode_str,
                    leaderboard_name,
                    api_base_url,
                    api_key
                )
                player['api_calls'] += 1
                if not success:
                    player['api_errors'] += 1
                # Rate limiting: minimum interval between requests
                time.sleep(WORKER_MIN_REQUEST_INTERVAL)
            
            elif action_type == 'check_standing':
                # Query player standing
                success, latency_ms = self._make_api_call(
                    'getPlayerLBStanding',
                    player_id,
                    game_id,
                    game_mode_str,
                    leaderboard_name,
                    api_base_url,
                    api_key
                )
                player['api_calls'] += 1
                if not success:
                    player['api_errors'] += 1
                # Rate limiting: minimum interval between requests
                time.sleep(WORKER_MIN_REQUEST_INTERVAL)
            
            else:
                # Pause action - no API call
                success = True
            
            # Schedule next action based on gameplay pattern
            action_interval_ms = player['gameplay_simulator'].get_action_interval()
            # Clamp interval to safety bounds
            action_interval_ms = max(MIN_ACTION_INTERVAL_MS, min(action_interval_ms, MAX_ACTION_INTERVAL_MS))
            player['next_action_time'] = current_time + (action_interval_ms / 1000.0)
            
            return True
        
        except Exception as e:
            self.logger.error(
                f"Multi-Player Worker {self.worker_id}: Error executing action for player {player_id}: {e}"
            )
            self.logger.error(traceback.format_exc())
            # Schedule retry after 10 seconds
            player['next_action_time'] = time.time() + 10.0
            return False
    
    def _fetch_leaderboard_players(self, game_id, game_mode, leaderboard_name, api_base_url, api_key, limit=100):
        """
        Fetch players from a leaderboard for aroundPlayer queries.
        
        Makes a single call to get current leaderboard state.
        
        Args:
            game_id: Game ID
            game_mode: Game mode
            leaderboard_name: Leaderboard name
            api_base_url: API Gateway base URL
            api_key: API key for authentication
            limit: Number of players to fetch (default: 100, capped to prevent memory issues)
        
        Returns:
            tuple: (success: bool, latency_ms: float, player_ids: list)
        """
        try:
            endpoint = f"{api_base_url}/leaderboards/scores"
            
            request_body = {
                "leaderboardScoresRequest": {
                    "gameID": game_id,
                    "gameMode": game_mode,
                    "leaderboardName": leaderboard_name,
                    "queryType": "top",
                    "limit": min(limit, 100)  # Cap at 100 to prevent memory issues
                }
            }
            
            headers = {
                'Authorization': f'Bearer {api_key}',
                'Content-Type': 'application/json'
            }
            
            start_time = time.time()
            response = self.http_session.post(
                endpoint,
                json=request_body,
                headers=headers,
                timeout=API_TIMEOUT_READ
            )
            latency_ms = (time.time() - start_time) * 1000
            
            if response.status_code == 200:
                response_data = response.json()
                
                # Extract player IDs from response
                player_ids = []
                if 'leaderboardScores' in response_data:
                    scores = response_data['leaderboardScores']
                    if isinstance(scores, list):
                        player_ids = [score.get('playerID') for score in scores if score.get('playerID')]
                
                return True, latency_ms, player_ids
            else:
                # API error - return empty list
                return False, latency_ms, []
                    
        except Exception as e:
            self.logger.debug(
                f"Multi-Player Worker {self.worker_id}: Exception fetching players from {leaderboard_name}: {e}"
            )
            return False, 0, []
    
    def _claim_player_session(self, total_players, max_retries=10):
        """
        Attempt to claim a player session from the player pool.
        
        Randomly selects players and attempts to claim them using DynamoDB
        conditional writes. Retries with different players if claim fails.
        
        Args:
            total_players: Total number of players in the pool
            max_retries: Maximum number of claim attempts (default: 10)
        
        Returns:
            str: Player ID if claimed successfully, None if all attempts failed
        
        Requirements: 14.1, 14.2, 14.3
        Task: 13.2 - Player session claiming
        """
        
        # Ensure total_players is an integer (may be Decimal from DynamoDB)
        total_players = int(total_players)
        
        table = self.dynamodb.Table(PLAYER_STATE_TABLE_NAME)
        
        attempted_players = set()
        
        for attempt in range(max_retries):
            if self.shutdown_event.is_set():
                self.logger.debug(
                    f"Player Worker {self.worker_id}: Shutdown requested during claim attempt"
                )
                return None
            
            # Select random player (avoid already attempted players)
            available_players = set(range(1, total_players + 1)) - attempted_players
            
            if not available_players:
                self.logger.warning(
                    f"Player Worker {self.worker_id}: Exhausted all {total_players} players "
                    f"without successful claim"
                )
                return None
            
            # Use consistent format: player_NNNNNN (6 digits, underscore)
            player_num = random.choice(list(available_players))
            player_id = f"player_{player_num:06d}"
            attempted_players.add(player_num)
            
            # Attempt to claim this player
            try:
                current_time = int(time.time())
                ttl_time = current_time + (90 * 60)  # 90 minutes (Requirement 14.5)
                composite_key = f"{self.test_config_id}_{player_id}"
                
                # Conditional write - only succeeds if player not already claimed
                table.put_item(
                    Item={
                        'TestConfigID_PlayerID': composite_key,
                        'SessionStatus': 'ACTIVE',
                        'TestConfigID': self.test_config_id,
                        'PlayerID': player_id,
                        'InstanceID': self.worker_id,
                        'StartTime': current_time,
                        'Level': 1,
                        'Statistics': {},
                        'TTL': ttl_time,
                        'Version': 1
                    },
                    ConditionExpression='attribute_not_exists(TestConfigID_PlayerID) AND attribute_not_exists(SessionStatus)'
                )
                
                # Success!
                self.logger.debug(
                    f"Player Worker {self.worker_id}: Claimed player {player_id} "
                    f"(attempt {attempt + 1}/{max_retries})"
                )
                return player_id
                
            except ClientError as e:
                error_code = e.response.get('Error', {}).get('Code', 'Unknown')
                
                if error_code == 'ConditionalCheckFailedException':
                    # Player already claimed - try another player
                    self.logger.debug(
                        f"Player Worker {self.worker_id}: Player {player_id} already claimed, "
                        f"trying another (attempt {attempt + 1}/{max_retries})"
                    )
                    continue
                else:
                    # Unexpected error
                    self.logger.error(
                        f"Player Worker {self.worker_id}: Unexpected error claiming player "
                        f"{player_id}: {error_code} - {e}"
                    )
                    continue
            
            except Exception as e:
                self.logger.error(
                    f"Player Worker {self.worker_id}: Exception claiming player {player_id}: {e}"
                )
                self.logger.error(traceback.format_exc())
                continue
        
        # Failed all attempts
        self.logger.warning(
            f"Player Worker {self.worker_id}: Failed to claim player after {max_retries} attempts"
        )
        return None
    
    def _release_player_session(self, player_id):
        """
        Release a player session by deleting the active session record.
        
        Args:
            player_id: Player ID to release
        
        Requirements: 14.4, 14.11
        Task: 13.2 - Player session release (partial implementation)
        """
        try:
            table = self.dynamodb.Table(PLAYER_STATE_TABLE_NAME)
            
            composite_key = f"{self.test_config_id}_{player_id}"
            
            # Delete the active session record
            table.delete_item(
                Key={
                    'TestConfigID_PlayerID': composite_key,
                    'SessionStatus': 'ACTIVE'
                }
            )
            
            self.logger.debug(
                f"Player Worker {self.worker_id}: Released player {player_id}"
            )
            
        except Exception as e:
            self.logger.error(
                f"Player Worker {self.worker_id}: Failed to release player {player_id}: {e}"
            )
            self.logger.error(traceback.format_exc())
            # Don't raise - best effort release
    
    def _execute_gameplay_session(self, player_id, api_base_url, api_key, game_id, api_distribution):
        """
        Execute a complete gameplay session for a player.
        
        Simulates realistic gameplay by:
        - Generating random session duration (1-60 minutes)
        - Selecting game mode and leaderboards
        - Using RealisticGameplaySimulator for action selection and pauses
        - Tracking latency and errors
        
        Args:
            player_id: Player ID for this session
            api_base_url: API Gateway base URL
            api_key: API key for authentication
            game_id: Game ID
            api_distribution: API call distribution percentages
        
        Returns:
            bool: True if session completed successfully, False otherwise
        
        Requirements: 10.21, 13.1-13.17, 14.9, 30.1, 30.2, 30.6, 30.8, 30.10
        Task: 13.3 - Gameplay session execution
        Task: 27.3 - Realistic API call sequencing
        """
        
        # Mark as in session for metrics tracking
        self.in_session = True
        
        try:
            # ============================================================================
            # TASK 31.11: Load player progression at session start
            # ============================================================================
            # Load persistent progression for this player (Requirement 34.6, 34.16)
            player_progression = self.progression_manager.load_player_progression(player_id)
            
            if not player_progression:
                # New player - initialize progression
                self.logger.info(
                    f"Player Worker {self.worker_id}: New player {player_id}, initializing progression"
                )
                player_progression = self.progression_manager.initialize_new_player(player_id)
                
                # Record new player event in metrics (Task 31.12)
                if self.metrics_collector:
                    self.metrics_collector.record_progression_event(
                        event_type='new_player',
                        player_level=1
                    )
            else:
                # Returning player
                self.logger.info(
                    f"Player Worker {self.worker_id}: Returning player {player_id}, "
                    f"Level {player_progression.get('level', 1)}, "
                    f"XP {player_progression.get('total_xp', 0)}, "
                    f"Games played: {player_progression.get('cumulative_statistics', {}).get('games_played', 0)}"
                )
                
                # Record returning player event in metrics (Task 31.12)
                if self.metrics_collector:
                    self.metrics_collector.record_progression_event(
                        event_type='returning_player',
                        player_level=player_progression.get('level', 1)
                    )
            
            # Get progression-based behavior modifiers (Requirement 34.10, 34.17)
            progression_modifiers = self.progression_manager.get_progression_modifiers(player_progression)
            
            self.logger.debug(
                f"Player Worker {self.worker_id}: Progression modifiers for {player_id}: "
                f"Leaderboard check probability: {progression_modifiers['leaderboard_check_probability']:.2f}, "
                f"Score multiplier: {progression_modifiers['score_multiplier']:.2f}, "
                f"Session duration multiplier: {progression_modifiers['session_duration_multiplier']:.2f}, "
                f"Behavior profile: {progression_modifiers['behavior_profile']}"
            )
            
            # Apply initial pause for returning players (shorter for higher levels, Requirement 34.16)
            initial_pause = progression_modifiers['initial_pause_seconds']
            self.logger.debug(
                f"Player Worker {self.worker_id}: Applying initial pause of {initial_pause:.1f}s "
                f"for {'new' if not player_progression.get('cumulative_statistics', {}).get('sessions_completed', 0) else 'returning'} player"
            )
            if not interruptible_sleep(initial_pause, self.shutdown_event):
                return False  # Shutdown requested during initial pause
            
            # Generate session duration with progression modifier (1-60 minutes base, per Requirement 9.4)
            base_duration_seconds = random.randint(60, 3600)
            session_duration_seconds = int(base_duration_seconds * progression_modifiers['session_duration_multiplier'])
            session_start_time = time.time()
            session_end_time = session_start_time + session_duration_seconds
            
            # ============================================================================
            # TASK 27.3: Initialize RealisticGameplaySimulator for this session
            # ============================================================================
            
            # Use progression-based behavior profile (Task 31.10, Requirement 34.17)
            behavior_profile = progression_modifiers['behavior_profile']
            
            # Initialize gameplay simulator for this session
            self.gameplay_simulator = RealisticGameplaySimulator(
                player_id=player_id,
                behavior_profile=behavior_profile
            )
            
            # Start the gameplay session in the simulator
            self.gameplay_simulator.start_session(session_duration_seconds)
            
            self.logger.info(
                f"Player Worker {self.worker_id}: Starting gameplay session for {player_id}. "
                f"Duration: {session_duration_seconds}s ({session_duration_seconds/60:.1f} minutes), "
                f"Behavior: {behavior_profile} (Level {player_progression.get('level', 1)})"
            )
            
            # Select game mode using popularity weights
            game_modes = self.config.get('game_modes', [])
            game_mode = select_game_mode_by_popularity(game_modes)
            if not game_mode:
                self.logger.error(
                    f"Player Worker {self.worker_id}: Failed to select game mode"
                )
                return False
            
            self.logger.debug(
                f"Player Worker {self.worker_id}: Selected game mode: {game_mode}"
            )
            
            # Select active leaderboards for this game mode
            event_schedule = self.config.get('event_schedule', [])
            leaderboard_configs = self.config.get('leaderboard_configs', [])
            current_time = int(time.time())
            active_leaderboards = select_active_leaderboards(event_schedule, leaderboard_configs, current_time)
            
            # Filter leaderboards to only those matching the selected game mode
            # This enforces the relationship between game modes and leaderboards
            matching_leaderboards = get_leaderboards_for_game_mode(active_leaderboards, game_mode)
            
            if not matching_leaderboards:
                game_mode_str = game_mode.get('modeName') if isinstance(game_mode, dict) else game_mode
                self.logger.warning(
                    f"Player Worker {self.worker_id}: No active leaderboards for game mode {game_mode_str}"
                )
                return False
            
            # Select primary leaderboard for this session from matching leaderboards
            primary_leaderboard = random.choice(matching_leaderboards)
            
            game_mode_str = game_mode.get('modeName') if isinstance(game_mode, dict) else game_mode
            self.logger.debug(
                f"Player Worker {self.worker_id}: Primary leaderboard: {primary_leaderboard.get('leaderboardName')}, "
                f"Game mode: {game_mode_str}, "
                f"Total matching: {len(matching_leaderboards)}/{len(active_leaderboards)}"
            )
            
            # Session statistics
            session_api_calls = 0
            session_api_errors = 0
            session_total_latency = 0
            
            # API call counters for distribution tracking
            stats_submissions = 0
            leaderboard_queries = 0
            player_stats_queries = 0
            player_standing_queries = 0
            
            # Track last submitted score for personal best detection
            last_submitted_score = None
            
            # Extract string values for API calls
            game_mode_str = game_mode.get('modeName') if isinstance(game_mode, dict) else game_mode
            leaderboard_name_str = primary_leaderboard.get('leaderboardName') if isinstance(primary_leaderboard, dict) else primary_leaderboard
            
            # ============================================================================
            # REALISTIC PLAYER BEHAVIOR FLOW WITH INTELLIGENT RANDOMIZATION
            # ============================================================================
            # Flow varies based on player behavior patterns:
            # - Casual players: Shorter gameplay, fewer checks, simpler queries
            # - Competitive players: Longer gameplay, frequent checks, detailed queries
            # - Mix of query types: top10/25/50/100, aroundPlayer with neighbors
            # - Stats checks: Before game (preparation) and after game (review)
            # ============================================================================
            
            self.logger.debug(
                f"Player Worker {self.worker_id}: Starting realistic gameplay flow for {player_id}"
            )
            
            # Determine player behavior style for this session
            behavior_styles = ['casual', 'competitive', 'explorer']
            behavior_weights = [0.5, 0.3, 0.2]  # 50% casual, 30% competitive, 20% explorer
            session_behavior = random.choices(behavior_styles, weights=behavior_weights)[0]
            
            self.logger.debug(f"Player Worker {self.worker_id}: Session behavior style: {session_behavior}")
            
            # Initial leaderboard check - see who's leading before playing
            # Vary the query based on behavior
            if session_behavior == 'competitive':
                # Competitive players want detailed view
                initial_limit = random.choice([50, 100])
            elif session_behavior == 'explorer':
                # Explorers check everything
                initial_limit = random.choice([25, 50, 100])
            else:
                # Casual players just want top players
                initial_limit = random.choice([10, 25])
            
            self.logger.debug(
                f"Player Worker {self.worker_id}: Checking top {initial_limit} leaderboard before first game"
            )
            success, latency_ms = self._make_api_call(
                'getLeaderboardScores',
                player_id,
                game_id,
                game_mode_str,
                leaderboard_name_str,
                api_base_url,
                api_key,
                query_type='top',
                query_limit=initial_limit
            )
            session_api_calls += 1
            leaderboard_queries += 1
            if not success:
                session_api_errors += 1
            if latency_ms:
                session_total_latency += latency_ms
            
            # Competitive/Explorer players might check their stats before playing
            if session_behavior in ['competitive', 'explorer'] and random.random() < 0.7:
                if not interruptible_sleep(random.uniform(0.5, 1.0), self.shutdown_event):
                    return False
                
                self.logger.debug(f"Player Worker {self.worker_id}: Checking own stats before playing")
                success, latency_ms = self._make_api_call(
                    'getPlayerStatsAndScores',
                    player_id,
                    game_id,
                    game_mode_str,
                    leaderboard_name_str,
                    api_base_url,
                    api_key
                )
                session_api_calls += 1
                player_stats_queries += 1
                if not success:
                    session_api_errors += 1
                if latency_ms:
                    session_total_latency += latency_ms
            
            # ============================================================================
            # DYNAMIC SLEEP CONFIGURATION BASED ON WORKER COUNT
            # ============================================================================
            # Get worker count from config to adjust sleep times
            num_workers = self.config.get('num_player_workers', 9)
            
            # Calculate sleep multiplier based on worker count
            # Few workers (1-10): Minimal sleep for higher RPS per worker
            # Medium workers (11-50): Moderate sleep for realistic behavior
            # Many workers (51+): Full sleep for realistic behavior
            if num_workers <= 10:
                sleep_multiplier = 0.1  # 10% of normal sleep (aggressive)
            elif num_workers <= 50:
                sleep_multiplier = 0.5  # 50% of normal sleep (moderate)
            else:
                sleep_multiplier = 1.0  # 100% of normal sleep (realistic)
            
            self.logger.debug(
                f"Player Worker {self.worker_id}: Sleep multiplier: {sleep_multiplier:.1f}x "
                f"(based on {num_workers} workers)"
            )
            
            # Main gameplay loop - play games until session duration expires
            game_number = 0
            games_since_last_standing_check = 0
            
            while time.time() < session_end_time and not self.shutdown_event.is_set():
                game_number += 1
                games_since_last_standing_check += 1
                
                # ============================================================================
                # STEP 1: Play game (variable duration based on behavior and worker count)
                # ============================================================================
                if session_behavior == 'competitive':
                    # Competitive players play longer, more focused games
                    base_gameplay_duration = random.uniform(3.0, 5.0)
                elif session_behavior == 'explorer':
                    # Explorers vary their gameplay time
                    base_gameplay_duration = random.uniform(2.0, 4.0)
                else:
                    # Casual players have shorter, quicker games
                    base_gameplay_duration = random.uniform(1.5, 3.0)
                
                # Apply sleep multiplier
                gameplay_duration = base_gameplay_duration * sleep_multiplier
                
                self.logger.debug(
                    f"Player Worker {self.worker_id}: Playing game #{game_number} "
                    f"(simulated {gameplay_duration:.1f}s gameplay, {session_behavior} style, "
                    f"{sleep_multiplier:.1f}x speed)"
                )
                if not interruptible_sleep(gameplay_duration, self.shutdown_event):
                    break  # Shutdown requested during gameplay
                
                # ============================================================================
                # STEP 2: Submit stats after playing
                # ============================================================================
                self.logger.debug(f"Player Worker {self.worker_id}: Submitting stats for game #{game_number}")
                
                # Generate score with progression modifiers
                score_generator = self.generator_factory.get_score_generator()
                base_score = score_generator.generate_score(leaderboard_name_str, 'intermediate')
                current_score = int(base_score * progression_modifiers['score_multiplier'])
                
                # Check if this is a new personal best
                is_personal_best = self.gameplay_simulator.check_for_personal_best(current_score)
                if is_personal_best:
                    self.logger.debug(
                        f"Player Worker {self.worker_id}: New personal best! Score: {current_score}"
                    )
                
                last_submitted_score = current_score
                
                success, latency_ms = self._make_api_call(
                    'storePlayerStatsAndScores',
                    player_id,
                    game_id,
                    game_mode_str,
                    leaderboard_name_str,
                    api_base_url,
                    api_key,
                    pre_generated_score=current_score
                )
                session_api_calls += 1
                stats_submissions += 1
                if not success:
                    session_api_errors += 1
                if latency_ms:
                    session_total_latency += latency_ms
                
                # Short pause after submitting (0.3-0.8s, adjusted by sleep multiplier)
                pause_duration = random.uniform(0.3, 0.8) * sleep_multiplier
                if not interruptible_sleep(pause_duration, self.shutdown_event):
                    break
                
                # ============================================================================
                # STEP 3: Check leaderboard (varied queries based on behavior)
                # ============================================================================
                # Decide query type and parameters
                # Initialize variables to avoid NameError
                query_type_choice = 'top'
                query_limit = 10
                neighbor_count = 5
                
                if session_behavior == 'competitive':
                    # Competitive players check their position frequently
                    if random.random() < 0.6:
                        # Check position with neighbors
                        query_type_choice = 'aroundPlayer'
                        neighbor_count = random.choice([5, 10, 15])
                        self.logger.debug(
                            f"Player Worker {self.worker_id}: Checking position with {neighbor_count} neighbors"
                        )
                    else:
                        # Check top rankings
                        query_type_choice = 'top'
                        query_limit = random.choice([25, 50])
                        self.logger.debug(
                            f"Player Worker {self.worker_id}: Checking top {query_limit} leaderboard"
                        )
                elif session_behavior == 'explorer':
                    # Explorers vary their queries
                    if random.random() < 0.4:
                        query_type_choice = 'aroundPlayer'
                        neighbor_count = random.choice([10, 20])
                        self.logger.debug(
                            f"Player Worker {self.worker_id}: Checking position with {neighbor_count} neighbors"
                        )
                    else:
                        query_type_choice = 'top'
                        query_limit = random.choice([10, 25, 50, 100])
                        self.logger.debug(
                            f"Player Worker {self.worker_id}: Checking top {query_limit} leaderboard"
                        )
                else:
                    # Casual players mostly check top rankings
                    if random.random() < 0.2:
                        query_type_choice = 'aroundPlayer'
                        neighbor_count = random.choice([5, 10])
                        self.logger.debug(
                            f"Player Worker {self.worker_id}: Checking position with {neighbor_count} neighbors"
                        )
                    else:
                        query_type_choice = 'top'
                        query_limit = random.choice([10, 25])
                        self.logger.debug(
                            f"Player Worker {self.worker_id}: Checking top {query_limit} leaderboard"
                        )
                
                success, latency_ms = self._make_api_call(
                    'getLeaderboardScores',
                    player_id,
                    game_id,
                    game_mode_str,
                    leaderboard_name_str,
                    api_base_url,
                    api_key,
                    query_type=query_type_choice,
                    query_limit=query_limit if query_type_choice == 'top' else None,
                    neighbor_count=neighbor_count if query_type_choice == 'aroundPlayer' else None
                )
                session_api_calls += 1
                leaderboard_queries += 1
                if not success:
                    session_api_errors += 1
                if latency_ms:
                    session_total_latency += latency_ms
                
                # Short pause (0.3-0.8s, adjusted by sleep multiplier)
                pause_duration = random.uniform(0.3, 0.8) * sleep_multiplier
                if not interruptible_sleep(pause_duration, self.shutdown_event):
                    break
                
                # ============================================================================
                # STEP 4: Check own standing (not every game, varies by behavior)
                # ============================================================================
                should_check_standing = False
                if session_behavior == 'competitive':
                    # Competitive players check frequently
                    should_check_standing = (games_since_last_standing_check >= random.choice([1, 2]))
                elif session_behavior == 'explorer':
                    # Explorers check occasionally
                    should_check_standing = (games_since_last_standing_check >= random.choice([2, 3]))
                else:
                    # Casual players check rarely
                    should_check_standing = (games_since_last_standing_check >= random.choice([3, 4, 5]))
                
                if should_check_standing:
                    games_since_last_standing_check = 0
                    self.logger.debug(f"Player Worker {self.worker_id}: Checking detailed standing")
                    
                    # Vary whether to include neighbors
                    include_neighbors = random.random() < 0.6
                    
                    success, latency_ms = self._make_api_call(
                        'getPlayerLBStanding',
                        player_id,
                        game_id,
                        game_mode_str,
                        leaderboard_name_str,
                        api_base_url,
                        api_key,
                        include_neighbors=include_neighbors
                    )
                    session_api_calls += 1
                    player_standing_queries += 1
                    if not success:
                        session_api_errors += 1
                    if latency_ms:
                        session_total_latency += latency_ms
                    
                    # Short pause (0.3-0.8s)
                    if not interruptible_sleep(random.uniform(0.3, 0.8), self.shutdown_event):
                        break
                
                # ============================================================================
                # STEP 5: Check own scores/stats (varies by behavior)
                # ============================================================================
                should_check_stats = False
                if session_behavior == 'competitive':
                    # Competitive players track their stats closely
                    should_check_stats = random.random() < 0.7
                elif session_behavior == 'explorer':
                    # Explorers check stats regularly
                    should_check_stats = random.random() < 0.5
                else:
                    # Casual players check occasionally
                    should_check_stats = random.random() < 0.3
                
                if should_check_stats:
                    self.logger.debug(f"Player Worker {self.worker_id}: Checking own scores/stats")
                    success, latency_ms = self._make_api_call(
                        'getPlayerStatsAndScores',
                        player_id,
                        game_id,
                        game_mode_str,
                        leaderboard_name_str,
                        api_base_url,
                        api_key
                    )
                    session_api_calls += 1
                    player_stats_queries += 1
                    if not success:
                        session_api_errors += 1
                    if latency_ms:
                        session_total_latency += latency_ms
                    
                    # Short pause (0.3-0.8s)
                    if not interruptible_sleep(random.uniform(0.3, 0.8), self.shutdown_event):
                        break
                
                # Pause before next game (varies by behavior)
                if session_behavior == 'competitive':
                    # Competitive players jump back in quickly
                    pre_game_pause = random.uniform(0.5, 1.5)
                elif session_behavior == 'explorer':
                    # Explorers take time to review
                    pre_game_pause = random.uniform(1.0, 2.5)
                else:
                    # Casual players have varied pacing
                    pre_game_pause = random.uniform(0.8, 2.0)
                
                if not interruptible_sleep(pre_game_pause, self.shutdown_event):
                    break
                
                # Loop continues to play another game
            
            # Session complete
            elapsed_time = time.time() - session_start_time
            avg_session_latency = (
                session_total_latency / session_api_calls
                if session_api_calls > 0
                else 0
            )
            
            # ============================================================================
            # TASK 31.11: Update player progression after session completes
            # ============================================================================
            # Calculate session statistics for progression update (Requirement 34.7)
            session_stats = {
                'games_played': 1,  # Each session counts as 1 game
                'score': last_submitted_score if last_submitted_score else 0,
                'playtime_seconds': int(elapsed_time),
                'xp_earned': session_api_calls * 10  # 10 XP per API call (simple formula)
            }
            
            # Update persistent progression
            updated_progression = self.progression_manager.update_player_progression(
                player_id,
                session_stats
            )
            
            if updated_progression:
                # Check if player leveled up
                old_level = player_progression.get('level', 1)
                new_level = updated_progression.get('level', 1)
                
                if new_level > old_level:
                    self.logger.info(
                        f"Player Worker {self.worker_id}: 🎉 Player {player_id} leveled up! "
                        f"Level {old_level} → {new_level}"
                    )
                    
                    # Record level-up event in metrics (Task 31.12)
                    if self.metrics_collector:
                        self.metrics_collector.record_progression_event(
                            event_type='level_up',
                            player_level=new_level
                        )
                
                # Check for new achievements - safely handle mixed types
                old_achievements_raw = player_progression.get('achievements', [])
                old_achievements = set()
                for ach in old_achievements_raw:
                    if isinstance(ach, str):
                        old_achievements.add(ach)
                    elif isinstance(ach, dict) and 'id' in ach:
                        old_achievements.add(ach['id'])
                
                new_achievements_raw = updated_progression.get('achievements', [])
                new_achievements = set()
                for ach in new_achievements_raw:
                    if isinstance(ach, str):
                        new_achievements.add(ach)
                    elif isinstance(ach, dict) and 'id' in ach:
                        new_achievements.add(ach['id'])
                
                newly_unlocked = new_achievements - old_achievements
                
                if newly_unlocked:
                    achievement_names = [
                        self.progression_manager.ACHIEVEMENTS[ach_id]['name']
                        for ach_id in newly_unlocked
                    ]
                    self.logger.info(
                        f"Player Worker {self.worker_id}: 🏆 Player {player_id} unlocked achievements: "
                        f"{', '.join(achievement_names)}"
                    )
                
                # Record session completion with progression metrics (Task 31.12)
                if self.metrics_collector:
                    self.metrics_collector.record_progression_event(
                        event_type='session_complete',
                        player_level=new_level,
                        achievements_unlocked=len(newly_unlocked),
                        xp_earned=session_stats['xp_earned'],
                        games_played=session_stats['games_played']
                    )
                
                self.logger.debug(
                    f"Player Worker {self.worker_id}: Progression updated for {player_id}. "
                    f"Level: {new_level}, Total XP: {updated_progression.get('total_xp', 0)}, "
                    f"Total games: {updated_progression.get('cumulative_statistics', {}).get('games_played', 0)}"
                )
            else:
                # Only log warning if not shutting down (during shutdown, failures are expected)
                if not self.shutdown_event.is_set():
                    self.logger.warning(
                        f"Player Worker {self.worker_id}: Failed to update progression for {player_id}"
                    )
            
            # ============================================================================
            # TASK 27.7: Log player behavior patterns for analysis
            # ============================================================================
            # Get behavior summary from simulator
            behavior_summary = self.gameplay_simulator.get_behavior_summary()
            
            self.logger.info(
                f"Player Worker {self.worker_id}: Session complete for {player_id}. "
                f"Duration: {elapsed_time:.1f}s, API calls: {session_api_calls}, "
                f"Errors: {session_api_errors}, Avg latency: {avg_session_latency:.2f}ms"
            )
            
            self.logger.debug(
                f"Player Worker {self.worker_id}: API distribution for session: "
                f"Stats={stats_submissions}, Leaderboard={leaderboard_queries}, "
                f"PlayerStats={player_stats_queries}, Standing={player_standing_queries}"
            )
            
            # Log comprehensive behavior summary
            self.logger.info(
                f"Player Worker {self.worker_id}: Behavior Summary for {player_id}:\n"
                f"  Profile: {behavior_summary.get('profile', 'unknown')}\n"
                f"  Total Actions: {behavior_summary.get('total_actions', 0)}\n"
                f"  Action Breakdown: {behavior_summary.get('action_breakdown', {})}\n"
                f"  Session Phase: {behavior_summary.get('session_phase', 'unknown')}\n"
                f"  Personal Best: {behavior_summary.get('personal_best', 'N/A')}"
            )
            
            # Log pause statistics
            pause_stats = behavior_summary.get('pause_statistics', {})
            self.logger.debug(
                f"Player Worker {self.worker_id}: Pause Statistics for {player_id}:\n"
                f"  Total Pauses: {pause_stats.get('total_pauses', 0)}\n"
                f"  Average Pause: {pause_stats.get('avg_ms', 0):.2f}ms\n"
                f"  Min Pause: {pause_stats.get('min_ms', 0):.2f}ms\n"
                f"  Max Pause: {pause_stats.get('max_ms', 0):.2f}ms"
            )
            
            return True
            
        except Exception as e:
            self.logger.error(
                f"Player Worker {self.worker_id}: Error during gameplay session for {player_id}: {e}"
            )
            self.logger.error(traceback.format_exc())
            return False
        finally:
            # Mark as no longer in session
            self.in_session = False
    
    def _make_api_call(self, api_type, player_id, game_id, game_mode, leaderboard_name, api_base_url, api_key, pre_generated_score=None, query_type=None, query_limit=None, neighbor_count=None, include_neighbors=None, is_validation=False):
        """
        Make a single API call to the target system with retry logic.
        
        Implements exponential backoff retry for transient errors including:
        - 429 throttling (respects Retry-After header)
        - 5xx server errors
        - Network errors and timeouts
        - 404 on getPlayerLBStanding (player not found - retries with different player ONLY in non-validation scenarios)
        
        Args:
            api_type: Type of API call (storePlayerStatsAndScores, getLeaderboardScores, etc.)
            player_id: Player ID
            game_id: Game ID
            game_mode: Game mode
            leaderboard_name: Leaderboard name
            api_base_url: API Gateway base URL
            api_key: API key for authentication
            pre_generated_score: Optional pre-generated score (for personal best tracking)
            query_type: Optional query type for getLeaderboardScores ('top' or 'aroundPlayer')
            query_limit: Optional limit for 'top' queries (10, 25, 50, 100)
            neighbor_count: Optional neighbor count for 'aroundPlayer' queries (countBefore/countAfter)
            include_neighbors: Optional flag for getPlayerLBStanding to include neighbors
            is_validation: If True, this is a validation call after score submission - 404 is NOT acceptable
        
        Returns:
            tuple: (success: bool, latency_ms: float)
        
        Requirements: 13.1-13.17, 17.1-17.5, 18.1-18.4, 30.7
        Task: 13.3 - API call implementation with retry logic
        Task: 27.5 - Support pre-generated scores for personal best tracking
        """
        
        # Generate event ID for log correlation (used throughout method)
        event_id = generate_event_id()
        
        max_retries = 3
        retry_delays = [1, 2, 4]  # Exponential backoff: 1s, 2s, 4s
        max_404_retries = 12  # Special retry limit for 404 on getPlayerLBStanding (non-validation only)
        retry_404_count = 0  # Track 404 retries separately
        
        for attempt in range(max_retries + 1):  # 0, 1, 2, 3 (initial + 3 retries)
            try:
                # Prepare request based on API type
                # NOTE: This is inside the retry loop so we can rebuild with new player_id on 404 retries
                if api_type == 'storePlayerStatsAndScores':
                    # POST /leaderboards/stats
                    endpoint = f"{api_base_url}/leaderboards/stats"
                    
                    # Use pre-generated score if provided (for personal best tracking)
                    # Otherwise generate score using data generator
                    if pre_generated_score is not None:
                        player_score = pre_generated_score
                    else:
                        score_generator = self.generator_factory.get_score_generator()
                        player_score = score_generator.generate_score(leaderboard_name, 'intermediate')
                    
                    # Generate fullRawGameReport with correct parameters
                    game_report_generator = self.generator_factory.get_game_report_generator()
                    session_id = f"session_{player_id}_{int(time.time())}"
                    player_state = {'level': 1}
                    full_raw_game_report = game_report_generator.generate_game_report(
                        player_id,
                        game_mode,
                        session_id,
                        player_state
                    )
                    
                    request_body = {
                        "gameReportBody": {
                            "playerID": player_id,
                            "gameID": game_id,
                            "gameMode": game_mode,
                            "playerScore": player_score,
                            "leaderboardName": leaderboard_name,
                            "fullRawGameReport": full_raw_game_report
                        }
                    }
                    
                elif api_type == 'getLeaderboardScores':
                    # POST /leaderboards/scores
                    endpoint = f"{api_base_url}/leaderboards/scores"
                    
                    # Use provided query_type or default to 'top'
                    if query_type is None:
                        query_type = 'top'
                    
                    if query_type == 'top':
                        # Use provided query_limit or default to random choice
                        limit = query_limit if query_limit is not None else random.choice([10, 25, 50, 100])
                        request_body = {
                            "leaderboardScoresRequest": {
                                "gameID": game_id,
                                "gameMode": game_mode,
                                "leaderboardName": leaderboard_name,
                                "queryType": "top",
                                "limit": limit
                            }
                        }
                    else:  # aroundPlayer
                        # Use provided neighbor_count or default to 5
                        count = neighbor_count if neighbor_count is not None else 5
                        request_body = {
                            "leaderboardScoresRequest": {
                                "gameID": game_id,
                                "gameMode": game_mode,
                                "leaderboardName": leaderboard_name,
                                "queryType": "aroundPlayer",
                                "playerID": player_id,
                                "countBefore": count,
                                "countAfter": count
                            }
                        }
                    
                elif api_type == 'getPlayerStatsAndScores':
                    # POST /leaderboards/player/stats
                    endpoint = f"{api_base_url}/leaderboards/player/stats"
                    
                    request_body = {
                        "playerStatsAndScoresRequest": {
                            "playerID": player_id,
                            "gameID": game_id,
                            "gameMode": game_mode,
                            "leaderboardName": leaderboard_name,
                            "limit": 10
                        }
                    }
                    
                elif api_type == 'getPlayerLBStanding':
                    # POST /leaderboards/player/standing
                    endpoint = f"{api_base_url}/leaderboards/player/standing"
                    
                    # Use provided include_neighbors or default to random choice
                    include_neighbours = include_neighbors if include_neighbors is not None else random.choice([True, False])
                    request_body = {
                        "playerLBStandingRequest": {
                            "playerID": player_id,
                            "gameID": game_id,
                            "gameMode": game_mode,
                            "leaderboardName": leaderboard_name,
                            "includePercentile": True,
                            "includeNeighbours": include_neighbours,
                            "neighbourCount": 5
                        }
                    }
                    
                else:
                    self.logger.error(
                        f"Player Worker {self.worker_id}: Unknown API type: {api_type}"
                    )
                    return False, 0
                
                # Make the API call
                headers = {
                    'Authorization': f'Bearer {api_key}',
                    'Content-Type': 'application/json'
                }
                
                start_time = time.time()
                response = self.http_session.post(
                    endpoint,
                    json=request_body,
                    headers=headers,
                    timeout=API_TIMEOUT_WRITE
                )
                latency_ms = (time.time() - start_time) * 1000
                
                # Parse response
                try:
                    response_data = response.json()
                except:
                    response_data = response.text
                
                # ============================================================================
                # SMART LOGGING STRATEGY:
                # 1. PRIMING phase: ALL requests go to events-worker.log
                # 2. WORKER phase: Each worker logs to its OWN worker-N.log (NOT events-worker.log)
                # 3. main.log: High-level overview, errors/warnings with Event IDs only
                # ============================================================================
                
                # Log to worker-specific log (worker-N.log) - ALL workers log to their own file
                if self.worker_logger:
                    self.worker_logger.log_api_call(
                        endpoint=endpoint,
                        method='POST',
                        request_data=request_body,
                        response_data=response_data,
                        latency_ms=latency_ms,
                        status_code=response.status_code,
                        event_id=event_id,
                        request_headers=headers,
                        response_headers=dict(response.headers),
                        is_validation=is_validation  # Pass validation context to logger
                    )
                
                # Log to main log - only summary for errors/warnings, not full details
                if response.status_code >= 400:
                    # Error or client error - log summary to main log
                    error_msg = response_data.get('message', 'Unknown error') if isinstance(response_data, dict) else str(response_data)[:100]
                    
                    # Special handling: Check if this is a "Player Not Found" error (404 with specific message)
                    is_player_not_found = False
                    if response.status_code == 404 and api_type == 'getPlayerLBStanding':
                        # Check for specific error pattern in response body
                        if isinstance(response_data, dict):
                            standing_response = response_data.get('playerLBStandingResponse', {})
                            error_field = standing_response.get('error', '')
                            message_field = standing_response.get('message', '')
                            
                            # Check for exact error pattern: error="Player Not Found" and message contains "not found in leaderboard"
                            if error_field == 'Player Not Found' and 'not found in leaderboard' in message_field:
                                is_player_not_found = True
                    
                    # If this is a validation call and player not found, this is a REAL ERROR (not acceptable)
                    if is_player_not_found and is_validation:
                        self.logger.error(
                            f"[PlayerWorker-{self.worker_id}] [EventID: {event_id}] "
                            f"VALIDATION FAILURE: {api_type} returned 404 - Player {player_id} not found after score submission! "
                            f"This indicates a consistency issue. Message: {error_msg}"
                        )
                    # If this is NOT a validation call and player not found, this is expected (will retry with different player)
                    elif is_player_not_found and not is_validation:
                        # This is expected - player not in leaderboard yet
                        # Will be handled by retry logic below, no need to log as error
                        pass
                    # For 400 errors, include more context to help debug validation issues
                    elif response.status_code == 400:
                        # Extract key request fields for debugging
                        request_summary = {}
                        if api_type == 'getLeaderboardScores' and 'leaderboardScoresRequest' in request_body:
                            req = request_body['leaderboardScoresRequest']
                            request_summary = {
                                'gameID': req.get('gameID'),
                                'gameMode': req.get('gameMode'),
                                'leaderboardName': req.get('leaderboardName'),
                                'queryType': req.get('queryType')
                            }
                            # Add query-specific fields
                            if req.get('queryType') == 'top':
                                request_summary['limit'] = req.get('limit')
                            elif req.get('queryType') == 'aroundPlayer':
                                request_summary['playerID'] = req.get('playerID')
                                request_summary['countBefore'] = req.get('countBefore')
                                request_summary['countAfter'] = req.get('countAfter')
                        
                        self.logger.error(
                            f"[PlayerWorker-{self.worker_id}] [EventID: {event_id}] "
                            f"API Validation Error: {api_type} returned 400 - {error_msg}. "
                            f"Request: {request_summary}"
                        )
                    else:
                        # Check if this is a "Player Not Found" error (specific pattern)
                        # Need to check again here because this else block handles all non-400 errors
                        is_player_not_found_check = False
                        if response.status_code == 404 and api_type == 'getPlayerLBStanding' and isinstance(response_data, dict):
                            standing_response = response_data.get('playerLBStandingResponse', {})
                            error_field = standing_response.get('error', '')
                            message_field = standing_response.get('message', '')
                            if error_field == 'Player Not Found' and 'not found in leaderboard' in message_field:
                                is_player_not_found_check = True
                        
                        # Only log if NOT a player-not-found in non-validation scenario
                        if not (is_player_not_found_check and not is_validation):
                            self.logger.error(
                                f"[PlayerWorker-{self.worker_id}] [EventID: {event_id}] "
                                f"API Error: {api_type} returned {response.status_code} - {error_msg}"
                            )
                elif latency_ms > 2500:
                    # High latency - log warning to main log
                    self.logger.warning(
                        f"[PlayerWorker-{self.worker_id}] [EventID: {event_id}] "
                        f"High latency: {api_type} took {latency_ms:.0f}ms"
                    )
                # Success cases (200) are not logged to main.log to reduce noise
                
                # Check response status
                if response.status_code == 200:
                    # Record successful API call metrics (Requirements 19.4, 19.5)
                    if self.metrics_collector:
                        endpoint_name = f"POST {endpoint.split(api_base_url)[1]}" if api_base_url in endpoint else api_type
                        self.metrics_collector.record_request(endpoint_name, latency_ms, success=True)
                    
                    # ============================================================================
                    # TASK 26.2: Stat Submission Validation
                    # ============================================================================
                    # After successful stat submission, validate consistency (Requirements 29.2, 29.3, 29.4)
                    if api_type == 'storePlayerStatsAndScores' and self.consistency_validator:
                        if self.consistency_validator.should_validate():
                            # Perform consistency validation
                            validation_success = self._validate_stat_submission(
                                player_id=player_id,
                                game_id=game_id,
                                game_mode=game_mode,
                                leaderboard_name=leaderboard_name,
                                submitted_score=player_score,
                                api_base_url=api_base_url,
                                api_key=api_key
                            )
                            # Note: validation_success is logged in _validate_stat_submission
                            
                            # ============================================================================
                            # TASK 26.6: fullRawGameReport Validation
                            # ============================================================================
                            # Validate that fullRawGameReport is retrievable (Requirement 29.13)
                            validation_success = self._validate_fullRawGameReport(
                                player_id=player_id,
                                game_id=game_id,
                                game_mode=game_mode,
                                leaderboard_name=leaderboard_name,
                                api_base_url=api_base_url,
                                api_key=api_key,
                                submitted_report=full_raw_game_report
                            )
                            # Note: validation_success is logged in _validate_fullRawGameReport
                    
                    # ============================================================================
                    # TASK 26.3: Player Stats Consistency Check
                    # ============================================================================
                    # After querying player stats, validate consistency (Requirements 29.6, 29.14)
                    if api_type == 'getPlayerStatsAndScores' and self.consistency_validator:
                        if self.consistency_validator.should_validate():
                            # Perform player stats consistency validation
                            validation_success = self._validate_player_stats_consistency(
                                player_id=player_id,
                                game_id=game_id,
                                game_mode=game_mode,
                                leaderboard_name=leaderboard_name,
                                api_base_url=api_base_url,
                                api_key=api_key
                            )
                            # Note: validation_success is logged in _validate_player_stats_consistency
                    
                    if attempt > 0:
                        self.logger.debug(
                            f"Player Worker {self.worker_id}: {api_type} success on retry {attempt}. "
                            f"Latency: {latency_ms:.2f}ms"
                        )
                    else:
                        self.logger.debug(
                            f"Player Worker {self.worker_id}: {api_type} success. "
                            f"Latency: {latency_ms:.2f}ms"
                        )
                    
                    return True, latency_ms
                
                # Handle errors with retry logic
                is_retryable = False
                retry_delay = retry_delays[attempt] if attempt < len(retry_delays) else retry_delays[-1]
                
                if response.status_code == 429:
                    # Throttling - retryable, respect Retry-After header (Requirement 18.8)
                    retry_after = response.headers.get('Retry-After')
                    if retry_after:
                        try:
                            retry_delay = int(retry_after)
                            self.logger.debug(
                                f"Player Worker {self.worker_id}: Using Retry-After: {retry_delay}s"
                            )
                        except ValueError:
                            pass  # Use default exponential backoff
                    
                    is_retryable = True
                    self.logger.warning(
                        f"Player Worker {self.worker_id}: {api_type} throttled (429) on attempt {attempt + 1}"
                    )
                    
                elif response.status_code >= 500:
                    # Server error - retryable
                    is_retryable = True
                    self.logger.warning(
                        f"Player Worker {self.worker_id}: {api_type} server error ({response.status_code}) "
                        f"on attempt {attempt + 1}"
                    )
                else:
                    # Client error (4xx except 429) - not retryable by default
                    
                    # SPECIAL CASE: 404 "Player Not Found" on getPlayerLBStanding
                    # - In VALIDATION scenarios: This is a REAL ERROR (player should exist after score submission)
                    # - In NON-VALIDATION scenarios: This is EXPECTED (random player queries), retry with different player
                    
                    is_player_not_found = False
                    if response.status_code == 404 and api_type == 'getPlayerLBStanding':
                        # Check for specific error pattern in response body
                        if isinstance(response_data, dict):
                            standing_response = response_data.get('playerLBStandingResponse', {})
                            error_field = standing_response.get('error', '')
                            message_field = standing_response.get('message', '')
                            
                            # Verify this is specifically a "Player Not Found" error
                            if error_field == 'Player Not Found' and 'not found in leaderboard' in message_field:
                                is_player_not_found = True
                    
                    # Handle player-not-found based on context
                    if is_player_not_found and not is_validation and retry_404_count < max_404_retries:
                        # NON-VALIDATION scenario: Expected behavior, retry with different player
                        retry_404_count += 1
                        self.logger.debug(
                            f"Player Worker {self.worker_id}: Player {player_id} not found in leaderboard {leaderboard_name}. "
                            f"Trying different player (404 retry {retry_404_count}/{max_404_retries})..."
                        )
                        # Generate a new random player ID for retry (use consistent format)
                        player_id = f"player_{random.randint(1, 100000):06d}"
                        time.sleep(0.1)  # Brief delay
                        # Don't increment attempt counter for 404 retries - they're separate
                        # Just continue to rebuild request with new player_id
                        continue  # Retry with new player
                    elif is_player_not_found and is_validation:
                        # VALIDATION scenario: This is a REAL ERROR - player should exist after score submission
                        # This indicates a consistency problem - don't retry, report as failure
                        if self.metrics_collector:
                            endpoint_name = f"POST {endpoint.split(api_base_url)[1]}" if api_base_url in endpoint else api_type
                            error_details = {
                                'status_code': response.status_code,
                                'error_type': 'ValidationFailure_PlayerNotFound',
                                'message': f'Player {player_id} not found in leaderboard after score submission',
                                'context': 'validation'
                            }
                            self.metrics_collector.record_request(endpoint_name, latency_ms, success=False, error_details=error_details)
                        
                        self.logger.error(
                            f"Player Worker {self.worker_id}: VALIDATION FAILURE - {api_type} returned 404. "
                            f"Player {player_id} not found in leaderboard {leaderboard_name} after score submission. "
                            f"This indicates a consistency issue. Latency: {latency_ms:.2f}ms"
                        )
                        
                        return False, latency_ms
                    
                    # Record failed API call metrics (Requirements 19.4, 19.5)
                    if self.metrics_collector:
                        endpoint_name = f"POST {endpoint.split(api_base_url)[1]}" if api_base_url in endpoint else api_type
                        error_details = {
                            'status_code': response.status_code,
                            'error_type': 'ClientError',
                            'message': f'{api_type} returned {response.status_code}'
                        }
                        self.metrics_collector.record_request(endpoint_name, latency_ms, success=False, error_details=error_details)
                    
                    # Enhanced logging for 400 errors to help debug validation issues
                    if response.status_code == 400:
                        error_msg = response_data.get('message', 'Unknown error') if isinstance(response_data, dict) else str(response_data)[:200]
                        self.logger.error(
                            f"Player Worker {self.worker_id}: {api_type} validation error (400). "
                            f"Error: {error_msg}, Latency: {latency_ms:.2f}ms"
                        )
                        # Log request body for debugging (truncated for readability)
                        request_summary = str(request_body)[:300] if len(str(request_body)) > 300 else str(request_body)
                        self.logger.debug(
                            f"Player Worker {self.worker_id}: Request body: {request_summary}"
                        )
                    else:
                        # Check if this is a "Player Not Found" error in non-validation scenario (acceptable)
                        is_player_not_found_acceptable = False
                        if response.status_code == 404 and api_type == 'getPlayerLBStanding' and not is_validation:
                            if isinstance(response_data, dict):
                                standing_response = response_data.get('playerLBStandingResponse', {})
                                error_field = standing_response.get('error', '')
                                message_field = standing_response.get('message', '')
                                if error_field == 'Player Not Found' and 'not found in leaderboard' in message_field:
                                    is_player_not_found_acceptable = True
                        
                        # Only log if NOT an acceptable player-not-found scenario
                        if not is_player_not_found_acceptable:
                            self.logger.warning(
                                f"Player Worker {self.worker_id}: {api_type} client error ({response.status_code}). "
                                f"Latency: {latency_ms:.2f}ms"
                            )
                    
                    return False, latency_ms
                
                # If retryable and we have retries left, retry
                if is_retryable and attempt < max_retries:
                    self.logger.debug(
                        f"Player Worker {self.worker_id}: Retrying {api_type} in {retry_delay}s..."
                    )
                    time.sleep(retry_delay)
                    continue  # Retry
                else:
                    # No more retries - record failed API call
                    if self.metrics_collector:
                        endpoint_name = f"POST {endpoint.split(api_base_url)[1]}" if api_base_url in endpoint else api_type
                        error_details = {
                            'status_code': response.status_code,
                            'error_type': 'Throttling' if response.status_code == 429 else 'ServerError',
                            'message': f'{api_type} failed after {attempt + 1} attempts with status {response.status_code}'
                        }
                        self.metrics_collector.record_request(endpoint_name, latency_ms, success=False, error_details=error_details)
                    
                    self.logger.warning(
                        f"Player Worker {self.worker_id}: {api_type} failed after {attempt + 1} attempts. "
                        f"Status: {response.status_code}, Latency: {latency_ms:.2f}ms"
                    )
                    
                    return False, latency_ms
                    
            except requests.exceptions.Timeout:
                # Timeout - retryable
                if attempt < max_retries:
                    retry_delay = retry_delays[attempt] if attempt < len(retry_delays) else retry_delays[-1]
                    self.logger.warning(
                        f"Player Worker {self.worker_id}: {api_type} timeout on attempt {attempt + 1}. "
                        f"Retrying in {retry_delay}s..."
                    )
                    time.sleep(retry_delay)
                    continue  # Retry
                else:
                    self.logger.warning(
                        f"Player Worker {self.worker_id}: {api_type} timeout after {attempt + 1} attempts"
                    )
                    
                    return False, 30000
                
            except requests.exceptions.RequestException as e:
                # Network error - retryable
                if attempt < max_retries:
                    retry_delay = retry_delays[attempt] if attempt < len(retry_delays) else retry_delays[-1]
                    self.logger.warning(
                        f"Player Worker {self.worker_id}: {api_type} network error on attempt {attempt + 1}: {e}. "
                        f"Retrying in {retry_delay}s..."
                    )
                    time.sleep(retry_delay)
                    continue  # Retry
                else:
                    self.logger.error(
                        f"Player Worker {self.worker_id}: {api_type} network error after {attempt + 1} attempts: {e}"
                    )
                    
                    return False, 0
                
            except Exception as e:
                # Unexpected error - not retryable
                self.logger.error(
                    f"Player Worker {self.worker_id}: {api_type} unexpected error: {e}"
                )
                self.logger.error(traceback.format_exc())
                
                return False, 0
        
        # Should never reach here, but just in case
        return False, 0
    
    def _validate_stat_submission(self, player_id, game_id, game_mode, leaderboard_name, submitted_score, api_base_url, api_key):
        """
        Validate that a submitted stat appears in the leaderboard.
        
        Queries the player's standing to verify the submitted score is reflected
        in the leaderboard within the validation timeout window.
        
        Args:
            player_id: Player ID
            game_id: Game ID
            game_mode: Game mode
            leaderboard_name: Leaderboard name
            submitted_score: Score that was submitted
            api_base_url: API Gateway base URL
            api_key: API key for authentication
        
        Returns:
            bool: True if validation succeeded, False otherwise
        
        Requirements: 29.2, 29.3, 29.4, 29.14
        Task: 26.2 - Stat submission validation
        """
        
        validation_start = time.time()
        max_attempts = MAX_RETRY_ATTEMPTS_CONSISTENCY  # Max attempts over validation window
        retry_interval = RETRY_INTERVAL_SHORT  # seconds between attempts
        
        endpoint = f"{api_base_url}/leaderboards/player/standing"
        headers = {
            'Authorization': f'Bearer {api_key}',
            'Content-Type': 'application/json'
        }
        request_body = {
            "playerLBStandingRequest": {
                "playerID": player_id,
                "gameID": game_id,
                "gameMode": game_mode,
                "leaderboardName": leaderboard_name,
                "includePercentile": True,
                "includeNeighbours": False
            }
        }
        
        for attempt in range(max_attempts):
            try:
                # Query player standing
                attempt_start = time.time()
                response = self.http_session.post(
                    endpoint,
                    json=request_body,
                    headers=headers,
                    timeout=5
                )
                attempt_latency = (time.time() - attempt_start) * 1000  # Convert to ms
                
                if response.status_code == 200:
                    response_data = response.json()
                    
                    # Check if player standing is returned
                    standing_response = response_data.get('playerLBStandingResponse', {})
                    
                    # CRITICAL: Check for error field first (API returns 200 even when player not found)
                    if 'error' in standing_response:
                        # Player not found yet - this is expected during eventual consistency
                        if attempt == 0:
                            # Log first attempt only to avoid spam
                            self.logger.debug(
                                f"Player Worker {self.worker_id}: Validation attempt 1/{max_attempts}: "
                                f"Player {player_id} not yet in leaderboard {leaderboard_name} "
                                f"(latency: {attempt_latency:.0f}ms, error: {standing_response.get('error')})"
                            )
                        
                        if attempt < max_attempts - 1:
                            time.sleep(retry_interval)
                            continue
                        else:
                            # Failed after all attempts
                            validation_latency = time.time() - validation_start
                            
                            self.consistency_validator.record_validation_result(
                                success=False,
                                latency=validation_latency,
                                endpoint='POST /leaderboards/stats',
                                leaderboard_name=leaderboard_name,
                                details={
                                    'player_id': player_id,
                                    'submitted_score': submitted_score,
                                    'attempts': max_attempts,
                                    'reason': 'player_not_found_in_leaderboard',
                                    'api_error': standing_response.get('error'),
                                    'api_message': standing_response.get('message')
                                }
                            )
                            
                            # Log consistency warning with full context
                            self.logger.warning(
                                f"CONSISTENCY WARNING: Player Worker {self.worker_id}: "
                                f"Submitted score not found in leaderboard after {max_attempts} attempts. "
                                f"Player: {player_id}, Leaderboard: {leaderboard_name}, "
                                f"Score: {submitted_score}, Validation time: {validation_latency:.3f}s, "
                                f"API response: {standing_response.get('error')} - {standing_response.get('message')}"
                            )
                            return False
                    
                    # API returns 'playerLBStandingInfo' not 'playerStanding'
                    player_standing = standing_response.get('playerLBStandingInfo')
                    
                    if player_standing:
                        # Player found in leaderboard - validation successful
                        validation_latency = time.time() - validation_start
                        
                        self.consistency_validator.record_validation_result(
                            success=True,
                            latency=validation_latency,
                            endpoint='POST /leaderboards/stats',
                            leaderboard_name=leaderboard_name,
                            details={
                                'player_id': player_id,
                                'submitted_score': submitted_score,
                                'attempts': attempt + 1
                            }
                        )
                        
                        # Log success only if it took more than 1 attempt
                        if attempt > 0:
                            self.logger.debug(
                                f"Player Worker {self.worker_id}: Consistency validation PASSED for "
                                f"player {player_id} on leaderboard {leaderboard_name} "
                                f"(attempts: {attempt + 1}, latency: {validation_latency:.3f}s)"
                            )
                        return True
                    else:
                        # No error and no playerLBStandingInfo - unexpected response format
                        if attempt < max_attempts - 1:
                            self.logger.debug(
                                f"Player Worker {self.worker_id}: Validation attempt {attempt + 1}/{max_attempts}: "
                                f"Unexpected response format (no error, no playerLBStandingInfo) for {player_id}. "
                                f"Response keys: {list(standing_response.keys())}"
                            )
                            time.sleep(retry_interval)
                            continue
                        else:
                            # Failed after all attempts
                            validation_latency = time.time() - validation_start
                            
                            self.consistency_validator.record_validation_result(
                                success=False,
                                latency=validation_latency,
                                endpoint='POST /leaderboards/stats',
                                leaderboard_name=leaderboard_name,
                                details={
                                    'player_id': player_id,
                                    'submitted_score': submitted_score,
                                    'attempts': max_attempts,
                                    'reason': 'unexpected_response_format',
                                    'response_keys': list(standing_response.keys())
                                }
                            )
                            
                            self.logger.warning(
                                f"CONSISTENCY WARNING: Player Worker {self.worker_id}: "
                                f"Unexpected response format after {max_attempts} attempts. "
                                f"Player: {player_id}, Leaderboard: {leaderboard_name}, "
                                f"Score: {submitted_score}, Validation time: {validation_latency:.3f}s, "
                                f"Response keys: {list(standing_response.keys())}, "
                                f"Full response: {standing_response}"
                            )
                            return False
                else:
                    # API error during validation
                    if attempt < max_attempts - 1:
                        time.sleep(retry_interval)
                        continue
                    else:
                        validation_latency = time.time() - validation_start
                        
                        self.consistency_validator.record_validation_result(
                            success=False,
                            latency=validation_latency,
                            endpoint='POST /leaderboards/stats',
                            leaderboard_name=leaderboard_name,
                            details={
                                'player_id': player_id,
                                'submitted_score': submitted_score,
                                'attempts': max_attempts,
                                'reason': f'api_error_{response.status_code}'
                            }
                        )
                        
                        self.logger.warning(
                            f"CONSISTENCY WARNING: Player Worker {self.worker_id}: "
                            f"Validation failed due to API error {response.status_code}. "
                            f"Player: {player_id}, Leaderboard: {leaderboard_name}, "
                            f"Submitted score: {submitted_score}, "
                            f"Response: {response.text[:500] if hasattr(response, 'text') else 'N/A'}"
                        )
                        return False
                        
            except Exception as e:
                # Exception during validation
                if attempt < max_attempts - 1:
                    time.sleep(retry_interval)
                    continue
                else:
                    validation_latency = time.time() - validation_start
                    
                    self.consistency_validator.record_validation_result(
                        success=False,
                        latency=validation_latency,
                        endpoint='POST /leaderboards/stats',
                        leaderboard_name=leaderboard_name,
                        details={
                            'player_id': player_id,
                            'submitted_score': submitted_score,
                            'attempts': max_attempts,
                            'reason': f'exception_{type(e).__name__}'
                        }
                    )
                    
                    self.logger.warning(
                        f"CONSISTENCY WARNING: Player Worker {self.worker_id}: "
                        f"Validation failed due to exception: {e}. "
                        f"Player: {player_id}, Leaderboard: {leaderboard_name}, "
                        f"Submitted score: {submitted_score}, "
                        f"Attempts: {max_attempts}, "
                        f"Exception type: {type(e).__name__}"
                    )
                    return False
        
        # Should never reach here
        return False
    
    def _validate_player_stats_consistency(self, player_id, game_id, game_mode, leaderboard_name, api_base_url, api_key, expected_score=None):
        """
        Validate that player stats returned from query match previously submitted values.
        
        Queries player stats and verifies consistency with submitted data.
        
        Args:
            player_id: Player ID
            game_id: Game ID
            game_mode: Game mode
            leaderboard_name: Leaderboard name
            api_base_url: API Gateway base URL
            api_key: API key for authentication
            expected_score: Expected score value (optional, for comparison)
        
        Returns:
            bool: True if validation succeeded, False otherwise
        
        Requirements: 29.6, 29.14
        Task: 26.3 - Player stats consistency check
        """
        
        validation_start = time.time()
        
        endpoint = f"{api_base_url}/leaderboards/player/stats"
        headers = {
            'Authorization': f'Bearer {api_key}',
            'Content-Type': 'application/json'
        }
        request_body = {
            "playerStatsAndScoresRequest": {
                "playerID": player_id,
                "gameID": game_id,
                "gameMode": game_mode,
                "leaderboardName": leaderboard_name,
                "limit": 10
            }
        }
        
        try:
            # Query player stats
            response = self.http_session.post(
                endpoint,
                json=request_body,
                headers=headers,
                timeout=5
            )
            
            validation_latency = time.time() - validation_start
            
            if response.status_code == 200:
                response_data = response.json()
                
                # Extract player stats from response
                stats_response = response_data.get('playerStatsAndScoresResponse', {})
                player_stats = stats_response.get('playerStats', [])
                
                if player_stats:
                    # Player has stats - validation successful
                    # Note: We validate that stats are retrievable and contain expected structure
                    # Detailed value comparison would require tracking all submitted values,
                    # which is memory-intensive. For now, we validate structure and presence.
                    
                    first_stat = player_stats[0] if isinstance(player_stats, list) else player_stats
                    
                    # Validate expected fields are present
                    has_player_id = 'playerID' in first_stat or 'playerId' in first_stat
                    has_score = 'playerScore' in first_stat or 'score' in first_stat
                    has_leaderboard = 'leaderboardName' in first_stat
                    
                    if has_player_id and has_score and has_leaderboard:
                        # Structure is valid
                        self.consistency_validator.record_validation_result(
                            success=True,
                            latency=validation_latency,
                            endpoint='POST /leaderboards/player/stats',
                            leaderboard_name=leaderboard_name,
                            details={
                                'player_id': player_id,
                                'stats_count': len(player_stats) if isinstance(player_stats, list) else 1,
                                'validation_type': 'structure'
                            }
                        )
                        
                        self.logger.debug(
                            f"Player Worker {self.worker_id}: Player stats consistency validation PASSED for "
                            f"player {player_id} on leaderboard {leaderboard_name} "
                            f"(latency: {validation_latency:.3f}s, stats count: {len(player_stats) if isinstance(player_stats, list) else 1})"
                        )
                        return True
                    else:
                        # Structure is invalid - missing expected fields
                        self.consistency_validator.record_validation_result(
                            success=False,
                            latency=validation_latency,
                            endpoint='POST /leaderboards/player/stats',
                            leaderboard_name=leaderboard_name,
                            details={
                                'player_id': player_id,
                                'reason': 'missing_expected_fields',
                                'has_player_id': has_player_id,
                                'has_score': has_score,
                                'has_leaderboard': has_leaderboard
                            }
                        )
                        
                        # Log discrepancy with full context (Requirement 29.6, 29.14)
                        self.logger.warning(
                            f"CONSISTENCY WARNING: Player Worker {self.worker_id}: "
                            f"Player stats missing expected fields. "
                            f"Player: {player_id}, Leaderboard: {leaderboard_name}, "
                            f"Has playerID: {has_player_id}, Has score: {has_score}, Has leaderboard: {has_leaderboard}, "
                            f"Response: {first_stat}"
                        )
                        return False
                else:
                    # No stats returned - could be valid if player hasn't submitted yet
                    # We'll consider this a successful validation (empty is valid)
                    self.consistency_validator.record_validation_result(
                        success=True,
                        latency=validation_latency,
                        endpoint='POST /leaderboards/player/stats',
                        leaderboard_name=leaderboard_name,
                        details={
                            'player_id': player_id,
                            'stats_count': 0,
                            'validation_type': 'empty_valid'
                        }
                    )
                    
                    self.logger.debug(
                        f"Player Worker {self.worker_id}: Player stats query returned empty (valid) for "
                        f"player {player_id} on leaderboard {leaderboard_name}"
                    )
                    return True
            else:
                # API error during validation
                self.consistency_validator.record_validation_result(
                    success=False,
                    latency=validation_latency,
                    endpoint='POST /leaderboards/player/stats',
                    leaderboard_name=leaderboard_name,
                    details={
                        'player_id': player_id,
                        'reason': f'api_error_{response.status_code}'
                    }
                )
                
                self.logger.warning(
                    f"CONSISTENCY WARNING: Player Worker {self.worker_id}: "
                    f"Player stats validation failed due to API error {response.status_code}. "
                    f"Player: {player_id}, Leaderboard: {leaderboard_name}, "
                    f"Response: {response.text[:500] if hasattr(response, 'text') else 'N/A'}"
                )
                return False
                
        except Exception as e:
            # Exception during validation
            validation_latency = time.time() - validation_start
            
            self.consistency_validator.record_validation_result(
                success=False,
                latency=validation_latency,
                endpoint='POST /leaderboards/player/stats',
                leaderboard_name=leaderboard_name,
                details={
                    'player_id': player_id,
                    'reason': f'exception_{type(e).__name__}'
                }
            )
            
            self.logger.warning(
                f"CONSISTENCY WARNING: Player Worker {self.worker_id}: "
                f"Player stats validation failed due to exception: {e}. "
                f"Player: {player_id}, Leaderboard: {leaderboard_name}, "
                f"Exception type: {type(e).__name__}"
            )
            return False


    def _validate_fullRawGameReport(self, player_id, game_id, game_mode, leaderboard_name, api_base_url, api_key, submitted_report):
        """
        Validate that fullRawGameReport data is retrievable via player stats query.
        
        After submitting stats with fullRawGameReport, queries POST /leaderboards/player/stats
        to verify the report data is retrievable. Validates that the response contains
        fullRawGameReport field and has expected structure.
        
        Args:
            player_id: Player ID
            game_id: Game ID
            game_mode: Game mode
            leaderboard_name: Leaderboard name
            api_base_url: API Gateway base URL
            api_key: API key for authentication
            submitted_report: The fullRawGameReport that was submitted (for reference)
        
        Returns:
            bool: True if validation passed, False otherwise
        
        Requirements: 29.13, 29.14
        Tasks: 26.6
        """
        
        validation_start = time.time()
        
        try:
            # Query POST /leaderboards/player/stats to retrieve fullRawGameReport
            endpoint = f"{api_base_url}/leaderboards/player/stats"
            
            request_body = {
                "playerStatsAndScoresRequest": {
                    "playerID": player_id,
                    "gameID": game_id,
                    "gameMode": game_mode,
                    "leaderboardName": leaderboard_name,
                    "limit": 10
                }
            }
            
            headers = {
                'Content-Type': 'application/json',
                'Authorization': f'Bearer {api_key}'
            }
            
            response = self.http_session.post(
                endpoint,
                json=request_body,
                headers=headers,
                timeout=5
            )
            
            validation_latency = (time.time() - validation_start) * 1000  # Convert to ms
            
            if response.status_code == 200:
                response_data = response.json()
                
                # Extract player stats from response
                stats_response = response_data.get('playerStatsAndScoresResponse', {})
                player_stats = stats_response.get('playerStats', [])
                
                if player_stats:
                    # Check if fullRawGameReport is present in response
                    first_stat = player_stats[0] if isinstance(player_stats, list) else player_stats
                    
                    has_full_raw_game_report = 'fullRawGameReport' in first_stat
                    
                    if has_full_raw_game_report:
                        retrieved_report = first_stat['fullRawGameReport']
                        
                        # Validate that retrieved report is a dict/object (not null or empty)
                        if isinstance(retrieved_report, dict) and retrieved_report:
                            # fullRawGameReport is present and has data - validation successful
                            self.consistency_validator.record_validation_result(
                                success=True,
                                latency=validation_latency / 1000,  # Convert ms to seconds
                                endpoint='POST /leaderboards/stats',
                                leaderboard_name=leaderboard_name
                            )
                            
                            self.logger.debug(
                                f"Player Worker {self.worker_id}: fullRawGameReport validation PASSED for "
                                f"player {player_id} on leaderboard {leaderboard_name} "
                                f"(latency: {validation_latency:.1f}ms, report fields: {len(retrieved_report)})"
                            )
                            return True
                        else:
                            # fullRawGameReport is present but empty or invalid
                            self.consistency_validator.record_validation_result(
                                success=False,
                                latency=validation_latency / 1000,  # Convert ms to seconds
                                endpoint='POST /leaderboards/stats',
                                leaderboard_name=leaderboard_name
                            )
                            
                            self.logger.warning(
                                f"CONSISTENCY WARNING: Player Worker {self.worker_id}: "
                                f"fullRawGameReport is empty or invalid. "
                                f"Player: {player_id}, Leaderboard: {leaderboard_name}, "
                                f"Retrieved report type: {type(retrieved_report)}, "
                                f"Retrieved report: {retrieved_report}"
                            )
                            return False
                    else:
                        # fullRawGameReport field is missing from response
                        self.consistency_validator.record_validation_result(
                            success=False,
                            latency=validation_latency / 1000,  # Convert ms to seconds
                            endpoint='POST /leaderboards/stats',
                            leaderboard_name=leaderboard_name
                        )
                        
                        self.logger.warning(
                            f"CONSISTENCY WARNING: Player Worker {self.worker_id}: "
                            f"fullRawGameReport field missing from player stats response. "
                            f"Player: {player_id}, Leaderboard: {leaderboard_name}, "
                            f"Response fields: {list(first_stat.keys())}"
                        )
                        return False
                else:
                    # No stats returned - player may not have submitted yet
                    # This is valid, but we can't validate fullRawGameReport
                    # We'll consider this a successful validation (empty is valid)
                    self.consistency_validator.record_validation_result(
                        success=True,
                        latency=validation_latency,
                        endpoint='POST /leaderboards/stats',
                        leaderboard_name=leaderboard_name
                    )
                    
                    self.logger.debug(
                        f"Player Worker {self.worker_id}: Player stats query returned empty (valid) for "
                        f"player {player_id} on leaderboard {leaderboard_name}"
                    )
                    return True
            else:
                # API error during validation
                self.consistency_validator.record_validation_result(
                    success=False,
                    latency=validation_latency / 1000,  # Convert ms to seconds
                    endpoint='POST /leaderboards/stats',
                    leaderboard_name=leaderboard_name
                )
                
                self.logger.warning(
                    f"CONSISTENCY WARNING: Player Worker {self.worker_id}: "
                    f"fullRawGameReport validation failed due to API error {response.status_code}. "
                    f"Player: {player_id}, Leaderboard: {leaderboard_name}, "
                    f"Response: {response.text[:500] if hasattr(response, 'text') else 'N/A'}"
                )
                return False
                
        except Exception as e:
            # Exception during validation
            validation_latency = (time.time() - validation_start) * 1000
            
            self.consistency_validator.record_validation_result(
                success=False,
                latency=validation_latency,
                endpoint='POST /leaderboards/stats',
                leaderboard_name=leaderboard_name
            )
            
            self.logger.warning(
                f"CONSISTENCY WARNING: Player Worker {self.worker_id}: "
                f"fullRawGameReport validation failed due to exception: {e}. "
                f"Player: {player_id}, Leaderboard: {leaderboard_name}, "
                f"Exception type: {type(e).__name__}"
            )
            return False


