def discover_infrastructure(stack_name, aws_profile, aws_region, logger=None):
    """
    Discover infrastructure from CloudFormation stack outputs.
    
    Reads AWS CDK deployment outputs to extract API Gateway endpoints and
    resource identifiers needed for test execution.
    
    Args:
        stack_name: CloudFormation stack name
        aws_profile: AWS profile name
        aws_region: AWS region
        logger: Optional ThreadSafeLogger instance
    
    Returns:
        dict: Dictionary of stack outputs with keys like:
            - ApiEndpoint: API Gateway endpoint URL
            - SSMParameterPrefix: SSM parameter prefix
            - TestDefinitionsTableName: DynamoDB table name
            - PlayerStateTableName: DynamoDB table name
            - GameLeaderboardsConfigTableName: Target system table
            - GameStatsTableName: Target system table
    
    Raises:
        Exception: If stack not found or inaccessible
    
    Requirements: 1.1
    Design: Section 23.1
    """
    
    if logger:
        logger.info(f"Discovering infrastructure from stack: {stack_name}")
    
    try:
        # Create boto3 session with profile and region
        session = boto3.Session(profile_name=aws_profile, region_name=aws_region)
        cfn = session.client('cloudformation')
        
        # Describe stack to get outputs
        response = cfn.describe_stacks(StackName=stack_name)
        
        if not response.get('Stacks'):
            error_msg = f"Stack '{stack_name}' not found"
            if logger:
                logger.error(error_msg)
            raise Exception(error_msg)
        
        stack = response['Stacks'][0]
        
        # Extract outputs into dictionary
        outputs = {}
        for output in stack.get('Outputs', []):
            outputs[output['OutputKey']] = output['OutputValue']
        
        if logger:
            logger.info(f"Discovered {len(outputs)} stack outputs")
            for key, value in outputs.items():
                logger.info(f"  {key}: {value}")
        
        return outputs
    
    except ClientError as e:
        error_code = e.response.get('Error', {}).get('Code', 'Unknown')
        
        if error_code == 'AccessDeniedException':
            print()
            print(f"❌ ERROR: Access denied when describing stack '{stack_name}'")
            print()
            print("Required IAM permissions:")
            print("  - cloudformation:DescribeStacks")
            print()
            print(f"Resource ARN: arn:aws:cloudformation:{aws_region}:*:stack/{stack_name}/*")
            print()
            if logger:
                logger.error(f"Access denied when describing stack '{stack_name}'")
            raise
        elif error_code == 'ValidationError':
            print()
            print(f"❌ ERROR: Stack '{stack_name}' does not exist in region '{aws_region}'")
            print()
            print("Please verify:")
            print(f"  - Stack name is correct: {stack_name}")
            print(f"  - Stack exists in region: {aws_region}")
            print(f"  - AWS profile is correct: {aws_profile}")
            print()
            if logger:
                logger.error(f"Stack '{stack_name}' not found in region '{aws_region}'")
            raise
        else:
            if logger:
                logger.error(f"Failed to discover infrastructure: {e}")
            raise
    
    except Exception as e:
        if logger:
            logger.error(f"Unexpected error discovering infrastructure: {e}")
        raise


