def retrieve_api_key_from_ssm(ssm_prefix, studio_id, game_id, aws_profile, aws_region, logger=None):
    """
    Retrieve API key and complete studio/game metadata from SSM Parameter Store.
    
    SSM Parameter Store is the SOURCE OF TRUTH for all studio and game metadata.
    This function retrieves and validates the complete metadata including:
    - apiKey: The API key for authentication
    - studioId: Studio identifier (validated against expected value)
    - gameId: Game identifier (validated against expected value)
    - studioName: Human-readable studio name
    - gameTitle: Human-readable game title
    - gameGenre: Game genre classification
    - contactEmail: Contact email for the studio
    - status: API key status (must be 'active')
    
    SECURITY: API keys must NEVER come from CloudFormation outputs.
    CloudFormation outputs are placeholders only - SSM is authoritative.
    
    Args:
        ssm_prefix: SSM parameter prefix from stack outputs
        studio_id: Studio identifier (for validation)
        game_id: Game identifier (for validation)
        aws_profile: AWS profile name
        aws_region: AWS region
        logger: Optional ThreadSafeLogger instance
    
    Returns:
        dict: Complete metadata dictionary with all fields if found and active, None otherwise
        {
            'apiKey': str,
            'studioId': str,
            'gameId': str,
            'studioName': str,
            'gameTitle': str,
            'gameGenre': str,
            'contactEmail': str,
            'status': str,
            'permissions': list,
            'rateLimit': int,
            'environment': str,
            'createdAt': str,
            'lastUpdated': str
        }
    
    Requirements: 1.2
    Design: Section 23.3
    """
    
    # Clean up the prefix - remove trailing slash if present
    clean_prefix = ssm_prefix.rstrip('/')
    
    # Construct parameter name
    parameter_name = f"{clean_prefix}/api-keys/{studio_id}-{game_id}"
    
    if logger:
        logger.info(f"Retrieving API key from SSM: {parameter_name}")
    
    try:
        # Create boto3 session with profile and region
        session = boto3.Session(profile_name=aws_profile, region_name=aws_region)
        ssm = session.client('ssm')
        
        # Get parameter with decryption
        response = ssm.get_parameter(
            Name=parameter_name,
            WithDecryption=True
        )
        
        # Parse key data
        key_data = json.loads(response['Parameter']['Value'])
        
        # Validate API key exists
        api_key = key_data.get('apiKey')
        if not api_key:
            warning_msg = f"SSM validation failed: No apiKey field found in {parameter_name}"
            if logger:
                logger.warning(warning_msg)
            print(f"⚠️  WARNING: {warning_msg}")
            return None
        
        # Validate studioId matches (SECURITY: Prevent key misuse)
        ssm_studio_id = key_data.get('studioId')
        if ssm_studio_id != studio_id:
            warning_msg = f"SSM validation failed: studioId mismatch (expected: {studio_id}, got: {ssm_studio_id})"
            if logger:
                logger.warning(warning_msg)
            print(f"⚠️  WARNING: {warning_msg}")
            return None
        
        # Validate gameId matches (SECURITY: Prevent key misuse)
        ssm_game_id = key_data.get('gameId')
        if ssm_game_id != game_id:
            warning_msg = f"SSM validation failed: gameId mismatch (expected: {game_id}, got: {ssm_game_id})"
            if logger:
                logger.warning(warning_msg)
            print(f"⚠️  WARNING: {warning_msg}")
            return None
        
        # Validate status is active (SECURITY: Only use active keys)
        status = key_data.get('status')
        if status != 'active':
            warning_msg = f"SSM validation failed: API key status is '{status}' (expected: active)"
            if logger:
                logger.warning(warning_msg)
            print(f"⚠️  WARNING: {warning_msg}")
            return None
        
        # All validations passed
        if logger:
            logger.info(f"Retrieved and validated active API key for {studio_id}/{game_id}")
            logger.info(f"  Studio Name: {key_data.get('studioName', 'N/A')}")
            logger.info(f"  Game Title: {key_data.get('gameTitle', 'N/A')}")
            logger.info(f"  Game Genre: {key_data.get('gameGenre', 'N/A')}")
        
        # Return complete metadata dictionary (SSM is source of truth)
        return {
            'apiKey': api_key,
            'studioId': key_data.get('studioId'),
            'gameId': key_data.get('gameId'),
            'studioName': key_data.get('studioName', 'Unknown Studio'),
            'gameTitle': key_data.get('gameTitle', 'Unknown Game'),
            'gameGenre': key_data.get('gameGenre', 'unknown'),
            'contactEmail': key_data.get('contactEmail', ''),
            'status': key_data.get('status'),
            'permissions': key_data.get('permissions', []),
            'rateLimit': key_data.get('rateLimit', 1000),
            'environment': key_data.get('environment', 'dev'),
            'createdAt': key_data.get('createdAt', ''),
            'lastUpdated': key_data.get('lastUpdated', '')
        }
    
    except ClientError as e:
        error_code = e.response.get('Error', {}).get('Code', 'Unknown')
        
        if error_code == 'ParameterNotFound':
            warning_msg = f"API key not found: {parameter_name}"
            if logger:
                logger.warning(warning_msg)
            print(f"⚠️  WARNING: {warning_msg}")
            return None
        elif error_code == 'AccessDeniedException':
            print()
            print(f"❌ ERROR: Access denied when retrieving parameter '{parameter_name}'")
            print()
            print("Required IAM permissions:")
            print("  - ssm:GetParameter")
            print()
            print(f"Resource ARN: arn:aws:ssm:{aws_region}:*:parameter{parameter_name}")
            print()
            if logger:
                logger.error(f"Access denied when retrieving parameter '{parameter_name}'")
            raise
        else:
            if logger:
                logger.error(f"Failed to retrieve API key: {e}")
            raise
    
    except Exception as e:
        if logger:
            logger.error(f"Unexpected error retrieving API key: {e}")
        raise


def discover_service_quotas(aws_profile, aws_region, logger=None):
    """
    Discover current AWS service quotas for Lambda and API Gateway.
    
    Queries AWS Service Quotas to retrieve current limits for:
    - Lambda concurrent executions
    - API Gateway throttle rate
    - API Gateway burst limit
    
    Args:
        aws_profile: AWS profile name
        aws_region: AWS region
        logger: Optional ThreadSafeLogger instance
    
    Returns:
        dict: Dictionary with quota values:
            - lambda_concurrency: Lambda concurrent execution limit
            - api_throttle_rate: API Gateway throttle rate (requests per second)
            - api_burst_limit: API Gateway burst limit
    
    Requirements: 1.3, 1.4
    Design: Section 23.2
    """
    
    if logger:
        logger.info("Discovering AWS service quotas")
    
    # Create boto3 session with profile and region
    session = boto3.Session(profile_name=aws_profile, region_name=aws_region)
    quotas_client = session.client('service-quotas')
    
    quotas = {}
    
    # Query Lambda concurrent executions quota
    try:
        response = quotas_client.get_service_quota(
            ServiceCode='lambda',
            QuotaCode='L-B99A9384'  # Concurrent executions
        )
        quotas['lambda_concurrency'] = int(response['Quota']['Value'])
        if logger:
            logger.info(f"Lambda concurrent executions quota: {quotas['lambda_concurrency']}")
    except ClientError as e:
        error_code = e.response.get('Error', {}).get('Code', 'Unknown')
        if error_code == 'NoSuchResourceException':
            # Use default if quota not found
            quotas['lambda_concurrency'] = 1000
            if logger:
                logger.warning(f"Lambda quota not found, using default: {quotas['lambda_concurrency']}")
        else:
            if logger:
                logger.warning(f"Failed to query Lambda quota: {e}, using default: 1000")
            quotas['lambda_concurrency'] = 1000
    
    # Query API Gateway throttle rate quota
    try:
        response = quotas_client.get_service_quota(
            ServiceCode='apigateway',
            QuotaCode='L-8A5B8E43'  # Throttle rate
        )
        quotas['api_throttle_rate'] = int(response['Quota']['Value'])
        if logger:
            logger.info(f"API Gateway throttle rate quota: {quotas['api_throttle_rate']}")
    except ClientError as e:
        error_code = e.response.get('Error', {}).get('Code', 'Unknown')
        if error_code == 'NoSuchResourceException':
            # Use default if quota not found
            quotas['api_throttle_rate'] = 10000
            if logger:
                logger.warning(f"API Gateway throttle rate quota not found, using default: {quotas['api_throttle_rate']}")
        else:
            if logger:
                logger.warning(f"Failed to query API Gateway throttle rate: {e}, using default: 10000")
            quotas['api_throttle_rate'] = 10000
    
    # Query API Gateway burst limit quota
    try:
        response = quotas_client.get_service_quota(
            ServiceCode='apigateway',
            QuotaCode='L-CDF5615A'  # Burst limit
        )
        quotas['api_burst_limit'] = int(response['Quota']['Value'])
        if logger:
            logger.info(f"API Gateway burst limit quota: {quotas['api_burst_limit']}")
    except ClientError as e:
        error_code = e.response.get('Error', {}).get('Code', 'Unknown')
        if error_code == 'NoSuchResourceException':
            # Use default if quota not found
            quotas['api_burst_limit'] = 5000
            if logger:
                logger.warning(f"API Gateway burst limit quota not found, using default: {quotas['api_burst_limit']}")
        else:
            if logger:
                logger.warning(f"Failed to query API Gateway burst limit: {e}, using default: 5000")
            quotas['api_burst_limit'] = 5000
    
    # Query DynamoDB capacity limits (optional, for informational purposes)
    try:
        response = quotas_client.get_service_quota(
            ServiceCode='dynamodb',
            QuotaCode='L-F98FE922'  # Read capacity units per table (on-demand)
        )
        quotas['dynamodb_read_capacity'] = int(response['Quota']['Value'])
        if logger:
            logger.info(f"DynamoDB read capacity quota: {quotas['dynamodb_read_capacity']}")
    except ClientError:
        quotas['dynamodb_read_capacity'] = 40000  # Default
        if logger:
            logger.warning(f"DynamoDB read capacity quota not found, using default: {quotas['dynamodb_read_capacity']}")
    
    return quotas


