def calculate_required_quotas(target_rps, logger=None):
    """
    Calculate required service quotas for target load.
    
    Computes the required Lambda concurrency and API Gateway throttle limits
    needed to handle the target requests per second with a 20% buffer.
    
    Args:
        target_rps: Target requests per second
        logger: Optional ThreadSafeLogger instance
    
    Returns:
        dict: Dictionary with required quota values:
            - lambda_concurrency: Required Lambda concurrent executions
            - api_throttle_rate: Required API Gateway throttle rate
    
    Requirements: 1.5
    Design: Section 23.2
    """
    # Lambda: Assume 100ms average execution time
    # Concurrency = RPS * execution_time_seconds * buffer
    required_lambda_concurrency = int(target_rps * 0.1 * 1.2)  # 20% buffer
    
    # API Gateway: Direct RPS requirement with buffer
    required_api_throttle = int(target_rps * 1.2)  # 20% buffer
    
    required = {
        'lambda_concurrency': required_lambda_concurrency,
        'api_throttle_rate': required_api_throttle
    }
    
    if logger:
        logger.info(f"Calculated required quotas for {target_rps} RPS:")
        logger.info(f"  Lambda concurrency: {required_lambda_concurrency}")
        logger.info(f"  API Gateway throttle rate: {required_api_throttle}")
    
    return required


def request_quota_increase(service_code, quota_code, desired_value, aws_profile, aws_region, logger=None):
    """
    Request service quota increase.
    
    Submits a request to AWS Service Quotas to increase a specific quota.
    The request may take time to process and requires manual approval in some cases.
    
    Args:
        service_code: AWS service code (e.g., 'lambda', 'apigateway')
        quota_code: Quota code (e.g., 'L-B99A9384')
        desired_value: Desired quota value
        aws_profile: AWS profile name
        aws_region: AWS region
        logger: Optional ThreadSafeLogger instance
    
    Returns:
        dict: Request details if successful, None if failed
    
    Requirements: 1.6, 1.7
    Design: Section 23.2
    """
    
    if logger:
        logger.info(f"Requesting quota increase: {service_code}/{quota_code} -> {desired_value}")
    
    try:
        # Create boto3 session with profile and region
        session = boto3.Session(profile_name=aws_profile, region_name=aws_region)
        quotas_client = session.client('service-quotas')
        
        # Request quota increase
        response = quotas_client.request_service_quota_increase(
            ServiceCode=service_code,
            QuotaCode=quota_code,
            DesiredValue=float(desired_value)
        )
        
        request_info = response['RequestedQuota']
        
        if logger:
            logger.info(f"Quota increase requested successfully")
            logger.info(f"  Request ID: {request_info['Id']}")
            logger.info(f"  Status: {request_info['Status']}")
        
        print(f"✓ Quota increase requested: {service_code}/{quota_code} -> {desired_value}")
        print(f"  Request ID: {request_info['Id']}")
        print(f"  Status: {request_info['Status']}")
        
        return request_info
    
    except ClientError as e:
        error_code = e.response.get('Error', {}).get('Code', 'Unknown')
        error_message = e.response.get('Error', {}).get('Message', str(e))
        
        if logger:
            logger.error(f"Failed to request quota increase: {error_code} - {error_message}")
        
        print(f"✗ Failed to request quota increase: {service_code}/{quota_code}")
        print(f"  Error: {error_code} - {error_message}")
        
        return None
    
    except Exception as e:
        if logger:
            logger.error(f"Unexpected error requesting quota increase: {e}")
        
        print(f"✗ Unexpected error requesting quota increase: {e}")
        
        return None


def handle_insufficient_quotas(current, required, aws_profile, aws_region, logger=None):
    """
    Handle insufficient quotas with user prompt.
    
    Displays current vs required quotas and prompts user to:
    1. Attempt automatic quota increase requests
    2. Continue with test using current quotas
    3. Abort test execution
    
    Args:
        current: Dictionary of current quota values
        required: Dictionary of required quota values
        aws_profile: AWS profile name
        aws_region: AWS region
        logger: Optional ThreadSafeLogger instance
    
    Returns:
        bool: True if user wants to continue, False to abort
    
    Requirements: 1.8
    Design: Section 23.2
    """
    print()
    print("⚠️  INSUFFICIENT SERVICE QUOTAS DETECTED")
    print("=" * 80)
    print()
    print("Current Quotas:")
    print(f"  Lambda Concurrency: {current.get('lambda_concurrency', 'Unknown')}")
    print(f"  API Gateway Throttle: {current.get('api_throttle_rate', 'Unknown')} requests/second")
    print()
    print("Required Quotas:")
    print(f"  Lambda Concurrency: {required.get('lambda_concurrency', 'Unknown')}")
    print(f"  API Gateway Throttle: {required.get('api_throttle_rate', 'Unknown')} requests/second")
    print()
    print("=" * 80)
    print()
    
    if logger:
        logger.warning("Insufficient service quotas detected")
        logger.warning(f"  Current Lambda: {current.get('lambda_concurrency')}, Required: {required.get('lambda_concurrency')}")
        logger.warning(f"  Current API Gateway: {current.get('api_throttle_rate')}, Required: {required.get('api_throttle_rate')}")
    
    # Ask user if they want to attempt quota increases
    response = input("Attempt to request quota increases? (yes/no): ").strip().lower()
    
    if response == 'yes':
        print()
        print("Requesting quota increases...")
        print()
        
        results = {}
        
        # Request Lambda concurrency increase if needed
        if required.get('lambda_concurrency', 0) > current.get('lambda_concurrency', 0):
            result = request_quota_increase(
                'lambda',
                'L-B99A9384',
                required['lambda_concurrency'],
                aws_profile,
                aws_region,
                logger
            )
            results['lambda'] = result is not None
        else:
            results['lambda'] = True
        
        # Request API Gateway throttle increase if needed
        if required.get('api_throttle_rate', 0) > current.get('api_throttle_rate', 0):
            result = request_quota_increase(
                'apigateway',
                'L-8A5B8E43',
                required['api_throttle_rate'],
                aws_profile,
                aws_region,
                logger
            )
            results['apigateway'] = result is not None
        else:
            results['apigateway'] = True
        
        print()
        
        # Check if all requests succeeded
        if not all(results.values()):
            print("⚠️  Some quota increase requests failed.")
            print()
            response = input("Continue with test anyway? (yes/no): ").strip().lower()
            return response == 'yes'
        
        print("✅ Quota increase requests submitted successfully.")
        print()
        print("NOTE: Quota increases may take time to process and may require manual approval.")
        print("      The test will proceed with current quotas.")
        print()
        response = input("Continue with test using current quotas? (yes/no): ").strip().lower()
        return response == 'yes'
    else:
        print()
        response = input("Continue with test using current quotas? (yes/no): ").strip().lower()
        return response == 'yes'


# ============================================================================
# SECTION 10: THREAD-SAFE LOGGING SYSTEM
# ============================================================================

class CloudWatchLogHandler:
    """
    Non-blocking CloudWatch Logs handler with background thread and batching.
    
    Features:
    - Asynchronous log streaming to CloudWatch Logs
    - Automatic batching (up to 100 events per API call)
    - Background thread for non-blocking I/O
    - Automatic retry with exponential backoff
    - Graceful degradation (logs locally if CloudWatch fails)
    - Thread-safe queue-based architecture
    - Automatic log stream creation
    - Sequence token management
    
    Architecture:
    - Main thread: Adds logs to queue (non-blocking)
    - Background thread: Batches and sends to CloudWatch
    - Queue: Thread-safe communication between threads
    
    Requirements: Centralized logging, non-blocking I/O, automatic retry
    """
    
    def __init__(self, log_group_name, log_stream_name, region, aws_session, logger=None):
        """
        Initialize CloudWatch log handler.
        
        Args:
            log_group_name: CloudWatch log group name (e.g., '/loadtest/stats-leaderboards')
            log_stream_name: CloudWatch log stream name (e.g., 'worker-0-instance-1')
            region: AWS region
            aws_session: boto3 Session object
            logger: Optional logger for handler errors (avoids circular dependency)
        """
        self.log_group_name = log_group_name
        self.log_stream_name = log_stream_name
        self.region = region
        self.logger = logger
        
        # Create CloudWatch Logs client
        try:
            self.logs_client = aws_session.client('logs', region_name=region)
        except Exception as e:
            if self.logger:
                self.logger.warning(f"Failed to create CloudWatch Logs client: {e}")
            self.logs_client = None
            return
        
        # Queue for log events (thread-safe)
        self.log_queue = queue.Queue(maxsize=10000)  # Max 10k events in queue
        
        # Sequence token for log stream (required by CloudWatch)
        self.sequence_token = None
        self.sequence_token_lock = threading.Lock()
        
        # Background thread for sending logs
        self.shutdown_event = threading.Event()
        self.flush_thread = threading.Thread(
            target=self._flush_loop,
            name=f"CloudWatchLogHandler-{log_stream_name}",
            daemon=True
        )
        self.flush_thread.start()
        
        # Statistics
        self.total_events_sent = 0
        self.total_events_failed = 0
        self.total_api_calls = 0
        
        # Ensure log group and stream exist
        self._ensure_log_group_and_stream()
    
    def _ensure_log_group_and_stream(self):
        """
        Ensure CloudWatch log group and stream exist.
        Creates them if they don't exist.
        """
        if not self.logs_client:
            return
        
        try:
            # Create log group if it doesn't exist
            try:
                self.logs_client.create_log_group(logGroupName=self.log_group_name)
                if self.logger:
                    self.logger.info(f"Created CloudWatch log group: {self.log_group_name}")
            except self.logs_client.exceptions.ResourceAlreadyExistsException:
                pass  # Log group already exists
            
            # Create log stream if it doesn't exist
            try:
                self.logs_client.create_log_stream(
                    logGroupName=self.log_group_name,
                    logStreamName=self.log_stream_name
                )
                if self.logger:
                    self.logger.info(f"Created CloudWatch log stream: {self.log_stream_name}")
            except self.logs_client.exceptions.ResourceAlreadyExistsException:
                # Log stream exists, get the sequence token
                self._get_sequence_token()
        
        except Exception as e:
            if self.logger:
                self.logger.warning(f"Failed to ensure CloudWatch log group/stream: {e}")
    
    def _get_sequence_token(self):
        """
        Get the current sequence token for the log stream.
        Required when appending to an existing stream.
        """
        if not self.logs_client:
            return
        
        try:
            response = self.logs_client.describe_log_streams(
                logGroupName=self.log_group_name,
                logStreamNamePrefix=self.log_stream_name,
                limit=1
            )
            
            if response.get('logStreams'):
                stream = response['logStreams'][0]
                with self.sequence_token_lock:
                    self.sequence_token = stream.get('uploadSequenceToken')
        
        except Exception as e:
            if self.logger:
                self.logger.warning(f"Failed to get sequence token: {e}")
    
    def emit(self, level, message, timestamp=None):
        """
        Add log event to queue (non-blocking).
        
        Args:
            level: Log level (DEBUG, INFO, WARNING, ERROR, CRITICAL)
            message: Log message
            timestamp: Optional timestamp (milliseconds since epoch)
        
        Returns:
            bool: True if added to queue, False if queue is full
        """
        if not self.logs_client:
            return False
        
        if timestamp is None:
            timestamp = int(time.time() * 1000)
        
        log_event = {
            'timestamp': timestamp,
            'message': f"[{level}] {message}"
        }
        
        try:
            self.log_queue.put_nowait(log_event)
            return True
        except queue.Full:
            # Queue is full, drop the log event
            self.total_events_failed += 1
            return False
    
    def _flush_loop(self):
        """
        Background thread that batches and sends logs to CloudWatch.
        Runs continuously until shutdown.
        """
        batch = []
        last_flush_time = time.time()
        
        while not self.shutdown_event.is_set():
            try:
                # Try to get log events from queue (with timeout)
                try:
                    event = self.log_queue.get(timeout=0.1)
                    batch.append(event)
                except queue.Empty:
                    pass
                
                # Flush if batch is full or interval elapsed
                should_flush = (
                    len(batch) >= CLOUDWATCH_BATCH_SIZE or
                    (batch and time.time() - last_flush_time >= CLOUDWATCH_FLUSH_INTERVAL)
                )
                
                if should_flush:
                    self._send_batch(batch)
                    batch.clear()
                    last_flush_time = time.time()
            
            except Exception as e:
                if self.logger:
                    self.logger.warning(f"CloudWatch flush loop error: {e}")
                time.sleep(1)
        
        # Final flush on shutdown
        if batch:
            self._send_batch(batch)
    
    def _send_batch(self, batch):
        """
        Send a batch of log events to CloudWatch.
        
        Args:
            batch: List of log events to send
        """
        if not batch or not self.logs_client:
            return
        
        # Sort by timestamp (required by CloudWatch)
        sorted_batch = sorted(batch, key=lambda x: x['timestamp'])
        
        # Retry logic with exponential backoff
        for attempt in range(CLOUDWATCH_MAX_RETRIES):
            try:
                params = {
                    'logGroupName': self.log_group_name,
                    'logStreamName': self.log_stream_name,
                    'logEvents': sorted_batch
                }
                
                # Add sequence token if we have one
                with self.sequence_token_lock:
                    if self.sequence_token:
                        params['sequenceToken'] = self.sequence_token
                
                # Send to CloudWatch
                response = self.logs_client.put_log_events(**params)
                
                # Update sequence token for next call
                with self.sequence_token_lock:
                    self.sequence_token = response.get('nextSequenceToken')
                
                # Update statistics
                self.total_events_sent += len(sorted_batch)
                self.total_api_calls += 1
                
                return  # Success
            
            except self.logs_client.exceptions.InvalidSequenceTokenException as e:
                # Sequence token is invalid, extract the correct one from error
                error_message = str(e)
                if 'expectedSequenceToken' in error_message:
                    # Extract token from error message
                    import re
                    match = re.search(r'expectedSequenceToken: ([a-zA-Z0-9+/=]+)', error_message)
                    if match:
                        with self.sequence_token_lock:
                            self.sequence_token = match.group(1)
                        continue  # Retry with correct token
                
                # If we can't extract token, get it from API
                self._get_sequence_token()
                continue  # Retry
            
            except self.logs_client.exceptions.DataAlreadyAcceptedException:
                # Events already accepted, consider it success
                self.total_events_sent += len(sorted_batch)
                return
            
            except self.logs_client.exceptions.ResourceNotFoundException:
                # Log group or stream doesn't exist, recreate
                self._ensure_log_group_and_stream()
                continue  # Retry
            
            except Exception as e:
                if self.logger:
                    self.logger.warning(f"CloudWatch send batch error (attempt {attempt + 1}): {e}")
                
                if attempt < CLOUDWATCH_MAX_RETRIES - 1:
                    time.sleep(CLOUDWATCH_RETRY_DELAY * (2 ** attempt))  # Exponential backoff
                else:
                    # Final attempt failed
                    self.total_events_failed += len(sorted_batch)
    
    def flush(self):
        """
        Force flush all pending log events.
        Blocks until queue is empty or timeout.
        """
        timeout = 5.0  # 5 second timeout
        start_time = time.time()
        
        while not self.log_queue.empty() and time.time() - start_time < timeout:
            time.sleep(0.1)
    
    def shutdown(self):
        """
        Shutdown the handler and flush remaining logs.
        """
        self.shutdown_event.set()
        
        # Wait for flush thread to finish
        if self.flush_thread.is_alive():
            self.flush_thread.join(timeout=5.0)
        
        # Log statistics
        if self.logger:
            self.logger.info(
                f"CloudWatch handler shutdown: {self.total_events_sent} events sent, "
                f"{self.total_events_failed} failed, {self.total_api_calls} API calls"
            )
    
    def get_statistics(self):
        """
        Get handler statistics.
        
        Returns:
            dict: Statistics including events sent, failed, and API calls
        """
        return {
            'events_sent': self.total_events_sent,
            'events_failed': self.total_events_failed,
            'api_calls': self.total_api_calls,
            'queue_size': self.log_queue.qsize()
        }


class ThreadSafeLogger:
    """
    Thread-safe logger for main orchestration activities.
    
    This logger handles all main thread logging with file locking to prevent
    race conditions. It creates a top-level log directory with timestamp pattern
    and maintains a single log file for orchestration activities.
    
    Features:
    - Thread-safe file writes with locking
    - Log buffering for performance
    - Periodic flushing (every 5 seconds)
    - Flush on critical events
    - Structured logging format with timestamps
    - Multiple log levels (DEBUG, INFO, WARNING, ERROR, CRITICAL)
    
    Requirements: 4.1, 4.2, 4.5, 4.7
    """
    
    def __init__(self, log_dir=None, instance_id=None, cloudwatch_handler=None):
        """
        Initialize the Main Thread Logger.
        
        Args:
            log_dir: Optional custom log directory path. If not provided,
                    uses "testing/testlogs" (persistent across runs)
            instance_id: Optional unique instance identifier for log file naming
            cloudwatch_handler: Optional CloudWatchLogHandler for streaming logs
        """
        # Use persistent log directory (no timestamp in directory name)
        if log_dir is None:
            self.log_dir = Path(__file__).parent / "testlogs"
        else:
            self.log_dir = Path(log_dir)
        
        self.log_dir.mkdir(parents=True, exist_ok=True)
        
        # Store instance_id for later use
        self.instance_id = instance_id
        
        # CloudWatch handler for streaming logs
        self.cloudwatch_handler = cloudwatch_handler
        
        # Create main log file with instance_id if provided (append mode to preserve history)
        if instance_id:
            self.log_file = self.log_dir / f"main-{instance_id}.log"
        else:
            self.log_file = self.log_dir / "main.log"
        
        # Add separator if log file already exists
        if self.log_file.exists():
            self._write_separator()
        
        # Thread safety
        self.lock = threading.Lock()
        
        # Log buffering
        self.buffer = []
        self.buffer_size = 100  # Flush after 100 entries
        self.last_flush_time = time.time()
        self.flush_interval = 5.0  # Flush every 5 seconds
        
        # Start background flush thread
        self.flush_thread = threading.Thread(target=self._periodic_flush, daemon=True)
        self.flush_thread.start()
        
        # Log levels
        self.LOG_LEVELS = {
            'DEBUG': 10,
            'INFO': 20,
            'WARNING': 30,
            'ERROR': 40,
            'CRITICAL': 50
        }
        self.current_level = self.LOG_LEVELS['INFO']
        
        # Write initial log entry
        self.info(f"Main Thread Logger initialized: {self.log_dir}")
        if self.cloudwatch_handler:
            self.info(f"CloudWatch streaming enabled: {self.cloudwatch_handler.log_group_name}/{self.cloudwatch_handler.log_stream_name}")
    
    def update_instance_id(self, new_instance_id):
        """
        Update the instance ID and re-point the log file.
        
        This is called after the real instance ID is allocated (replacing "pending").
        Flushes any buffered content to the old file first, then switches to the new file.
        
        Args:
            new_instance_id: The real instance ID (e.g., "gen-1", "dryrun-1", "instance-1")
        """
        with self.lock:
            # Flush buffer to old file first
            if self.buffer:
                with open(self.log_file, 'a', encoding='utf-8') as f:
                    for entry in self.buffer:
                        f.write(entry)
                self.buffer.clear()
            
            old_file = self.log_file
            self.instance_id = new_instance_id
            self.log_file = self.log_dir / f"main-{new_instance_id}.log"
            
            # Copy content from old file to new file if they differ
            if old_file != self.log_file and old_file.exists():
                try:
                    content = old_file.read_text(encoding='utf-8')
                    with open(self.log_file, 'a', encoding='utf-8') as f:
                        f.write(content)
                    old_file.unlink()  # Remove the old pending file
                except Exception:
                    pass  # Best effort - don't fail if rename doesn't work
    
    def _write_separator(self):
        """Write a separator to distinguish between test runs."""
        separator = "\n" + "=" * 100 + "\n"
        separator += f"NEW TEST RUN STARTED AT: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n"
        separator += "=" * 100 + "\n\n"
        
        with open(self.log_file, 'a', encoding='utf-8') as f:
            f.write(separator)
    
    def set_level(self, level):
        """Set the minimum log level."""
        if level in self.LOG_LEVELS:
            self.current_level = self.LOG_LEVELS[level]
    
    def _should_log(self, level):
        """Check if message should be logged based on level."""
        return self.LOG_LEVELS.get(level, 0) >= self.current_level
    
    def _format_message(self, level, message, thread_id=None):
        """
        Format log message with timestamp, level, process ID, and thread ID.
        
        Format: [YYYY-MM-DDTHH:MM:SS.mmm] [LEVEL] [PID:TID] Message
        """
        
        timestamp = datetime.now().isoformat(timespec='milliseconds')
        
        if thread_id is None:
            thread_id = threading.get_ident()
        
        process_id = os.getpid()
        
        return f"[{timestamp}] [{level:8}] [PID:{process_id}|TID:{thread_id}] {message}\n"
    
    def _write_to_file(self, formatted_message):
        """Write formatted message to file with locking."""
        with self.lock:
            with open(self.log_file, 'a', encoding='utf-8') as f:
                f.write(formatted_message)
    
    def _add_to_buffer(self, formatted_message):
        """Add message to buffer and flush if needed."""
        with self.lock:
            self.buffer.append(formatted_message)
            
            # Flush if buffer is full
            if len(self.buffer) >= self.buffer_size:
                self._flush_buffer()
    
    def _flush_buffer(self):
        """Flush buffer to file (must be called with lock held)."""
        if self.buffer:
            with open(self.log_file, 'a', encoding='utf-8') as f:
                f.writelines(self.buffer)
            self.buffer.clear()
            self.last_flush_time = time.time()
    
    def _periodic_flush(self):
        """Background thread that flushes buffer periodically."""
        while True:
            time.sleep(1.0)  # Check every second
            
            with self.lock:
                # Flush if interval has passed
                if time.time() - self.last_flush_time >= self.flush_interval:
                    if self.buffer:
                        self._flush_buffer()
    
    def flush(self):
        """Force flush buffer to file."""
        with self.lock:
            self._flush_buffer()
    
    def log(self, level, message, thread_id=None):
        """
        Log a message at the specified level.
        
        Args:
            level: Log level (DEBUG, INFO, WARNING, ERROR, CRITICAL)
            message: Message to log
            thread_id: Optional thread identifier
        """
        if not self._should_log(level):
            return
        
        formatted_message = self._format_message(level, message, thread_id)
        self._add_to_buffer(formatted_message)
        
        # Also stream to CloudWatch if handler is available
        if self.cloudwatch_handler:
            try:
                # Extract just the message part (without formatting) for CloudWatch
                self.cloudwatch_handler.emit(level, message)
            except Exception:
                # Silently fail - local logs are primary
                pass
        formatted_message = self._format_message(level, message, thread_id)
        self._add_to_buffer(formatted_message)
    
    def debug(self, message, thread_id=None):
        """Log DEBUG level message."""
        self.log('DEBUG', message, thread_id)
    
    def info(self, message, thread_id=None):
        """Log INFO level message."""
        self.log('INFO', message, thread_id)
    
    def warning(self, message, thread_id=None):
        """Log WARNING level message."""
        self.log('WARNING', message, thread_id)
        # Print warnings to console for visibility
        print(f"⚠️  WARNING: {message}", flush=True)
    
    def error(self, message, thread_id=None):
        """Log ERROR level message."""
        self.log('ERROR', message, thread_id)
        self.flush()  # Flush immediately on errors
        # Print errors to console for visibility
        print(f"❌ ERROR: {message}", flush=True)
    
    def critical(self, message, thread_id=None):
        """Log CRITICAL level message."""
        self.log('CRITICAL', message, thread_id)
        self.flush()  # Flush immediately on critical events
    
    def print_and_log(self, message, level='INFO', thread_id=None, flush_console=True):
        """
        Print to console and log simultaneously.
        
        This ensures all console output is also captured in the log file.
        Useful for progress messages, status updates, and user-facing output.
        
        Args:
            message: Message to print and log
            level: Log level (INFO, WARNING, ERROR, etc.)
            thread_id: Optional thread identifier
            flush_console: Whether to flush console output immediately
        """
        # Print to console
        print(message, flush=flush_console)
        
        # Log to file (clean up special characters for log file)
        clean_message = (message
                        .replace('✓', 'OK')
                        .replace('✗', 'FAIL')
                        .replace('❌', 'ERROR')
                        .replace('⚠', 'WARNING')
                        .replace('○', 'O'))
        
        self.log(level.upper(), clean_message, thread_id)
    
    def log_api_call(self, endpoint, method, request_data, response_data, latency_ms, status_code, thread_id=None):
        """
        Log API call with request/response details and latency.
        
        Args:
            endpoint: API endpoint URL
            method: HTTP method (GET, POST, PUT, DELETE)
            request_data: Request payload (logged in full for debugging)
            response_data: Response payload (logged in full for debugging)
            latency_ms: Request latency in milliseconds
            status_code: HTTP status code
            thread_id: Optional thread identifier
        
        Requirements: 4.5
        """
        # Log full payloads for complete traceability (no truncation)
        
        def format_payload(data):
            """Format payload as pretty JSON if possible."""
            if data is None:
                return "None"
            
            try:
                if isinstance(data, (dict, list)):
                    return json.dumps(data, indent=2, default=str)
                elif isinstance(data, str):
                    # Try to parse as JSON
                    try:
                        parsed = json.loads(data)
                        return json.dumps(parsed, indent=2, default=str)
                    except:
                        return data
                else:
                    return str(data)
            except Exception as e:
                return f"<Error formatting payload: {e}>"
        
        request_str = format_payload(request_data)
        response_str = format_payload(response_data)
        
        message = (
            f"API Call: {method} {endpoint}\n"
            f"  Status: {status_code}\n"
            f"  Latency: {latency_ms:.2f}ms\n"
            f"  Request:\n{request_str}\n"
            f"  Response:\n{response_str}"
        )
        
        if status_code >= 400:
            self.error(message, thread_id)
        else:
            self.info(message, thread_id)
    
    def get_log_dir(self):
        """Get the log directory path."""
        return self.log_dir


