def create_directory_structure():
    """
    Create the required directory structure for test execution.
    
    Creates:
    - testing/load-stress-testing/testlogs/ - For test execution logs
    - testing/load-stress-testing/config/ - For test configuration files
    - testing/load-stress-testing/reports/ - For test reports and results
    
    Requirements: 4.1, 4.2, 23.1
    """
    base_dir = Path(__file__).parent
    
    # Define required directories
    directories = [
        base_dir / "testlogs",
        base_dir / "config",
        base_dir / "reports"
    ]
    
    # Create directories if they don't exist
    for directory in directories:
        directory.mkdir(parents=True, exist_ok=True)
        print(f"✓ Directory ready: {directory}")


# ============================================================================
# SECTION 12: MAIN ENTRY POINT
# ============================================================================

def main():
    """
    Main entry point for the load and stress testing system.
    
    This function orchestrates the entire test execution lifecycle:
    1. Parses command-line arguments
    2. Handles special modes (list, delete, force-unlock)
    3. Validates Python version and dependencies
    4. Creates directory structure
    5. Loads configuration
    6. Executes test based on mode (generation/execution/dry-run)
    7. Generates reports and performs cleanup
    """
    # ============================================================================
    # CRITICAL: Increase file descriptor limit for this process
    # macOS default soft limit is 256, which is too low for many worker threads
    # Each worker needs ~4-5 FDs (boto3 clients, log files, network connections)
    # Set to 4096 to support up to ~800 workers safely
    # ============================================================================
    try:
        import resource
        soft_limit, hard_limit = resource.getrlimit(resource.RLIMIT_NOFILE)
        
        # Try to set to 4096, or hard limit if lower
        desired_limit = min(4096, hard_limit)
        
        if soft_limit < desired_limit:
            resource.setrlimit(resource.RLIMIT_NOFILE, (desired_limit, hard_limit))
            print(f"✓ Increased file descriptor limit: {soft_limit} → {desired_limit}")
        else:
            print(f"✓ File descriptor limit: {soft_limit} (sufficient)")
            
    except Exception as e:
        print(f"⚠️  Warning: Could not increase file descriptor limit: {e}")
        print(f"   Current limit may cause 'Too many open files' errors with many workers")
    
    # Parse command-line arguments first
    args = parse_arguments()
    
    # Handle special modes that don't require full initialization
    if args.list_supported_genres:
        list_supported_genres()
        return
    
    if args.list:
        list_test_configs()
        return
    
    if args.delete_config:
        delete_test_config(args.delete_config)
        return
    
    if args.force_unlock:
        # Force unlock needs region and profile from args
        region = args.region if args.region else DEFAULT_AWS_REGION
        profile = args.aws_profile if args.aws_profile else None
        force_unlock_global_lock(region, profile)
        return
    
    print("=" * 80)
    print("Load and Stress Testing System for Stats & Leaderboards")
    print("=" * 80)
    print()
    
    # Skip validation if requested (advanced users only)
    if not args.skip_validation:
        # Check Python version first (critical requirement)
        check_python_version()
        
        # Check package dependencies
        check_package_dependencies()
        
        # Check AWS CLI
        check_aws_cli()
        
        # Check AWS credentials and create session
        aws_session = check_aws_credentials(args.aws_profile, args.region)
        
        # Check IAM permissions
        check_iam_permissions(aws_session)
    else:
        print("⚠ WARNING: Skipping validation checks (--skip-validation)")
        print()
        # Still need to create AWS session
        session_kwargs = {}
        if args.aws_profile:
            session_kwargs['profile_name'] = args.aws_profile
        if args.region:
            session_kwargs['region_name'] = args.region
        aws_session = boto3.Session(**session_kwargs)
    
    # Load and merge configuration
    config = load_configuration(args)
    
    # ========================================================================
    # INSTANCE ID ALLOCATION - Deferred until test_config_id is available
    # ========================================================================
    # ========================================================================
    # DISTRIBUTED INSTANCE ID ALLOCATION
    # ========================================================================
    # Instance ID allocation happens AFTER test_config_id is available
    # in each mode (GENERATION, EXECUTION, DRY-RUN)
    # 
    # GENERATION and DRY-RUN use fixed instance IDs (gen-1, dryrun-1)
    # EXECUTION uses distributed numeric IDs (1, 2, 3...) with DynamoDB coordination
    
    def allocate_distributed_instance_id(test_config_id, aws_session, region, mode='execution'):
        """
        Allocate instance ID based on mode.
        
        - GENERATION: Returns ("gen-1", 1) - fixed ID for generation mode
        - DRY-RUN: Returns ("dryrun-1", 1) - fixed ID for dry-run mode
        - EXECUTION: Atomically allocates sequential IDs (1, 2, 3...) using DynamoDB
        
        Args:
            test_config_id: Test Config ID (required)
            aws_session: boto3 Session object
            region: AWS region
            mode: Mode of operation ('generation', 'dry-run', 'execution')
        
        Returns:
            tuple: (instance_id, instance_num) e.g., ("instance-1", 1) or ("gen-1", 1)
        
        Raises:
            RuntimeError: If unable to allocate ID after max attempts (execution mode only)
        """
        # GENERATION and DRY-RUN modes use fixed instance IDs
        if mode == 'generation':
            return ("gen-1", 1)
        elif mode == 'dry-run':
            return ("dryrun-1", 1)
        
        # EXECUTION mode: Use DynamoDB atomic counter for distributed coordination
        # A single atomic increment guarantees a unique ID with no retries or limits
        dynamodb = aws_session.resource('dynamodb', region_name=region)
        table = dynamodb.Table(TEST_DEFINITIONS_TABLE_NAME)
        
        current_time = int(time.time())
        ttl = current_time + (24 * 3600)  # 24 hours
        
        # Atomically increment the instance counter and get the new value
        response = table.update_item(
            Key={
                'TestConfigID': test_config_id,
                'ConfigCategory': 'INSTANCE_COUNTER'
            },
            UpdateExpression='ADD InstanceCount :inc SET #ttl = :ttl',
            ExpressionAttributeNames={
                '#ttl': 'TTL'
            },
            ExpressionAttributeValues={
                ':inc': 1,
                ':ttl': ttl
            },
            ReturnValues='UPDATED_NEW'
        )
        
        instance_num = int(response['Attributes']['InstanceCount'])
        instance_id = f"instance-{instance_num}"
        
        # Also write the instance record for status tracking
        config_category = f'INSTANCE#{instance_id}'
        table.put_item(
            Item={
                'TestConfigID': test_config_id,
                'ConfigCategory': config_category,
                'InstanceID': instance_id,
                'InstanceNumber': instance_num,
                'Status': 'ACTIVE',
                'StartTime': current_time,
                'Hostname': socket.gethostname(),
                'PID': os.getpid(),
                'TTL': ttl
            }
        )
        
        return (instance_id, instance_num)
    
    # Instance ID will be allocated later after test_config_id is available
    # For now, set to None - will be allocated in each mode's flow
    instance_id = None
    instance_num = None
    
    # ========================================================================
    # INITIALIZE LOGGING - Use placeholder instance ID initially
    # ========================================================================
    # Instance ID will be allocated after test_config_id is available
    # For now, use "pending" as placeholder - will be updated later
    log_dir = config.get('log_dir', os.path.join(os.path.dirname(__file__), 'testlogs'))
    os.makedirs(log_dir, exist_ok=True)
    os.makedirs(os.path.join(log_dir, 'workers'), exist_ok=True)
    
    # Create logger with placeholder instance ID
    # Will be updated with actual instance ID after allocation
    logger = ThreadSafeLogger(log_dir, instance_id="pending", cloudwatch_handler=None)
    logger.info("=" * 80)
    logger.info("Load and Stress Testing System - Session Started")
    logger.info("=" * 80)
    logger.info("")
    logger.info("=" * 80)
    logger.info(f"Mode: {config.get('mode', 'unknown')}")
    logger.info(f"Instance ID: pending (will be allocated after test_config_id is available)")
    logger.info(f"Timestamp: {time.strftime('%Y-%m-%d %H:%M:%S')}")
    
    # Create CloudWatch handler for events worker (will be updated with real instance_id later)
    events_cloudwatch_handler = None
    
    # Create event worker logger for all modes (will be updated with real instance_id later)
    events_log_file = os.path.join(log_dir, 'workers', f'events-worker-pending.log')
    events_logger = WorkerLogger(events_log_file, "Events", logger, cloudwatch_handler=events_cloudwatch_handler)
    
    if ENABLE_LOCAL_WORKER_LOGS:
        events_logger.info("=" * 80)
        events_logger.info(f"Events Manager Worker Log - {config.get('mode', 'unknown').title()} Mode")
        events_logger.info("=" * 80)
        events_logger.info(f"Instance ID: pending (will be allocated)")
        events_logger.info(f"Timestamp: {time.strftime('%Y-%m-%d %H:%M:%S')}")

    
    logger.print_and_log("✓ Logging initialized")
    logger.print_and_log(f"  Main log: {os.path.join(log_dir, 'main-pending.log')} (will be renamed after instance ID allocation)")
    if not ENABLE_LOCAL_WORKER_LOGS:
        logger.print_and_log(f"  Worker logs: CloudWatch only (local files disabled)")
    logger.print_and_log("")
    
    # Create directory structure
    logger.print_and_log("Initializing directory structure...")
    create_directory_structure()
    logger.print_and_log("")
    
    # Run sanity checks for generation mode (basic checks only)
    if config['mode'] == 'generation' and not args.skip_validation:
        if not run_sanity_checks(config, mode='generation'):
            logger.print_and_log("❌ Pre-flight sanity checks failed", level='ERROR')
            logger.print_and_log("   Cannot proceed with test generation", level='ERROR')
            sys.exit(1)
    
    # Display configuration summary
    logger.print_and_log("Configuration Summary:")
    logger.print_and_log(f"  Mode: {config['mode']}")
    logger.print_and_log(f"  Region: {config['region']}")
    if 'test_config_id' in config:
        logger.print_and_log(f"  Test Config ID: {config['test_config_id']}")
    if 'test_name' in config:
        logger.print_and_log(f"  Test Name: {config['test_name']}")
    if 'genre' in config:
        logger.print_and_log(f"  Genre: {config['genre']}")
    if 'duration' in config:
        logger.print_and_log(f"  Duration: {config['duration']} seconds")
    if 'max_players' in config:
        logger.print_and_log(f"  Max Players: {config['max_players']}")
    logger.print_and_log("")
    
    # Handle generation mode
    if config['mode'] == 'generation':
        logger.print_and_log("=" * 80)
        logger.print_and_log("Generation Mode: Creating New Test Configuration")
        logger.print_and_log("=" * 80)
        logger.print_and_log("")
        
        # ====================================================================
        # INFRASTRUCTURE DISCOVERY (Requirements 1.1, 1.2)
        # ====================================================================
        logger.print_and_log("Discovering infrastructure from CloudFormation stack...")
        logger.print_and_log("")
        
        stack_name = config.get('stack_name', 'GameStatsLeaderboardsStack')
        
        try:
            infrastructure = discover_infrastructure(
                stack_name=stack_name,
                aws_profile=config.get('aws_profile'),
                aws_region=config['region'],
                logger=None
            )
            
            # Store infrastructure details in config (using correct output keys)
            config['api_base_url'] = infrastructure.get('ApiEndpoint')
            # NOTE: studio_id and game_id from CloudFormation are HINTS ONLY
            # They are used to construct the SSM parameter path, but SSM is the source of truth
            # These values are HINTS from CloudFormation to locate the SSM parameter
            # SSM Parameter Store is the ONLY source of truth for authentication
            config['studio_id'] = infrastructure.get('StudioId')
            config['game_id'] = infrastructure.get('GameId')
            
            # IMPORTANT: CloudFormation SSMParameterPrefix output may be incorrect
            # The actual SSM prefix used by Lambda functions is based on the environment
            # Pattern: /game-statsleaderboards-{environment}
            # We derive it from the API endpoint or use a sensible default
            cf_prefix = infrastructure.get('SSMParameterPrefix', '/gamestatsleaderboardsstack/')
            
            # Try to derive the correct prefix from the API endpoint
            # API endpoint format: https://{api-id}.execute-api.{region}.amazonaws.com/{environment}/
            api_url = config['api_base_url']
            if '/dev/' in api_url:
                config['ssm_parameter_prefix'] = '/game-statsleaderboards-dev'
            elif '/prod/' in api_url:
                config['ssm_parameter_prefix'] = '/game-statsleaderboards-prod'
            elif '/staging/' in api_url:
                config['ssm_parameter_prefix'] = '/game-statsleaderboards-staging'
            else:
                # Fallback to CloudFormation output (may be incorrect)
                config['ssm_parameter_prefix'] = cf_prefix
                logger.print_and_log(f"⚠️  WARNING: Could not derive SSM prefix from API endpoint, using CloudFormation output", level='WARNING')
            
            config['config_table_name'] = infrastructure.get('ConfigTableName')
            config['stats_table_name'] = infrastructure.get('StatsTableName')
            
            logger.print_and_log(f"✓ Infrastructure discovery complete")
            logger.print_and_log(f"  API Endpoint: {config['api_base_url']}")
            logger.print_and_log(f"  Studio ID (hint): {config['studio_id']}")
            logger.print_and_log(f"  Game ID (hint): {config['game_id']}")
            logger.print_and_log(f"  SSM Parameter Prefix: {config['ssm_parameter_prefix']}")
            logger.print_and_log(f"  Config Table: {config['config_table_name']}")
            logger.print_and_log(f"  Stats Table: {config['stats_table_name']}")
            logger.print_and_log("")
            
            # CRITICAL: Retrieve studio metadata from SSM Parameter Store
            # The backend APIs ONLY authenticate against SSM values
            # We MUST use these exact values - cannot generate or use CloudFormation outputs
            logger.print_and_log("=" * 80)
            logger.print_and_log("INFO: Retrieving Studio Metadata from SSM Parameter Store")
            logger.print_and_log("=" * 80)
            logger.print_and_log("")
            logger.print_and_log("The backend APIs authenticate using API keys stored in SSM.")
            logger.print_and_log("We MUST retrieve and use the exact metadata from SSM Parameter Store.")
            logger.print_and_log("")
            
            # Create boto3 session for SSM access
            session_kwargs = {'region_name': config['region']}
            if config.get('aws_profile'):
                session_kwargs['profile_name'] = config['aws_profile']
            session = boto3.Session(**session_kwargs)
            
            # Create SSM client
            ssm = session.client('ssm')
            
            # Query ALL API keys from SSM Parameter Store
            logger.print_and_log(f"Querying SSM path: {config['ssm_parameter_prefix']}/api-keys/")
            logger.print_and_log("")
            
            try:
                # Get all parameters under the api-keys path
                response = ssm.get_parameters_by_path(
                    Path=f"{config['ssm_parameter_prefix']}/api-keys",
                    Recursive=True,
                    WithDecryption=True
                )
                
                parameters = response.get('Parameters', [])
                
                if not parameters:
                    logger.print_and_log(f"❌ ERROR: No API keys found in SSM Parameter Store", level='ERROR')
                    logger.print_and_log("")
                    logger.print_and_log(f"Path checked: {config['ssm_parameter_prefix']}/api-keys/")
                    logger.print_and_log("")
                    logger.print_and_log("The developer registration must exist before running load tests.")
                    logger.print_and_log("")
                    logger.print_and_log("To create a developer registration:")
                    logger.print_and_log(f"  1. Use the developer registration API: POST {config['api_base_url']}/developer/register")
                    logger.print_and_log(f"  2. Or run the developer registration test script")
                    logger.print_and_log("")
                    sys.exit(1)
                
                logger.print_and_log(f"Found {len(parameters)} API key parameter(s) in SSM")
                logger.print_and_log("")
                
                # Parse and validate each parameter
                active_keys = []
                inactive_keys = []
                
                for param in parameters:
                    param_name = param['Name']
                    param_value = param['Value']
                    
                    try:
                        key_data = json.loads(param_value)
                        status = key_data.get('status', 'unknown')
                        studio_id = key_data.get('studioId')
                        game_id = key_data.get('gameId')
                        
                        if status == 'active':
                            active_keys.append({
                                'parameter_name': param_name,
                                'data': key_data,
                                'studio_id': studio_id,
                                'game_id': game_id
                            })
                        else:
                            inactive_keys.append({
                                'parameter_name': param_name,
                                'status': status,
                                'studio_id': studio_id,
                                'game_id': game_id
                            })
                    except json.JSONDecodeError:
                        logger.print_and_log(f"⚠️  WARNING: Invalid JSON in parameter: {param_name}", level='WARNING')
                        continue
                
                # Display summary
                logger.print_and_log(f"SSM Key Status Summary:")
                logger.print_and_log(f"  Total: {len(parameters)}")
                logger.print_and_log(f"  Active: {len(active_keys)}")
                logger.print_and_log(f"  Inactive/Other: {len(inactive_keys)}")
                logger.print_and_log("")
                
                # Validate exactly 1 active key
                if len(active_keys) == 0:
                    logger.print_and_log(f"❌ ERROR: No active API keys found in SSM Parameter Store", level='ERROR')
                    logger.print_and_log("")
                    logger.print_and_log(f"Found {len(inactive_keys)} inactive/revoked key(s):")
                    for key in inactive_keys:
                        logger.print_and_log(f"  - {key['parameter_name']}: {key['studio_id']}/{key['game_id']} (status: {key['status']})")
                    logger.print_and_log("")
                    logger.print_and_log("The system requires exactly 1 active API key.")
                    logger.print_and_log("Please create a new developer registration or activate an existing one.")
                    sys.exit(1)
                
                elif len(active_keys) > 1:
                    logger.print_and_log(f"❌ ERROR: Multiple active API keys found - this is unacceptable!", level='ERROR')
                    logger.print_and_log("")
                    logger.print_and_log(f"Found {len(active_keys)} active key(s):")
                    for key in active_keys:
                        logger.print_and_log(f"  - {key['parameter_name']}: {key['studio_id']}/{key['game_id']}")
                    logger.print_and_log("")
                    logger.print_and_log("Single-tenant system must have exactly 1 active key.")
                    logger.print_and_log("Please deactivate or revoke all but one active key.")
                    logger.print_and_log("")
                    logger.print_and_log("To deactivate a key, update its 'status' field to 'inactive' in SSM.")
                    sys.exit(1)
                
                # Exactly 1 active key found - use it!
                active_key = active_keys[0]
                ssm_metadata = active_key['data']
                parameter_name = active_key['parameter_name']
                
                logger.print_and_log(f"✓ Found exactly 1 active API key")
                logger.print_and_log(f"  Parameter: {parameter_name}")
                logger.print_and_log("")
                
                # SSM is the ONLY source of truth - use these exact values
                config['studio_name'] = ssm_metadata.get('studioName')
                config['game_title'] = ssm_metadata.get('gameTitle')
                config['contact_email'] = ssm_metadata.get('contactEmail')
                config['game_genre'] = ssm_metadata.get('gameGenre')
                config['api_key'] = ssm_metadata.get('apiKey')
                config['studio_id'] = ssm_metadata.get('studioId')  # Override with SSM value
                config['game_id'] = ssm_metadata.get('gameId')      # Override with SSM value
                
                # Validate all required fields are present
                required_fields = ['studio_name', 'game_title', 'contact_email', 'game_genre', 'api_key', 'studio_id', 'game_id']
                missing_fields = [f for f in required_fields if not config.get(f)]
                
                if missing_fields:
                    logger.print_and_log(f"❌ ERROR: SSM parameter is missing required fields: {', '.join(missing_fields)}", level='ERROR')
                    logger.print_and_log("")
                    logger.print_and_log(f"Parameter: {parameter_name}")
                    logger.print_and_log(f"SSM parameter content: {json.dumps(ssm_metadata, indent=2)}")
                    logger.print_and_log("")
                    logger.print_and_log("The SSM parameter must contain complete developer registration metadata.")
                    logger.print_and_log("Please ensure the developer registration was created correctly.")
                    sys.exit(1)
                
                logger.print_and_log(f"✓ Successfully retrieved studio metadata from SSM")
                logger.print_and_log("")
                logger.print_and_log(f"Studio Metadata (Source of Truth):")
                logger.print_and_log(f"  Studio ID: {config['studio_id']}")
                logger.print_and_log(f"  Game ID: {config['game_id']}")
                logger.print_and_log(f"  Studio Name: {config['studio_name']}")
                logger.print_and_log(f"  Game Title: {config['game_title']}")
                logger.print_and_log(f"  Contact Email: {config['contact_email']}")
                logger.print_and_log(f"  Game Genre: {config['game_genre']}")
                logger.print_and_log(f"  API Key: {config['api_key']} (loaded) _intentionally displaying this one time here_")
                logger.print_and_log("")
                logger.print_and_log(f"✓ All API calls will use these authenticated values")
                logger.print_and_log("")
                
            except Exception as e:
                logger.print_and_log(f"❌ ERROR: Failed to retrieve studio metadata from SSM: {e}", level='ERROR')
                logger.print_and_log("")
                logger.print_and_log(f"Path: {config['ssm_parameter_prefix']}/api-keys/")
                logger.print_and_log("")
                logger.print_and_log("Possible causes:")
                logger.print_and_log("  - SSM parameters do not exist")
                logger.print_and_log("  - Insufficient IAM permissions (ssm:GetParametersByPath)")
                logger.print_and_log("  - Incorrect SSM parameter prefix")
                logger.print_and_log("  - Network connectivity issues")
                logger.print_and_log("")
                traceback.print_exc()
                logger.print_and_log("")
                logger.print_and_log("Cannot proceed without valid developer registration from SSM.")
                sys.exit(1)
            
        except Exception as e:
            logger.print_and_log(f"❌ Infrastructure discovery failed: {e}", level='ERROR')
            logger.print_and_log("")
            logger.print_and_log("Please ensure:")
            logger.print_and_log(f"  - CloudFormation stack '{stack_name}' exists in region '{config['region']}'")
            logger.print_and_log(f"  - AWS profile '{config.get('aws_profile')}' has cloudformation:DescribeStacks permission")
            logger.print_and_log("")
            sys.exit(1)
        
        # Check if a test configuration with this name already exists
        existing_config_id = find_test_config_by_name(config['test_name'], config['region'], config.get('aws_profile'))
        
        if existing_config_id:
            logger.print_and_log("")
            logger.print_and_log("=" * 80)
            logger.print_and_log(f"⚠️  WARNING: Test configuration with name '{config['test_name']}' already exists", level='WARNING')
            logger.print_and_log("=" * 80)
            logger.print_and_log("")
            logger.print_and_log(f"  Existing Test Config ID: {existing_config_id}")
            logger.print_and_log("")
            
            # Check if --overwrite flag is set
            if args.overwrite:
                logger.print_and_log("  --overwrite flag detected: Automatically overwriting existing configuration")
                choice = '1'
            else:
                print("Options:")
                print("  1. Overwrite existing configuration (delete and recreate)")
                print("  2. Create new configuration with same name (new Test Config ID)")
                print("  3. Cancel")
                print()
                
                choice = input("Enter your choice (1/2/3): ").strip()
            
            if choice == '1':
                print()
                print(f"Deleting existing configuration: {existing_config_id}")
                print()
                
                # Delete existing configuration
                try:
                    session_kwargs = {'region_name': config['region']}
                    if config.get('aws_profile'):
                        session_kwargs['profile_name'] = config['aws_profile']
                    session = boto3.Session(**session_kwargs)
                    dynamodb = session.resource('dynamodb')
                    table = dynamodb.Table(TEST_DEFINITIONS_TABLE_NAME)
                    
                    # Query all categories for this config
                    response = table.query(
                        KeyConditionExpression='TestConfigID = :id',
                        ExpressionAttributeValues={
                            ':id': existing_config_id
                        }
                    )
                    
                    items = response.get('Items', [])
                    
                    # Delete all configuration categories
                    for item in items:
                        table.delete_item(
                            Key={
                                'TestConfigID': item['TestConfigID'],
                                'ConfigCategory': item['ConfigCategory']
                            }
                        )
                        print(f"  ✓ Deleted category: {item['ConfigCategory']}")
                    
                    print()
                    print(f"✓ Deleted {len(items)} configuration records")
                    print()
                    
                    # Also clear GLOBAL lock if it references this config
                    print("Checking for stale GLOBAL lock...")
                    try:
                        lock_response = table.get_item(
                            Key={
                                'TestConfigID': 'GLOBAL',
                                'ConfigCategory': 'TEST_LOCK'
                            }
                        )
                        
                        if 'Item' in lock_response:
                            lock = lock_response['Item']
                            locked_config_id = lock.get('ActiveTestConfigID')
                            print(f"  Found GLOBAL lock for config: {locked_config_id}")
                            
                            if locked_config_id == existing_config_id:
                                print(f"  Clearing stale GLOBAL lock (references deleted config)...")
                                table.delete_item(
                                    Key={
                                        'TestConfigID': 'GLOBAL',
                                        'ConfigCategory': 'TEST_LOCK'
                                    }
                                )
                                print(f"  ✓ GLOBAL lock cleared")
                                print()
                            else:
                                print(f"  GLOBAL lock references different config ({locked_config_id}), leaving it")
                                print()
                        else:
                            print(f"  No GLOBAL lock found")
                            print()
                    except Exception as e:
                        print(f"  ⚠ Warning: Could not check/clear GLOBAL lock: {e}")
                        print("    You may need to use --force-unlock if needed")
                        print()
                    
                except Exception as e:
                    print(f"❌ Failed to delete existing configuration: {e}")
                    print("Aborting generation.")
                    sys.exit(1)
                    
            elif choice == '2':
                print()
                print("Creating new configuration with same name...")
                print()
                
            elif choice == '3':
                print()
                print("Generation cancelled.")
                sys.exit(0)
                
            else:
                print()
                print("Invalid choice. Aborting.")
                sys.exit(1)
        
        # Generate unique Test Config ID
        test_config_id = generate_test_config_id()
        config['test_config_id'] = test_config_id
        
        print(f"Generated Test Config ID: {test_config_id}")
        print()
        
        # Allocate instance ID for GENERATION mode (uses fixed ID "gen-1")
        print("Allocating instance ID for generation mode...")
        try:
            instance_id, instance_num = allocate_distributed_instance_id(
                test_config_id, aws_session, config.get('region', DEFAULT_AWS_REGION),
                mode='generation'
            )
            print(f"✓ Allocated instance ID: {instance_id}")
        except Exception as e:
            print(f"❌ ERROR: Failed to allocate instance ID: {e}")
            print("   Cannot proceed without instance ID")
            sys.exit(1)
        print()
        
        # Update logger and events_logger with actual instance ID
        logger.update_instance_id(instance_id)
        
        # Initialize CloudWatch handler now that we have instance_id
        try:
            main_cloudwatch_handler = CloudWatchLogHandler(
                log_group_name=CLOUDWATCH_LOG_GROUP_PREFIX,
                log_stream_name=f"main-{instance_id}",
                region=config.get('region', DEFAULT_AWS_REGION),
                aws_session=aws_session
            )
            logger.cloudwatch_handler = main_cloudwatch_handler
        except Exception as e:
            print(f"⚠️  Warning: Failed to initialize CloudWatch handler: {e}")
        
        # Update events_logger with real instance_id
        try:
            events_cloudwatch_handler = CloudWatchLogHandler(
                log_group_name=CLOUDWATCH_LOG_GROUP_PREFIX,
                log_stream_name=f"events-worker-{instance_id}",
                region=config.get('region', DEFAULT_AWS_REGION),
                aws_session=aws_session,
                logger=logger
            )
            events_logger.cloudwatch_handler = events_cloudwatch_handler
        except Exception as e:
            print(f"⚠️  Warning: Failed to initialize events CloudWatch handler: {e}")
        
        if ENABLE_LOCAL_WORKER_LOGS:
            new_events_log_file = os.path.join(log_dir, 'workers', f'events-worker-{instance_id}.log')
            events_logger.log_file = Path(new_events_log_file)
        
        logger.info(f"Logger updated with instance ID: {instance_id}")
        print(f"✓ Logger updated with instance ID: {instance_id}")
        print()
        
        # Select genre (user-specified or random)
        user_genre = config.get('genre')
        selected_genre_key, selected_genre_data = select_genre(user_genre)
        
        # Store selected genre in config
        config['selected_genre_key'] = selected_genre_key
        config['selected_genre_data'] = selected_genre_data
        
        print(f"✓ Genre selection complete: {selected_genre_key}")
        print()
        
        # Select stats from genre pool
        selected_stats = select_stats_from_genre(selected_genre_data)
        
        # Store selected stats in config
        config['selected_stats'] = selected_stats
        
        print(f"✓ Stats selection complete: {len(selected_stats)} stats selected")
        print()
        
        # Generate game modes FIRST (needed for leaderboard generation)
        game_modes = generate_game_modes(selected_genre_key, selected_genre_data)
        
        # Store game modes in config
        config['game_modes'] = game_modes
        
        print(f"✓ Game mode generation complete: {len(game_modes)} modes configured")
        print()
        
        # Generate leaderboard configurations (now with game modes available)
        leaderboard_configs = generate_leaderboard_configs(
            selected_genre_key,
            selected_genre_data,
            selected_stats,
            game_modes  # Pass game modes for assignment
        )
        
        # Store leaderboard configs in config
        config['leaderboard_configs'] = leaderboard_configs
        
        print(f"✓ Leaderboard generation complete: {len(leaderboard_configs)} leaderboards configured")
        print()
        
        # Generate fullRawGameReport template
        game_report_template = generate_game_report_template(
            selected_genre_key,
            selected_stats
        )
        
        # Store game report template in config
        config['game_report_template'] = game_report_template
        
        print(f"✓ Game report template generation complete")
        print()
        
        # Generate event schedule with time-bound leaderboards
        test_duration = config.get('duration', 3600)  # Default 1 hour if not specified
        event_schedule = generate_event_schedule(test_duration, game_modes)
        
        # Store event schedule in config
        config['event_schedule'] = event_schedule
        
        print(f"✓ Event schedule generation complete: {len(event_schedule)} events scheduled")
        print()
        
        # Generate player pool definition
        player_pool = generate_player_pool_definition(selected_genre_key)
        
        # Store player pool in config
        config['player_pool'] = player_pool
        
        print(f"✓ Player pool definition complete: {player_pool['poolSize']} players")
        print()
        
        # Create METADATA record
        metadata_record = create_metadata_record(
            test_config_id,
            config['test_name'],
            selected_genre_key
        )
        
        # Store METADATA record in config
        config['metadata_record'] = metadata_record
        
        print(f"✓ METADATA record creation complete")
        print()
        
        # Validate configuration completeness (Task 7.13.1)
        is_valid, errors, warnings = validate_configuration_completeness(config)
        
        if not is_valid:
            print("❌ Configuration validation failed")
            print("   Cannot proceed with invalid configuration.")
            print("   Please review the errors above and regenerate.")
            sys.exit(1)
        
        # Check DynamoDB permissions before attempting storage
        if not check_dynamodb_permissions(config['region'], config.get('aws_profile')):
            print("❌ Cannot proceed without DynamoDB permissions")
            print("   Please configure IAM permissions and try again.")
            sys.exit(1)
        
        # Store configuration to DynamoDB
        if not store_test_configuration_to_dynamodb(test_config_id, config, config['region'], config.get('aws_profile')):
            print("❌ Failed to store configuration to DynamoDB")
            print("   Configuration was generated but not persisted.")
