            test_start_time = int(time.time())
            
            # Find the earliest event start time in the original schedule
            original_first_event_time = min(event['startTime'] for event in config['event_schedule'])
            
            # Start first event 2-5 minutes after test start (random for variety)
            # This allows time for workers to spawn and stabilize before events begin
            first_event_delay = random.randint(120, 300)  # 2-5 minutes
            
            # Calculate the shift needed: (test_start + delay) - original_first_event
            time_shift = (test_start_time + first_event_delay) - original_first_event_time
            
            # Apply shift to all events
            for event in config['event_schedule']:
                event['startTime'] += time_shift
                event['endTime'] += time_shift
                
                # Update ISO timestamps for human readability
                event['startTimeISO'] = datetime.fromtimestamp(event['startTime'], tz=timezone.utc).isoformat()
                event['endTimeISO'] = datetime.fromtimestamp(event['endTime'], tz=timezone.utc).isoformat()
                
                # IMPORTANT: Do NOT set optionalLBExpiryDateTimeStamp here!
                # Expiry will be set via UPDATE API after leaderboard creation
                # This ensures expiry is always relative to actual test execution time
            
            logger.print_and_log(f"  ✓ Adjusted {len(config['event_schedule'])} events (shifted by {time_shift} seconds)")
            logger.print_and_log(f"  First event starts in {first_event_delay} seconds ({first_event_delay//60}m {first_event_delay%60}s)")
            logger.print_and_log(f"  First event starts at: {config['event_schedule'][0]['startTimeISO']}")
            logger.print_and_log("")
            
